CREATE TABLE councils (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    slug TEXT NOT NULL UNIQUE,
    level TEXT NOT NULL  -- 'local', 'county', 'regional', 'westminster'
);
INSERT INTO "councils" VALUES(1,'Lerwick Town Council','lerwick-town-council','local');
INSERT INTO "councils" VALUES(2,'Zetland County Council','zetland-county-council','county');
INSERT INTO "councils" VALUES(3,'Shetland Islands Council','shetland-islands-council','regional');
INSERT INTO "councils" VALUES(4,'Parliament of Great Britain','parliament-great-britain','westminster');
INSERT INTO "councils" VALUES(5,'Parliament of the United Kingdom','parliament-uk','westminster');
INSERT INTO "councils" VALUES(6,'Scottish Parliament','scottish-parliament','devolved');
CREATE TABLE elections (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    council_id INTEGER NOT NULL REFERENCES councils(id),
    constituency_id INTEGER REFERENCES constituencies(id),
    constituency_display_name TEXT,  -- historical name if different from current constituency name
    election_date TEXT,       -- ISO date or partial
    election_type TEXT NOT NULL,  -- 'general', 'by-election'
    electorate INTEGER,
    electorate_detail TEXT,   -- e.g. '107 men, 19 women'
    turnout INTEGER,
    turnout_pct REAL,
    notes TEXT,
    replaced_person TEXT,        -- for by-elections: who resigned/died to trigger it
    replaced_person_id INTEGER REFERENCES people(id),
    wiki_page_title TEXT NOT NULL,
    hidden INTEGER NOT NULL DEFAULT 0  -- boolean: hide from site without deleting
);
