INSERT INTO "elections" VALUES(21,1,NULL,NULL,'1874-09-03','general',NULL,NULL,NULL,NULL,'1st Council Group. The councillors were split on the interpretation of the the procedures and as such two votes were held in two different rooms of the County Halls. The second set of Councillors ended up being the selected councillors.',NULL,NULL,'Lerwick Town Council Election September 1874',0);
INSERT INTO "elections" VALUES(22,1,NULL,NULL,'1874-09-03','general',NULL,NULL,NULL,NULL,'2st Council Group. The councillors were split on the interpretation of the the procedures and as such two votes were held in two different rooms of the County Halls. The second set of Councillors ended up being the selected councillors.',NULL,NULL,'Lerwick Town Council Election September 1874',0);
