CREATE TABLE people (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    born_date TEXT,          -- ISO date or partial e.g. '1775-11-10'
    died_date TEXT,
    birth_place TEXT,
    death_place TEXT,
    intro TEXT,              -- opening text before any section
    biography TEXT,          -- content from ==Biography== section
    image_ref TEXT,          -- main image filename from wiki (body, not templates)
    headshot_ref TEXT,       -- small headshot filename from succession templates
    bayanne_id TEXT,         -- bayanne.info person ID e.g. 'I18328'
    wiki_page_title TEXT,
    categories TEXT,          -- JSON array of original wiki categories
    born_in_shetland INTEGER, -- 1 = yes, 0 = no, NULL = unknown
    died_in_shetland INTEGER, -- 1 = yes, 0 = no, NULL = unknown
    findagrave_id INTEGER     -- Find A Grave memorial ID
);
INSERT INTO "people" VALUES(1,'Adam Halcrow (i)','adam-halcrow-i','1872-12-09','1940-12-24','Punstow','6 Carlton Place, Lerwick','Captain Adam Halcrow was a sea captain and author who published under the name Captain A. Halcrow, the second of eight children born to James Halcrow and his wife Barbara (Jarmson), both of Cunningsburgh. James was a seaman, and two of the children became Master Mariners, Adam and his younger brother William. Another brother, Jeremiah, became a schoolmaster in North Berwick.','Adam started his sea-going career as a fisherman on sail herring boats, and was cod fishing on the Faroe banks. After a season whaling at Greenland, he shipped on the four masted barque Falls of Dee for San Francisco, a trip which saw the vessel considerably overdue because of severe Cape Horn weather. After further sea time, he obtained his master''s ticket, aged 29, and sailed world-wide. From 1910 to 1930 he was employed on the west coast of Africa. He qualified as a pilot on the river Niger, and in 1918 was appointed Marine Superintendent at Lagos and later Freetown. He retired from the sea in 1930 and returned to Shetland. Entering public life at home, he became Chairman of Lerwick Ratepayers'' Association and was elected toLerwick Town Council, becoming Junior and later Senior Bailie. He was a member of Lerwick Harbour Trust and was also Vice-Convenor and later Convenor of Zetland County Council in April 1937. He retired from this position in May 1938 for health reasons. Captain Adam Halcrow married Jane Smith of Sandwick on the 23rd of January 1902, and they had two children. The eldest, James Alexander Smith Halcrow, was lost at sea when serving as a Lieutenant in the Royal Naval Reserve. His ship, the corvette H.M.S. Marigold, was sunk west of Gibraltar Strait on the 9th of December 1942 - on what would have been his father''s 70th birthday, had Capt. Halcrow not had already died on the 24th of December 1940 at 6 Carlton Place, Lerwick. His published works include: Deep-sea Plunderings: tales of fact, Oliver &amp; Boyd, Edinburgh 1938; A compilation of articles previously published in magazines and newspapers. The Sail Fishermen of Shetland : and their Norse and Dutch forerunners, T and J Manson, 1950, reprinted in facsimile by the Shetland Times, 1994 (ISBN 0900662980). His second cousin, [person:adam-halcrow-ii:Adam], was also a County Councillor.','Adam Halcrow 1872-1940.png',NULL,'I81067','Adam_Halcrow_(i)','["Lerwick Town Councillors", "Zetland County Councillors", "1872 Births", "1940 Deaths"]',1,1,202734797);
INSERT INTO "people" VALUES(2,'Adam Halcrow (ii)','adam-halcrow-ii','1908-04-07','1958-09-23','Aithsetter','Lerwick','Adam Halcrow was a County Councillor for Cunningburgh between 1949 to 1955. His second cousin, [person:adam-halcrow-i:Adam], was also a County Councillor.','In Cunningsburgh, Adam was the secretary of the local agricultural society, and he worked with the Shetland Hand Knitting Association. During WWII he worked with Shell-Mex.',NULL,NULL,'I84590','Adam_Halcrow_(ii)','["Zetland County Councillors", "1908 Births", "1958 Deaths"]',1,1,179137869);
INSERT INTO "people" VALUES(3,'Adam Jamieson','adam-jamieson','1861-10-04','1925-03-12','Walls','Tingwall','Adam James Jamieson MBE was a merchant, justice of the peace and a County Councillor for Burra between 1913 and 1919.','Adam was educated in Scalloway, and began his career in the town. He worked with Robert Fraser (after whom Scalloway''s Fraser Park is named), after Robert left for Aberdeen. [person:henry-mouat:Henry Mouat] described him as "everybody''s right hand man".','Adam J. Jamieson.jpg',NULL,'I102720','Adam_Jamieson','["Zetland County Councillors", "1861 Births", "1923 Deaths", "Councillors pictured"]',1,1,179137476);
INSERT INTO "people" VALUES(4,'Adam Thomson','adam-thomson','1911-10-09','1977-04-19','Aithsting','Hagersville, Ontario, Canada','Reverend Adam Thomson was a minister for the Church of Scotland and a County Councillor for Nesting between 1945 and 1949.','Adam spent some time in Baltasound and Lunna. After leaving Shetland around 1950, he went the St Andrew''s Scots'' Kirk in Saint George''s, Grenada. In 1955, he returned to Scotland for a brief period before accepting an assistantship at Knox Crescent and Kensington Presbyterian Church in Montreal as he wanted to study for admission into the Presbyterian Church in Canada. He studied evening classes at McGill University and by 1960 he was formally inducted into the Presbytery of Ottawa. By 1964 he preached at the St. Andrew''s Presbyterian in Hagarsville. He returned to Shetland in 1966 and 1972 to be a guest preacher at the Lunna Kirk.',NULL,NULL,'I52517','Adam_Thomson','["Zetland County Councillors", "Councillors - Clergymen", "1911 Births", "1977 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(5,'Addie Doull','addie-doull','1945-07-27',NULL,'Muckle Roe',NULL,'Adam Thomas ''Addie'' Doull is a former Shetland Islands Councillor for the Shetland North ward from 2007 until 2012.',NULL,NULL,NULL,'I58511','Addie_Doull','["Shetland Islands Councillors", "Natives of Shetland", "1945 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(6,'Alan Fraser','alan-fraser','1907-10-24','1999-02-28','Unst','Unst','Alan Bradshaw Fraser was a County Councillor and Shetland Islands Councillor for Unst between 1970 until 1978, then 1982 until 1986.','Alan lived his entire life on his native island of Unst. The youngest of seven sons, four of Alan''s brothers had already left Shetland looking for work when Alan left school aged 14. He began croft work, but his early years were blighted by loss. By the end of 1993, Alan had lost both parents and four brothers. He worked with Pearl Insurance, and was known to assist young visitors to Unst by car. He opened a youth hostel in Gardiesfauld which was later bought by a charitable trust.',NULL,NULL,'I11472','Alan_Fraser','["Zetland County Councillors", "Shetland Islands Councillors", "1907 Births", "1999 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(7,'Alastair Cooper','alastair-cooper','1950-05-30',NULL,'Mossbank',NULL,'Alastair Thomas James Cooper is a Shetland Islands Councillor for the Shetland North ward, having represented the area since 2007.',NULL,NULL,NULL,'I118506','Alastair_Cooper','["Shetland Islands Councillors", "Natives of Shetland", "1950 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(8,'Alex Arthur','alex-arthur','1924-12-16','1993-07-10','Lerwick','Lerwick','Alexander David Arthur was an engineer and a Shetland Islands Councillor for Whiteness, Weisdale &amp; Tingwall between 1986 and 1993.',NULL,NULL,NULL,'I41542','Alex_Arthur','["Shetland Islands Councillors", "1924 Births", "1993 Deaths"]',1,1,195675044);
INSERT INTO "people" VALUES(9,'Alexander Bennet','alexander-bennet','1916-08-11','2003','Glasgow',NULL,'Alexander Dixon ''Sandy'' Bennet, was a PE teacher, merchant and was a County Councillor for Burra between 1959 and 1964.','Sandy was a PE teacher who later became the head of Shetland Wools at 111 Commercial Street','Abennet.JPG','Alexander Bennet Headshot.JPG','I87231','Alexander_Bennet','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Death Date", "Councillors pictured", "1916 Births", "2003 Deaths"]',0,NULL,NULL);
INSERT INTO "people" VALUES(10,'Alexander Carmichael','alexander-carmichael','1965-07-15',NULL,'Islay',NULL,'The Right Honorable Alexander Morrison ''Alistair'' Carmichael PC is a former solicitor, deputy Procurator Fiscal and the current Member of Parliament for Orkney and Shetland, having first been elected in 2001. As of the 2015 General Election, he is the only Scottish MP representing the Liberal Democrats in the House of Commons. During the Coalition Government, Carmichael became the first Orkney and Shetland MP to hold a Cabinet post, and the second to hold a Ministerial Post.','He was born on Islay, and attended Port Ellen Primary School and Islay High School. He worked between 1984–89 as a hotel manager, before beginning study at the University of Glasgow. There, he was a member of the Students'' Representative Council and President of the Liberal Club, however he left his course early. He returned to education at the University of Aberdeen, where he gained an LLB in 1992, qualifying as a solicitor in 1993. From 1993 to 1996, he was a Procurator Fiscal Depute for Edinburgh and Aberdeen, and from 1996 to 2001 he was a solicitor with Aberdeen and Macduff.',NULL,NULL,NULL,'Alexander_Carmichael','["Members of the Parliament of the United Kingdom", "Liberal Democrats"]',0,NULL,NULL);
INSERT INTO "people" VALUES(11,'Alexander Cluness','alexander-cluness','1941-05-01',NULL,'Hayfield Cottage',NULL,'Alexander Jamieson &quot;Sandy&quot; Cluness is a former Shetland Islands Councillor for Lerwick North, former Convener, Civic Head of the Shetland Islands Council and former Procurator Fiscal. Cluness has had much involvement with local politics in the past 30 years.',NULL,NULL,'Sandy Cluness Headshot.png',NULL,'Alexander_Cluness','["Conveners of the Shetland Islands Council", "Shetland Islands Councillors", "1941 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(12,'Alexander Douglas','alexander-douglas',NULL,NULL,NULL,NULL,'Sir Alexander Douglas was a Burgh and Shire Commissioner of Orkney and Shetland for the Parliament of Scotland and was also the first Member of Parliament to the newly formed Parliament of the United Kingdom. His father, [person:william-douglas:William] was a Burgh and Shire Commissioner for Orkney and Shetland in 1667.','Douglas was of Egilsay, a small Island of Orkney. He was a member of the Parliament of Scotland in 1703 and again between 1705 until the Parliament was dissolved in 1707. His first term in 1703 was declared illegitimate at the 26 June meeting of the Parliament of Scotland, and thus Sir Archibald Stewart of Burray was appointed as the legal Burgh commissioner. He was made a knight after agreeing to vote in accordance with the 11th Earl of Morton''s wishes. He was then elected (or rather, appointed) into the newly established Parliament of Great Britain, representing Orkney and Shetland from 1708 until 1713, with [person:george-douglas:George Douglas], who despite the shared name was not a close relation, taking the seat from then. He died in 1718.',NULL,NULL,NULL,'Alexander_Douglas','["Members of the Parliament of Great Britain", "Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(13,'Alexander Groundwater','alexander-groundwater','1871-04-30','1952-01-17','Scorradale','Coupar Angus, Blairgowrie','Reverend Alexander William Groundwater was a minister and a County Councillor for Walls from 1919 until his resignation in October 1921.','Alexander began life as a blacksmith. After moving to Manchester, he took up mission work and became a minister of the Congressional church there. After resigning his Manchester appointment due to ill health, he was appointed to Harray in Orkney, where he served 4 1/2 years. In 1909, he came to Shetland to take up the post in Walls which he held until 1921 when he was transferred to Couper Angus and Blairgowrie. While there, he served on their Town Council for 16 years. He was a member of the Labour Party and contested the Banff seat for them in 1924, placing third behind the Unionist and Liberal Party candidates.',NULL,NULL,'I439106','Alexander_Groundwater','["Zetland County Councillors", "Councillors - Clergymen", "1871 Births", "1952 Deaths", "Orcadians"]',1,0,NULL);
INSERT INTO "people" VALUES(14,'Alexander Hay','alexander-hay','1845-03-30','1920-02-10','Edinburgh','Lerwick','Alexander Cunningham Hay was a merchant and County Councillor, first for Northmavine East between 1890 and 1892, then again for Tingwall between 1897 and 1901.','Alexander was educated at the Edinburgh Academy between 1856 and 1860. His began his career in a London bank, before leaving the UK for three or four years. He moved to Durban in South Africa where he joined the Standard Bank of South Africa. Upon his return, he passed for the army, but after waiting more than two years to be deployed, he left for Nashville, Missouri where he kept a farm for a few years before returning to the UK again 1875. He returned to Shetland and joined the family business of Hay & Co and upon the retiral of William Irvine in 1882, Alexander became a partner in the business. By 1896, he was the managing partner in the business owing to the deaths of his uncle [person:george-hay:George] and brother [person:arthur-hay:Arthur], a post he held for a number of years until his health began to wane. He was an honorary Sheriff-Substitute of Orkney and Shetland, a Justice of the Peace and a Director of the Shetland Fishermen''s Windows'' Relief Fund. He was Vice-Consular agent for France, and Vice-Consul for Denmark, Norway and Spain and was Chamberlain for the Marquis of Zetland.','ACHay.jpeg',NULL,'I6307','Alexander_Hay','["Zetland County Councillors", "1845 Births", "1920 Deaths"]',0,1,175882926);
INSERT INTO "people" VALUES(15,'Alexander Irvine','alexander-irvine','1799-03-13','1830-03-03','Lerwick','Madeira','Alexander Cumming Irvine was a merchant and Lerwick Town Councillor between 1826 until his death in 1830.',NULL,NULL,NULL,'I4121','Alexander_Irvine','["Lerwick Town Councillors", "1799 Births", "1830 Deaths"]',1,0,163057244);
INSERT INTO "people" VALUES(16,'Alexander Manson','alexander-manson','1883-07-18','1938-07-22','Clumly, Dunrossness','Lerwick','Alexander Sinclair Manson was a shoemaker and Lerwick Town Councillor initially from 1921 until 1925, and later from 1929 until his death in 1938.','Alexander came to Lerwick as a young man to serve a shoemaking apprenticeship with John White. After this he joined the staff of Goodlad & Coutts shoemakers and worked for a number of years. In 1919, he entered into a partnership with Thomas Pottinger, trading under Manson & Pottinger in Harbour Street. In 1935, the partnership was dissolved and Alexander continued in the shop on his own account. He also held the secretary role for the Dockers section of the Transport and General Workers Union.',NULL,NULL,'I168141','Alexander_Manson','["Lerwick Town Councillors", "1883 Births", "1938 Deaths"]',1,1,259426354);
INSERT INTO "people" VALUES(17,'Alexander Mitchell (i)','alexander-mitchell-i','1827-04-28','1904-08-21','Tain','Lerwick','Alexander Mitchell was an agent for the Union Bank in Lerwick, and a Lerwick Town Councillor. His son, [person:alexander-mitchell-ii:Alexander] was the a County Councillor.','The Stirling Observer noted that Alexander was a pioneer of many of Doune''s best improvements, including founding the Gas-Light Company, the library and Volunteer movement, as well as improvements to paths in the area. He was transferred to Lerwick around 1869.',NULL,NULL,'I93131','Alexander_Mitchell_(i)','["Lerwick Town Councillors", "1827 Births", "1904 Deaths"]',0,1,179949206);
INSERT INTO "people" VALUES(18,'Alexander Mitchell (ii)','alexander-mitchell-ii','1867-07-27','1919-07-02','Doune','Lerwick','Alexander Mitchell was a solicitor and County Councillor for Sandsting between 1898 and 1904. He is the son of [person:alexander-mitchell-i:Alexander], agent for the Union bank and Lerwick Town Councillor.','Alex began his career at the Union Bank, before later joining the firm of [person:john-small:John Small], a local solicitor for about three years. He then moved to Edinburgh to join Messrs Nelson & Bell, eventually qualifying as a legal practitioner. He returned to Lerwick and in 1897 set up his own legal firm. Alex was involved in setting up the Zetland Liberal Association with [person:john-irvine-iii:John Irvine] and was the Liberal Agent in Shetland.',NULL,NULL,'I143228','Alexander_Mitchell_(ii)','["Zetland County Councillors", "1867 Births", "1919 Deaths"]',0,1,179949099);
INSERT INTO "people" VALUES(19,'Alexander Morrison','alexander-morrison','1914-09-25','1980-10-29','Lerwick','Lerwick','Alexander ''Alex'' Morrison was proprietor of a grocer/greengrocer/confectioner retail shop in Brown''s Buildings, Lerwick which traded under the name &quot;Alex Morrison&quot;, and which continues today trading as &quot;Morrisons&quot;. He was a Lerwick Town Councillor between the years from 1945 until his death in 1980, a stalwart of the Labour cause. Morrison Dock which was completed in 1981 is named after him. His father, [person:james-morrison:John] was a stonemason, builder and Lerwick Town Councillor, and his 3rd cousin [person:george-morrison:George] was a Zetland County Councillor.','Alex was a founding member of the Shetland Labour Party in 1937, and was an organiser and agent in the post-war period in every electoral contest fought by Labour in Shetland up to the 1979 General Election. His main contributions in Lerwick in the post-were periods were in Housing and Fishing.','Alex Morrison - Shetland Museum and Archives RY00051.jpg',NULL,'I63735','Alexander_Morrison','["Lerwick Town Councillors", "Shetland Islands Councillors", "1914 Births", "1980 Deaths"]',1,1,214369227);
INSERT INTO "people" VALUES(20,'Alexander Nicol','alexander-nicol','1816-12-10','1848-03-22','Lerwick','Lerwick','Alexander Nicol was a Sheriff clerk deputee (replacing his father in 1838) and a Lerwick Town Councillor.',NULL,NULL,NULL,'I122945','Alexander_Nicol','["Lerwick Town Councillors", "1817 Births", "1848 Deaths"]',1,1,175856301);
INSERT INTO "people" VALUES(21,'Alexander Ratter','alexander-ratter','1863-02-14','1943-12-18','Lerwick','Lerwick','Alexander Reid Saunders Ratter was a letterpress printer and Lerwick Town Councillor who had a lengthy period in office, starting in 1905 and finishing in 1929. He was also one of the first Shetland socialist/Labour councillors when he was elected in 1905.','Alex was the county librarian and School Attendance Officer in Lerwick.',NULL,NULL,'I116732','Alexander_Ratter','["Lerwick Town Councillors", "1863 Births", "1943 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(22,'Alexander Sandison','alexander-sandison','1827-04-08','1900-07-04','Delting','Uyeasound, Unst','Alexander Sandison was general merchant, grocer and a County Councillor for Unst South between 1890 and 1898. His sons [person:thomas-sandison:Thomas], [person:john-sandison:John] and [person:charles-gilbert-duncan-sandison-i:Charles] were also County Councillors. Alexander was a witness in the Napier Commission and his testimony can be read here.','When Alexander moved to Unst, it was an island of, according to Jessie Saxby, "extreme poverty". Nevertheless, Alexander set about trying to improve conditions for Unst residents. He was a pioneer in establishing new knitting and fishing operations in the Isle, providing many jobs for local people. His eldest daughter, Isabella, married Thomas McKinnock Wood, a descendent of Orkney who later chaired the London County Council. Politically, he was a Liberal and described as "never a mere party man, he used his influences to advance the Liberal cause." His obituary in the Shetland Times was penned by Jessie Saxby.','AlexanderSandison.png',NULL,'I11852','Alexander_Sandison','["Zetland County Councillors", "1827 Births", "1900 Deaths", "Councillors pictured", "Liberals"]',1,1,NULL);
INSERT INTO "people" VALUES(23,'Alexander Tulloch','alexander-tulloch','1904-12-16','1986-05-03','Lerwick','Lerwick','Alexander Irvine ''AI'' Tulloch was the proprietor of Tulloch''s of Shetland, a hosiery and knitwear shop in Lerwick, also owner of Linkshouse Stores in Mid Yell and a County Councillor for Sandsting between 1955 and 1974. When, in 1974 the County Council reformed as the Shetland Islands Council, Tulloch represented Aithsting And Sandsting until his death, one day before the 1986 SIC election.','Alexander had his first job while he was still at school - selling copies of a daily newsheet of war news during WWI. He then became a message boy at D & G Kay''s. Upon leaving education, he worked for the firm full time, eventually being tasked with running the company''s Mid Yell & Burravoe branches, as well as Ollaberry for a time. In the 1930''s, he went into partnership with D & G Kay''s Theo Kay. Alexander entered the knitwear industry, targeting rich buyers from England. He was invalidated out of the war, and subsequently bought out Theo Kay, with Kays of Shetland becoming Tullochs of Shetland. Alexander developed branches in Mid Yell and Burravoe. The family moved from Yell to Reawick in 1950. In the mid-50s, Alexander bought Queen''s Hotel in Lerwick He is said to have begun every morning with a swim in the sea, even in his later years.','AI Tulloch.png','AI Tulloch Headshot.png','I23565','Alexander_Tulloch','["Zetland County Councillors", "Shetland Islands Councillors", "Conveners of the Shetland Islands Council", "1904 Births", "1986 Deaths"]',1,1,179949289);
INSERT INTO "people" VALUES(24,'Alfred Stove','alfred-stove','1840-03-20','1901-10-13','Lerwick','Lerwick','Alfred Sturge Stove was a wood merchant and County Councillor who represented Gulberwick from 1890 until his death in October 1901. As a County Council election was scheduled for December of that year, his seat remained vacant until then. He was also a Lerwick Town Councillor from 1895 until his death. His brother [person:laurence-stove:Laurence] was also a Lerwick Town Councillor.','Alfred entered his fathers wood merchant business upon leaving education, and when his brother [person:laurence-stove:Laurence], returned to Shetland in 1858, the two brothers entered into business together as L. G. Stove and Co. Laurence died in 1889 but Alfred continued the business until 1895. He travelled extensively, including to Scandinavia, Western Europe, Russia and America. While in America, he met President McKinley, who was later infamously assassinated. He was associated with the Wesleyan Church.',NULL,NULL,'I123844','Alfred_Stove','["Zetland County Councillors", "Lerwick Town Councillors", "1840 Births", "1901 Deaths"]',1,1,179138460);
INSERT INTO "people" VALUES(25,'Allan Roy','allan-roy','1890-10-09','1970-09-19','Bellshill','Aboyne','Allan Roy was a land surveyor, factor to the Gardie estate, hotel proprietor and a Zetland County Councillor for Bressay from 1922 and 1929.','He ran the Towers Private Hotel in Ballater for 20 years with his sister.','Aroy.jpg',NULL,NULL,'Allan_Roy','["Zetland County Councillors", "1890 Births", "1970 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(26,'Allan Wishart','allan-wishart','1945-06-10',NULL,'Scalloway',NULL,'Allan Sinclair Wishart is a councillor for the Shetland Islands Council ward Lerwick North, having represented the area since 2007.',NULL,NULL,NULL,'I131317','Allan_Wishart','["Shetland Islands Councillors", "Natives of Shetland", "1945 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(27,'Allison Duncan','allison-duncan','1946-11-25',NULL,'Dunrossness',NULL,'Allison George Leslie ''Flea'' Duncan is a Shetland Islands Council for the Shetland South ward, representing the area since 2007.','Allison, better known to most people in Shetland as ''Da Flea'', is a crofter from Dunrossness. Until he retired he worked in the income &amp; recovery department of the SIC. Allison is a very passionate football fan, coach, and referee. On the morning the 2007 election results were announced, Duncan was one of those who couldn''t hang around for interviews with the press as he had to get home for the lambing. He is a distant relative of [person:sinclair-duncan:Sinclair Duncan] (first cousin twice removed to Sinclair''s wife) and a very distant cousin of [person:andrew-duncan:Andrew Duncan] (8th cousin twice removed to Andrew''s wife)',NULL,NULL,'I35657','Allison_Duncan','["Shetland Islands Councillors", "Natives of Shetland", "1946 Births", "Duncan", "Female"]',1,NULL,NULL);
INSERT INTO "people" VALUES(28,'Amanda Westlake','amanda-westlake','1971-04-18',NULL,'Lerwick',NULL,'Amanda Joan Westlake (nee Hawick) is a Shetland Islands Councillor for Lerwick South, a position she has held since 2012.','Amanda was born in Lerwick and attended Bell''s Brae Primary and Anderson High School. She worked in Environmental Health for 11 years before moving to Aberdeen to study at Robert Gordon University where she received a Masters Degree in International Tourism Management. She founded and ran her own business, Blyde-tae-Bide and was appointed as a project manager for Scottish Enterprise before returning to Shetland in 2010. She currently works for Voluntary Action Shetland supporting Disability Shetland, and has held posts with the Shetland Tourism Association, Lerwick Community Council and the Isleburgh Drama Group. She also served a term on the Shetland Children''s Panel. She was a member of pro-Shetland devolution pressure group Wir Shetland, but quit when the group endorsed Tavish Scott at the 2016 Scottish Parliament Election She appeared on the cooking TV program Come Dine With Me (season 6, episode 9).',NULL,NULL,'I209929','Amanda_Westlake','["Shetland Islands Councillors", "Natives of Shetland", "1971 Births", "Female"]',1,NULL,NULL);
INSERT INTO "people" VALUES(29,'Amanda Youngman','amanda-youngman','1914-01-31','2001-10-01','Greenock','Ellon','Amanda Youngman (neé Diamond) was a nurse and a County Councillor for Yell North from 1955 until 1961.','She was first married to John W. Regate in 1937 in Marylebone, London. She later married William Robert Youngman, but he died in 1959 in Lerwick aged 69. Her son, Robin, was born at the Gilbert Bain Hospital in 1945 and married Wilma Iris Ewen Ross in 1968, Aberdeen.','Ma & Queens Invitation.jpg','Amanda Youngman Headshot.png','I358018','Amanda_Youngman','["Zetland County Councillors", "Female", "1914 Births", "2001 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(30,'Andrea Manson','andrea-manson','1958-08-22',NULL,NULL,NULL,'Andrea Isobel Manson is a Shetland Islands Councillor representing the three-member Shetland North ward, along with [person:william-ratter:Drew Ratter] and [person:alastair-cooper:Alastair Cooper].',NULL,NULL,NULL,'I134632','Andrea_Manson','["Shetland Islands Councillors", "Female", "1958 Births"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(31,'Andrew Anderson','andrew-anderson','1916-05-09','1986-11-19','Lerwick','Lerwick','Andrew Irvine Anderson worked in Home Furnishings and was a Lerwick Town Councillor.','Andrew achieved the rank of Warrant Officer in the army, and once he was demobbed he returned to Lerwick to start Home Furnishings, a homeware shop, with his brother Laurence ''Lol''. He was an elder of St Ringan''s church, and the Session Clerk of the Lerwick and Bressay Parish church, a position he held until 1985. In 1974, he was the chairman of the Shetland Chamber of Commerce and helped found the Rotary Club of Shetland in 1972. He held the Presidency of that group in 1976 and 1977.',NULL,NULL,'I13835','Andrew_Anderson','["Lerwick Town Councillors", "1916 Births", "1986 Deaths"]',1,1,178584075);
INSERT INTO "people" VALUES(32,'Andrew Clark','andrew-clark','1888-10-07','1966-04-23','Yell','Aithsting','Andrew Dishington Clark was a justice of the peace and a County Councillor, representing Aithsting first between 1921 and 1922, then later 1932 to 1945.','Andrew was educated in Yell and left aged 14 to work in a shop in Camb. He later emigrated to America and sailed on the Great Lakes for some years, before returning to Britain. He continued as a merchant seaman until he joined his uncle, James Clark in the business of Clark & Company, Aith, and worked in that business for half a century.',NULL,NULL,'I71829','Andrew_Clark','["Zetland County Councillors", "1888 Births", "1966 Deaths"]',1,1,178995933);
INSERT INTO "people" VALUES(33,'Andrew Cromarty','andrew-cromarty','1934-08-12','2012-11-26','Scalloway','Brae','Andrew Peter Cromarty was a Zetland County Councillor for Northmavine North from 1964 to 1970.','Andrew was brought up at Lochend in Northmavine. He was a crofter and landowner all his life.',NULL,NULL,'I44731','Andrew_Cromarty','["Zetland County Councillors", "1934 Births", "2012 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(34,'Andrew Dick','andrew-dick','1637','1701-01-03',NULL,NULL,'Captain Andrew Dick was a member of the Parliament of Scotland for Orkney and Shetland 1678 and also the Stewart Principal of the same area in 1669, Chamberlain of Stewartry in 1675, and also took Bishopric rents in 1675-81. In 1686, he was accused of &quot;many malversations and oppressions&quot; in Orkney and banished. He moved to Shetland and bought land in Lerwick. He was accused and subsequently convicted of purchasing goods that had been stolen at sea from Philip Van Portan. Captain Dick claimed that he did not know the goods he was purchasing were stolen, but the ruling fell against him.',NULL,NULL,NULL,'I10549','Andrew_Dick','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(35,'Andrew Duncan','andrew-duncan','1776','1847-04-20','Anness, Cunningsburgh','Lerwick','Andrew Duncan was Sheriff Substitute for Shetland. Sheriff''s Closs (now Law Lane) was named after him. In 1806 he was appointed Captain Commandant of the Lerwick Volunteer Infantry, a post he held until their disbandment in 1814. At a meeting of the burgesses of Lerwick on 2 April 1818 he produced the charter, dated 10 February 1818 creating Lerwick a Burgh. In 1819 he built Prospect House on the site of an old fort or battery which commanded the southern approach to Lerwick Harbour. Also in the same year, on the instructions of The Court of Session he complied a population census of the town of Lerwick. He also used these census figures to act as advisor on the required seating capacity of Lerwick Parish Church, thus settling a dispute with the Heritors of Lerwick. Andrew married Grace Scott, daughter of Walter Scott Sheriff Substitute for Shetland 1787 - 1808, direct descendants of the Scott of Scottshall family. Their second child, and eldest son, also named [person:andrew-duncan-ii:Andrew Duncan], was a lawyer and a Lerwick Town Councillor, and represented the plaintiff in the Eunson vs. William Arthur Bruce of Symbister and the Bruce of Symbister Estate in a tenancy dispute involving several years of litigation in the late 1840''s and early 1850''s. His brother, [person:gilbert-duncan:Gilbert] and his son [person:charles-duncan:Charles] were councillors. Andrew and Grace''s fifth child, and third son, William Rae Duncan, was appointed Lerwick Postmaster in 1833 and his grandson, [person:william-duncan-ii:William] was a Zetland County Councillor. When he retired, he was succeeded by Robert Bell on 17th November, 1843.',NULL,NULL,NULL,'I10506','Andrew_Duncan','["Councillors - Missing B/D", "Councillors - Missing Birth Date", "1776 Births", "1847 Deaths", "Duncan"]',1,1,NULL);
INSERT INTO "people" VALUES(36,'Andrew Garriock','andrew-garriock','1866-07-15','1946-01-08','Lerwick','Scalloway','Andrew Baillie Garriock was a County Councillor for Northmavine North between 1919 and 1925. His father, [person:peter-garriock-i:Peter], was a Lerwick Town Councillor.','After completing his education in Shetland, Andrew went out to China under the employment of Butterfield & Squires, an importer firm. After serving them for some years, he became a partner in Garriock & Pearce importers in Hankou (now part of Wuhan). The business was successful and Andrew was able to retire in 1914. He returned to Shetland afterwards. Upon his return, he acquired the Lochend estate While in China, Andrew participated in pony racing, and won many cups.','Andrew B Garriock.jpg','A B Garriock headshot.png','I84547','Andrew_Garriock','["Zetland County Councillors", "1866 Births", "1946 Deaths"]',1,1,292691994);
INSERT INTO "people" VALUES(37,'Andrew Grierson (i)','andrew-grierson-i','1764-04-20','1835-06-30','Lerwick','Lerwick','Andrew Grierson was the fourth son, and second youngest of seven children of Andrew John Grierson and Elizabeth Kelday. He married Agnes Grant, born 1765 at Kippochie, Aberdeenshire, second eldest daughter, and second child of eight of William Grant, factor of Rippachie in the Parish of Tarland &amp; Migivie, Aberdeenshire, and Elizabeth Lumsden. Elizabeth died on 29 December 1847 at Lerwick. They produced seven descendants. *James Grierson. Born 1787. Died on December 10th 1863 at Quendale, Dunrossness.
*Andrew John Grierson, Born Mar 13th 1787. Died in America about 1830.
*Creighton Grierson. Born August 26th 1790. Lieutenant General, Royal Engineers, British Army. Died at Liverpool England in November 1871
*Alexander Grierson. Born after 1790. Officer in the Royal Navy. Died in Liverpool, England.
*Mitchell Grierson. Born Aug 26th 1791.
*Maxwell Grierson. Born May 1st 1812. Twin with Agnes Grierson (below).
*Agnes Grierson. Born May 1st 1812. Twin with Maxwell Grierson (above). Upon the death of their father Andrew John Grierson, the first Laird of the Grierson of Quendale family estate, at sea in March 1766, James, the elder brother of Andrew, at about six years of age, became successor to Andrew John Grierson, and served as his heir on September 24th 1767 becoming the second Laird of the Grierson of Quendale family estate. Almost nothing further is recorded concerning the life of James, and he appears to also have died at a relatively young age. Andrew succeeded him and served as his heir on March 17th 1807, becoming the third Laird of the Grierson of Quendale family esate. Andrew further served as heir to his great-grandfather, Andrew Greig, on November 11th 1825, acquiring extensive lands in the parish of Aithsting. Andrew was elected in 1818 to the first Lerwick Town Council. Upon Andrew''s death on 30 June 1835, he was succeeded by his eldest son James who became the fourth laird of the Grierson of Quendale family estate.',NULL,NULL,NULL,'I18032','Andrew_Grierson_(i)','["Lerwick Town Councillors", "1764 Births", "1835 Deaths", "Grierson"]',1,1,NULL);
INSERT INTO "people" VALUES(38,'Andrew Grierson (ii)','andrew-grierson-ii','1832-08-30','1896-04-12','Quendale','Quendale House, Lerwick','Andrew John Grierson was a laird and Lerwick Town Councillor. Andrew was the eldest son, and eldest of four children of James Grierson of Quendale and Elizabeth Sinclair Craigie. He died on April 12th 1896 at Quendale House, Lerwick. In 1860 he married Alice Geraldine Clifford, born June 9th 1837 in Sligo, Ireland. Died August 17th 1917. The daughter of Herbert John Clifford, of Sligo, Ireland. Born before 1815. They produced six descendants. *Lucy Margaret Grierson. Born August 26th 1861 at Lerwick. Died May 26th 1911.
*[person:james-grierson:James Cullen Grierson]. Born August 7th 1863 at Lerwick. Died July 3rd 1915.
*Herbert John Clifford Grierson, Born January 16th 1866 at Quendale House, Lerwick. Died February 22nd 1960.
*Elizabeth Mitchell Sinclair Grierson. Born March 21st 1868 at Lerwick. Died June 16th 1945 in Lerwick. On July 3rd 1897 she married, in Lerwick, William Arthur Bruce, born September 23rd 1863. A descendant of the Bruce of Symbister and the Bruce of Sumburgh families.
*Andrew Grierson. Born April 11th 1870 in Lerwick. Died July 10th 1891 at Portland, Oregon, U.S.A.
*Bernard Grant Grierson. Born 1875 in Lerwick. Upon the death of his father James, the fourth Laird of the Grierson of Quendale family estate, on December 10th 1863, Andrew became his successor and the fifth Laird of the Grierson of Quendale family estate. Upon Andrew''s death on April 12th 1896 he was succeeded by his eldest son [person:james-grierson:James Cullen Grierson] who became the sixth and final laird of the Grierson of Quendale family estate.','Andrew, like his predecessors and equals held a position of some power and influence over a wide section of Shetland society, and it could be said he was possibly the most active of the Greirson lairds in wielding it. In 1862 he is noted as being the Chairman of the opening ceremony of the Anderson Educational Institute. Almost immediately after succeeding to the lairdship of the Grierson of Quendale family estate, in 1864/1865 he built the large mansion Quendale House in what was then Craigie Court on South Commercial Street as a family home, replacing the previous Grierson family town house at the Commercial Street end of Quendale Lane. Around ten years later he was to view sheep farming as a more valuable enterprise for the lands on the Grierson of Quendale family estate at Quendale than renting it as crofts to his tenants, and on his orders the six families who were tenants of the township of Garth and a further twenty one families from neighbouring townships were evicted in 1874. The methods used by Andrew to achieve these evictions are considered, by some, as questionable. In 1858, he started a fishcuring business with [person:john-bruce:John Bruce] which existed for several years before dissolution. He was also a Trustee of the Heritors and Feuars for 32 years. Initially a Liberal, he became a Conservative in his older age. In 1878 he was appointed a Deputy Lieutenant of Zetland.',NULL,NULL,'I18029','Andrew_Grierson_(ii)','["Lerwick Town Councillors", "1832 Births", "1896 Deaths"]',1,1,181925156);
INSERT INTO "people" VALUES(39,'Andrew Halcrow','andrew-halcrow','1877-10-08','1955-01-25','Walls','Lerwick','Andrew Fraser Halcrow was a County Councillor for Walls.','When Andrew left school aged 13, he first worked on the roads, and later he went to sea on a smack at the Faroe fishing. In the 1890''s, he went to Liverpool with the intention of joining the Merchant Navy, but instead enlisted in the Royal Marine Artillery and served there for 25 years, finishing there as colour sergeant. After a long career at sea, he returned to the UK in a office based role, which he held throughout WWI. After the war, he joined the coastguard in Lossiemouth. He was eventually transferred back to Lerwick in 1923. In 1927, he transferred to Customs, as a coast preventative officer, a position he held until 1942. Latterly, he was an enforcement officer and warehouse inspector for the Ministry of Food.',NULL,NULL,'I42651','Andrew_Halcrow','["Zetland County Councillors", "1877 Births", "1955 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(40,'Andrew Hughson','andrew-hughson','1953-09-05',NULL,'West Sandwick',NULL,'Andrew James Hughson is a former Shetland Islands Councillor for the Shetland Central ward from 2007 to 2012.',NULL,NULL,NULL,NULL,'Andrew_Hughson','["Shetland Islands Councillors", "Natives of Shetland", "1953 Deaths"]',1,NULL,NULL);
INSERT INTO "people" VALUES(41,'Andrew Irvine (i)','andrew-irvine-i','1902','1989-02-10','Uyeasound, Unst','Yell','Andrew John ''Andy'' Irvine was a County Councillor for Unst South between 1938 and 1945.',NULL,NULL,NULL,'I48205','Andrew_Irvine_(i)','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1902 Births", "1989 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(42,'Andrew Irvine (ii)','andrew-irvine-ii','1922-05-02','2002-12-21','Tingwall','Lerwick','Andrew Bruce Irvine was a County Councillor for Tingwall between 1964 and 1973, and when the County Council reformed as the Shetland Islands Council, he represented Scalloway between 1974 until 1978.',NULL,NULL,NULL,'I53751','Andrew_Irvine_(ii)','["Zetland County Councillors", "Shetland Islands Councillors", "1922 Births", "2002 Deaths", "Biography Missing"]',1,1,284528731);
INSERT INTO "people" VALUES(43,'Andrew Jamieson','andrew-jamieson','1835-12-24','1925-03-07','Lerwick','Lerwick','Andrew Borrowman Jamieson was a shipping merchant and Lerwick Town Councillor between the years of 1874 and 1889.','Andrew left education aged 18 and joined the business of merchant and fishcurer [person:joseph-leask:Joseph Leask], in 1852. Andrew initially was exposed to the whaling trade as Leask was the local agent for whaling vessels. When that industry began to decline, cod fishing grew in importance and Andrew found himself as a Senior Clerk at Leask''s, helping crews fit out their Faroe Smacks (boats). After the Faroe cod fishing industry collapsed, Leask''s business moved away from fishing, just as the herring-curing industry was taking over the isles. After Leask''s death in 1882, Andrew left the firm and became the Agent for the North of Scotland Steam Navigation Company in Scalloway, where they had recently opened a port of call for mail steamers. In later years, he came back to Lerwick as a clerk in the same company''s office, where he worked until his health prevented him from working further. Before the opening of the Anderson Educational Institute, he taught Subscription Classes (private, paid), in the Auld Kirk.','AndrewJamieson.png',NULL,'I92383','Andrew_Jamieson','["Lerwick Town Councillors", "1835 Births", "1925 Deaths", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(44,'Andrew Mouat','andrew-mouat','1888-07-26','1959-06-24','Yell','Lerwick','Andrew Marshall Mouat was a car hirer and Lerwick Town Councillor.','Andrew was in the car hiring business.',NULL,NULL,'I136850','Andrew_Mouat','["Lerwick Town Councillors", "1888 Births", "1959 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(45,'Andrew Nicolson','andrew-nicolson','1891-07-31','1967-07-07','Noss Sound',NULL,'Andrew John Nicolson was a Post Office Clerk, Telegraphist and Lerwick Town Councillor.','He was a Labour man who was active within the party, and his style of politics was of a quiet, genial nature. He was the Provost between 1965 and 1967. Nicolson himself would often recall how as a member of the Post Office, he and some colleagues were jailed during the First World War, accused of theft of documents - these allegations were false, however.','Andrew Nicolson Provost.png','Andrew Nicolson Headshot.png','I171828','Andrew_Nicolson','["Lerwick Town Council Provosts", "Lerwick Town Councillors", "1891 Births", "1967 Deaths", "Councillors pictured"]',1,NULL,284536335);
INSERT INTO "people" VALUES(46,'Andrew Peterson','andrew-peterson','1918-12-19','2004-09-16','Lerwick','on board the M.V. Hrossey','Andrew William ''Willie'' Peterson was a plumber and County Councillor for Yell North between 1961 and 1962, then Delting North from 1963 to 1964.','Willie died on the Northlink''s passenger vessel, the MV Hrossey. He was was returning from the Forres Bible Readings. He had been a member of the kirk throughout Scotland for over 60 years. He was in the fellowship of the Sound Gospel Hall.',NULL,NULL,'I17666','Andrew_Peterson','["Zetland County Councillors", "1918 Births", "2004 Deaths"]',1,NULL,NULL);
INSERT INTO "people" VALUES(47,'Andrew Riddell','andrew-riddell','1917-01-20','1978-11-14','Glasgow','Lerwick','Reverend Andrew Gordon Riddell was a Church of Scotland minister and County Councillor for Nesting between 1973 and 1975.','Was ordained to Nesting and Lunnasting on 12 July 1968, and transferred to Walls on 2 March 1977, where he died the following year.',NULL,NULL,'I256899','Andrew_Riddell','["Zetland County Councillors", "Councillors - Clergymen", "1917 Births", "1978 Deaths"]',0,1,290831437);
INSERT INTO "people" VALUES(48,'Andrew Robertson','andrew-robertson','1857-09-21','1922-01-26','Toft','Edinburgh','Andrew Robertson was a wine/spirit merchant and a County Councillor for Northmavine North from 1897 until 1903.','Andrew had a shop in Lerwick named Turk''s Head in Market Street (previously known as Market Refreshment Rooms) and was for some time the proprietor of Sandwater Hotel in Weisdale. He began business in Lerwick around 1886, prior to which he was the an assistant to Peter Tulloch in his business. He acquired that business from the latter''s trustees after Tulloch''s death. In 1903, Andrew was declared bankrupt and as a result lost his seat on the County Council.','AndrewRobertson.jpeg',NULL,'I94343','Andrew_Robertson','["Zetland County Councillors", "1857 Births", "1922 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(49,'Andrew Smith','andrew-smith','1842-02-04','1917-12-01','Isleburgh','Lerwick','Andrew Smith was a commission agent, grocer, spirit merchant, shipbroker and Lerwick Town Councillor. Andrew was the father of seven children, four of whom had lengthy lives: Arthur and Agnes died aged 87, Alfred aged 93 and Elizabeth aged 104.',NULL,NULL,NULL,'I70270','Andrew_Smith','["Lerwick Town Councillors", "1842 Births", "1917 Deaths"]',1,1,259417274);
INSERT INTO "people" VALUES(50,'Andrew Tait','andrew-tait','1930-11-14','1992-10-02','Brae','Lerwick','Andrew James Rogers ''Jim'' Tait was a headmaster and a Lerwick Town Councillor between 1970 and 1972.','Jim went to Primary school in Brae before attending the Anderson Educational Institute. He graduated Edinburgh University with an MA and spent a year training as a teacher as the Moray House School of Education and Sport. He returned to Shetland and taught at the Anderson, Aith, Scalloway and Bells Brae before he was appointed headmaster of Sound School in 1977. In 1985, he became a fellow of the Educational Institute of Scotland. After returning as a teacher, Jim worked for with Shetladn Salmon Producers in Selivoe. He was a founding member of the Shetland Movement, and a co-editor of The Shetland Folk Book with [person:john-graham:John Graham].',NULL,NULL,'I98212','Andrew_Tait','["Lerwick Town Councillors", "1930 Births", "1992 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(51,'Andrew Tulloch','andrew-tulloch','1936-01-11','2021-02-20','Heylor','Lerwick','Andrew Thomas Hawick Tulloch was the owner of Hughson Brothers wholesalers and was a County Councillor for Delting North between 1964 and 1970. His father [person:john-tulloch-i:John] was also a councillor. He was Guizer Jarl for the 1969 Lerwick Up Helly-Aa.',NULL,NULL,NULL,'I126009','Andrew_Tulloch','["Zetland County Councillors", "1936 Births", "2021 Deaths", "Biography Missing"]',1,1,NULL);
INSERT INTO "people" VALUES(52,'Andrew Williamson','andrew-williamson','1925-02-13','2014-11-26','Yell','Lerwick','Andrew William Williamson was the Curator of the Lerwick Museum and a former Shetland Islands Councillor for Yell North and Fetlar between 1990 and 1994.',NULL,NULL,NULL,'I379','Andrew_Williamson','["Shetland Islands Councillors", "Natives of Shetland", "1925 Births", "2014 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(53,'Angus Gunn','angus-gunn','1871-09-24','1940-02-24','Delting','6 St. Magnus Street, Lerwick','Captain Angus Gunn was a merchant seaman and County Councillor, representing Cunningsburgh from 1938 until his death in 1940.','Angus''s family moved to Shetland when his father took over a sheep farm. While still a boy, the family then relocated to Cunningsburgh to take over the farm of the late [person:john-bruce:John Bruce]. He attended the Cunningsburgh Parish School and after completing his studies held the role of acting pupil teacher there. At the age of 16, he entered the counting house of [person:joseph-leask:Joseph Leask] & Sons, shipowners, fishcurers etc in Lerwick where he apprenticed as an accountant and clerk. However, like for many young men in Shetland, the call of the sea was strong and he eventually moved south to pursue a career on the water. He worked for some years in Nova Scotia and when he returned to the UK, he set up his base in South Shields and later Hull, where he pursued a Master''s Certificate. For 47 years, he worked at sea, only retiring in 1937. He worked with three companies: Stag Line of North Shields, Messrs Williams & Co in Cardiff and latterly with the Pool Steam Shipping Co managed by Messrs Ropner & Co, West Hartlepool. He was appointed as secretary of the Lerwick Lifeboat Committee in 1937.',NULL,NULL,'I168396','Angus_Gunn','["Zetland County Councillors", "1871 Births", "1940 Deaths"]',1,1,179137815);
INSERT INTO "people" VALUES(54,'Anthony Anderson','anthony-anderson','1906-02-06','1976-08-01','Laxfirth','Weisdale','Anthony ''Tony'' Anderson was a farmer and County Councillor between 1945 and 1970.','Tony was the son of shepherd in Gremista and first learned his trade on the family farm. His first job elsewhere was as a butcher, and he eventually combined farming and butchery to great success. When still a young man, he took over the farm at Stenswell, Weisdale and later expanded his interests into Orkney, as well as other parts of Shetland. There was not much of the Shetland agricultural industry in which Tony was not involved. He was associated with the Shetland Marts at its founding, was previously the branch-president of the Shetland National Farmers Union, was a stock dealer and a supporter of the local wool trade.','AnthonyAnderson.png',NULL,'I27977','Anthony_Anderson','["Zetland County Councillors", "1906 Births", "1976 Deaths"]',1,1,178837136);
INSERT INTO "people" VALUES(55,'Archibald Garriock','archibald-garriock','1828-11-22','1899-02-28','Reawick','Lerwick','Archibald John Garriock was an accountant, Lerwick Town Councillor and a County Councillor.','Archibald attended a parochial school in Sandsting as a boy, and completed his education in Lerwick. He returned to Reawick, but struggled to find joy in country living and subsequently left Shetland, moving to Glasgow where he took up working in a mercantile office as a clerk. He then moved to London for some time, where he found himself drawn to the prospects in Australia, which was experiencing something of a boom period. Archibald travelled to Melbourne and began prospecting, and would visit many parts of the country in search for gold, but his digging was unsuccessful and he returned to Melbourne. He then moved to Sydney where he became a financial editor to a local daily newspaper. In 1874, he moved back to Shetland and Reawick. In 1876, he returned to Lerwick and worked for the Caledonian and North Western Railway, arranging for Shetland fish to be distributed on their lines after it was landed in Aberdeen. He would later add auctioneering to his repertoire and had much success in this field. In the fish business, he was a pioneer of the "days" price for herring, and popular among local fishermen. He was the honorary secretary of the Shetland Agricultural Society. He taught young boys to swim and successfully convinced the County Council to fund a teacher to visit different parts of Shetland to teach swimming. In politics, he was a staunch Liberal. His nephew, [person:lewis-garriock:Lewis], was a Zetland County Councillor for Tingwall while his uncle [person:james-greig:James Greig] and cousin [person:archibald-greig:Archibald Greig] were Lerwick Town Councillors.',NULL,NULL,'I68315','Archibald_Garriock','["Zetland County Councillors", "Lerwick Town Councillors", "1828 Births", "1899 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(56,'Archibald Greig','archibald-greig','1818-02-12','1852-10-11','Lerwick','Lerwick','Archibald Greig was a Town Councillor and Procurator Fiscal for Shetland. His father [person:james-greig:James] was also a councillor from 1818 until 1820, then 1823 and 1835.',NULL,NULL,NULL,'I18009','Archibald_Greig','["Lerwick Town Councillors", "1818 Births", "1852 Deaths"]',1,1,163057227);
INSERT INTO "people" VALUES(57,'Archibald MacIntyre','archibald-macintyre','1870-03-11','1952-11-23','Kirkintilloch','Aberdeen','Reverend Archibald MacIntyre was a Church of Scotland minister in Lerwick at St. Columba''s and a County Councillor for Bressay between 1929 and 1933.','After graduating Glasgow University, he was appointed to St Fittick''s in Torry, Aberdeen around 1900. He then moved to Shetland and served the Church of Scotland in Tingwall, Whiteness and Weisdale from 30 April 1908 until he was transferred to Lerwick on 15 May 1918. He served at St Columbus until he retired on 16 May 1933.',NULL,NULL,NULL,'Archibald_MacIntyre','["Zetland County Councillors", "Councillors - Clergymen", "1870 Births", "1952 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(58,'Archibald Stewart','archibald-stewart',NULL,'1704',NULL,NULL,'Sir Archibald Stewart of Burray was a Burgh and Shire Commissioner for Orkney and Shetland to the Parliament of Scotland between 1703 and 1705 (or 1707).',NULL,NULL,NULL,NULL,'Archibald_Stewart','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(59,'Arthur Anderson','arthur-anderson','1792-02-19','1868-02-27','Böd of Gremista','London','Arthur Anderson was a businessman and Liberal Member of Parliament for Orkney and Shetland. He was the first Shetland-born man to represent the Isles. In 1808, at the age of 16, he joined the Royal Navy. He was released from the Navy after 10 years, and was employed as a clerk in Brodie McGhie Willcox''s shipping company. He became a partner in the company in 1822, and later they formed the &quot;Peninsula Steam Navigation Company&quot;, which later became the &quot;Peninsular and Oriental Steam Navigation Company&quot;. Despite living most of his life in London, he never forgot the islands where he was born. In 1836 he founded Shetland''s first newspaper, the Shetland Journal. He both financed, edited and partly wrote the newspaper himself. In 1837 he founded the Shetland Fishery Company at the island of Vaila. It was an attempt to break the monopoly of the Lairds He served as a radical Liberal Member of Parliament for the Orkney and Shetland from 1847 to 1852. He was elected as the first MP for Orkney and Shetland not from the landowning class. He a founded a school in Out Skerries in 1852, and provided the funds for the building of (and later endowed) the Anderson Educational Institute which was opened in November 1862, now the Anderson High School, &quot;providing a school such that from it the youth of Shetland could proceed to any University&quot;. He also provided funds for the building of Widows Homes in Lerwick, in memory of his wife. Anderson was a close friend of James Scott R.N., who acted as his political agent. John Nicolson wrote an early biography. He died in London on 27 February 1868 and is buried at West Norwood Cemetery.',NULL,'Arthur anderson2.jpg',NULL,'I8236','Arthur_Anderson','["Members of the Parliament of the United Kingdom", "Liberals", "Natives of Shetland"]',1,0,163057282);
INSERT INTO "people" VALUES(60,'Arthur Buchanan','arthur-buchanan',NULL,NULL,NULL,NULL,'Arthur Buchanan of Sound (d. between 1677 and 1681) was a landowner and member of the Parliament of Scotland in 1667 for Orkney and Shetland. He was a supporter of uniting the Scottish and English Parliament, and owned land throughout the West Mainland of Orkney, as well as Shapinsay, most of Stronsay and North Ronaldsay. In 1677, he was the "largest ratepayer" in Kirkwall (£14 14 shillings). He was married to Margaret Buxtoun.',NULL,NULL,NULL,NULL,'Arthur_Buchanan','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(61,'Arthur Edmondston','arthur-edmondston','1775-11-10','1841-02-17','Lerwick','Lerwick','Arthur Edmondston, doctor, Lerwick Town Councillor and author of A View of the Ancient and Present State of the Zetland Islands (2 vols., 1809), two treatises on opthalmia, and other works. He was born on the 10th of November, 1775, the eldest son of Laurence Edmondston, merchant in Fetlar, and Mary Sanderson of Buness House, Unst. Edmondston studied medicine in Edinburgh, becoming a Fellow of the Royal College of Surgeons. He then served as an army surgeon in Egypt under Sir Ralph Abercromby, and subsequently settled in Lerwick, where he was a well-known and notoriously litigous figure. He was the uncle of Thomas Edmondston and Jessie M. E. Saxby. Arthur Edmondston also published Observations on the nature and extent of the cod fishery carried on off the coasts of the Zetland and Orkney Islands, Edinburgh, 1820. He died on 17 February 1841 in Lerwick. Arthur''s brother, Laurence, had a great-grandson, also called [person:laurence-edmondston:Laurence], who represented Unst in the Zetland County Council.',NULL,'Arthur Edmondston.png','A Edmondston headshot.png','I10638','Arthur_Edmondston','["Lerwick Town Councillors", "Natives of Shetland", "1775 Births", "1841 Deaths", "Council Leaders", "Senior Bailies", "Doctors", "Writers", "Edmondston", "Councillors pictured"]',1,1,175626382);
INSERT INTO "people" VALUES(62,'Arthur Hay','arthur-hay','1835-08-05','1896-12-25','Lerwick','Lerwick','Arthur James Hay was a Chamberlain for the Lordship of Zetland, a shipping merchant, a Lerwick Town Councillor and a County Councillor His father [person:william-hay:William] and brother [person:george-hay:George] were also Lerwick Town Councillors. He withdrew from consideration from the Whiteness and Weisdale seat at the inaugural Zetland County Council election in 1890, but was elected to the Tingwall seat anyway.','Arthur was educated at an academy in Montrose and returned to Lerwick upon completing his education to work for his family''s firm, Hay & Co, subsequently becoming a partner in the firm. Following the death of his brother, [person:george-hay:George], he assumed management of the business as the senior partner. During his tenure at the family firm, it was one of the largest employers in Shetland & was the sole largest shipowner. As Chamberlain of the Lordship of Zetland, he engaged with tenants on his lands. The Shetland Times paints him as being on the side of the poor, saying "Not a few of the tenants on [Lord Zetland''s] estate, as well as on the estate of Hayfield will sorry at his death, for in him the poor and needy, the widow and orphan ever found a sympathetic and generous friend. This claim is dubious, since Hay had testified against crofters in the 1883 Crofters Commission. He held a long list of public positions including Deputy Lieutenant for the County, a Commissioner of Income Tax, Honorary Sheriff-substitute, a Justice of the Peace, a Commissioner of Supply, Vice-Convener of the Zetland County Council and a member of other boards and committees. In politics, Arthur was an ardent Liberal during the [person:frederick-dundas:Dundas] campaigns. On the introduction of the Home Rule Bill, however, he did not support Gladstone and then became a Unionist.',NULL,NULL,'I6291','Arthur_Hay','["Lerwick Town Councillors", "Zetland County Councillors", "1835 Births", "1896 Deaths"]',1,1,290621113);
INSERT INTO "people" VALUES(63,'Arthur Irvine (i)','arthur-irvine-i','1900-03-18','1975-11-27','Hillswick','Lerwick','Arthur Irvine was a general merchant and a County Councillor for Northmavine South between 1927 and 1945.',NULL,NULL,NULL,'I115628','Arthur_Irvine_(i)','["Zetland County Councillors", "1900 Births", "1975 Deaths", "Biography Missing"]',1,1,197377343);
INSERT INTO "people" VALUES(64,'Arthur Irvine (ii)','arthur-irvine-ii','1905-11-24','1995-04-25','Yell','Whalsay','Arthur Irvine was a teacher and County Councillor for Gulberwick between 1970 and 1975.',NULL,NULL,NULL,'I163365','Arthur_Irvine_(ii)','["Zetland County Councillors", "1905 Births", "1995 Deaths", "Biography Missing"]',1,1,255726431);
INSERT INTO "people" VALUES(65,'Arthur Johnson','arthur-johnson','1888-09-07','1978-10-12','Weathersta','Lerwick','Arthur ''Ertie'' Johnson was a draper at 109 Commercial Street, (currently Millers Opticians) a Lerwick Town Councillor sporadically between 1941 and 1967 and a County Councillor between 1967 and 1970. Much of his appointments to the Lerwick Town Council were through by-elections. He was the convener of the Finance Committee, 1 July 1947 and Dean of Guild on 9 May 1952 Initially, he was elected in 1941, and was a councillor until 1945. He was then elected soon after via a by-election in the same year and lasted until 1949. Once again, he was by-elected into the council in the same year and represented until 1955. For the third time in a row, he was elected once again soon after the 1955 election, and was in the council until 1958 when he failed to get elected. Following a resignation in the council he was once again co-opted into the council in 1958 and represented until 1961. His final stint, and his most stable, was between 1962 and 1967. Following his on-and-off Town Council experience, he spent his final 3 years in public life as a County Councillor for Fetlar (1967-1970). In his later years, he stayed in the St. Magnus rectory, although not through having a religious background.','Arthur ran a draper business in Lerwick and was a staunch supporter of the Labour Party. In his many candidatures in local government, he stood under the Socialist banner. In 1953, when MP for Caithness Sir David Robertson proposed that Lerwick should be scheduled as a development area, the Scottish Secretary James Stuart concluded that he would not approved such an area. Arthur responded by suggesting that Shetland become a territory of the USA "I am sure the United States of America would be very grateful to get the Shetland Islands as a static aircraft carrier"
- Arthur, January 1953','Ajohnson.JPG','A Johnson headshot.png','I180461','Arthur_Johnson','["Lerwick Town Councillors", "Zetland County Councillors", "Councillors pictured", "1888 Births", "1978 Deaths"]',1,1,179138451);
INSERT INTO "people" VALUES(66,'Arthur Laing','arthur-laing','1858-05-22','1942-02-19','Gulberwick','Lerwick','Arthur Laurenson Laing was a pharmacist and founder of A. L. Laing, a chemist which still exists in Shetland. He was a County Councillor for Lerwick South between 1901 and 1910, while also serving as a Lerwick Town Councillor from 1888 to 1913, spending the last 3 years as Provost.','Laing first began his career as a pharmacist in February 1873. Upon completing his apprenticeship he moved to Edinburgh and became a junior assistant in George Street, late moving to Greenwich, Sandwich and London. He moved to Hove as a dispensing chemist, and from there he moved to Buxton then Edinburgh and Berwickshire. When in 1886 101 Commercial Street became vacant, Laing sold up his business in Berwickshire and moved up, opening on 6 March of that same year. He opened another shop in Commercial Street in 1905, following the success of his business. In the Council, he was a Baillie and held this position from 1904 until he became provost in 1910. He was appointed Justice of the Peace in 1910. He also was enthusiastic in the Volunteers, joining the 1st Zetland Rifle Volunteer Corps. When the 7th Volunteer Battalion Gordon Highlanders formed in 1901, he was one of the first to join and hold the rank of Sergeant in this unit, and when this later became the Shetland Companies Gordon Highlanders, Laing held the position of Lieutenant. As a young man he joined the Independent Order of Rechabites and was the secretary for St Columba''s Tent in Lerwick, and performed the same role in the Zetland District. He was a Church of Scotland member and was appointed an elder in 1902 for St. Columba''s Church.','A L Laing Provost.png','A L Laing Headshot.png','I29884','Arthur_Laing','["Lerwick Town Council Provosts", "Lerwick Town Councillors", "Zetland County Councillors", "1858 Births", "1942 Deaths", "Councillors pictured"]',1,1,289887228);
INSERT INTO "people" VALUES(67,'Arthur Laurenson','arthur-laurenson','1832-11-04','1890-11-14','Lerwick','Leog House, Lerwick','Arthur Laurenson was an antiquarian, author and politician.','Arthur was the oldest of two children born to [person:laurence-laurenson-i:Laurence Laurenson] (1799-1867) and his wife Catherine Hoseason Gray, (b. 28 September 1794, Cliff, Unst). His father had established a drapery and hosiery business in Lerwick in 1818, Laurenson &amp; Co., in which Arthur would himself work. In the 1851 census, the family are recorded at 1 Hill lane, Lerwick. Arthur was a pupil of the Moravian teacher John Glass at the Lerwick Subscription School. He subsequently travelled in Norway and Sweden to pursue his interest in the literature and language of Scandinavia, evidenced in his study ''The Colour-Sense in the Edda''. His father died in 1867, after which Arthur took over the management of the family business. Politically, Laurenson was a Liberal and a long-term member of Lerwick Town Council, as well as the Zetland County Council (briefly). With John Gatherer he founded the Shetland Literary and Scientific Society, afterwards serving as secretary, and he was a friend of Gilbert Goudie. He was given the responsibility for the decoration of the new Lerwick Town Hall, designing the stained glass windows and roof shields, as well as the Zetland County Seal. Arthur Laurenson never married. Latterly, he lived in Leog House, Lerwick, where he died on the 14th of November, 1890. Although he died a few years before Jakob Jakobsen the Faeroese philologist arrived in Shetland, nonetheless his work was one Jakobsen''s sources, and his study, written in Danish Om sproget paa Shetlandsoerne (on the language of the Shetland islands), was later translated by [person:john-nicolson:John Nicolson], and published by Johnson and Greig as The Shetland Dialect. A memorial shield in the Town Hall bears the following inscription: In memory of the services he [Laurenson] rendered his birthplace by employing his many intellectual gifts in furtherance of every good, noble and patriotic enterprise, his high accomplishment as an exponent of Scandinavian literature, his rare taste and love for everything beautiful and seemly and that modest nature that made him loved and honoured not only in his native country but in many distant lands - Friends erected this tablet, 1892. His letters and papers were edited by Catherine Spence and published by T Fisher Unwin of London in 1901 as Arthur Laurenson: his letters and literary remains: a selection with an introductory memoir. Other works by Arthur Laurenson include On Certain Beliefs and phrases of Shetland Fishermen, Two Norse Lays, The Franco-German War, and Diplomatarium Hialtlandense. His death caused the Lerwick South by-election in 1891. His nephew [person:william-tulloch:William Tulloch] was also a councillor.','Arthur Laurenson - Shetland Museum and Archives X00041.jpg',NULL,'I13170','Arthur_Laurenson','["Lerwick Town Councillors", "Zetland County Councillors", "1832 Births", "1890 Deaths"]',1,1,163057239);
INSERT INTO "people" VALUES(68,'Arthur Nicolson (i)','arthur-nicolson-i','1842-11-06','1917-05-27','Adelaide','Fetlar','Sir Arthur Thomas Bennet Robert Nicolson was a landlord and County Councillor who represented Fetlar from 1895 to 1901 and again from 1902 to 1917. He was the father of [person:arthur-nicolson-ii:Arthur].','He was President of the Shetland Agricultural Society, and frequently attended shows in Lerwick to judge horses and ponies.','Arthur TB Nicolson.jpg','A T B Nicolson headshot.png','I21709','Arthur_Nicolson_(i)','["Zetland County Councillors", "1842 Births", "1917 Deaths", "Incomers to Shetland", "Councillors pictured"]',0,1,175881252);
INSERT INTO "people" VALUES(69,'Arthur Nicolson (ii)','arthur-nicolson-ii','1882-06-08','1952-04-25','Melbourne','Delting','Sir Arthur John Frederick William Nicolson was born 11th Baronet of that Ilk and Lasswade, 1629, of Brough Lodge, Fetlar, Shetland.','He was born in Melbourne, Victoria, Australia to [person:arthur-nicolson-i:Arthur] of Adelaide, SA, Australia, 10th. Baronet and Annie Rutherford, Buninyong, Victoria, Australia, (died 1936), daughter of the late John Rutherford, Bruntsfield Place, Edinburgh; born 8 June 1882. He succeeded his father in 1917. He was educated at Merchiston Castle School in Edinburgh and studied law at Edinburgh University (M.A. LL.B.). He received the O.B.E. in December 1944. He served as Lord Lieutenant for Shetland 1948-52, and as a Justice of the Peace. He was a Lieutenant in the R.N.V.R. during World War 1 and served in World War 2 as Lt. Col. commanding the 1st Zetland Battalion Home Guard. The family roots can be traced back to James Nicolson (1530-1580), writer and burgess of Edinburgh, clerk to the Collector of Thirds. Nicolson was also a County Councillor for Fetlar between 1917 and 1932.','Sanicolsonjr.jpg',NULL,'I21711','Arthur_Nicolson_(ii)','["Zetland County Councillors", "1882 Births", "1952 Deaths"]',0,1,NULL);
INSERT INTO "people" VALUES(70,'Arthur Porteous','arthur-porteous','1857-05-17','1935-07-07','Stromness','Gladsmuir, East Lothian','Arthur Alexander Porteous was a chemist with premises in Union Bank and he was also a Lerwick Town Councillor from 1887 to 1910','Arthur served as an apprentice chemist in Orkney after passing his exams, and became a Member of the Pharmaceutical Society. After working on the Scottish mainland for some time, he came to Lerwick in December 1879 and opened his own shop a chemist. He continued to operate the same business until he retired in 1932. He was an advocate for education in the isles. Not long after arriving in Shetland, he joined the Lerwick School Board, including holding the role of Chair of that organisation during the 1902 opening of the Lerwick Central School.','Arthur Porteous Provost.png','Arthur Porteous Headshot.png','I93859','Arthur_Porteous','["Lerwick Town Councillors", "1857 Births", "1935 Deaths", "Councillors pictured", "Orcadians"]',0,0,NULL);
INSERT INTO "people" VALUES(71,'Arthur White','arthur-white','1874-08-02','1940-12-21','Innhouse','Laxobigging, Delting','Arthur White was a factor to the Busta estate and a County Councillor first for Northmavine South from 1904 until 1907, then Delting South from 1913 to 1919.','After leaving school, Arthur worked with Thomas Gifford of Busta. Upon Gifford''s death in 1899, Arthur took over as factor on the Busta estate and held that position until his death. During WWI, Arthur was responsible for organising the Home Guard at Brae and was a registrar in the same area.','Awhite.jpg',NULL,'I134528','Arthur_White','["Zetland County Councillors", "1874 Births", "1940 Deaths"]',1,1,179138215);
INSERT INTO "people" VALUES(72,'Arthur Williamson','arthur-williamson',NULL,NULL,NULL,NULL,'Arthur Williamson is a former Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'Arthur_Williamson','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(73,'Balfour Spence','balfour-spence','1777-03-17','1843-10-01','Unst','Lerwick','Balfour Spence was a Shipping Agent, Merchant and Lerwick Town Councillor.','Bayanne genealogy page notes that Spence was involved in the trading of illegal goods on top of his legal activities and indicates that he was a 4th Great-Grandfather of Shetland Archivist, Brian Smith. In 1817, Balfour was made Vice Consul for the kingdom of Hanover in Shetland. He was married to Charlotte Ogilvy, daughter of [person:charles-ogilvy-i:Charles] and brother of [person:charles-ogilvy-ii:Charles], both councillors. His great-great grandson [person:charles-spence:Charles Spence] was a Zetland County Councillor and his third cousin once-removed [person:william-spence:William Spence] was also a councillor.',NULL,NULL,'I4066','Balfour_Spence','["Lerwick Town Councillors", "Natives of Shetland", "1777 Births", "1843 Deaths", "Merchants", "Spence"]',1,1,NULL);
INSERT INTO "people" VALUES(74,'Barbara Anderson','barbara-anderson','1895-07-18','1987-07-28','Yell','Lerwick','Barbara Ann ''Brannie'' Anderson B.E.M. was a postmaster and County Councillor for Burra from 1970 to 1972.','Barbara was founding member of the WRI in Lerwick. She was the President and Secretary of the War Savings Group She was awarded a British Empire Medal in 1968 for her part in the SWRI savings movement. By 1968, she had been the honorary secretary for 26 years. She was involved in the local drama scene.','BrannieAnderson.png',NULL,'I34568','Barbara_Anderson','["Zetland County Councillors", "Natives of Shetland", "1895 Births", "1987 Deaths", "Female"]',1,1,179137625);
INSERT INTO "people" VALUES(75,'Barbara Cheyne','barbara-cheyne','1947-08-07',NULL,'Old Manse',NULL,'Barbara Jane Cheyne (neé Anderson) is a former Shetland Islands Councillor who represented Delting from 2003 until 2007.',NULL,NULL,NULL,'I131386','Barbara_Cheyne','["Shetland Islands Councillors", "Natives of Shetland", "1947 Births", "Female"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(76,'Basil Neven-Spence','basil-neven-spence','1888-05-12','1974-09-13','Leith','Edinburgh','Sir Basil Hamilton Hebden Neven-Spence was elected as a conservative MP for the constituency of Orkney &amp; Shetland on 14th November 1935, replacing [person:robert-hamilton:Robert Hamilton]. He served until 1950 when he was replaced by [person:jo-grimond:Jo Grimond].','After graduating from Edinburgh University in 1911, he served with the Royal Army Medical Corps, mainly in the Middle East, before returning to the UK in 1924 and continuing his army career as a specialist medical officer at Aldershot. He retired from the army in 1927 with the rank of Major. He contested the 1929 election, which was won by [person:robert-hamilton:Robert Hamilton], and pulled out of the 1931 campaign, prior to the election, before winning the seat in 1935. He had the Haa on Uyea in his pomp. Jack Priest''s memoir of WW2 gives an interesting insider''s view of him and the big hoose, from a small boy''s point of view.',NULL,NULL,'I18388','Basil_Neven-Spence','["Members of the Parliament of the United Kingdom", "Conservatives", "Zetland County Councillors", "1888 Births", "1974 Deaths"]',0,0,175852698);
INSERT INTO "people" VALUES(77,'Brian Gregson','brian-gregson','1948-05-06',NULL,NULL,NULL,'Brian Philip Gregson is a former Shetland Islands Councillor for Yell North & Fetlar from 1994 to 1999 and Unst & Fetlar from 2003 to 2007.',NULL,NULL,NULL,'I293744','Brian_Gregson','["Shetland Islands Councillors", "Incomers to Shetland", "1948 Births"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(78,'Caroline Miller','caroline-miller',NULL,NULL,'Lerwick',NULL,'Caroline Helen Janette Miller (neé Munro) is a former Shetland Islands Council and record shop owner.','Prior to being a councillor, she was a partner at Clive''s Record Shop with her brother Clive.',NULL,NULL,'I37562','Caroline_Miller','["Shetland Islands Councillors", "Natives of Shetland", "1957 Births", "Female"]',1,NULL,NULL);
INSERT INTO "people" VALUES(79,'Cathcart Wason','cathcart-wason','1848-11-17','1921-04-19','Colmonell','London','(John) Cathcart Wason, generally known as Cathcart Wason, was a farmer and politician who served as a Member of Parliament in two countries: first in New Zealand and then in Scotland. He established Barrhill, a model village, and after the failure of this colonial venture, he returned to Scotland. An unusually large man (he was over 6 feet 6 inches (1.98 m) tall), he is noted both as an innovative farmer and for having passed his time in the British House of Commons by knitting.','Born in Colmonell near Girvan, South Ayrshire, he was the son of Rigby Wason and his wife Euphemia McTier. Rigby Wason was a barrister and a successful farmer who converted much of his Corwar estate from moor to arable land; he had also served as a Member of Parliament. He was educated at Laleham and at Rugby School. He came to Canterbury in New Zealand in 1868.[3] Cathcart Wason had four siblings; three older brothers (Rigby, Eugene and James) and one younger sister (Catherine Rigby).[4] Peter Cathcart Wason was Eugene''s grandchild.[5]','Cathcart Wason 1878.JPG',NULL,NULL,'Cathcart_Wason','["Members of the Parliament of the United Kingdom", "Liberals"]',0,0,NULL);
INSERT INTO "people" VALUES(80,'Catherine Anderson','catherine-anderson','1917-02-17','1995-08-01','Wallacetown','Effirth, Sandsting','Catherine Janet ''Kate'' Anderson (neé Johnston) was the director of Home Furnishings and a County Councillor for Aithsting from 1959 to 1961.','Catherine attended Twatt School and later was dux at Lerwick Central School. Upon leaving school, she worked with Aitken & Wright and then the Prudential Insurance. She joined Home Furnishings around 1938, she was one of the first in Shetland to see the benefit of the knitting machine and travelled around the isles demonstrating their use. Catherine''s thirst for knowledge continued through into her 70s, when she took courses in reflexology, aromatherapy and massage at Edinburgh School of Natural Therapy.','Kate Anderson.jpg','Kate Anderson headshot.png','I53146','Catherine_Anderson','["Zetland County Councillors", "Female", "By-elected Zetland County Councillors", "1917 Births", "1995 Deaths", "Natives of Shetland", "Councillors pictured"]',0,1,288999091);
INSERT INTO "people" VALUES(81,'Cecil Eunson (i)','cecil-eunson-i','1928-12-30','2007-12-25','Lerwick','Aberdeen','Cecil Burgess Eunson, was a farmer, butcher and Shetland Islands Councillor from 1986 until his death in 2007.','Unable to afford further education, Eunson''s first job was as a farmhand at Berry. He later became a butcher at Scalloway and then Lerwick. In later life he became wealthy, and was able to travel on the QE2 and on Concorde by the early 1980s. Much of this money was made by sheep trading. He was elected the chairman of the SIC Adult Services Board. Cecil served until his death on 25th December 2007, aged 78. He was a disability advocate, and campaigned vigorously on behalf of people with MS. Dr [person:jonathan-wills:Jonathan Wills] who succeeded Eunson as local councillor said of him that he was &quot;a brave and formidable defender of the public interest&quot;.',NULL,NULL,'I97839','Cecil_Eunson_(i)','["Shetland Islands Councillors", "Natives of Shetland", "1982 Births", "2007 Deaths", "Died in Office"]',1,0,166072257);
INSERT INTO "people" VALUES(82,'Cecil Eunson (ii)','cecil-eunson-ii',NULL,NULL,NULL,NULL,'Cecil Robert Hugh Eunson is a former Shetland Islands Councillor for Whiteness, Weisdale And Tingwall between 1982 and 1986. Cecil was the Shetland branch president of the National Farmers Union 2012-13.',NULL,NULL,NULL,'I33880','Cecil_Eunson_(ii)','["Shetland Islands Councillors", "1951 Births"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(83,'Cecil Smith','cecil-smith','1946-09-22',NULL,'Levenwick',NULL,'Cecil Laing Smith is a councillor for the Shetland Islands Council ward Lerwick South, former Policeman and proprietor of Star Rent-A-Car.',NULL,NULL,NULL,NULL,'Cecil_Smith','["Shetland Islands Councillors", "Natives of Shetland", "1946 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(84,'Charles Brown','charles-brown','1888-12-19','1977-07-28','North Dale','Leith Hospital, Edinburgh','Charles Brown was a R. N. R. Seaman, gunner in World War I and County Councillor for Fetlar between 1945 and 1967.',NULL,'Fetlar School Opening.jpg',NULL,'I153461','Charles_Brown','["Zetland County Councillors", "1888 Births", "1977 Deaths", "Biography Missing"]',1,0,NULL);
INSERT INTO "people" VALUES(85,'Charles Charleson','charles-charleson','1895-09-11','1979-10-05','Northmavine','Hillswick, Northmavine','Charles William Charleson was a crofter and County Councillor for Northmavine South between 1945 and 1955.',NULL,'Charles Charleson.jpg','Charles Charleson Headshot.png','I140901','Charles_Charleson','["Zetland County Councillors", "Natives of Shetland", "1895 Births", "1979 Deaths", "Biography Missing"]',1,1,NULL);
INSERT INTO "people" VALUES(86,'Charles Duncan','charles-duncan','1816-10-01','1884-11-10','Lerwick','Lerwick','Charles Gilbert Duncan was the eldest son of [person:gilbert-duncan:Gilbert Duncan], a solicitor in the town, and Elizabeth Ogilvy, daughter of [person:charles-ogilvy-i:Charles].','Charles became an apprentice to a writer to the signet in Edinburgh, and eventually began to practise the law in his native town. He became a popular solicitor for ordinary people. In the 1850s he was appointed Procurator Fiscal. After his death Sheriff Charles Rampini referred to his ''acute mind, his singularly lucid judgment, his profound knowledge of law, and the keen interest which he took in all pertaining to the functions of the Procurator Fiscal''s office''. He held the position of Agent for the Union Bank in Lerwick since it began operations there in 1867 and upon death had been the Procurator-Fiscal for 32 years. Duncan eventually became a town councillor in 1850, spending 3 years as junior Baillie, between 1856 to 1862 and 1865 to 1874 as senior Baillie. In those offices he became a reformer. He and his supporters introduced a water and drainage system in the town, against opposition from some ratepayers. He set up a competent police force and improved Lerwick''s Hillhead with pavements and grass. It is also said by some that it was Duncan''s influence that was behind journalist Donald Stephen moving to Shetland in 1872 and founding The Shetland Times. Duncan was knighted by the King of Belgium and the King of Holland for services rendered to visitors from those countries. He died in Lerwick in November 1884 of asthma. His father [person:gilbert-duncan:Gilbert] and uncle [person:andrew-duncan:Andrew] were also Lerwick Town Councillors.',NULL,NULL,'I10511','Charles_Duncan','["Lerwick Town Councillors", "1816 Births", "1884 Deaths"]',1,1,290620113);
INSERT INTO "people" VALUES(87,'Charles Dundas','charles-dundas',NULL,'1786-04-10',NULL,NULL,'Charles Dundas, 1st Baron Amesbury (5 August 1751 – 7 July 1832) was a Member of Parliament for Orkney and Shetland from 1781 to 1784.','Charles was a younger son of [person:thomas-dundas-i:Thomas Dundas] of Fingask, MP for Orkney and Shetland (1768–1771) and a commissioner of police in Scotland (31 January 1771), who died on 10 April 1786. His mother was his father''s second wife, Janet, daughter of Charles Maitland, 6th Earl of Lauderdale. He was educated at Edinburgh Academy and Trinity College, Cambridge. He was called to the bar from the Middle Temple, but devoted himself to a political life. His father''s younger brother Lawrence became a successful banker and an MP for over 30 years. Charles''s older brother [person:thomas-dundas-ii:Thomas] was a British Army officer who became Governor of Guadeloupe and also represented Orkney and Shetland for a number of years.','CharlesDundas.jpg',NULL,NULL,'Charles_Dundas','["Members of the Parliament of Great Britain", "1751 Births", "1832 Deaths"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(88,'Charles Gilbert Duncan Sandison (i)','charles-gilbert-duncan-sandison-i','1856-12-29','1931-11-10','Cullivoe','Baltasound, Unst','Charles Gilbert Duncan Sandison son of [person:alexander-sandison:Alexander Sandison] was a County Councillor for Unst North for 36 years, first representing between 1892 and 1910, then again from 1911 until 1929. His long tenure as a Councillor earned him the title of ''Grandfather of the Council''. His son, [person:charles-sandison-ii:Charles] was also a councillor, first elected for Unst North in 1929. Charles unsuccessfully stood in the inaugural Zetland County Council election in 1890.','Hailing from Yell, Charles'' family relocated to Uyeasound where Charles was educated. After leaving school, he moved to Lerwick and worked under George R. Tait in his drapery business for a few years. He eventually returned to Unst and, in 1873, became a partner in his father''s business, which then became Alexander Sandison & Sons in 1895 in Baltasound. The business''s primary trade was in fishcuring, stockbreeding, farming in general merchandise, but expanded to include engineering, baking and hosiery. Charles'' main focus early on in the business was in the buying, selling and curing of fish. As the white fish industry began to fail, Charles''s focus was shifted to herring. He managed a herring station, cooperate and the fleet of boats owned by the firm. Later, he helped to develop the knitwear arm of the business and was responsible for adding a bakery to the business.','CharlesSandisonSnr.png',NULL,'I16461','Charles_Gilbert_Duncan_Sandison_(i)','["Zetland County Councillors", "Councillors pictured", "1856 Births", "1931 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(89,'Charles Goodlad','charles-goodlad','1943-09-19','2013-12-16','Yell','Trondra','Charles Alistair Goodlad was a businessman, academic, public figure, fishing industry pioneer as well as a Shetland Islands Councillor for Burra between 1994 and 2003. An obituary in the Shetland News described him as one of Shetland''s "greatest sons".','Alistair, as he was better known, was born into a family of fishermen in Yell in 1943. After completing high school in Scalloway and the Anderson High School, he went to Aberdeen where he completed a degree in Geography. He then started a PhD into the Shetland fishing industry, which would later be published as Shetland Fishing Saga, which remains one of the most authoritative books on the industry. He was appointed assistant professor at Memorial University in Newfoundland, Canada, in 1968 where he also partook in fishing. From this role he was headhunted by the United Nations Fisheries and Agriculture as a fisheries expert. In 1975, he moved to the Middle East where he set up a chain of cold stores. While in the Middle East, he moved to Saudi Arabia and became the General Manager for the Saudi Fisheries Company, a position he held until moving back to Shetland in 1982. Back in Shetland, Alistair became a pioneer of the Shetland salmon industry. He founded Shetland Sea Farms in 1985 and sold it in 1990. He then bought the Burra Isle of Hildasay where his sole house still stands. During this period, he also chaired the Shetland Salmon Farmers'' Association. He was the founder of Saga Seafoods, which became a major employer in Scalloway. In 1994, he was first elected to the Burra and Trondra seat for the Shetland Islands Council. He held his seat until 2003. During his time as councillor, he was elected as chairman to the Council''s Harbour Board and of the Lerwick Port Authority.',NULL,NULL,'I1855','Charles_Goodlad','["Shetland Islands Councillors", "Natives of Shetland", "1943 Births", "2013 Deaths", "Writers"]',1,1,196366195);
INSERT INTO "people" VALUES(90,'Charles Hoseason','charles-hoseason','1843-07-27','1905-02-16','Mossbank','Mossbank','Charles Hoseason was a merchant, postmaster and County Councillor, representing Delting North very briefly between February 4 and 25 1890.','Partner with [person:william-pole:William Pole] in the firm of Pole, Hoseason & Co., Mossbank. After a few years the partnership was dissolved and Charles was appointed Sub-Postmaster at Mossbank, April 1867.',NULL,NULL,'I3425','Charles_Hoseason','["Zetland County Councillors", "1843 Births", "1905 Deaths"]',1,1,175854883);
INSERT INTO "people" VALUES(91,'Charles Inkster','charles-inkster','1901-12-29','1983-03-27','Duncansclate','Bridgewater, Nova Scotia, Canada','Charles Inkster was a Lerwick Town Councillor from 1941 until 1944. He was appointed with [person:john-gear:John Gear] following the resignation of both Thomas Irvine and Joseph Linklater from the council.',NULL,NULL,NULL,'I78635','Charles_Inkster','["Lerwick Town Councillors", "1901 Births", "1983 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(92,'Charles Laurenson','charles-laurenson','1852-02-21','1933-08-29','Bressay','Edinburgh','Charles Duncan Laurenson was a bank manager and a Lerwick Town Councillor.','Charles joined the Commercial Bank in 1867, between the completion of his apprenticeship and his return to Lerwick as Agent for the bank, Charles served in various branches south. His appointment as Agent came in 1884 after the death of [person:charles-duncan:Charles Gilbert Duncan], who had been the first man to hold that title in the bank and whom had trained Charles when he was a young man. His rise to Agent was considered fast, coming only 17 years after he first started with the Commercial Bank. In 1907 he was appointed Agent at the Chief Office in Greenock and held that post until 1919. His vacancy was filled by [person:william-macdougall:William MacDougall].','CharlesDuncanLaurenson.JPG',NULL,'I18159','Charles_Laurenson','["Lerwick Town Councillors", "Councillors pictured", "1852 Births", "1933 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(93,'Charles Lennie','charles-lennie','1859-10-31','1909-06-27','Ophir','Scalloway Hotel','Charles Lennie was a builder, hotel owner and County Councillor for Burra from December 1898 until his death in June 1909.','When he was 20, he emigrated to Canada to work as a builder. He worked between there and Texas, before eventually returning home to Kirkwall where he stayed for 5 years. When he moved to Shetland he became the owner of the Scalloway Hotel. Unfortunately the hotel and his residence within it was ravaged with fire in 1908, and although this was covered by insurance, he lost all his possessions and the event contributed to his ailing health. He was a member of the Gordon Highlanders, and he also presented the &quot;Lennie Cup&quot; to the winner of an annual shooting competition.',NULL,NULL,'I442429','Charles_Lennie','["Zetland County Councillors", "Died in Office", "Incomers to Shetland", "1859 Births", "1909 Deaths", "Orcadians"]',1,1,NULL);
INSERT INTO "people" VALUES(94,'Charles Manson','charles-manson','1899-01-09','1983-09-21',NULL,'Portree, Isle of Skye','Charles Arthur Manson was a sorting clerk, telegraphist and Lerwick Town Councillor.','Charles moved to Stromness, Orkney in 1940 to take up the role as Postmaster. In 1946, he moved to Portree on the Isle of Skye to take up the same role there, and had also worked in Crieff. He retired in 1961. He was also the Guizer Jarl for Lerwick Up Helly Aa in 1926.',NULL,NULL,'I42687','Charles_Manson','["Lerwick Town Councillors", "1899 Births", "1983 Deaths"]',NULL,0,NULL);
INSERT INTO "people" VALUES(95,'Charles Merrylees','charles-merrylees','1843-10-23','1911-10-01','Lerwick','Aberdeen','Charles Magnus Henderson Merrylees was a manager of the North of Scotland, Orkney &amp; Shetland Steam Navigation company, and Lerwick Town Councillor.','Charles joined the North of Scotland and Shetland Steam Navigation Company in 1858 becoming manager in Aberdeen for a period of at least 30 years. When his length of service had extended for 50 years, (from 1858 to February 1908), it was decided to present him with his portrait in oils and other gifts. The artist commissioned was Charles Martin Hardie, R.S.A. The jubilee celebrations for Charles were held in Aberdeen. In his speech he recalled that 50 years previously Shetland had one steamer per week carrying mails for eight months of the year and during the other four months the sail clipper Fairy delivered a mail about once in every 10 days. Eventually, there were four mails per week all the year round. Letters in those days cost 3d and 6d whilst the time taken in transmission was very uncertain. In Aberdeen passengers and cargo had often to be taken off in large boats to disembark,but the later steamers could comfortably enter and leave all states of the tide. Disembarking in Lerwick was similar until the Victoria Pier opened in 1886. Charles was the youngest son in a family of 11 children. He married Louisa Anne Umphray and their eldest son William who trained in Aberdeen came to Lerwick as agent when Mr [person:william-shand:William Shand] retired. Charles devoted all his time to his business. His wife died on 18th November 1905 and his death followed in Aberdeen six years later at the age of 67. His father, [person:william-merrylees:William], was also a Lerwick Town Councillor, and his nephew [person:thomas-anderson-i:Thomas] was a County Councillor.',NULL,NULL,'I40213','Charles_Merrylees','["Lerwick Town Councillors", "1843 Births", "1911 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(96,'Charles Mitchell','charles-mitchell','1882-01-18','1963-09-25','Fraserburgh','Lerwick','Charles Ernest Mitchell was a fish curer and County Councillor for Gulberwick between 1945 and 1949.','Charles was educated in Fraserburgh and at Aberdeen Grammar School. As a boy, he frequently visited Shetland through the family''s fish-curing business at North Ness. In 1901, Charles took charge of the North Ness operation, and the other stations which stretched from Baltasound to Sandwick. The business then became James Mitchell & Sons, with Charles''s brother James also joining. During this period, Charles also dabbled in coopering, along with some of the 300 others employed by the firm for that role. In WWI, Charles served in the Shetland Gordon Highlanders as a Captain. After the war, he settled in Lerwick married Mary Williamson, the daughter of [person:david-williamson:David]. The North Ness operation became the largest single employer of men in Lerwick, and for many years the state of employment in the town hinged on the business having a good year. The business eventually grew to operate across Britain. The North Ness operation was requisitioned by the army during WWII, and did not reopen after the war, with Charles retiring. Other interests for Charles included being the Director of the British Oil and Guano Company, with a factory in Bressay and he was Director of MacLeod & MacLean, which later became Shetland Lime Ltd.',NULL,NULL,'I85363','Charles_Mitchell','["Zetland County Councillors", "Incomers to Shetland", "1882 Births", "1963 Deaths"]',0,1,163057276);
INSERT INTO "people" VALUES(97,'Charles Murray','charles-murray',NULL,NULL,NULL,NULL,'Charles Murray of Hadden was a Burgh and Shire Commissioner for Orkney and Shetland to the Parliament of Scotland between 1685 and 1686 with [person:henry-graham:Henry Graham]. He was bankrupt before he passed away. Category:Burgh and Shire Commissioners to the Parliament of Scotland',NULL,NULL,NULL,NULL,'Charles_Murray','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(98,'Charles Ogilvy (i)','charles-ogilvy-i','1761-02-26','1827-02-13','Seafield','Lerwick','Charles Ogilvy was a general merchant and Lerwick Town Councillor. His nephew [person:james-ogilvy:James], and two of his sons, [person:charles-ogilvy-ii:Charles] and [person:john-ogilvy:John] were also councillors. His daughter Margaret was married to [person:william-hay:William Hay], farmer, banker, Lerwick Town Councillor.',NULL,NULL,NULL,'I7816','Charles_Ogilvy_(i)','["Lerwick Town Councillors", "1761 Births", "1827 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(99,'Charles Ogilvy (ii)','charles-ogilvy-ii','1802-08-28','1844-06-05','Lerwick','Edinburgh','Charles Ogilvy was a business owner, Lerwick Town Councillor, and man of high-importance in Lerwick''s history, despite his short life. His father, [person:charles-ogilvy-i:Charles], his older brother [person:john-ogilvy:John] and his uncle [person:james-ogilvy:James] were also councillors in Lerwick.',NULL,NULL,NULL,'I9184','Charles_Ogilvy_(ii)','["Lerwick Town Councillors", "1802 Births", "1844 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(100,'Charles Robertson','charles-robertson','1838-06-20','1895-07-21','Lerwick','Lerwick','Charles Robertson was a licensed grocer (R. & C. Robertson) and Lerwick Town Councillor. Robertson was the first councillor to hold the title &quot;Provost&quot; - until 1893 it had been know as Chief Magistrates or Senior Baillie.','Charles first job was as a shopboy to James Arcus, a local merchant. In 1858, he joined up with his brother Robert as successors to Andrew Fordyce, opening R & C Robertson in Lerwick. Politically, Charles was a staunch conservative and upholder of the established church.','Charles Robertson Provost.png','Charles Robertson Headshot.png','I11326','Charles_Robertson','["Lerwick Town Councillors", "Council Leaders", "Lerwick Town Council Chief Magistrates", "Lerwick Town Council Provosts", "Natives of Shetland", "1838 Births", "1895 Deaths", "Merchants", "Councillors pictured"]',1,1,290650617);
INSERT INTO "people" VALUES(101,'Charles Sandison (ii)','charles-sandison-ii','1892-02-10','1967-07-13','Baltasound','Baltasound, Unst','Charles Gilbert Duncan Sandison was an author and County Councillor for Unst North between 1929 and 1937. He was the fifth child of [person:charles-gilbert-duncan-sandison-i:Charles] and Mary Mundell . His father was known as the ''Grandfather of the Council'', as he represented it for over 30 years.','Charles had the opportunity to begin a career in aeronautical engineering, but the pull of working in his family''s business, Alexander Sandison & Sons Ltd was too great and so he returned to Unst and became head of that firm. But for men like Charles Sandison the economy, and indeed the very life of Shetland might well have collapsed
* Shetland Times obituary, 1967','CharlesSandisonJr.png',NULL,'I18344','Charles_Sandison_(ii)','["Zetland County Councillors", "Councillors pictured", "1892 Births", "1967 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(102,'Charles Spence','charles-spence','1924-03-14','1996-09-22','Yell','Yell','Charles Gilbert ''Charlie'' Spence was a County Councillor for Yell South between 1958 and 1964.','During WWII, Charles served with the Royal Navy Patrol Service, serving in the Middle East at one point. At the end of the conflict, he returned to Shetland to the family croft. Alongside his council service, he was the chair of the local Community Council and a member of the Shetland Council of Social Service. His great grandfather, [person:balfour-spence:Balfour Spence], was an early Lerwick Town Councillor.',NULL,NULL,'I15017','Charles_Spence','["Zetland County Councillors", "1924 Births", "1996 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(103,'Charles Stobie','charles-stobie','1847-12-26','1935-12-09','Keiss','Ferryport-on-Craig Manse, Tayport, Fife','Reverend Charles M. Stobie was a minister in Whalsay and Zetland County Councillor.','He represented the Whalsay Church of Scotland from 1876 until 1910 when he was appointed as Chaplin to the Royal Infirmary, Aberdeen. He was also a keen photographer and probably one of the few on Whalsay who possessed one in that era. Many pictures taken by him are on the Shetland Museum and Archives photo archive, one of which is linked to below.',NULL,NULL,'I127030','Charles_Stobie','["Zetland County Councillors", "Councillors - Clergymen", "1847 Births", "1935 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(104,'Charles Stout','charles-stout','1845-11-26','1928-03-22','Uyeasound','Medical Hall, Lerwick','Charles Brown Stout was a chemist, the owner of Medical Hall at 92 Commercial Street, Lerwick Town Councillor and County Councillor.','Charles was first educated in Baltasound under Rev. George Robertson. He left school aged 17 intending to pursue a career at sea. He arrived in Lerwick aged 19 and became apprenticed to Dr Loeterbach, a medical practitioner at the Medical Hall. Charles would go on to be connected to the Medical Hall for the next 63 years, where he was both a chemist and registered dentist. He retired from active practice in 1926, by his son Charles carried on the business. He was a member of the Lerwick School Board and a director of the Lerwick Gaslight Company. In 1866, the Diana, a whaling ship on expedition to Baffin Bay, became frozen in ice and lay trapped for 6 months. The ship''s crew had a large Shetland contingent, and the conditions combined with the lack of provisions saw the more than one third of the Shetland crew lose their lives. When the ship was finally freed, it sailed to Lerwick where upon its arrival in Ronas Voe, Charles and Dr Loeterbach rode on horseback to provide medical assistance. Charles'' daughter Elizabeth, who settled in America, recounted this story in a letter to the Lerwick Harbour Trust in 1941.','Cstout.jpg',NULL,'I25918','Charles_Stout','["Lerwick Town Councillors", "Zetland County Councillors", "1846 Births", "1928 Deaths"]',1,1,179137691);
INSERT INTO "people" VALUES(105,'Charles Whyte','charles-whyte','1866','1949-03-27','Forfar','Aberdeen','Reverend Charles Whyte was a Free Church Minister in Dunrossness and a County Councillor for Dunrossness North from August 1898 until December 1898.','Charles studied first at St Andrew''s University then New College. His first posting with the church was in the United Free Church of Dunrossness on 13 October 1892, serving until 2 December 1909 when he was transferred to Towie. He served in various Aberdeenshire parishes before transferring to Kingswell in 1917, where he served for nearly 30 years, retiring in 1947. In 1919, he received an honorary degree of LL.D from the Lincoln Memorial Presbyterian University in American and was for more than 30 years a Fellow of the Royal Astronomical Society. While in Shetland he took a keen interest in astronomy, and he began writing series of monthly articles for the Press and Journal and published books on the topic.','RevCharlesWhyte.png',NULL,'I188976','Charles_Whyte','["Zetland County Councillors", "Councillors - Clergymen", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1866 Births", "1949 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(106,'Charlotte Nicol','charlotte-nicol','1864','1954-11-25',NULL,'Breiwick Hospital, Lerwick','Charlotte Nicol neé Stuart was a teacher and the first woman to ever be elected onto the highest level of Local Government in Shetland, representing the Lerwick Town Council between 1933 and 1937.','Charlotte was a native of Banffshire, and upon leaving school became a teacher. She taught in Banff, Abedeen and Fraserburgh until she married Alexander Bisset Nicol (b. 1864, d. 14 November 1905, Yarmouth) who was a member of the firm Smith & Schultz, a fishbroker and herring merchant firm. Alexander was reported missing on 17 November 1905 while on business with the firm in Yarmouth, and his body was located a month later in the Breydon water. Returning to teaching in 1896, Charlotte taught at Braemar and Helhevie where she was headmistress for four years. She then took up residence in Lerwick, where Alexander had conducted some of his business, and started teaching at the Lerwick Central School on 19 January 1908, and continued until her retiral on 22 August 1928. She and Alex had two sons, Charles Robert Stuart Nicol (b. 7 October 1891, d. 21 January 1967, Canada) who became a banker in Canada and Alexander Bisset Nicol (b. 1893, d. 27 August, 1917, France). The latter son died from injuries sustained during the attack on Frezenberg, east of Ypres, during the subsequent operations from the Battle of Langemarck.','Charlotte Nicol.jpg',NULL,'I410091','Charlotte_Nicol','["Lerwick Town Councillors", "Incomers to Shetland", "1864 Births", "1954 Deaths", "Female", "Councillors pictured"]',NULL,1,NULL);
INSERT INTO "people" VALUES(107,'Christine Begg','christine-begg',NULL,'2014',NULL,NULL,'Doctor Christine M. Begg was a doctor and former Liberal Democrat Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'Christine_Begg','["Shetland Islands Councillors", "Councillors - Missing All", "Female"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(108,'Christopher Dowle','christopher-dowle',NULL,NULL,NULL,NULL,'Christopher ''Chris'' Dowle is a solicitor and former Shetland Islands Councillor. When elected in 1978, he was one of the youngest ever Councillors in Shetland''s history at only 24 years old.',NULL,NULL,NULL,NULL,'Christopher_Dowle','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(109,'Christopher Sandison','christopher-sandison','1841-10-11','1883-04-28','Sursetter','Lerwick','Christopher Sandison was an editor of the Shetland Times and briefly a Lerwick Town Councillor between 1874 and 1876. He was the grandson of famous Shetland diarist Christopher Sandison.','He arrived in Lerwick at age 16 and started working with Charles D. Jamieson, stationer and printer. He worked there for 7 years after which he worked for a stationer in Inverness. Subsequently, he was employed as a travelling stationary salesman by a Glasgow-based firm. Failing health saw him return to Shetland in 1869. While working for Charles Jamieson, Sandison took an active role in publishing the Shetland Advertiser - the first newspaper attempted in Lerwick. When the owner of the Shetland Times, Mr Donald Stephen, felt his health was failing, Sandison took over the Shetland Times. His Shetland Times obituary describes him as "in favour of progress and Liberalism, both in municipal and imperial affairs".',NULL,NULL,'I11970','Christopher_Sandison','["Lerwick Town Councillors", "1841 Births", "1883 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(110,'David Burns','david-burns','1809-04-01','1848-03-29','Lerwick','Lerwick','David Nisbet Burns was a draper, inspector of the poor and a Lerwick Town Councillor between 1844 until his death of Typhus in 1848.',NULL,NULL,NULL,'I122333','David_Burns','["Lerwick Town Councillors", "1809 Births", "1848 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(111,'David Gray (i)','david-gray-i','1842','1901-05-29','Kirkcaldy','Burra','Reverend David Gray was the United Free Church Reverend for Burra and a County Councillor for the same constituency first from 1890 to 1892 then again from 1893 to 1898','Upon completing his education in Fife, he attended Edinburgh University where he studied divinity. Upon graduation, he became a missionary in Maryhill, Glasgow. He was ordained on 12 June 1884 and served the Burra United Free Church until his death. Though a Liberal in politics, he did not support the Liberal Party during William Gladstone''s Home Rule for Ireland measure.',NULL,NULL,'I82862','David_Gray_(i)','["Zetland County Councillors", "Councillors - Clergymen", "1843 Births", "1901 Deaths"]',0,1,NULL);
INSERT INTO "people" VALUES(112,'David Gray (ii)','david-gray-ii','1888-08-22','1946-03-04','West Yell','Lerwick','David Gray was an Estate Factor, purser on the Earl of Zetland and Lerwick Town Councillor from 1945 until his death in 1946.','David entered the services of the North of Scotland Company and after some time became purser on the Earl of Zetland II. When health prevented his continued work on the Earl of Zetland, he took up duties as the factor of the Garth Estate. He was noted as a keen swimmer, and was a judge for the Lerwick Swimming Club.',NULL,NULL,'I49984','David_Gray_(ii)','["Lerwick Town Councillors", "1888 Births", "1946 Deaths"]',1,1,291202948);
INSERT INTO "people" VALUES(113,'David Harbison','david-harbison','1933-08-26','2017-10-25','Greenock',NULL,'Reverend David John Hislop Harbison was a former Minister and Zetland County Councillor for Whalsay And Skerries from 1961 to 1964. He was in Whalsay for 9 years (1958-1967) before moving to Hamilton, Lanarkshire. He was married to Winifred and had three children. His love of football helped to encourage the development of football on Whalsay, and in 2002 he opened Harbison Park on the Isle.',NULL,'David and Winifred Harbison.jpg','David Harbison Headshot.png','I261640','David_Harbison','["Zetland County Councillors", "Councillors - Clergymen", "1933 Births", "Councillors pictured"]',0,NULL,NULL);
INSERT INTO "people" VALUES(114,'David Johnston','david-johnston','1913-02-07','1993-02-20','North Sandwick','North Sandwick, Yell','David John ''Davy'' Johnston was a merchant seaman, ferry operator and Shetland Islands Councillor for Yell North in the Zetland County Council and for Yell North and Fetlar in the Shetland Islands Council.','After leaving school, Davy went into the merchant navy and became the ship''s carpenter. After World War II, he started a ferry service that linked Unst, Fetlar and Yell and operated this service until the 1970''s when the roll-on-roll-off ferries were introduced by the Shetland Islands Council. Davy was a singer/songwriter and he could play the fiddle and he owned a sailing boat called the Barann, with which he had considerable success at local regattas.',NULL,NULL,'I6710','David_Johnston','["Zetland County Councillors", "Shetland Islands Councillors", "1913 Births", "1993 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(115,'David Leask','david-leask','1781-04-08','1848-03-09','Sand','Lerwick','David Leask was a merchant and Lerwick Town Councillor between 1835 and 1841.',NULL,NULL,NULL,'I92693','David_Leask','["Lerwick Town Councillors", "1781 Births", "1848 Deaths"]',1,1,290622659);
INSERT INTO "people" VALUES(116,'David Murray','david-murray','1880-04-16','1961-03-21','Wadbister','Braeview, Brae','David Murray was a joiner and Lerwick Town Councillor between 1921 and 1926. He was unsuccessful in 1920 and again in 1926.','After retiring from his Lerwick business in 1947, David settled in Brae where he was commissioned to create communion furnishings for the church.',NULL,NULL,'I69412','David_Murray','["Lerwick Town Councillors", "1880 Births", "1961 Deaths"]',1,1,287523880);
INSERT INTO "people" VALUES(117,'David Nicolson','david-nicolson','1789','1849-06-04','Unst','Lerwick','David Nicolson was a joiner and a Lerwick Town Councillor.',NULL,NULL,NULL,'I4222','David_Nicolson','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1789 Births", "1849 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(118,'David Sandison','david-sandison','1960-09-28',NULL,'Stratford-on-Avon',NULL,'David Alexander ''Davie'' Sandison is a Shetland Islands Councillor, representing Shetland Central since 2011.','Davie was born in England to Shetland parents. He works for Shetland Aquaculture, the representative body for the salmon industry in Shetland.',NULL,NULL,'I225338','David_Sandison','["Shetland Islands Councillors", "Natives of Shetland", "1960 Births"]',0,NULL,NULL);
INSERT INTO "people" VALUES(119,'David Sutherland','david-sutherland','1850-10-01','1929-10-02','Colvadale','Lerwick','David Sutherland was a watchmaker and a County Councillor for Sandness between 1904 and 1921.','David grew up on Unst and came to Lerwick around 1880 where he started a watchmaker and jewellery business. He was noted as having a keen interest in scientific matters and was an early authority in Shetland on telephone technology. In later life, he leaned into socialism and became an advocate for laying out a garden city in Lerwick. A stroke he suffered in 1920 kept him confined to his bed for the last 9 years of his life.',NULL,NULL,'I11643','David_Sutherland','["Zetland County Councillors", "1850 Births", "1929 Deaths"]',1,1,179947214);
INSERT INTO "people" VALUES(120,'David Walker','david-walker','1916-01-29',NULL,'d. June 2006',NULL,'David Andrew Walker was a Church of Scotland Missionary and County Councillor for Northmavine North between 1949 and 1950.','Walker was married to Ruth Naomi Robinson (28 Feb 1942) and had 3 children, Paul, Naomi and Miriam. While in Shetland they lived in the Burndale Manse in North Roe (which no longer exists) and Paul and Naomi briefly attended the North Roe Primary school until the whole family left Shetland in September 1950. David later returned in 1982 to preach in the Brae kirk.',NULL,NULL,NULL,'David_Walker','["Zetland County Councillors", "Councillors - Clergymen", "Councillors - Missing B/D", "Councillors - Missing Death Date", "1916 Births", "2006 Deaths"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(121,'David Williamson','david-williamson','1860-09-18','1937-01-06','Arbirlot','Royal Hairdressing Saloon, Lerwick','David Williamson was a Bank Agent and a County Councillor for Yell South first between 1895 and 1901, then again between 1902 and 1910. His eldest daughter, Mary, was married to councillor [person:charles-mitchell:Charles Mitchell].','David came to Shetland in 1883 from Banff and was employed by the Lerwick branch of the North of Scotland Bank Ltd. He rose to the position of Agent in the bank after the death of William Irvine, a position he held for some 40 years, retiring on 30 September 1928, with more than 45 years service.',NULL,NULL,'I76326','David_Williamson','["Zetland County Councillors", "1860 Births", "1937 Deaths"]',0,1,163057273);
INSERT INTO "people" VALUES(122,'Donald Morrison','donald-morrison','1859-01-03','1923-05-27','Sandwick','Lerwick','Donald Robert Morrison was a bookseller, stationer and Lerwick Town Councillor between 1899 and 1905.','Donald moved to Shetland with his family around 1870, with his father Hector opening a bookseller/stationery business in Lerwick. He first served as an apprentice in the office of the Shetland Times, before joining his father''s business, H. Morrison & Son. He continued with the business after the death of his father in 1903. He was part of the first football team in Lerwick captained by [person:alexander-mitchell-ii:Alex Mitchell].',NULL,NULL,'I122730','Donald_Morrison','["Lerwick Town Councillors", "1859 Births", "1923 Deaths", "Orcadians"]',1,1,NULL);
INSERT INTO "people" VALUES(123,'Donald Sutherland','donald-sutherland','1914-07-06','1989-11-11','Yell','Lerwick','Donald George Sutherland was an author and County Councillor for Delting North between 1952 and 1955.','Donald attended the Ulsta school in Yell as a boy and later in Lerwick. He qualified as an accountant and worked for many years in Dunfermline. When he returned to Shetland, he worked for AQS and Pearson & Tawse. He was a regular participant at the Althing.',NULL,NULL,'I24218','Donald_Sutherland','["Zetland County Councillors", "1914 Births", "1989 Deaths"]',1,1,166072266);
INSERT INTO "people" VALUES(124,'Edward Adie','edward-adie','1890-09-09','1977-05-18','Voe','Voe, Delting','Major Edward Percival Douglas ''Ted'' Adie was a County Councillor for Delting South from 1928 to 1952 and again between 1955 and 1967','Edward was born into a large family, the seven child of eleven who survived into adulthood. His grandfather, Thomas, had founded a business in Voe which was still operating as Edward came of age to work. The business originally began as a general merchants, it expanded into fish curing during the Faroese fishing boom, and exported salt fish to Europe. The arrival of steamships and changing fortunes in the fishing trade saw the company pivot into woolen goods. Edward did not immediately join the family business. Instead, he and brother Douglas emigrated to Canada where they bought land and began lumberjacking. At the outbreak of WWI, Edward joined the Canadian Scottish Infantry and reached the rank of Captain. His foot was severely wounded in France and he received a Military Cross. He returned to Canada for four years after the war, before returning to Shetland to take over the family business, after the retiral of [person:james-adie:James Adie]. Edward grew the businesses woolen trade considerably, and the company was among the first in Shetland to deploy knitting machines. The company''s produce was used by adventurers in the 1953 British Everest Expedition. During WWII, Edward not only continued to run the business with a reduced number of staff, he was also County Convener, and second in command to the Home Guard to [person:arthur-nicolson-ii:Arthur Nicolson].','Edward Adie.png','Edward Adie headshot.png','I9189','Edward_Adie','["Zetland County Councillors", "1890 Births", "1977 Deaths"]',1,1,175970485);
INSERT INTO "people" VALUES(125,'Edward Knight','edward-knight','1939-11-14','2022-10-15','Lerwick','Lerwick','Edward John Knight is a former Shetland Islands Councillor who represented Lerwick Harbour and Bressay from 2003 until 2007.',NULL,NULL,NULL,'I45255','Edward_Knight','["Shetland Islands Councillors", "Natives of Shetland", "1939 Births"]',1,1,NULL);
INSERT INTO "people" VALUES(126,'Edward Sinclair','edward-sinclair',NULL,NULL,NULL,NULL,'Edward Sinclair of Essenquoy was a Burgh and Shire Commissioner for Orkney and Shetland to the Parliament of Scotland in 1617 with [person:robert-henderson-i:Robert Henderson of Holland].','*Biography from http://www.fionamsinclair.co.uk/genealogy/isles/Essenquoy.htm The rental of 1614 notes the bishopric lands of North Widfirth (St.Ola''s) as in the hands of Sinclair of Essenquoy, feued to Robert Chalmer. He was Member of Parliament for Orkney and Shetland in the Scottish Parliament of 1617, on 4th November in which year he heads the list of suitors before the Earldom Court. On 15th August 1615, James, son of John Louttit (by Helene Sinclair his spouse), receives from Essenquoy a discharge for money lent to his people. On 25th November 1616, he appears for Robert Sinclair of Campston against Francis Mudie of Breckness; and on l0th May 1619, sues William Sinclair of Tolhop and John Sinclair, merchant in Kirkwall. He granted charter to Alexander Flet in How, Harray, of the houses and lands of Ramsgar in Overton in Harray, which was produced 23rd November 1621. Edward Sinclair of Aestenquoy is Sheriff-Depute of Orkney 1st July 1623. He was conjoined with Robert Sinclair of Campston for the purpose of reporting upon the King''s lands in the isle of Rousay, of which they were taksmen, and was sworn thereto at Kirkwall, 12th June 1627; and again in the Report of the Parish of St.Andrews. At St.Ringan’s Chapel the 21st day of June anno 1627 the Commissioners elected thereto viz. Robert Sinclair of Campston, David Kinked of Yeinsta judicially sworn in that respect of their knowledge and insight in that business; and for their better proceeding did choose the most ancientest men within the parish to help them by their information, that is, Edward Sinclair of Essenquoy etc., who can testify their diligence. As for prebendries there is a part of St.John''s prebendries in this parish of St.Andrews sett by Mr. Patrick Inglis, minister at Kirk, and prebender of the said stowke, with consent of ane reverant father in God, George Bishop of Orkney and the whole chapter, to Campston and Essenquoy for the payment of £20 money to the said prebender as it has been to his predecessors of old". In the parish report at Our Lady Kirk in Deerness, 25th June 1627, "The worth of the Rowms of this Parish contains allusion to the ten penny half penny land in Sandwick bishop’s land of old, and set to umquhill [deceased] Olefer Sinclair of Essenquoy for the payment of 20 merks money, and now in the hands of Edward Sinclair of Essenquoy his son for the payment of £20 to his Majesty''s chamberlains, conform to the rental". On the 2nd April 1630, he was Sheriff-Depute, and commissioned as such by the Lords of Session to take the Oaths of Verity of George Bishop of Orkney and Patrick Smyth of Draco, in the case of Mr. Alexander Bruce of Cultmulindie, etc. He was Sheriff-Depute 6th November 1632; and on 26th May 1637, when William Sinclair of Saba compeared in the matter of security for John Cromartie for the corns embarked by him in the "Gift of God", Essenquoy again fills that honourable office. On 16th August 1635, he was judge of assise on the Dittay of witchcraft against Helene Isbuster. On 26th December 1616, he and his son Gilbert are als of James Baikie of Tankerness for 1,600 merks Scots, etc. In 1640 he is a bailie ordained for St.Ola''s, and is a suitor present at the Curia Capitalis 24th May 1641. He married Ursilla Fulzie, second daughter of Gilbert Fulzie, Archdeacon of Orkney (sasine 1641), and was succeeded by his son Category: Burgh and Shire Commissioners to the Parliament of Scotland',NULL,NULL,NULL,'Edward_Sinclair','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(127,'Edward Thomason','edward-thomason','1922-08-12','1997-12-16','105a Commercial Street','Aberdeen','Edward Thomason OBE was a Zetland County Councillor, Shetland Islands Councillor and Convener.','He was the son of Edward Thomason (b. 5 Nov 1885, Horn, Lunnasting) and Mary Margaret Anderson (b. 15 Sep 1887, Treawick, Whalsay). He married Dinah Janet McPherson Patterson Hunter, (b. 10 Jan 1921, Nesting) on 25 November 1949 at Newington, Edinburgh. He was Prudential Assurance Manager in Lerwick, and a councillor, later Convener, retiring in 1994. His book Island Challenge (1997) reflects in part on the era of North Sea Oil. He also provided an introduction to Mindin Rhoda, a Festschrift for the poet Rhoda Bulter whose mother also came from ''Da Horn''. In an obituary in The Herald, Edward was described as overseeing the "transformation of his native islands from being a poverty-stricken community dominated by the highest unemployment rate in Scotland and haemorrhaging its most able young population to an island group enjoying an unprecedentedly high standard of living" in reference to his work securing the Zetland County Council Act 1974. That act granted the Zetland County Council and Shetland Islands Council substantial powers to ensure that Shetland was able to benefit from the boom in oil production which began in the 1970''s. In the late 1950s Edward was one of a group of islanders wanted to fix Shetland''s deep social problems. The collapse of the whaling and herring industry had hurt the isles financially. The group, successively called the Shetland Development Council and the Shetland Council of Social Service, persuaded businessmen to establish a canning factory and launched an initiative to sell locally-built boats via London''s International Boat Show. In 1989, he was granted an OBE and he spent his final living months in the eponymous Edward Thomason House for the elderly in Lerwick.','Edward Thomason.png','Edward Thomason Headshot.png','I34441','Edward_Thomason','["Conveners of the Shetland Islands Council", "Shetland Islands Councillors", "Zetland County Councillors", "1922 Births", "1997 Deaths", "Councillors pictured"]',1,0,292906114);
INSERT INTO "people" VALUES(128,'Edwin Hyde','edwin-hyde','1873','1940-08-12',NULL,'54 Windsor Road, Ashton-in-Makerfield, Lancashire','Edwin Thomas Hyde was a governor of Zetland County Homes and a County Councillor for Whalsay.','Edwin took up pastoral duties in Scalloway in 1907. He and his wife were appointed Governor and Matron of the Zetland County Homes on 2 December 1911 and held that post until 15 May 1935, when they moved back to England. He was the honorary treasurer of the Shetland Football Association from 1924 to 1928, and the chairman of the same organisation for the two years that followed. He was also responsible for starting the Boy Scouts movement in Shetland in 1914, in both Lerwick and Sandwick.',NULL,'Edwin Hyde headshot.png','I182298','Edwin_Hyde','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "Councillors - Missing Birth Location", "1940 Deaths"]',NULL,0,NULL);
INSERT INTO "people" VALUES(129,'Edwyn Tait','edwyn-tait','1884-12-14','1960-11-06','Lerwick','Braehead, Scalloway','Edwyn Seymour Reid Tait was an author, folklorist merchant, draper and Councillor.','Edwyn worked as a merchant and draper in Lerwick at the family business. He was the second child of [person:george-tait:George Reid Tait] (b. 1829, Lerwick), and Johan Frances Johnson (b. 7 Aug 1859, Lind, West Yell). Reid Tait married Jemima Brown, (b. 1894, Lerwick), in 1922 at St. Nicholas, Aberdeen. Reid Tait was an antiquary, and founder and president of Shetland Folk Society. He was also a keen collector of books and articles about Shetland. One of his unfinished projects was the creation of a Shetland bibliography: his drafts of it are now in the Shetland Museum and Archives. When he died he bequeathed his collections to the Shetland Library. He was the 1911 Guizer Jarl for the Lerwick Up Helly-Aa in his own right, and performed the role again in 1912 substituting for an absent H. Kay. As a Rechabite, he was a prominent activist with the local temperance movement''s successful bid to introduce alcohol prohibition in Shetland in 1921.','Edwyn Tait.png',NULL,'I22521','Edwyn_Tait','["Lerwick Town Councillors", "1885 Births", "1960 Deaths", "Natives of Shetland", "Councillors pictured"]',1,1,163057284);
INSERT INTO "people" VALUES(130,'Elizabeth Fullerton','elizabeth-fullerton','1949-11-23',NULL,NULL,NULL,'Elizabeth Laureen ''Betty'' Fullerton (neé Christie) was a Shetland Islands Councillor for the Shetland Central ward, representing the area from 2007 until 2012.',NULL,NULL,NULL,NULL,'Elizabeth_Fullerton','["Shetland Islands Councillors", "Natives of Shetland", "1949 Births", "Female"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(131,'Elizabeth Nicolson','elizabeth-nicolson',NULL,NULL,NULL,NULL,'Elizabeth Nicolson is a former Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'Elizabeth_Nicolson','["Shetland Islands Councillors", "Councillors - Missing All", "Female"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(132,'Eric Gray','eric-gray','1917-11-27','1977-11-15','Lerwick',NULL,'Eric Gray was a Lerwick Town Councillor from 1958 to 1975 and a Shetland Islands Councillor. He was a distant relative of [person:harry-gray:Harry Gray] who was also the Provost of Lerwick (6th cousin).','Eric entered the drapery trade in Lerwick at a young age, eventually becoming the proprietor of Smith & Robertson, where he continued to work until illness prevented him in 1977. He was called to service during WWI with the Royal Armoured Corps and joined the 2nd Battalion Royal Tank REgiment in Egypt. With the 7th Armoured Brigade, he went to Burma, landing at Rangoon as the country was falling to the Japanese army. The army were forced to retreat on foot over the Chin Hills to Assam, and Eric eventually travelled to Iraq, serving in Syria and Palestine before eventually returning to Egypt to take part in the Italian Campaign. He finished the war in Austria and Germany, returning back to Shetland in July 1946.','Eric Gray Provost.png','Eric Gray Headshot.png','I50075','Eric_Gray','["Lerwick Town Councillors", "Shetland Islands Councillors", "1917 Births", "1977 Deaths", "Councillors pictured"]',1,NULL,214397113);
INSERT INTO "people" VALUES(133,'Erling Clausen','erling-clausen','1904-06-03','1984-06-28','16 Christines Gade','Lerwick','Erling Johan Fredrik Clausen was an insurance supervisor and Lerwick Town Councillor. His father, Frederick Wilhelm Clausen, was a Norwegian shipbroker who married Elizabeth Stout.','Erling worked in the insurance industry, starting in 1927. By 1930, he was promoted to the rank of assistant superintendent for Orkney and Shetland. In 1937, he was appointed to be in charge of Caithness, Orkney and Shetland, and moved to Thurso, where he also join the Council there. In 1942, he was appointed to the rank of Pilot Officer in Thurso Air Training Corps. He was again promoted to superintendent and moved to Aberdeen in 1945 where he was the district manager. In 1951, he became the manager of the Aberdeen South district, where he continued working at the Prudential Assurance Co. Ltd. until 1964. Upon retirement, he moved back to Shetland. He was a keen historian, contributing articles to the newspaper such as an article titled Shetland''s Folk Have Long Proud Story in the Press and Journal on 17 June 1948. He was the district secretary of the Viking Society for Northern Research in 1954.','Eclausen.jpg',NULL,'I82682','Erling_Clausen','["Lerwick Town Councillors", "1904 Births", "1984 Deaths"]',NULL,1,290702442);
INSERT INTO "people" VALUES(134,'Eustace Bankart','eustace-bankart','1858-05-10','1902-05-12','Bolton','Melby House, Sandness','Eustace George Lowenthal Bankart was a farmer, stuff merchant and County Councillor.','The Shetland Archives has a record of a police report against Bankart for accidentally poisoning three dogs, and a subsequent letter of apology from him . His death was registered by [person:james-grierson:James Grierson] and his remains were taken south on the Ninian. He was eventually buried back in Bolton.',NULL,NULL,'I356985','Eustace_Bankart','["Zetland County Councillors", "1858 Births", "1902 Deaths"]',0,1,NULL);
INSERT INTO "people" VALUES(135,'Florence Grains','florence-grains','1932-11-02','2025-03-05','Whiteness','Walls','Florence Barbara Grains (neé Abernethy) is a former Shetland Islands Councillor first elected in 1978. She decided to retire from a lengthy council career in 2012.',NULL,NULL,NULL,'I38402','Florence_Grains','["Shetland Islands Councillors", "Natives of Shetland", "Female", "1932 Births"]',1,1,285734543);
INSERT INTO "people" VALUES(136,'Francis Halcrow','francis-halcrow','1854-03-22','1916-07-09','Lerwick','Lerwick','Francis Hardy ''Frank'' Halcrow was a Lerwick Town Councillor. The Shetland Times often recorded his middle name as ''Hardie''.','Frank''s father Laurence was a shoemaker in Lerwick, and Frank was educated at the Lerwick Parochial School. Upon leaving education, he joined the North of Scotland and Orkney and Shetland Steam Navigation Company, where he remained employed for his entire career, latterly as Chief Indoor Clerk. His obituary in the Shetland Times notes that "he never ceased to be in sympathy with the workers, in whom he took a special interest", indicating his left leaning political outlook.',NULL,NULL,'I89646','Francis_Halcrow','["Lerwick Town Councillors", "1854 Births", "1916 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(137,'Francis Pottinger','francis-pottinger','1875-04-20','1918-12-24','Gletness','Edinburgh','Francis Henry Pottinger was a commission agent and County Councillor for Cunningsburgh.','He worked first in The Shetland Times office, and later as a compositor in Edinburgh. While there he became a member of the Social Democratic Federation. He returned to Lerwick, to work again at The Shetland Times, and after a serious illness worked for his relative [person:john-robertson-iv:John W. Robertson] as a commission agent. He was elected to Lerwick School Board in 1904 as a socialist, and soon became chairman of it. He was a main actor in the formation of a branch of the Social Democratic Federation in Lerwick in 1905. He became a County Councillor in 1910, and served on many committees. During the war he became chairman of the Mainland District Committee. Plagued by poor health he died in Edinburgh on Christmas eve, 1918, aged 43. At the next County Council meeting the convener remarked: ‘For the attainment of a satisfactory housing scheme [in Lerwick] no one wrought harder than he and, indeed, his last work on earth was to accompany … myself to the Local Government Board Office [in Edinburgh], where he put before them the whole housing problem, and afterwards drafted the report which will be submitted to you today. That report, gentlemen, is a pathetic document, for at the end there is an unsigned space that will not now be completed, for he had “crossed the bar” before it was ready for signature, and it will remain in our archives as a perpetual reminder of a valiant and brave soul, who, notwithstanding the knowledge that the angel of death was hovering near … struggled on to the very last to fulfil his public duty.’',NULL,NULL,'I129724','Francis_Pottinger','["Zetland County Councillors", "1875 Births", "1918 Deaths"]',1,0,179137735);
INSERT INTO "people" VALUES(138,'Frank Robertson','frank-robertson',NULL,NULL,NULL,NULL,'Frank A. Robertson is a Shetland Islands Councillor for the Shetland West ward.',NULL,NULL,NULL,NULL,'Frank_Robertson','["Shetland Islands Councillors", "Councillors - Missing B/D"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(139,'Fraser Peterson','fraser-peterson','1936-10-13','1982-06-18','Brae','Aberdeen','Fraser Peterson was a crofter, County Councillor and Shetland Islands Councillor for Delting North between 1970 until his death in 1982.',NULL,NULL,NULL,'I20819','Fraser_Peterson','["Zetland County Councillors", "Shetland Islands Councillors", "1936 Births", "1982 Deaths", "Biography Missing"]',1,0,179138017);
INSERT INTO "people" VALUES(140,'Frederick Dainty','frederick-dainty',NULL,'2009-01-02',NULL,NULL,'Colonel Frederick Leonard ''Tiny'' Dainty was a seaman and County Councillor between 1973 and 1975 and a Shetland Islands Councillor between 1974 and 1978, on both occasions for Whalsay And Skerries.','In 1976, Dainty proposed banning BBC Gaelic TV in Shetland, stating "if we must have foreign programmes let them be in some language taught in our schools, such as French". Other councillors opposed this, with [person:william-smith-iv:Bill Smith] saying he would "not try to ban any programme for aimed at a minority group", with [person:john-johnson:John Johnson] adding "In any case, Colonel Dainty can hardly understand Shetland dialect never mind Gaelic".',NULL,NULL,NULL,'Frederick_Dainty','["Shetland Islands Councillors", "Zetland County Councillors", "2009 Deaths"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(141,'Frederick Dundas','frederick-dundas','1802-06-14','1872-10-26',NULL,NULL,'Frederick Dundas was a Member of Parliament for Orkney and Shetland.','Dundas was the son of the Hon. Charles Dundas, Member of Parliament for Malton, younger son of Thomas Dundas, 1st Baron Dundas. His mother was Lady Caroline, daughter of Aubrey Beauclerk, 5th Duke of St Albans.',NULL,NULL,NULL,'Frederick_Dundas','["Members of the Parliament of the United Kingdom", "Liberals"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(142,'Frederick Tait','frederick-tait','1893-01-10','1958-10-25','Clousta','Clousta, Aithsting','Frederick Bowie Tait was a Master Mariner and County Councillor for Aithsting from 1955 until his death in 1958. His first cousin, [person:james-bowie:James Bowie], was also a Zetland County Councillor.','Frederick went to sea as soon as he finished school, quickly gaining his mate and master''s certificates. As second officer he served for several years in the Ben Line then became a chief with William Thomsons. He would later become captain with the same firm. In WWII, he captained on the s.s. Boswell, where he had to sail the vessel Mulberry Harbour where it was scuttled to provide shelter. After the war, he was the captain of the Glenlyon between Australia and New Zealand.',NULL,NULL,'I60446','Frederick_Tait','["Zetland County Councillors", "1893 Births", "1958 Deaths"]',1,1,289026706);
INSERT INTO "people" VALUES(143,'Gary Cleaver','gary-cleaver',NULL,NULL,NULL,NULL,'Gary Cleaver is a Shetland Islands Councillor, representing the North Isles since 2012.','Gary runs a textile crafts business with his wife, as well as being a relief postman for the Royal Mail. Prior to moving to Shetland, Gary worked in the building trade and was a heavy goods vehicle driver.',NULL,NULL,NULL,'Gary_Cleaver','["Shetland Islands Councillors", "Incomers to Shetland", "Councillors - Missing B/D", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(144,'Gary Robinson','gary-robinson','1969-04-04',NULL,NULL,NULL,'Gary Robinson is a Shetland Islands Councillor for the Shetland West ward. Robinson is the current Political Leader of the Council.',NULL,NULL,NULL,NULL,'Gary_Robinson','["Shetland Islands Councillors", "Conservatives", "Natives of Shetland", "1969 Births"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(145,'George Anderson','george-anderson','1880-12-19','1946-02-10','Lunnasting','St. Mary Abbotts Hospital, Kensington, London','George Theodore Anderson was a bookseller, stationer and County Councillor for Burra from 1920 until 1922.','',NULL,NULL,'I34645','George_Anderson','["Zetland County Councillors", "1880 Births", "1946 Deaths", "Biography Missing"]',1,0,NULL);
INSERT INTO "people" VALUES(146,'George Blance','george-blance','1905-06-09','1977-03-11','Lerwick','Lerwick','George William ''Dodie Willie'' Blance was Headmaster of the Lerwick Central School, Lerwick Town Councillor, Convener of the Zetland County Council from 1973 until it''s dissolution in 1975, the Guizer Jarl for the 1950 Lerwick Up Helly Aa and helped pioneer the Lerwick Junior Up Helly Aa.','In his youth, George was an active football player who represented Shetland in inter-county games, and after his time on the pitch came to an end, he became the President of the Shetland Football Association. In the 1930s, George was appointed as headmaster of the Lerwick Central School, and held that post until 1966. He was Guizer Jarl in 1950. During WWII, he was in command of the Air Cadets, and the chairman of the organisation committee that raised money for charity. As Convener, it was George''s signature on the document that saw the Shetland Islands benefit immensely from the oil trade.',NULL,NULL,'I70416','George_Blance','["Lerwick Town Councillors"]',1,1,214369251);
INSERT INTO "people" VALUES(147,'George Burgess','george-burgess','1894-11-26','1969-04-05','England','Lerwick','George Henry Burgess O.B.E. was a wholesale grocers manager and Lerwick Town Councillor.','George was educated at the Lerwick Central School, and became an assistant reporter at the Shetland News until he was called to service in WWI with the 7th Gordon Highlanders. He was captured as a prisoner of war in 1918 and remained as such in France until the Armistice. After the war, he returned to the Shetland News, and later joined Messrs Aitken & Wright, wholesale merchants where he became manager, retiring in June 1968. He received an O.B.E in 1960 connection with his work to expand the Lerwick Harbour. After the war, George was involved in compiling the 600+ Roll of Honour, and was an official of the Earl Haig Fund, which gave grants to families without a breadwinner. He was the Lerwick Guizer Jarl in 1922.','George Burgess Provost.png','George_Burgess_Headshot.png','I180046','George_Burgess','["Lerwick Town Councillors", "Councillors pictured", "1894 Births", "1969 Deaths"]',0,1,203599160);
INSERT INTO "people" VALUES(148,'George Clark','george-clark','1844-05-14','1922-10-05','Muthil','Dumfries','Reverend George Clark was a minister for the Free Kirk in Cunningsburgh from 11 September 1875 to 1900, then United Free Kirk from 1900 until 23 May 1908. He was also a County Councillor for Cunningsburgh from 1890 until 1896.','Clark was a supporter of the local crofters and working men in Cunningsburgh. He successfully abetted [person:sinclair-duncan:Sinclair T. Duncan] in defending the whalers in the Hoswick Whale Case, and also testified in the Napier Commission in 1883.',NULL,NULL,'I356872','George_Clark','["Zetland County Councillors", "Councillors - Clergymen", "1844 Births", "1922 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(149,'George Douglas','george-douglas','1662','1738-01-04','-',NULL,'George Douglas, 13th Earl of Morton, was a Member of the Parliament of the United Kingdom for Orkney and Shetland and a Scottish nobleman. He was elected to represent the Isles in 1713. He was the 2nd MP for the constituency, replacing [person:alexander-douglas:Sir Alexander Douglas], and served until 1715, when he was replaced by [person:james-moodie:James Moodie] He was elected to the seat again in 1722 and served until 1730 when he was replaced by [person:robert-douglas:Robert Douglas].','Morton was a younger son of James Douglas, 10th Earl of Morton, and Anne, daughter of Sir James Hay, 1st Baronet.',NULL,NULL,NULL,'George_Douglas','["Members of the Parliament of Great Britain"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(150,'George Duffin','george-duffin','1862','1936-06-28','Winchester, Hampshire, England','Lerwick','George Herbert Duffin was an insurance manager and Lerwick Town Councillor firstly between 1920 and 1934, being an unsuccessful candidate in the latter, before returning in 1935 until his death in 1936.','George arrived in Shetland around 1911 from Forfar as the District Manager for the Pearl Assurance Company for Orkney and Shetland. After some time, he relinquished the joint office when Orkney was instead connected to Wick, remaining as the a Manager for Shetland. While in the council, he was an advocate for the introduction of municipal electricity, and was Convener of the Electricity Committee. A keen sportsman, he was responsible for instituting a Sports Day at Gilbertson Park.',NULL,NULL,'I80203','George_Duffin','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1862 Births", "1936 Deaths"]',0,1,290676348);
INSERT INTO "people" VALUES(151,'George Dundas','george-dundas','1778-09-08','1834-10-07',NULL,NULL,'Rear Admiral George Heneage Lawrence Dundas CB was a senior officer in the Royal Navy and Member of Parliament for Orkney and Shetland. As a junior officer he came to prominence due to his brave conduct during a fire on the first-rate HMS Queen Charlotte. As a result of this he was appointed to the command of the sixth-rate HMS Calpe in which he took part in the Battle of Algeciras Bay in July 1801 during the French Revolutionary Wars. After serving for four years as Whig Member of Parliament for Richmond, he was given command of the fifth-rate HMS Euryalus and took part in the unsuccessful Walcheren Campaign in July 1809 during the Napoleonic Wars. He transferred to the third-rate HMS Edinburgh and landed troops at Viareggio in Italy in November 1812 later in that War. He went on to be Member of Parliament for Orkney and Shetland and became First Naval Lord in the First Melbourne ministry in August 1834 but died in office just two months later in October 1834.','<strong>Early career</strong>

Born the fifth son of Thomas Dundas (created Baron Dundas in 1794) by his wife Charlotte Dundas (daughter of William Fitzwilliam, 3rd Earl Fitzwilliam), Dundas became a lieutenant in the Royal Navy in 1797 and served for several years with the Mediterranean Fleet.

<strong>HMS Queen Charlotte</strong>

In February 1800 Dundas was aboard Lord Keith''s flagship, the first-rate HMS Queen Charlotte. Dundas was junior to Lieutenant Lord Cochrane but Cochrane had taken command of Nelson''s prize, the Genereaux, in late 1799 to take her into port; Dundas therefore became 5th Lieutenant of the Queen Charlotte. One month later, early in the morning of 17 March 1800, cries of "Fire" rang out throughout the vessel. Some hay lying under the half-deck had been set on fire by a match kept there for the signal guns. Dundas was in the forecastle where he organized fire-fighting efforts. Dundas led a party below decks where they secured the main and fore hatches and then opened the lower-deck ports and the sea cocks to flood the lower decks to prevent the fire spreading down. These efforts delayed the fire from reaching the two magazines. Dundas continued working below decks until some middle-deck guns fell through the deck. At about 9am Dundas climbed out the foremost lower-deck port and climbed up to the forecastle, joining the about 150 men there who were throwing water on the fire. Despite the crew''s exertions, the Queen Charlotte eventually blew up with the loss of 673 people out of its complement of 840 officers, men and boys, including the Captain and her first Lieutenant. Dundas however survived.

<strong>HMS Cameleon</strong>

By 14 June 1800 Dundas was captain of the sloop Cameleon. She and Salamine shared in the capture on that day of the Genoese brig Anima Purgatoria, which was sailing from Bastia to Salcolight.[5]

<strong>HMS Calpe</strong>

Next, Dundas was appointed to the command of the sixth-rate HMS Calpe. On the night of 27 October 1800, Francis Beaufort, inventor of the Beaufort Wind-Scale, had led Phaeton''s boats on a cutting out expedition. They captured the San José, alias Aglies, of 14 guns, which they immediately re-commissioned under the name of HMS Calpe, the ancient name of Gibraltar. Although it would have been usual to promote Beaufort, the successful and heroic leader of the expedition, to command Calpe, Lord Keith chose instead to promote Dundas who not only was not present at the battle, but was junior to Beaufort. Dundas was promoted to commander in December 1800. In July 1801 Dundas was in command of Calpe at the Battle of Algeciras Bay. After the third-rate HMS Hannibal grounded, Dundas, deceived by a signal from her, sent his boats to save Hannibal''s crew. The French detained the boats and their crews, including Calpe''s lieutenant, Thomas Sykes; after firing several broadsides at the enemy''s shipping and batteries, Dundas and Calpe returned to Gibraltar. In the subsequent second phase of the Battle of Algeciras Bay, the two Spanish first-rates Real Carlos and Hermenegildo fired upon each other during the night, caught fire and exploded, with tremendous loss of life. The British captured the third-rate St Antoine, with Superb and Calpe then assisting in securing the prize and removing the prisoners. Rear Admiral James Saumarez promoted Dundas to post-captain on 9 August 1801 and Dundas took command of St Antoine, which he sailed back to England.

<strong>Politics</strong>

After the peace of 1802, Dundas entered politics becoming Whig Member of Parliament for Richmond in the 1802 general election but resigned in February 1806, using the device of applying to be Steward of the Manor of East Hendred, to take up an offer of a naval command again and to allow his brother, Charles, to enter Parliament. In February 1805 he was given command of the fifth-rate HMS Quebec.

<strong>HMS Euryalus</strong>

In January 1806 Dundas took command of fifth-rate Apollo class frigate HMS Euryalus. Euryalus was asked, along with HMS Ocean and several other warships to act as escorts to a large convoy bound for Oporto, Lisbon and the Mediterranean. Towards the end of 1807 Euryalus returned to England with Niger as escort to a convoy of several thousand troops under Sir John Moore from Gibraltar. She went into dock at Plymouth for a refit and was then stationed in the North Sea. She carried the Duke d''Angoulême from Yarmouth to Gottenburg and escorted the Baltic convoys through the Great Belt. In June 1808 Dundas discovered several vessels at anchor at the entrance of Nakskov close into the shore. He anchored and sent four boats to destroy them. They burnt two large troop transports and captured a gun-vessel armed with two 18-pounders and carrying 64 men. The enemy lost seven men killed and twelve wounded, as well as many drowned; the British had one man slightly wounded. During the same year Dundas went to Elbing, a small port in West Prussia about 60 kilometers east of Dantzig (now in Poland) to embark Princess Marie Josephine Louise of Savoy (the consort of Louis XVIII), the Duc du Berry and other members of the French royal family. He took them to Carlscrona in southern Sweden and, after re-embarking them at Gottenburg, finally to Harwich. Dundas was also involved in the Walcheren Campaign in July 1809 when a British armed force of 39,000 men landed on Walcheren. Euryalus joined the squadron which forced the passage of the Scheldt between the batteries at Flushing and Cadsand on 11 August 1809. Euryalus had no casualties although two men were killed and nine wounded in the other ships. Later she was stationed off Cherbourg under the orders of Captain Sir Richard King, and in November 1809 she captured the French privateer lugger Etoile of 14 guns and 48 men. In the spring of 1810 Euryalus escorted a large convoy from Spithead to Portugal and the Mediterranean and was then attached to Captain Blackwood''s inshore squadron off Toulon. Early in 1811 Dundas temporarily took command of the 74-gun Third Rate Achille until relieved by Captain Aiskew Paffard Hollis, who had transferred from Standard. Dundas then returned to Euryalus. On 7 June 1811 the boats of Euryalus and Swallow captured the French privateer Intrepide off Corsica after a long chase. She had a crew of 58 and was armed with two 8-pounders. Dundas became Member of Parliament for Richmond again at a by-election in 1812 but was defeated at the 1812 general election.

<strong>HMS Edinburgh</strong>

In October 1812 Dundas transferred to the 74-gun Third Rate Edinburgh. In 1813 Dundas and Edinburgh were in the Mediterranean. On the morning of 5 October, Edinburgh joined Capt. Duncan of Imperieuse off Porto D''Anzo where he and Resistance, Swallow, Eclair and Pylades had been watching a convoy for some days with the intention of attacking it. The place was defended by two batteries mounting three heavy guns each on the mole, a tower with one gun and a battery with two guns. During the attack in the afternoon, Edinburgh supported Eclair and Pylades as they bore up against the battery to the south. After the ships opened fire, landing parties brought out the 29 vessels of the convoy, 20 of which were laden with wood for the arsenal at Toulon. All the works were blown up. On 30 November 1812 Dundas was placed in command of a small squadron consisting of Edinburgh, Furieuse and Termagant which landed troops at Viareggio in Italy. Some 600 cavalry and infantry from the Livorno garrison attacked the British troops, who routed them, capturing two field pieces and a howitzer. From the prisoners they learned of the weak state of the garrison and asked to be re-embarked to be taken to Livorno. The British troops and Marines landed on the evening of 13 December and they occupied the suburbs of the town. Some 700 cavalry and infantry attacked the marines, who opened to let the cavalry pass through them. The marines charged, killing, wounding or taking prisoner between 250 and 300 men. Edinburgh had just three marines wounded.',NULL,NULL,NULL,'George_Dundas','["Members of the Parliament of the United Kingdom"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(152,'George Hay','george-hay','1828-08-16','1890-11-13','Lerwick','Edinburgh','George Husband Baird Hay was a deputy lieutenant, convener of the county, benefactor to the Earl of Shetland and a Lerwick Town Councillor between 1856 and 1862 and later from 1879 to 1882. Both his father [person:william-hay:William] and brother [person:arthur-hay:Arthur] were Councillors.','He became the Head of Hay and Co in 1858 at age 30, following the death of his father, [person:william-hay:William]. He was chairman of the Parochial Board for many years, and chairman of the School Board during the first two terms of its existence; chairman of the Shetland Islands Steam Company; and of the Gas-Light Company. He was also chairman of the Road Trustees and consequently exofficio member of the County Council, was a Justice of the Peace, latterly of Deputy Lieutenant for the County, and Vice-Consul for France.',NULL,NULL,'I6284','George_Hay','["Lerwick Town Councillors", "1828 Births", "1890 Deaths", "Hay"]',1,0,163057268);
INSERT INTO "people" VALUES(153,'George Hoggan','george-hoggan','1875-11-09','1955-06-04','Lasswade','Brandon, Manitoba, Canada','George William Hoggan (or Hogan) was a solicitor in Lerwick and a County Councillor for Yell South between 1910 and 1919.','George was elected in 1904 to the Bonnyrigg Town Council, and re-elected in 1907. He arrived in Shetland in the summer of 1908, having acquired a legal practice in Shetland. In June 1908, he was appointed as secretary and treasurer of the Zetland Unionist Association. In WWI, he was in the Anson Battalion and he was stationed in Aldershot and Chatham.','GeorgeHoggan.png',NULL,'I163859','George_Hoggan','["Zetland County Councillors", "1875 Births", "1955 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(154,'George Jamieson','george-jamieson','1870-12-01','1932-04-14','Cullivoe','Bayanne House, Sellafirth, Yell','Captain George Jamieson was a master mariner and County Councillor for Yell North first 1919 and 1922 then 1929 until his death.','George began his career at sea as a young lad and quickly rose to the rank of Captain in the Merchant Navy. In WWI, he was a Lieutenant in the Royal Navy, serving mostly in the Mediterranean. After the war, he returned to Yell and purchased Bayanne House, where he continued to maintain the farm and kept livestock. He returned to the sea again until his retirenemt in 1925.',NULL,NULL,'I9924','George_Jamieson','["Zetland County Councillors", "1870 Births", "1932 Deaths"]',1,1,291847702);
INSERT INTO "people" VALUES(155,'George Johnston','george-johnston','1869-03-21','1909-06-08','Wadbister','Tresta','George Johnston was a merchant and a County Councillor for Aithsting between 1896 and December 1898.','George ran a shop in Tresta, which had been founded by his grandfather. George owned considerable land around Tresta and Gruting. His shop was licenced to sell alcohol until the Temperance vote. For some years, George also ran the post office in Tresta, as well as a restaurant.',NULL,NULL,'I50720','George_Johnston','["Zetland County Councillors", "1869 Births", "1909 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(156,'George Kay','george-kay','1862-03-17','1931-05-13','Lerwick','Edinburgh','George Goudie Kay was a Lerwick Town Councillor.','A son of David Kay, who worked for [person:joseph-leask:Joseph Leask]''s business, George was educated at the Anderson Institute, and after leaving education he apprenticed in the drapery trade in Glasgow, and upon returning to Lerwick, joined Leask''s business. When Joseph died in 1882, George and his brother David bought the business and operated a grocery and drapery business on Commercial Street (where the Grand Hotel is), trading under the name Messrs D. & G. Kay. When George retired in 1925, he moved to Edinburgh and periodically visited Lerwick. In his youth Kay was a socialist, perhaps the first in Shetland: he subscribed to William Morris''s journal Commonweal in the 1880s; later in life he became a staunch Conservative.',NULL,NULL,'I45581','George_Kay','["Lerwick Town Councillors", "1862 Births", "1931 Deaths"]',1,0,166072321);
INSERT INTO "people" VALUES(157,'George Laurence','george-laurence','1810-11-02','1885-09-02','Lerwick','Lerwick','George Laurence was grocer, plumber, auctioneer and Lerwick Town Councillor. At age 13 in 1823, George left Shetland to learn the plumbing trade, returning to the Isles in 1834 to practice his calling in Lerwick. At that point, he was the only plumber in Shetland, and was employed by many Lairds and other large homeowners throughout the Isles. The introduction of gas lamps in Lerwick in 1856 provided much work for George. In 1837, he opened a grocery business situated around 69 Commercial Street. In 1859, he opened a drapery at the site of Queen''s Lane (that site is now occupied by the Royal Bank of Scotland). He started work as an auctioneer in 1849, taking over from James Bain. His first sale, on 5th November of that same year, was a memorable one. It was a cattle sale but a huge storm hit Shetland (causing the loss of several lives), and made George consider giving up the gig. At the time of his death, George was the oldest merchant in Lerwick.',NULL,NULL,NULL,'I86837','George_Laurence','["Lerwick Town Councillors", "1810 Births", "1885 Deaths"]',1,1,269948555);
INSERT INTO "people" VALUES(158,'George Leslie (i)','george-leslie-i','1870-12-28','1950-12-08','Dunrossness','Laxfirth, Tingwall','George Leslie,, was farmer and County Councillor for Whiteness and Weisdale from 1925 until 1928.','For most of his life, George operated the Laxfirth farm, assisted by his sons, where he became one of Shetland''s leading milk suppliers. He also farmed sheep and bred some ponies. George was a founding member of the Shetland Agricultural Society, acting as President from 1926 until his death.',NULL,NULL,'I76548','George_Leslie_(i)','["Zetland County Councillors", "1870 Births", "1950 Deaths"]',1,1,284534630);
INSERT INTO "people" VALUES(159,'George Leslie (ii)','george-leslie-ii','1902-04-10','1970-03-09','Quendale','Barbados','George William Brand Leslie was a hotelier, fisherman and County Councillor for Dunrossness South between 1937 and 1945.','George was the proprietor of the Sumburgh Hotel around and during WWII. He was also a pioneering fisherman. In 1938 with the herring fishing in the doldrums, and before electronic fish-finding equipment became available, with the help of his brother in law Sam Reid who owned and piloted a small de Havilland DH 85 Leopard Moth plane, G-ACXH, they would fly over potential herring grounds during the summer season, and identify shoals of herring. Then relay their positions to fishing boats by either dropped message, or by phone to those ashore at the time, after landing at Sumburgh Airport. The experiment proved reasonably successful, and would probably have continued for some time had WWII not interrupted during the following year. He was Skipper of the Betty Leslie (LK497) during the later 1940''s and 1950''s, which was the largest vessel in the local fleet at the time, and claimed in some quarters to have been the U.K''s first purse net vessel. With her, in addition to participating in the summer herring season, and from 1945 - 1955 also the winter herring season off the coast of England, in 1955-57 he undertook voyages to Rockall, off the west coast of Scotland and to Faroe to engage in line fishing for whitefish. Experimental shark fishing was also undertaken by the vessel.',NULL,NULL,'I174106','George_Leslie_(ii)','["Zetland County Councillors", "1902 Births", "1970 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(160,'George Linklater','george-linklater','1771-02-06','1818-07-05','Tingwall','Lerwick','George Linklater was a merchant in Lerwick and the first junior magistrate to the Lerwick Town Council in April 1818, however this was short lived as he passed away a mere three months after getting elected. [person:joseph-leask:Joseph Leask] was a trainee at Linklater''s business.',NULL,NULL,NULL,'I64804','George_Linklater','["Lerwick Town Councillors", "1771 Births", "1818 Deaths", "Merchants", "Died in Office", "Linklater"]',1,1,NULL);
INSERT INTO "people" VALUES(161,'George Morrison','george-morrison','1921-02-09','1989-01-30','Weisdale',NULL,'George William ''Dodie'' Morrison (b. 9 February 1921, Weisdale, d. 30 January 1989, Lerwick was an auctioneer and County Councillor for Sandness between 1970 and 1973. He was a 3rd cousin to Lerwick shop owner and councillor [person:alexander-morrison:Alex].','George lived his entire life in Weisdale, and grew up with socialist political convictions. His abiding interest was agriculture, who bred sheep, supported the Shetland flock book supported the Shetland Wool Growers Cooperative. He was involved in the Shetland branch of the National Farmers Union from its early days in the 1960s. He was an auctioneer who specialised in sheep sales',NULL,NULL,'I126045','George_Morrison','["Zetland County Councillors", "Councillors pictured"]',1,NULL,245844647);
INSERT INTO "people" VALUES(162,'George Nelson','george-nelson','1901-10-07','1976-12-31','South Califf','Edinburgh','George Maxwell Nelson M. B. E. was an author, farmer, builder, taxi driver, and County Councillor for Burra between 1964 and 1970. He was the author of The Story of the Tingwall Kirk and he also built Herrislea House Hotel.','He was the second child of George Nelson (b. 27 September 1867, South Califf) and his wife Agnes Henderson (b.11 August 1868, Dunrossness. He married Catherine Ann Jane Jamieson (b. 22 October 1905, Scalloway) on the 16th of January, 1924. They had three children, Agnes Margaret, Elizabeth Ann and George Thomas Nelson. Prior to moving to Tingwall, the Nelson family were resident for generations at Brough (Bressay), their surname being originally Neilson. In his book Traditional Life in Shetland, James Nicolson wrote of George: &quot;His death in December 1976 robbed the islands of one of their most noted authorities on all aspects of traditional life.&quot;','George Nelson.png','George Nelson Headshot.png','I61169','George_Nelson','["Zetland County Councillors", "Councillors pictured", "1901 Births", "1976 Deaths"]',1,0,179137548);
INSERT INTO "people" VALUES(163,'George Pottinger','george-pottinger','1944-01-19',NULL,'Burra',NULL,'George William Pottinger is a former Shetland Islands Councillor for Burra between 1990 and 1994.',NULL,NULL,NULL,'I193675','George_Pottinger','["Shetland Islands Councillors", "Natives of Shetland", "1944 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(164,'George Ross','george-ross','1901-05-02','1974-05-12',NULL,'Gilbert Bain Hospital, Lerwick','George Ross was a County Councillor for Tingwall between 1945 and 1950.','George was the owner of confectioners in Scalloway, beginning trade in the early 1920s. In 1937, he and his wife acquired the Shetland Knitwear Company and in 1943 they bought Nicolson & Co. The family left Shetland in 1950 to take over the Stonefield Castle Hotel near Tarbert. He died in Shetland while on visiting on holiday. He lived in Thule Cottage in Scalloway, his parents property which they both passed away in between 1948 and 1950.',NULL,NULL,'I70614','George_Ross','["Zetland County Councillors", "1901 Births", "1974 Deaths"]',NULL,1,NULL);
INSERT INTO "people" VALUES(165,'George Sinclair','george-sinclair','1839-12-23','1908-09-28','Hillock','Hawick','George Sinclair was a merchant and County Councillor for Northmavine North between 1892 and 1897.','Sinclair had an extensive business in Ollaberry, the Shetland Tweed Manufacturers. He resigned from the council in 1897 and left Shetland he went to manage a farm in South Wales, but then later settled with his family in New York before finally moving to Hawick. He was Chairman of the Northmavine School board for a time.',NULL,NULL,'I69883','George_Sinclair','["Zetland County Councillors", "1839 Births", "1908 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(166,'George Smith (i)','george-smith-i','1822-12-01','1873-06-06','Inverarity','Lerwick','George Smith was a Sheriff Clerk of Shetland and a Lerwick Town Councillor.',NULL,NULL,NULL,'I17098','George_Smith_(i)','["Lerwick Town Councillors", "1828 Births", "1873 Deaths"]',0,1,176126080);
INSERT INTO "people" VALUES(167,'George Smith (ii)','george-smith-ii','1875-08-19','1957-02-21','Glasgow','1 Landale Road, Peterhead','Reverend George Smith was a minister for the United Free Church and a County Councillor for Gulberwick between 1936 and 1945.','He was ordained in 1929 and served until 1948, representing a wide variety of parishes in the south of Shetland and Lerwick. In 1948 he moved to Aberlour. He left there in 1952 and was minister emeritus.','Revgeorgesmith.JPG',NULL,NULL,'George_Smith_(ii)','["Zetland County Councillors", "Councillors - Clergymen", "1875 Births", "1957 Deaths"]',0,0,184606144);
INSERT INTO "people" VALUES(168,'George Smith (iii)','george-smith-iii',NULL,NULL,NULL,NULL,'George Smith is a current Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'George_Smith_(iii)','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(169,'George Spence','george-spence','1914-09-15','1971-10-12','Reafirth','Scalloway','George Keith Spence was a hotel proprietor and County Councillor, representing Yell South between 1949 and 1950, then Tingwall from 1950 until 1964.','George was the proprietor of the Scalloway Hotel, acquiring the re-opening the premises in August 1948 after its requisition for war time use in WWII. He remained the owner of the hotel until his death.',NULL,NULL,'I12991','George_Spence','["Zetland County Councillors", "1914 Births", "1971 Deaths"]',1,1,179953719);
INSERT INTO "people" VALUES(170,'George Tait','george-tait','1829','1889-07-08','Lerwick','Lerwick','George Reid Tait was a draper, shipping agent and Lerwick Town Councillor between 1856 and 1862, and again between 1874 and 1876, with the final 3 years as the junior baillie. He was the father of Lerwick councillor [person:edwyn-tait:Edwyn Tait].','At the age of 14, George started working at his father, Laurence''s shop. He eventually took over the business and ran it for a long period. After retiring from that position, he spent a few years in retirement before returning to work as a draper and shipping agent, which he continued doing until his death. After the resignation of [person:charles-laurenson:Charles Laurenson], Tait was appointed as the Belgian Consul at Lerwick. He was Master of the Viking Lodge of Masons. Politically, he was described as "lattery a Conservative".',NULL,NULL,'I10054','George_Tait','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1829 Births", "1889 Deaths"]',1,1,163057287);
INSERT INTO "people" VALUES(171,'George Traill','george-traill','1787-11-05','1871-09-29',NULL,NULL,'George Traill was a Liberal Party Member of Parliament for Orkney and Shetland.',NULL,NULL,NULL,NULL,'George_Traill','["Members of the Parliament of the United Kingdom", "Liberals"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(172,'Gilbert Duncan','gilbert-duncan','1787','1844-02-19','Anness, Cunningsburgh','Lerwick','Gilbert Duncan was a solicitor in Lerwick, the first Town Clerk and a Lerwick Town Councillor between 1820 to 1829, 1832 to 1838 until his death in 1844. He was the father of Lerwick Town Councillor [person:charles-duncan:Charles Gilbert Duncan] and brother of fellow councillor [person:andrew-duncan:Andrew]. He was married to Elizabeth Ogilvy, daughter of [person:charles-ogilvy-i:Charles] and brother of [person:charles-ogilvy-ii:Charles], both councillors.',NULL,NULL,NULL,'I10510','Gilbert_Duncan','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "Solicitors", "1787 Births", "1844 Deaths", "Natives of Shetland", "Duncan"]',1,1,NULL);
INSERT INTO "people" VALUES(173,'Gilbert Gauden','gilbert-gauden','1779-11-10','1860-07-12','Fetlar','Unst','Gilbert Gauden was a Lerwick Town Councillor between 1818 and 1826.','Gilbert came from the Gauden of Swinister and Overland family. Shetland author Gilbert Goudie in his book The Celtic and Scandinavian Antiquities of Shetland links the Gauden family to Princess Marjorie Bruce (p. 203). Gilbert was in fact the 16th Great Grandson of Princess Marjorie Bruce.',NULL,NULL,'I17134','Gilbert_Gauden','["Lerwick Town Councillors", "Natives of Shetland", "1779 Births", "1860 Deaths", "Gauden"]',1,1,NULL);
INSERT INTO "people" VALUES(174,'Gilbert Harrison','gilbert-harrison','1832-06-12','1912-05-14','Baltasound','Lerwick','Gilbert Harrison was a wine and spirit merchant, and a Lerwick Town Councillor. His son-in-law, [person:john-robertson-iv:John W. Robertson], was Convener of the Zetland County Council and his grandson, [person:lindsay-robertson:Lindsay Robertson], was a councillor for Unst North.','He was for 16 years a Trustee of the Feuars and Heritors and in the council he was the chair of the Lighting and Cleansing Committee for many years.','Gilbert Harrison.png',NULL,'I42909','Gilbert_Harrison','["Lerwick Town Councillors", "1832 Births", "1912 Deaths", "Councillors pictured"]',1,1,175911653);
INSERT INTO "people" VALUES(175,'Gilbert Paterson','gilbert-paterson','1793','1828-04-05','Tingwall','Lerwick','Gilbert Paterson was a merchant and Lerwick Town Councillor. He owned property in the site now occupied by the Grand Hotel in Lerwick.',NULL,NULL,NULL,'I18013','Gilbert_Paterson','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1793 Births", "1828 Deaths"]',1,1,163057192);
INSERT INTO "people" VALUES(176,'Gilbert Robertson','gilbert-robertson','1785-07-01','1857-11-28','North Setter','Lerwick','Gilbert John Robertson was a clothier, merchant and a Lerwick Town Councillor.',NULL,NULL,NULL,'I22434','Gilbert_Robertson','["Lerwick Town Councillors", "1785 Births", "1857 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(177,'Gilbert Tait','gilbert-tait','1789','1860-05-03','Fetlar','Lerwick','Gilbert Tait was a general merchant and Lerwick Town Councillor between 1835 until his death in 1860. Gilbert was the great-grandfather of [person:thomas-manson-ii:Thomas Mortimer Yule Manson].',NULL,NULL,NULL,'I5307','Gilbert_Tait','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1789 Births", "1860 Deaths"]',1,1,291929036);
INSERT INTO "people" VALUES(178,'Gordon Mitchell','gordon-mitchell',NULL,NULL,NULL,NULL,'Gordon Gilbert Mitchell is a former Shetland Islands Councillor who represented Dunrossness from 2003 until 2007.',NULL,NULL,NULL,NULL,'Gordon_Mitchell','["Shetland Islands Councillors", "Natives of Shetland", "1937 Births", "Councillors - Missing B/D", "Councillors - Missing Birth Date"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(179,'Gordon Walterson','gordon-walterson','1929-11-08','2019-08-27','Sandness',NULL,'Captain Gordon Arthur Walterson is a former Master Mariner Shetland Islands Councillor who represented Sandness and Walls from 1978 until 1986.',NULL,NULL,NULL,'I72193','Gordon_Walterson','["Shetland Islands Councillors", "Natives of Shetland", "1944 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(180,'Grace Halcrow','grace-halcrow','1916-06-01','1999-01-19','Glasgow','Lerwick','Grace Muriel Thomson Halcrow, was a teacher in Cunningsburgh, a County Councillor for the same area between 1955 and 1961, and a Lerwick Town Councillor from 1957 till the late 1960s. Although standing as an independent candidate in these elections, Halcrow was a stalwart of the Conservative cause in Shetland.','Grace was born in Glasgow after her parents had moved there 5 months prior. At the age of one, she was afflicted by polio which caused a lifelong disability. Despite her tough start, she was an accomplished student, at one point placing in the top 30 in a West of Scotland bursary competition, later emerging from Glasgow University with a First Class degree in Classics. She wanted to be a teacher by 1939, but found that barriers were put up by others due to her disability. She arrived back in Shetland in February 1942, helping to organise the call-up of women during WWII. She was 29 at the end of the war, she hoped to join the Civil Service but was denied by her age. She travelled to London after passing the appropriate examinations, only to be told by officials that she would not be able to do the work that Grace herself believed she had been doing for years anyway. She didn''t get to join the civil service, and instead got a job with the Zetland County Council in the motor taxation department. A staunch trade unionist, Grace commissioned the National and Local Government Officers'' Association to fight a grading appeal for her, a battle she only half won and subsequently resigned, spending her remaining career knitting for local merchants. She had an interest in politics from a young age, making her first speech in Glasgow aged 13 against a Scottish nationalist. She joined the Conservative party in 1950, and acted as sub-agent for countless prospective Conservative candidates.

<strong>Shetland and Norway</strong>

Upon the discovery of the charter in which King Christian 1 of Denmark, Sweden and Norway pledged Shetland in 1469 for 8000 Rhenish florins to James III of Scotland, Grace said "I hope that Britain will wake up to the fact that if Norway chooses to exert her undoubted rights it would be fantastically easy for her to take Shetland back". At a meeting of the Orkney and Zetland Association, Grace described Shetland as "the illegitimate foundling of the United Kingdom, knowing that we had rights, but unable to produce the one vital document which was the foundation on which our rights depended." Grace lamented that had the document been discovered before the unearthing of the St. Ninian''s Treasure, a legal challenge may have prevented the treasure from leaving Shetland. (Glasgow Herald, Mar 11 1968).

<strong>Resignation of Norman Lamont</strong>

In the 1990''s, Grace was the honorary president of the Shetland Conservative Association. When Shetland-born Norman Lamont resigned from Conservative Government in 1993, she said: "I am rather sorry as he has had a very, very difficult time of it. Nobody could be popular in that job. He had to do things which people didn''t like, like the heating tax. Having a Shetland Chancellor was really a very nice thing."',NULL,NULL,'I156949','Grace_Halcrow','["Lerwick Town Councillors", "Zetland County Councillors", "Female", "1916 Births", "1999 Deaths"]',0,1,NULL);
INSERT INTO "people" VALUES(181,'Greta McElvogue','greta-mcelvogue','1937-03-27',NULL,'Manchester',NULL,'Greta Mary McElvogue (neé Fletcher) is a former Shetland Islands Councillor for the Nesting and Lunnasting constituency from 1990 to 1999.',NULL,NULL,NULL,'I206223','Greta_McElvogue','["Shetland Islands Councillors", "Incomers to Shetland", "1937 Births", "Female"]',0,NULL,NULL);
INSERT INTO "people" VALUES(182,'Hamish Brydone','hamish-brydone','1917-07-10','1979-10-30','Kenmore','Glasgow','Reverend Hamish Alistair Stewart Brydone was a minister and County Councillor for Northmavine North between 1955 and 1964','He served the Parish of Northmavine for the Church of Scotland from 1951 until resigning in 1970 to take up the position of Assistant Clerk of the Presbytery of Glasgow on August 31. At the time of his resignation in 1970, he was the longest-serving Church of Scotland Minister, with his service including Banffshire, New Zealand and Shetland.',NULL,NULL,'I115884','Hamish_Brydone','["Zetland County Councillors", "Councillors - Clergymen", "1917 Births", "1979 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(183,'Harry Drever','harry-drever','1905-10-28','1997-07-19','South Ronaldsay','Lerwick','Harry Sinclair Drever was a bank manager and County Councillor for Walls between 1960 and 1970.','Harry served his apprenticeship in the St Margaret''s Hope branch of the Union Bank of Scotland in Orkney. He worked in Edinburgh, Glasgow and Lerwick up until the outbreak of WWII. During the war, he joined the Air Sea Rescue Service of the Royal Air Force and found himself stationed all around the UK coast, including in Northern Ireland and at Sullom Voe. After demobbing in 1946, he rejoined the bank and in 1950 was transferred to the Lerwick branch. While under his management, the Union Bank merged with the Bank of Scotland. Harry continued to work in the bank until he retired in 1970. He held a number of roles on public bodies in retirement, including as Chairman of the Shetland Health Board and Shetland Territorial Association and treasurer to the British Red Cross Society among many others.','Drever-etal.jpg',NULL,'I114602','Harry_Drever','["Zetland County Councillors", "1905 Births", "1997 Deaths", "Orcadians"]',0,1,214682803);
INSERT INTO "people" VALUES(184,'Harry Gray','harry-gray','1909-05-01','1980-04-04',NULL,'Lerwick','Harry Gray was a Lerwick Town Councillor initially between 1953 then following a by-election, 1959 to 1975 He was the first President of the Rotary Club of Shetland, founded in 1972. He was a distant relative of [person:eric-gray:Eric Gray] who was also the Provost of Lerwick (6th cousin).',NULL,'Harry Gray Provost.png','Harry Gray Headshot.png','I51744','Harry_Gray','["Lerwick Town Council Provosts", "Lerwick Town Councillors", "1909 Births", "1980 Deaths", "Councillors pictured"]',NULL,1,214369179);
INSERT INTO "people" VALUES(185,'Hazel Simpson','hazel-simpson','1940',NULL,NULL,NULL,'Hazel Mary Simpson (neé Johnson) is a former Shetland Islands Councillor for Whalsay and Skerries, replacing via by-election [person:henry-stewart:Henry Stewart] after he died. She is the wife of former councillor for the same area, [person:joseph-simpson:Josie].',NULL,NULL,NULL,'I13633','Hazel_Simpson','["Shetland Islands Councillors", "Natives of Shetland", "Female", "1940 Births", "Councillors - Missing B/D", "Councillors - Missing Birth Date"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(186,'Henry Graham','henry-graham','1648','1718',NULL,NULL,'Henry ''Harie'' Graham of Breckness was a member of the Parliament of Scotland for Orkney and Shetland 1865-6. He was educated at the Kirkwall Grammar School and St. Andrews University. Was tutored by James Stewart of Graemsay. Succeeded to the Breckness estate in 1666. Managed Bishopric estates for his father in law Bishop Honeyman. Appointed Sheriff and Admiral Depute of Orkney. One of the principal landowners in Orkney but came across financial difficulties and incurred heavy debts.',NULL,NULL,NULL,NULL,'Henry_Graham','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(187,'Henry Henderson','henry-henderson','1840-05-31','1910-06-11','Quarff','Leith','Henry Henderson was a Methodist preacher and briefly a Zetland County Councillor, representing Burra from February 1898 until December 1898, where he was beaten out by Scalloway hotelier [person:charles-lennie:Charles Lennie].','He left Shetland at a young age to move to England, but after living in England for a period of 18 to 20 years, he chose to return to Shetland. When he returned, he set up the International Organisation of Good Templars (IOGT) in Burra. The IOGT was a religious organisation aimed at reducing the harm caused by alcohol. He also provided local updates to the Shetland Times of the happenings in Burra. He was a preacher at the Wesleyan Church in Burra for a number of years.',NULL,NULL,'I56843','Henry_Henderson','["Zetland County Councillors", "Henderson", "1840 Births", "1910 Deaths", "Natives of Shetland", "Councillors - Clergymen", "Burra", "By-elected Zetland County Councillors"]',1,0,NULL);
INSERT INTO "people" VALUES(188,'Henry Hunter','henry-hunter','1886-10-29','1974-03-03','Baltasound','Baltasound, Unst','Captain Henry William Levie Hunter was an estate factor and County Councillor from 1942 and 1949.','Henry served in both World Wars, the first in the Royal Air Force and as a 2nd Lieutenant and Major with the Gordon Highlanders in WWII. He was the Clerk of Works with Cubitts during the building of RAF Saxavord in the 1950''s, which was completed around 1954-55, and was an early warning radar station during the Cold War. He was also a Factor to [person:laurence-edmondston:Laurence Edmondston].',NULL,NULL,'I48448','Henry_Hunter','["Zetland County Councillors", "1886 Births", "1974 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(189,'Henry Mouat','henry-mouat','1874-11-29','1944-03-20','Tingwall','Lerwick','Henry Mouat was the manager of a wholesalers and a County Councillor.','He was described by the Shetland Times as one of the "foremost business men and one of the most eminent figures ever to take part in the Island''s public life". Upon his marriage to Jane Smith, he moved from Tingwall to Sandsound and operated a general merchant shop in Weisdale. By the 1910s, the family had relocated to Lerwick where Henry was associated with the Shetland Island''s Steam Trading Company. In 1907, he began his association with the form J & J Tod & Sons. In the preceding century, the firm was one of the principle suppliers to the grocery trade in Shetland, and Henry was hired to run the Shetland operation of the firm, overseeing a significant expansion of the organisation''s operations. Under his stewardship, the firm opened their first depot in Lerwick and extended the operation into Orkney. His great-great-great uncle [person:james-mouat-i:James Mouat] was a Lerwick Town Councillor. Henry was also a distant relative of Robert Stewart, the first Earl of Orkney (9th Great-grandson).','Henry Mouat.png','Henry Mouat headshot.png','I179100','Henry_Mouat','["Zetland County Councillors", "Councillors pictured", "1874 Births", "1944 Deaths"]',1,1,288872223);
INSERT INTO "people" VALUES(190,'Henry Stewart','henry-stewart','1919-08-22','1993-02-12','Brough','Whalsay','Henry Anderson Stewart was a fisherman, engineer, sailor, Shetland Islands Councillor and altogether well-known figure in Whalsay. Anthony P. Cohen''s book, Whalsay: Symbol, Segment and Boundary in a Shetland Island Community, has a section specifically on Henry (pp. 153-9), as well as numerous other references to him throughout it. The front cover of the book features Whalsay''s fishermen, with Henry at the front.','Henry had 8 other siblings, and was the youngest among them. He was educated at the Anderson Educational Institute, initially living and working outwith Shetland. He had a variety of different jobs after leaving school, including working for the Post Office as an engineer in Orkney, as a signal engineer in Africa during World War 2, and he was also involved in the construction of water services in Unst. Politically, he was against the UK joining the European Union (European Economic Community at the time) as he foresaw the troubles which this would bring to small island communities like Shetland, and Whalsay. He had six daughters. One of them, Loretta, was also a councillor for Whalsay.',NULL,NULL,'I62467','Henry_Stewart','["Shetland Islands Councillors", "1919 Births", "1993 Deaths"]',1,1,175747602);
INSERT INTO "people" VALUES(191,'Herbert Anderton','herbert-anderton',NULL,'1937-11-16',NULL,'Vaila','Herbert Foster Anderton built the stately home on the Isle of Vaila in 1895 and was a County Councillor for Sandness between 1895 and 1898.','Herbert came to Shetland around 1892, where he bought the estates of Melby and Vaila. He used Vaila House as a summer home for many years, but in his latter years he had made it his permanent residence. Vaila Hall was originally built in 1696 by Scalloway merchant James Mitchell, and in 1893 Herbert had it enlarged. By 1901, Vaila had over 30 inhabitants, most of them staff of the Andertons. Herbert built a replica Buddhist temple on the isle, which by 1988 was in ruins.',NULL,NULL,'I314981','Herbert_Anderton','["Zetland County Councillors", "Incomers to Shetland", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1862 Births", "1937 Deaths"]',NULL,1,179947203);
INSERT INTO "people" VALUES(192,'Hercules Arthurson','hercules-arthurson','1881-09-18','1937-12-30','Sandsting','Lerwick','Captain Hercules James Arthurson was County Councillor for Sandsting from 1932 until his death in 1937.','He attended Skeld Public School, leaving at the age of 13 to work on the beach, washing and drying fish for Messrs Garriock & Co. After one season there, he returned to school aged 14 but he was hired as a crane-boy for the North of Scotland Steam Navigation Company''s steamer Queen. Across 3 years he served on that vessel and the St Magnus and St. Clair. Afterwards, he had a short service on the Design, before sailing out of Glasgow to work in the Black Sea and Mediterranean. His career at sea took him to such places as New Caledonia, Australia, USA and South Africa. By 1914, he was the Master of the steamer Moidart, and in 1915 moved to Edinburgh. He skippered the ships North Holland and Patmos during WWI under the Ministry of Shipping. In about 1925, he returned to Westerskeld.',NULL,NULL,'I58635','Hercules_Arthurson','["Zetland County Councillors", "1881 Births", "1937 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(193,'Hugh Craigie','hugh-craigie',NULL,'1670',NULL,NULL,'Hugh Craigie of Gairsay (d. 1670) was a member of the Parliament of Scotland in 1652 and 1661-2 for Orkney and Shetland. He was also a Commissioner to the Charles II Scottish Parliament in 1660.',NULL,NULL,NULL,NULL,'Hugh_Craigie','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(194,'Hugh Robertson','hugh-robertson','1868-10-04','1932-01-15','Weisdale',NULL,'Hugh Jamieson Robertson was a woolen draper, a Lerwick Town Councillor from 1916 to 1919, and County Councillor for Sandsting between 1910 and 1919. and the 1919 Lerwick Town Council election. His uncle [person:john-robertson-iii:John] was also a County Councillor.','In 1894 he started the business Smith & Robertson with [person:william-smith-ii:William Smith].',NULL,NULL,'I119190','Hugh_Robertson','["Lerwick Town Councillors", "Zetland County Councillors", "1868 Births", "1932 Deaths", "Councillors pictured"]',1,NULL,214369426);
INSERT INTO "people" VALUES(195,'Hugh Sutherland','hugh-sutherland','1900-01-01','1976-03-23','Lunnasting','Weisdale','Hugh Thomas Sutherland was a County Councillor initially for Yell North between 1962 and 1967, then for Delting South, and finally for Northmavine South.','Upon completing his education at the Anderson Educational Institute in 1917, Hugh became the clerk of the local Food Office. In 1919, he moved to the Education Officer where he spent the remainder of his career, retiring in 1962. He was heavily involved in Shetland''s voluntary sector, being secretary and later vice president of the committee that founded the local YMCA, also as secretary for the Shetland Football Association and he held the same title for the Shetland Youth Council. Additionally he was Session Clerk of Whiteness and of Tingwall and President of the Tingwall Nursing Association. He was closely associated with the Whiteness & Weisdale Hall and tragically died just three days before he was due to cut the ribbon of the new venue. He had served on the hall committee for more than 50 years including at times as secretary and chair.',NULL,NULL,'I30213','Hugh_Sutherland','["Zetland County Councillors", "1900 Births", "1976 Deaths"]',1,1,255755848);
INSERT INTO "people" VALUES(196,'Hugh Williamson','hugh-williamson','1909-12-07','1991-05-24','Yell','Lerwick','Hugh Robert Williamson was a piano tuner and County Councillor for Yell North between 1967 and 1973.',NULL,NULL,NULL,'I19109','Hugh_Williamson','["Lerwick Town Councillors", "1909 Births", "1991 Deaths", "Biography Missing"]',1,1,291847928);
INSERT INTO "people" VALUES(197,'Iain Caldwell','iain-caldwell',NULL,'2007-07-04',NULL,'Blairgowrie','Iain Clayton Caldwell was a business owner, County Councillor for Aithsting. He ran a knitwear firm in Aithsting, which employed 400-500 people.',NULL,NULL,NULL,NULL,'Iain_Caldwell','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "Councillors - Missing Birth Location", "2007 Deaths"]',NULL,0,NULL);
INSERT INTO "people" VALUES(198,'Iain Campbell','iain-campbell',NULL,NULL,NULL,NULL,'Reverend Iain T. Campbell was a Church of Scotland Minister and Zetland County Councillor for Dunrossness North from 1967 until he stood down in 1971.','Iain was inducted to the Dunrossness Parish Church on 25 August 1966. He demitted to take employment out with the Church 31 April 1969.',NULL,NULL,NULL,'Iain_Campbell','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing All", "Clergymen"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(199,'Ian Byrne','ian-byrne',NULL,NULL,NULL,NULL,'Ian Byrne is a former Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'Ian_Byrne','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(200,'Ian Holbourn','ian-holbourn','1872-11-05','1935-09-14','Huyton','Edinburgh','Professor John Bernard Stoughton ''Ian'' Holbourn was an academic, author, Zetland County Councillor and sometime laird of Foula.','The oldest son of Alfred Holborn and Mary Jane Stoughton, he was educated at Bradford Grammar School, and won a scholarship to study mathematics, his father''s profession, at the University of London. However, his own interests prevailed and instead he enrolled at Slade School of Art, where he founded the literary magazine Quarto. After five years at Slade, he entered Merton College, Oxford to pursue the humanities where he met amongst others the writer John Buchan, and was involved in the foundation of Ruskin College, designed to provide opportunities for the working class. In 1899, Holbourn was part of an expedition to Iceland. On the way north the ship passed Foula, which so intrigued him that the following year he returned. Once there, he determined to buy it and, despite family disapproval, in the end he had his way. He married Marion Archer-Shepherd in c.1902(?). Holbourn continued to lecture in England, variously at Oxford, Cambridge, and London, but Foula became the Holbourns'' summer retreat. When there he sat on the Zetland County Council, in the hope his advocacy might improve the quality of life of the Foula folk. In 1913, Holbourn went on a lecture tour of the USA which proved a great success and he returned in the autumn of 1914, taking with him the manuscript of his ''Fundamental Theory of Beauty'', a labour of twenty long years, which he was close to completing. He booked his return passage on the Lusitania, even though both he and his wife had premonitions that it would be torpedoed. Although he survived the sinking, the experience was deeply traumatic, compounded by his fear of losing the manuscript of his opus. After spending a long time in water, he was eventually picked up by a fishing smack, and finally made his way to Queenstown. Aboard the Lusitania, Holbourn had befriended a young girl, Avis Dolphin, who he took care of immediately after the loss of the Lusitania and who became a life-long friend. It was for Avis that he wrote The Child of the Moat and Children of Fancy, a book of poems. In 1918 Holbourn was offered a chair in the University of California in Art and Architecture, and later moved to Minnesota. He was a very popular lecturer and tutor. In the years following he travelled widely in Europe and the USA, as well as Japan. Holbourn died on the 14th of September 1935, leaving a great deal of unpublished material. Marion Holbourn compiled The Isle of Foula, according to his plan.','Windanwave.jpg',NULL,'I345551','Ian_Holbourn','["Zetland County Councillors", "1872 Births", "1935 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(201,'Iris Hawkins','iris-hawkins','1946-11-21',NULL,'Tingwall',NULL,'Iris Jean Hawkins is a former Shetland Islands Councillor for the Shetland Central ward. On October 27 2011, Hawkins announced her resignation due to impending marriage.',NULL,NULL,NULL,NULL,'Iris_Hawkins','["Shetland Islands Councillors", "Natives of Shetland", "1946 Births", "Female"]',1,NULL,NULL);
INSERT INTO "people" VALUES(202,'Isaac Cowie','isaac-cowie','1804-05-17','1847-06-11','Lerwick','Lerwick','Dr. Isaac Cowie was a surgeon and a Lerwick Town Councillor. His brother, [person:john-cowie:John], was also a Lerwick Town Councillor.',NULL,NULL,NULL,'I45542','Isaac_Cowie','["Lerwick Town Councillors", "1804 Births", "1847 Deaths"]',1,1,175653685);
INSERT INTO "people" VALUES(203,'James Adie','james-adie','1875-09-19','1948-05-04','Delting','Edinburgh','James Arthur Adie was a merchant and a County Councillor for Delting South between 1903 and 1907. His father, [person:william-adie:William Adie] had resigned from the seat in February 1903, and James was appointed in April.','James worked in the Adie family business in Voe until the 1920s. He married Hanka Lange, the daughter of Alexander Lange who managed the Olna whaling station, and the couple moved to Norway for some years. James then returned to the UK, before heading out to Antarctica with a whaling company. The couple eventually settled in North Berwick, where James became a partner in a firm that built wooden houses. During WWII, James served in Shetland in charge of the Home Office camp for Norwegian refugees, a role that Hanka was heavily involved in too.',NULL,NULL,'I9181','James_Adie','["Zetland County Councillors", "1875 Births", "1948 Deaths"]',1,0,179138084);
INSERT INTO "people" VALUES(204,'James Aitken','james-aitken','1895-04-03','1956-08-02','South Voe','Lerwick','James John Aitken was a Lerwick Town Councillor.',NULL,'JJ Aitken Provost.png','JJ Aitken Headshot.png','I169390','James_Aitken','["Lerwick Town Councillors", "1895 Births", "1956 Deaths", "Councillors pictured"]',1,1,176068255);
INSERT INTO "people" VALUES(205,'James Anderson (i)','james-anderson-i','1829-12-29','1907-02-26','Kergord','Aithsting','29 December 1829, Kergord, Weisdale, d. 26 February 1907, Aithsting) was a stonemason, farmer and a County Councillor for Sandsting from 1890 until 1892. Two of his sons, [person:james-anderson-ii:James] and [person:thomas-anderson-iii:Thomas] were also councillors.','On the Council, James advocated for improving the roads around Aith. In 1904, tragedy struck his family after a boating accident off Vementry took the lives of his youngest son, John and his son in law & Vementry proprietor William Fraser, as well as another Aith boy Thomas Fraser (not related to William).',NULL,NULL,'I51603','James_Anderson_(i)','["Zetland County Councillors", "1829 Births", "1907 Deaths", "Anderson"]',1,1,261020098);
INSERT INTO "people" VALUES(206,'James Anderson (ii)','james-anderson-ii','1858-05-27','1934-04-25','Kergord','Bixter','27 May 1858, Kergord, Weisdale, d. 25 April 1934, Bixter) was a master mariner and a County Councillor for Aithsting from 1928 until his resignation in 1932.','In his Shetland Times obituary, James was described as "the best kind of Shetlander - sturdy, independent, kindly, yet determined to make the best of life." His family were removed from their Kergord property during The Clearings and as a young boy he worked as a fisherman in Shetland and Greenland, before later joining what we now call the Merchant navy, sailing to America to work in the wood trade. He then transferred to a steam vessel in Australia and travelled as far and wide as the Solomon Islands. Upon the death of [person:james-anderson-i:his father], who was also a councillor, he returned to Shetland to manage the family farm in Aithness. His father, [person:james-anderson-i:James] and brother [person:thomas-anderson-iii:Thomas] were also councillors.',NULL,NULL,'I68570','James_Anderson_(ii)','["Zetland County Councillors", "1858 Births", "1934 Deaths"]',1,1,178996022);
INSERT INTO "people" VALUES(207,'James Anderson (iii)','james-anderson-iii','1877-12-27','1966-02-26','Nesting','Nesting','27 December 1877, Nesting, d. 26 February 1966, Nesting) was a master mariner and a County Councillor for Nesting between 1938 and 1945.','At age 17, James joined the schooner Lavinia, and eventually sat for a Master''s Certificate when he was in his late 20s. In 1912, he received command of the s.s. Cayo Gitano, and later the s.s. Messina, a ship that traded in the Far East. In 1914, while unaware of the outbreak of war, his ship called at Nauru Island for cargo and he was promptly taken prisoner by German soldiers. A fictitious cable arrived to the island to the German governor declaring that the war was over, and he was let go. He later returned to the island as the Australian troops liberated it from German rule, and he captained the ship that took the same Governor and German troops back to Sydney as prisoners of war. In 1916, he took command of the Lord Dufferin, running stores and troops to Salonica. While travelling from Malta to Gibraltar, the British convoy was attached, with James''s ship the only one who successfully escaped and fought off the attackers, arriving in Bone, Algeria. He was subsequently awarded the Lloyd''s silver medal. While on leave after the war in Shetland in 1918, the Lord Dufferin was accidentally rammed by the Aquitania in New York harbour and sank. James''s last two years at sea were spent at the helm of the s.s. Republic for the United States Shipping Board, training cadets for the United States Navy.',NULL,NULL,'I29187','James_Anderson_(iii)','["Zetland County Councillors", "1877 Births", "1966 Deaths"]',1,1,284529621);
INSERT INTO "people" VALUES(208,'James Anderson (iv)','james-anderson-iv','1910-01-26','1994-03-14','Voe','Stapness, Walls','29 January 1910, Voe, Delting, d. 14 March 1994, Stapness, Walls) was a shop manager, taxi driver and a Labour Zetland County Councillor for Walls from 1949 until 1952.',NULL,NULL,NULL,'I142050','James_Anderson_(iv)','["Zetland County Councillors", "Natives of Shetland", "1910 Births", "1994 Deaths", "Labour"]',1,1,295664657);
INSERT INTO "people" VALUES(209,'James Bairnson','james-bairnson','1898-08-08','1987-12-21','Culsetter','Fleck, Dunrossness','James Bairnson was a seaman and County Councillor for Dunrossness South between 1945 and 1952.','James worked for the Pearl Assurance company for 23 years.',NULL,NULL,'I165066','James_Bairnson','["Zetland County Councillors", "1898 Births", "1987 Deaths"]',1,1,179138360);
INSERT INTO "people" VALUES(210,'James Bowie','james-bowie','1867-11-08','1932-02-03','Lerwick',NULL,'Dr. James Cameron Bowie (b. 8 November 1867, Lerwick, d. 3 February 1932, Aithsting was a doctor and County Councillor for Sandsting between 1928 and 1930. He also was an unsuccessful candidate for Sandsting in 1910 and Aithsting in both 1913 and 1915. His first cousin, [person:frederick-tait:Frederick Tait], was also a Zetland County Councillor.','James was born in Lerwick and educated first at Hunter''s School and later the Anderson Educational Institute. He left the isles to study medicine at the University of Aberdeen and returned to Shetland to practice after graduating. He first worked in Clousta, and subsequently became the Medical Officer for Aithsting and Sandsting, a position he held until his death. In practice, he was known for his ability to treat eye and stomach issues. He was the first President of the Walls and District Agricultural Society, founded in 1913, and was a founder and President of the Shetland Flock-Book Society.','Dr. James Bowie - Shetland Museum and Archives JB00031.jpg',NULL,'I60495','James_Bowie','["Zetland County Councillors", "Incomers to Shetland", "1867 Births", "1932 Deaths", "Councillors pictured"]',1,NULL,295674697);
INSERT INTO "people" VALUES(211,'James Brownlie','james-brownlie','1897-06-06','1968-11-21','Hamilton','Bothwell','James Hannah Brownlie was a grocery manager and a Lerwick Town Councillor between 1946 and 1949.','James was the son of Thomas and Annie Hannah (d. September 1944, Calderhead) and was married to Sarah ''Sadie'' Dalziel (b. 1899 Ayr, d. 10 October 1968, Bothwell). James was the manager of the local Co-op grocery store in Shetland when it was located where Frank Williamson''s now stands. He lived in the flat above the shop and was in Shetland from the early 40''s until 1949 when he was transferred to Morayshire where he served as Assistant Area Manager until his retiral until around 1961.',NULL,NULL,'I366688','James_Brownlie','["Lerwick Town Councillors", "1897 Births", "1967 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(212,'James Budge (i)','james-budge-i','1868-01-23','1940-02-17','Bigton','Bigton, Dunrossness','James Budge was a County Councillor for Dunrossness North between 1907 and 1922. He was the grandfather of former Shetland Islands Councillor, [person:james-budge-ii:Jim].','James became the head of the Budge farm at Dunrossness after the death of his father in 1899 and farmed there for over 30 years. He was involved in the Dunrossness Nursing Association and was secretary for several years. After the death of [person:william-mcdougall:William McDougall] in 1937, James was the President of the Dunrossness Agricultural Society.',NULL,NULL,'I70183','James_Budge_(i)','["Zetland County Councillors", "1868 Births", "1940 Deaths"]',1,1,179138269);
INSERT INTO "people" VALUES(213,'James Budge (ii)','james-budge-ii','1947-09-24',NULL,'Lerwick',NULL,'James ''Jim'' Budge is a former Shetland Islands Councillor for the Shetland South ward for from 2007 to 2012. His grandfather, [person:james-budge-i:James Budge], was a County Councillor for Dunrossness North.',NULL,NULL,NULL,NULL,'James_Budge_(ii)','["Shetland Islands Councillors", "Natives of Shetland", "1947 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(214,'James Campbell','james-campbell','1845-01-15','1922-05-09','Douglas','Fetlar','Reverend James Archibald Campbell was a Minister and a County Councillor for Fetlar between 1890 and 1892. He was educated at the University of Aberdeen (MA, 1865). He invented the Campbell differential screw fine adjustment for microscopes. His son, [person:john-campbell-ii:John], also represented Fetlar from 1937 until 1945.','James Archibald Campbell, was educated at University of Aberdeen; M.A. (1865) and licenced by Presbytery of Lerwick 8th July 1868. He was the assistant at Huntly 1869-1871, Banff, February to July 1872; ord. to Quarter Chapel 10th October 1872; trans. adm. 27th September 1881; died 9th May 1922. He was interested in most scientific mater and was a skilful amateur mechanic. He made his own microscope, both instrument and the objectives and eye-pieces, also a fine dioptric telescope, calculating, grinding, and polishing the object-glass and eye-pieces. He invented the Campbell differential screw fine adjustment for microscopes. He marr. At Banff 13th Jan. 1875, Eliza Wallace, daughter of James Hunter, and had issue: John Archibald, master mariner, born 25th December 1875; Grace Craig Hunter, born 20th September 1877 (marr. David Crawford, min. of Midmar); James, M.B., Lieut. R.A.M.C., born 24th October 1879; Jane Menzies, born 23rd December 1881 (marr. 29th November 1904, Robert B. Turnbull, M.B., Ch.B., New Zealand); Elizabeth Hunter, born 22nd November 1883; Lilias Anne Turnbull, born 17th March 1886; Nelson, Sumatra, born 1st September 1890, lieut. R.A.F., Egypt and Palestine Expedition.','JamesCampbell.jpg',NULL,'I18195','James_Campbell','["Zetland County Councillors", "Councillors - Clergymen", "1845 Births", "1922 Deaths"]',0,1,179138420);
INSERT INTO "people" VALUES(215,'James Dalziel','james-dalziel','1830','1895-01-01','Sandsting','Dunedin, New Zealand','James Dalziel or Deyell was a merchant, grocer and Lerwick Town Councillor, from 1865 to 1871. His name is represented as either Deyell or Daziel (common for the era) however the 1868-71 and Lerwick Town Council minutes list him as Dalziel or Dalziell.',NULL,NULL,NULL,'I42572','James_Dalziel','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1830 Births", "1895 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(216,'James Daniel','james-daniel','1924-09-21','2020','St Machars',NULL,'James Anderson Daniel was a former accountant and Lerwick Town Councillor from 1955 until his resignation in 1962, always standing as an independent.','James was the Honorary Secretary of the Sandwick Scouts in 1962 and became Scout Commissioner in November 1964. In 1975, he was the treasurer for the Shetland Fisherman''s Association. One of his sons, Hamish, worked for the Foreign Office and has held such titles as Ambassador to East Timor and Deputy High Commissioner in Karachi, Pakistan.','Jdaniel.JPG',NULL,'I287211','James_Daniel','["Lerwick Town Councillors", "Councillors pictured", "1924 Births", "Incomers to Shetland", "2020 Deaths"]',0,NULL,NULL);
INSERT INTO "people" VALUES(217,'James Douglas','james-douglas','1703','1787-11-02',NULL,NULL,'Sir James Douglas, also known as Guid Sir James, and Black Douglas, was a Member of Parliament for Orkney and Shetland. He was elected in 1754, replacing [person:james-halyburton:John Halyburton]. He was returned to the seat in the 1761 election, and served until 1768 when he was replaced by [person:thomas-dundas-i:Thomas Dundas]. James Douglas was an officer in the Royal Navy and continued with this career during the time he represented the constituency.','Douglas became a captain in the Royal Navy in 1744. In 1745 he commanded the HMS Mermaid at Louisbourg and in 1746 he commanded the HMS Vigilante at Louisbourg. In 1746 was appointed Commodore of Newfoundland by Vice-Admiral Isaac Townsend. He then served as a Member of Parliament for Orkney & Shetland from 1754 to 1768. In 1757 served as a member of the court martial which tried and convicted Admiral Byng and in 1759 he was knighted for his participation in the capture of Québec. He was commander of the squadron which captured Dominica in 1761.[2] He served in the fleet under George Rodney which captured Martinique in February 1762 and then served in the fleet under George Pocock which captured Havana in August 1762.[2] He became Commander-in-Chief, Jamaica Station later in the year. Promoted to vice-admiral in 1770, he became Commander-in-Chief, Portsmouth in 1774 and was then promoted to admiral in 1778. In 1786 he was made a Baronet.

<strong>Timeline of Naval Career</strong>

*1744 Captain in the Royal Navy
*1745 Commanded the Mermaid at Louisbourg
*1746 appointed Commodore of Newfoundland
*1759 Knighted for his participation in the capture of Quebec
*1770 Promoted to Vice-Admiral
*1778 Promoted to Admiral }} Category: Members of the Parliament of Great Britain
Category: 1703 Births
Category: 1787 Deaths',NULL,NULL,NULL,'James_Douglas','["Members of the Parliament of Great Britain", "1703 Births", "1787 Deaths"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(218,'James Gear','james-gear','1943-06-09',NULL,'Foula',NULL,'James Ross Gear is a former Shetland Islands Councillor for Sandness and Walls from 1990 until 1999.',NULL,NULL,NULL,'I137391','James_Gear','["Shetland Islands Councillors", "Natives of Shetland", "1943 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(219,'James Goodlad','james-goodlad','1864-03-01','1953-11-10','Tingwall','Lerwick','James Mouat Goodlad was a shoemaker and County Councillor for Gulberwick between 1922 and 1924 and a Lerwick Town Councillor between 1921 and 1924. His brother, [person:peter-goodlad:Peter], was Provost of Lerwick 1915-1920.','James moved to Lerwick in his youth after his father died as a result of an accident at sea when James was just three. He began working as an apprentice with shoemaker David Affleck, and worked with him in Affleck''s passing in 1879. His brother, [person:peter-goodlad:Peter], had started the boot and shoemaking business Goodlad & Coutts in 1891, and in 1898, James joined as a partner as the business was expanding to Kirkwall. The business expanded again in 1905, opening a shop in Sandwich, followed by Fraserburgh and Peterhead in 1906 and 1913 respectively. At its peak, the firm employed 42 people, most of whom worked on the Esplanade where James was the manager. The breakout of WWI severely hampered the business, as 17 staff were called up and six killed. The war had seen a huge rise in the usage of rubber boots, which became the footwear of choice for the sea-farers that the business had previously served. As a result, the business had to scale back, with the branches in Sandwich, Fraserburgh and Peterhead all closing. When John Coutts died in 1921, the business became Goodlad & Goodlad. James continued to work for the family business until the early 1940s, at which time he had served nearly 50 years. Latterly, he attended Ratepayers Association meetings.',NULL,NULL,'I45507','James_Goodlad','["Zetland County Councillors", "1864 Births", "1953 Deaths"]',1,1,179138491);
INSERT INTO "people" VALUES(220,'James Gordon','james-gordon','1891-10-24','1978-06-03','Cunningsburgh','Dunrossness','James John Gordon was a County Councillor for Dunrossness South between 1955 and 1964.','In his youth, James went to the whaling off Greenland on the Dundee whaler Scotia. Upon his death, the Convener [person:alexander-tulloch:Alexander Tulloch] credited James with coming to the aid of his Fair Isle constituents when there was doubt about the ongoing survival of the islands, through the Fair Isle Conference, which occurred 7 and 8 June 1956.',NULL,NULL,'I80052','James_Gordon','["Zetland County Councillors", "1891 Births", "1978 Deaths"]',1,1,179138376);
INSERT INTO "people" VALUES(221,'James Goudie','james-goudie','1851-05-06','1928-10-17','Lerwick','Lerwick','James Mouat Goudie was an ironmonger, Lerwick Town Councillor between 1888 and 1907, spending the last three years (1904-7) as Provost, and County Councillor for Lerwick South between 1892 and 1901, then from 1901 to 1904 for Cunningsburgh. He was offered the opportunity to fill the a vacancy at the 1880 Lerwick Town Council election but turned the offer down. His grandfather, [person:james-mouat-i:James], and his uncle [person:james-mouat-ii:James Mouat] were also Lerwick Town Councillors.','James was educated at the Anderson Educational Institute. He developed an early interest in antiquities, and he assembled a large book collection about Shetland was acquired by Lerwick Town Council, and is now in the Shetland Archives James''s father Robert had established an ironworks in Lerwick in 1821. The business became a partnership and was known as Messrs R. Goudie & Son. After Robert''s death in 1869, James continued with the business until the 1920s when McGowan Scott was made a junior partner. He was the joint secretary of the Shetland Literary and Scientific Society and was made an honorary sheriff of the county in 1907. On 6 March 1894, he was added to the roll of Justices for the Peace for the County. He was a Liberal, politically.','James M Goudie Provost.png','James M Goudie Headshot.png','I68965','James_Goudie','["Lerwick Town Councillors", "Zetland County Councillors", "1851 Births", "1928 Deaths", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(222,'James Greig','james-greig','1785-01-10','1852-05-10','Walls','Lerwick','James Greig was a Procurator-Fiscal and Lerwick Town Councillor. He became Procurator Fiscal in 1806. His son, [person:archibald-greig:Archibald] was a councillor from 1844 until 1850. James''s second wife Cecilia was the widow of [person:gilbert-paterson:Gilbert Paterson], and his nephew [person:archibald-garriock:Archibald Garriock] was also a councillor.','James was a descendent of James Greig (1655 - 1742), who arrived in Shetland with his brother towards the end of the 17th century with Hugh Sinclair of Brough, known as the Baron of Brough. James was a baillie of Lerwick.',NULL,NULL,'I17100','James_Greig','["Lerwick Town Councillors", "1785 Births", "1852 Deaths", "Natives of Shetland", "Greig"]',1,1,163057225);
INSERT INTO "people" VALUES(223,'James Grierson','james-grierson','1863-08-07','1915-07-03','Lerwick','Lerwick','James Cullen Grierson . The eldest son, and second eldest of six children of Andrew John Grierson and Alice Geraldine Clifford. He died on July 3rd 1915 at Lerwick. On August 14th 1895 he married at Sleaford, Lincolnshire, England. Alice Stanley Peake, born June 9th 1861 at Westholme, Sleaford, Lincolnshire, England. Daughter of Henry Peake. Born before 1850. They produced six descendants.','James qualified as a Solicitor, and practiced in Lerwick. In keeping with what had by then become a family tradition, he took a very active role in public affairs from a relatively early age. Before the age of thirty he had been elected on to the Zetland County Council and in to the role of Vice Convener. He was a member of almost all of the Council Committees, and the Chairman of most of them. He was also a Commissioner of Supply, a member of the County Road Board, and Chairman of the Visiting Board of Lerwick Prison. In a broader sphere he was also a leading advocate of temperance and Chief of the local Rechabite movement, taking an active role in promoting and encouraging these not only in Lerwick but all over Shetland. Upon the death of his father Andrew, the fifth Laird of the Grierson of Quendale family estate, on April 12th 1896, James became his successor, the sixth and final Laird of the family estate. The sale, by James of what today is Quendale Farm to George Leslie around 1900 brought the final chapter of the family estate to a close. It may be of interest to note that George Leslie (grandfather of [person:george-leslie-ii:George WB Leslie]), the purchaser, was, as a child of about nine years old, along with the rest of his family, one of the evictees from one of the twenty seven crofts at and around Garth, cleared by James''s father Andrew, only around twenty six years previously. James Cullen Grierson''s eldest child, John Henry Clifford Grierson, (b. October 28th 1896) was a Lieutenant with the 8/10th Gordon Highlanders and was killed in action at Ypres, Flanders, Belgium on July 31st 1917. His death in Helensdale, Lerwick, was the result of a self-inflicted gunshot wound to the head. He was scheduled to face a military discipline for drinking according to procurator fiscal records released in 2015.','JC_Grierson.jpeg',NULL,'I18022','James_Grierson','["Zetland County Councillors", "Grierson", "Natives of Shetland", "1863 Births", "1915 Deaths", "Councillors pictured"]',1,1,106456049);
INSERT INTO "people" VALUES(224,'James Halcrow','james-halcrow','1919-07-29','1993-02-04','Hoswick','Lerwick','James Robert Halcrow was a bus driver, crofter, and County Councillor for Sandwick between 1961 and 1970.','During WWII, James sailed aboard cargo ships. When the war was over, he returned to Shetland where he drove cattle trucks and latterly was a school bus driver. He also worked in agriculture, and was involved in sheep and grazing committees.',NULL,NULL,'I72852','James_Halcrow','["Zetland County Councillors", "1919 Births", "1993 Deaths"]',1,1,179949299);
INSERT INTO "people" VALUES(225,'James Halyburton','james-halyburton',NULL,'1765-05-10',NULL,NULL,'James Halyburton of Pitcut in Angus and Firth of Orkney was a Lieutenant-Colonel and Member of Parliament for Orkney and Shetland from 1747 until 1754. The oldest son of James Halyburton of Pitcur (died 1747), he joined the British Army in 1721 as an ensign in the 13th Foot, rising to the rank of Lieutenant-Colonel in 1750.',NULL,NULL,NULL,NULL,'James_Halyburton','["Members of the Parliament of Great Britain", "1765 Deaths"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(226,'James Hay','james-hay','1877-08-07','1973-09-11','Mossbank','Delting','James Johnson Hay was an auctioneer and County Councillor first for Delting North between 1913 and 1922, then Whalsay & Skerries from 1937 and 1945 before returning again to Delting North for his final stint, between 1945 and 1952.','James was an Elder in the Church of Scotland and auctioneer.',NULL,'James Hay headshot.png','I134403','James_Hay','["Zetland County Councillors", "1877 Births", "1973 Deaths", "Biography Missing"]',1,1,179137951);
INSERT INTO "people" VALUES(227,'James Henry','james-henry','1937-08-31','2018-07-31','Hamnavoe',NULL,'James Herculson ''Jim'' Henry is a former Shetland Islands Councillor for the Shetland Central ward.',NULL,NULL,NULL,'I38587','James_Henry','["Shetland Islands Councillors", "Natives of Shetland", "1937 Births"]',1,NULL,262732655);
INSERT INTO "people" VALUES(228,'James Hunter (i)','james-hunter-i','1792-12-19','1847-08-02','Tingwall','Lerwick','James Hunter was a merchant and Lerwick Town Councillor between 1835 until his death in 1847.',NULL,NULL,NULL,'I18085','James_Hunter_(i)','["Lerwick Town Councillors", "1792 Births", "1847 Deaths"]',1,1,163057246);
INSERT INTO "people" VALUES(229,'James Hunter (ii)','james-hunter-ii','1850-11-21','1908-06-16','Lerwick','Edinburgh','James Hunter was an accountant, musician and Lerwick Town Councillor. His father, [person:samuel-hunter:Samuel Hunter], was also a councillor in Lerwick.','James was educated in the Parish School in Lerwick. He joined his uncle James at the Union Bank, first in Lerwick, then after some time he was transferred to the Edinburgh branch. Upon his uncle transferring to Edinburgh, James moved back to Lerwick, working under [person:alexander-mitchell-i:Alexander Mitchell]. He left Shetland again when he was appointed to the branch in Portsoy, Aberdeenshire, before finally transferring to the head office in Edinburgh, where he worked until his death.',NULL,NULL,'I18087','James_Hunter_(ii)','["Lerwick Town Councillors", "1850 Births", "1908 Deaths"]',1,0,163057195);
INSERT INTO "people" VALUES(230,'James Hunter (iii)','james-hunter-iii','1872-02-06','1920-09-21','Billister','Billister, Nesting','James Hunter was an author and County Councillor for Nesting from 1919 until his death in 1920. The vacancy he left in the council was filled by his brother [person:robert-hunter-ii:Robert].','James is described as &quot;a clever self-taught Nesting lad&quot; whose &quot;dialect is of the racy soil&quot;. He died relatively young on the 21st of September, 1920 at Billister, after which his works were collected. A deeply religious man, his last words on his death bed were addressed to all Shetlanders: &quot;Tell them that death has no terrors, but tell them too that the bed of death is no place for repentance. If I had not given my heart to Christ, where would I be today?&quot;',NULL,NULL,'I29428','James_Hunter_(iii)','["Zetland County Councillors", "1872 Births", "1920 Deaths"]',1,1,288609764);
INSERT INTO "people" VALUES(231,'James Hunter (iv)','james-hunter-iv','1914-05-02','1991-11-06','Eshaness','Lerwick','Doctor James Albert Hunter was a GP and Shetland Islands Councillor from 1978 until 1990. He was most commonly referred to as &quot;Albert Hunter&quot;.',NULL,NULL,NULL,'I50940','James_Hunter_(iv)','["Shetland Islands Councillors", "1914 Births", "1991 Deaths"]',1,1,295673393);
INSERT INTO "people" VALUES(232,'James Inkster','james-inkster','1850','1927-01-12','North Roe','Lerwick','James Inkster was a poet and County Councillor.','James was the author of Mansie''s Röd. He was the second of five children of Robert Inkster, who at nineteen had married Catherine Ratter of Uyea, a woman fourteen years older, already twice widowed with three children. The Inksters were originally from Brebister in Northmavine. In adulthood James Inkster moved to Lerwick, where he worked as a bookseller and stationer, and there he married a local woman, Eliza Catherine Manson in 1881. She was the sister of Thomas Manson, who in 1885 founded ''The Shetland News'', and the photographer James C. Manson. They had seven children, but tragically two of their three sons were killed in action in France during the First World War. Mansie’s Röd originally appeared as a series of dialect ‘sketches’ in The Shetland News. Inkster was able to draw on the voices of his childhood in the north mainland to produce a dense and yet accessible written style that found a contemporary audience. Some of the sketches were published in book form in 1922, five years before the death of their author, and proved very popular. The noun ''röd'' relates to the verb ''ta rö'' (to advise), as recorded in one of the fragments of old Shetlandic Norn provided by James Stout Angus for the Faroese philologist Jakob Jakobsen: ‘Guyt a taka gamla manna rö – It’s good to take old men’s advice’. Inkster is one those Shetlanders singled out for their assistance by Jakobsen in his introduction to his dictionary. Inkster also served as a County Councillor for Delting North between 1890 and 1904.',NULL,NULL,'I89755','James_Inkster','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1850 Births", "1927 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(233,'James Irvine (i)','james-irvine-i','1877','1952-02-02','Dunrossness','Lerwick','James William Irvine was a Lerwick Town Councillor.','When James left school, he worked in the Post Office in Boddam, and when he came to Lerwick he was employed in Malcolmsons & Co, bakery. He served a four year apprentice in a ship chandlery in Aberdeen, and when the returned to Lerwick he worked with Russell Anderson. At the time of James''s death, he had run his own business for more than 40 years.',NULL,NULL,'I154415','James_Irvine_(i)','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1877 Births", "1952 Deaths"]',1,1,185610746);
INSERT INTO "people" VALUES(234,'James Irvine (ii)','james-irvine-ii','1937-03-28','2021-09-04','Sand',NULL,'James Christopher ''Slim Jim'' Irvine was a former Shetland Islands Councillor known for his lengthy term of service in public office. He was first elected to the Council in 1974 for Bressay until 1994, then he rejoined the council in 1995 when Jonathan Wills resigned. In 1999 Nesting, Whiteness, Girlsta and Gott from 1999 until he retired in 2007, having served in public office for 35 years. At the 1994 election, he contested the Lerwick Harbour and Bressay seat against a young [person:tavish-scott:Tavish Scott], who was successfully elected.','Jim attended Lerwick Central School around the age of 12 in 1949. He looked forward to entering the world of work more than he did to school, and in May 1952 skipped an exam and successfully applied and interviewed for a job with the Post Office. He worked as a message boy for some years in Lerwick, delivering messages to business all over the town. By the mid 50s he trained to be a postie. He could not do national service due to suffering from scoliosis, but joined the Territorial Army. His step father, who was a socialist and trade unionist, inspired Jim into politics, and he eventually became treasurer and assistant secretary to the workers union there. Jim was originally persuaded to join the Labour Party by [person:alexander-morrison:Alex Morrison], but later left the party. He aligned himself with the Shetland Movement and giving up his Labour membership around 1982. He moved on from the Post Office to become secretary of the Shetland Council of Social Service. He later helped found ZetTrans and became its first chair.',NULL,NULL,'I53153','James_Irvine_(ii)','["Zetland County Councillors", "Shetland Islands Councillors", "1937 Births", "Natives of Shetland"]',1,NULL,NULL);
INSERT INTO "people" VALUES(235,'James Jamieson (i)','james-jamieson-i','1864-10-07','1934-07-26','Lerwick','Aberdeen','James Robert Jamieson was a flesher and County Councillor for Lerwick Central between 1904 and 1919.','After completing a brief education, James went to sea as a fisherman. After deciding that a seafaring career was not for him, he began working for James M. Aitken as a plumber, but also did not enjoy career and eventually opened a fleshing business in Tait''s place in 1885 in partnership with [person:john-irvine-iii:John G. Irvine]. They latter added a grocery shop to their enterprise. Their partnership did not last long, and was eventually dissolved, with James going into business for himself thereafter. Through his new business, he received the contract for the Admiralty to supply meat and vegetables to H. M. Naval ships. James''s shop was opened in 1901 at 123 Commercial Street as a general grocery store. He also owned 125 Commercial Street as a fleshery. In on 31 May 1919, he sold his premises to Henry & Jamieson, who had 103 Commercial Street. He and his wife moved to Banchory, but struggled to settle and left Scotland to tour New Zealand as a place in which they would retire. Health issues meant they did not settle in New Zealand, and they returned to Aberdeen. When James died, he left an estate worth £2,951 worth around £180k in 2024.',NULL,NULL,'I173602','James_Jamieson_(i)','["Zetland County Councillors", "1864 Births", "1934 Deaths"]',1,0,288397204);
INSERT INTO "people" VALUES(236,'James Jamieson (ii)','james-jamieson-ii','1896-09-07','1965-01-02','Norby','Lerwick','James Anthony ''Jeemie'' Jamieson was a wool merchant, County Councillor for Sandness between 1932 and 1949 and he was also a Lerwick Town Councillor from 1949 until his resignation in 1950','James was educated at Sandness Primary School and later at the Anderson Educational Institute. After school he joined the merchant navy, but the ship he joined was taken over by the Admiralty in WWI and was stationed at Scapa Flow as a supply ship to the Royal Navy. In 1923, James returned home and joined his father''s merchant business in partnership with his brother Laurence, who passed away in 1925 as result of injuries sustained in the war. After his father opened a business in Tagon, Voe, James became the sole partner of the Sandness business which he expanded into the wool trade. He sold his business and moved to Lerwick in 1946, operating as a wool dealer on his own, and then later with John Smith to form Jamieson & Smith (Shetland Wool Brokers) Ltd. He retired to Scalloway.',NULL,NULL,'I53514','James_Jamieson_(ii)','["Zetland County Councillors", "1896 Births", "1965 Deaths", "Councillors pictured"]',1,1,179947343);
INSERT INTO "people" VALUES(237,'James Johnson','james-johnson','1891-12-03','1952-06-13','Northmavine','Northmavine','James Robert Johnson was a County Councillor for Northmavine North between 1935 and 1949.','As a young man, he worked in the Alexandra Bakery in Lerwick. He was one of the original members of the Gordon Highlanders in 1914, and eventually became a Sergeant in the 1st Battalion. He was discharged from the army in 1917 after sustaining severe injuries near Monchy le Preux while fighting in the Battle of Arras. He was awarded the Distinguished Conduct Medal and the French Croix de Guerre. After returning to Shetland, he became the manager of D & G Kay''s in Burravoe. When his first wife died in 1923, he returned to Northmavine and took up croft work.','James R Johnson.jpg','James_R_Johnson_headshot.png','I20135','James_Johnson','["Lerwick Town Councillors", "1891 Births", "1952 Deaths"]',1,1,287983254);
INSERT INTO "people" VALUES(238,'James Laing','james-laing','1875-07-23','1946-08-31','Lerwick','Lerwick','James Laing was the secretary for the Seamans Union, a Lerwick Town Councillor and a County Councillor for Lerwick South between 1922 and 1929. He was also the Provost of Lerwick from 1924 to 1927, and Guizer Jarl for the Lerwick Up Helly Aa in 1909.','As a young man, James showed talent at stonemasonry and he had a hand in many of the public buildings in Lerwick. Before WWI, he was the secretary to the Seamen''s and Firemen''s Union which he held up to the early days of WWII, succeeded by [person:prophet-smith:Prophet Smith]. He became the first Labour Provost of Lerwick in 1924 and served until 1945.','James Laing Provost.png','James Laing Headshot.png','I108698','James_Laing','["Lerwick Town Councillors", "Zetland County Councillors", "1875 Births", "1946 Deaths", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(239,'James Leask','james-leask','1934-01-22','2004-05-11','Rumpa','Surrey, England','James William ''Willie'' Leask was a Zetland County Councillor, Shetland Islands Councillor and nightwatchman.',NULL,NULL,NULL,'I196163','James_Leask','["Zetland County Councillors", "Shetland Islands Councillors", "1934 Births", "2004 Deaths", "Biography Missing"]',1,0,NULL);
INSERT INTO "people" VALUES(240,'James Loggie','james-loggie','1873-10-17','1947-05-15','Braintree','Aberdeen','James Alexander Loggie was raised in the Aberdeen area. He married Flora Gibson at St Nicholas, Aberdeen, on January 9, 1895. (ref);Moving to Lerwick, he was the proprietor of the Royal Bar and the Queens Hotel, both on Commercial Street. Three of the five Loggie children were born in Lerwick. His Flora, a 19-foot Shamrock class racing boat built by John Shewan of Garthspool, won the local regatta in 1904 and 1905. He was denied a repeat win and possession of the cup in the following year by taking second to Flora''s sister boat, the Seamew, owned by Mr. Bruce of Sandlodge. (ref) In the political arena, Mr. Loggie made unsuccessful bids for County Council representing Northmavine North in 1904 and Lerwick Town Council in 1909. He was elected to Town
Council and to County Council representing Nesting and Lunnasting in 1910, and retained his County seat in 1913, only to resign one week later. Mr. Loggie championed the cause of the Shetland Sheepdog and was the first secretary of the Shetland Collie Club when it formed in 1908. He penned an article about the breed, fitting it out with the following resume: That the Shetland Sheep-dog is now a distinct breed of dog no one can deny. It was originally known as the &quot;Shetland Collie&quot; or &quot;Toonie Dog&quot;. The dog took its title from the fact of its being used to drive the sheep off the township, croft, or what is known in Shetland as the &quot;Toon.&quot; Many years ago, when large sheep farms were established in Shetland, shepherds from the mainland brought with them Scotch Collies and gave the progeny to the crofters: but in-breeding and the want of keeping up fresh blood soon caused the breed to become diminutive. Few people, who have not visited Shetland, are aware of the conditions of these crofts; very few of them have fences or dykes to protect their crops, or to divide the arable land from the hill pasture; and in seasons when the hills are scarce of pasturage, the sheep come down and feed off the stacks of hay and corn in the stackyard, and also eat the turnips and cabbage growing around the house. When this occurs the dog has a duty to perform, and is used to drive the sheep back to the hills, and need not be accompanied by its master when once it gets the order to go. When dipping seasons come round, the owners of the sheep on the hill scattald meet on a given date with their dogs and combine to drive the sheep to the dipping places appointed. This is known locally as &quot;caaing&quot; or &quot;driving.&quot; The Shetland sheep, although small, are very wild, and they require a good deal of handling to bring them together. They are very agile, and a five-foot wall does not deter them from getting out if they want to. The Shetland crofter grudges keeping a large dog, principally on account of the food it requires, while the smaller one suits his purpose. Years ago, when Greenland whalers called at Shetland on their way home to land the members belonging to those Islands who formed part of their crews, they brought with them what was known as the &quot;Yakki&quot; dog, called after the natives of Greenland, who are known among whalers as the Yaks. Distinct traces of this dog (which was found very useful among crofters) are still to be found among the Island dogs. These Yakki dogs were bred with the Shetland dogs, and some of the strongest characteristics of the breed are often seen in the present day Shetland dog, namely, the black muzzle, large prick ears, and heavy brush of a tail, which is invariably carried high, combined with a somewhat foxy appearance. The height of these dogs is usually from 14 to 17 inches, but fashion, as in several other breeds nowadays, demands that these dogs should be bred smaller, not for utility but for pets. This undoubtedly can be done, but like the building of Rome, cannot be expected in a day. In consequence of this desire for smallness, alien blood has been introduced, and with very unsatisfactory results, which have brought discredit on the native dogs. Fortunately, by the formation of two Specialist Clubs, the interests of the breed are now being more carefully looked after. In breeding, type is of the utmost importance, and Collie character must be most carefully kept in view. Meantime, the best and most typical specimens exceed the standard of height which is being tried for; but once type is properly fixed, height and weight may be arrived at. The colours usually met with are black and white, black and tan, black - tan and white, black, sable, and sable and white. They are very affectionate and faithful, and no kinder of more lovable dogs exist. They attach themselves readily to children, and are never treacherous. They require very little food or attention. They are very hardy, and can live in outdoor kennels when required to. They are not very prolific, having generally litters of about three or four; strange to say, females invariably predominate, being generally two to one. They are very fleet and can stand a hard day''s running well. In 1908 the Shetland Sheep-dog Club was formed at Lerwick, followed by the Scottish Shetland Sheep-dog Club in 1909. The combined membership of the two Clubs number about 130. In 1909 the Kennel Club in London agreed to recognise the breed, and registered the titles of both Clubs. The Shetland Sheep-dog Club''s standard height (to which breeders were to aim at) was about 12 inches, and the weight 14 lbs.; while the Scottish Shetland Sheep-dog Club''s standard of height was the same but that of weight was 12 lbs, Since the formation of these Clubs, the breed has been largely taken up, and classes have been given at many of the principal shows, which have been well supported. The Clubs have done a great deal to popularize the breed and to stamp out alien blood. Any dog showing signs of Spaniel blood should be carefully barred. The Shetland sheep is a very small animal, only half the size of the Scotch black-faced sheep. It is not, therefore, necessary to have so large a dog to herd and keep them in bounds as is required in the Highlands. The Shetland Sheep-dog is purely a crofter''s dog, and those who own from ten to thirty Shetland sheep will not have any other. Those shepherds, however, who have from three to seven hundred black-faced ewes have larger dogs.&lt;ref&gt;Beryl Thynne, The Shetland Sheepdog, The Illustrated Kennel News, London, 1916 (first monograph of the breed).&lt;/ref&gt; Loggie''s Lerwick Kennels, described as housing twenty-five individuals in 1908, produced some outstanding early representatives. Lerwick Jarl was a prominent winner at Crufts in 1910 and the little female Zesta was a sensation in 1912. Lerwick Olaf was sold to Lady Aberdeen, another early enthusiast. Lerwick Rex, born in 1910 and exported to the USA in 1912, became the first Champion for the breed in 1915. The first British Champions, Clifford Pat and Woodvold, were both grandsons of Jarl. Mr. Loggie emigrated to Brisbane, Australia, in 1914 and returned to Scotland in 1928. He died in 1947 and is buried in Logie Coldstone.',NULL,'ShetlandMuseumPhoto M00109.jpg',NULL,'I82193','James_Loggie','["Lerwick Town Councillors", "Zetland County Councillors", "1873 Births", "1947 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(241,'James Mainland','james-mainland','1853-06-23','1938-02-20','Dunrossness','Yell','James Prophet Mainland was a sheep farmer and County Councillor for Yell North between 1925 and 1929.',NULL,'Cstout.jpg',NULL,'I357','James_Mainland','["Zetland County Councillors", "1853 Births", "1938 Deaths", "Biography Missing"]',1,1,290835744);
INSERT INTO "people" VALUES(242,'James Manson','james-manson','1953-01-06','1991-04-23','Northmavine','Aberdeen','James Maurice Manson was a Shetland Islands Councillor for Northmavine between 1990 and 1991. He obtained an MA from the University of Aberdeen in 1975, and also worked for the London Met for seven years. After spending some time in Orkney, he returned to Shetland. In the 1990 SIC election, he defeated his fourth cousin [person:william-manson:Bill Manson] by 2 votes. The by-election which followed his death elected Bill Manson.',NULL,NULL,NULL,'I145434','James_Manson','["Shetland Islands Councillors", "Died in office", "1953 Births", "1991 Deaths"]',1,0,155802660);
INSERT INTO "people" VALUES(243,'James Matches','james-matches','1903','1974-07-22','Orkney','Bressay','James Lennie Matches was a Church of Scotland missionary and County Councillor, representing Unst North between 1949 and 1961, losing the 1961 election and also coming up short in 1964 in the Cunningsburgh parish.','James was a missionary in Shetland for 46 years, spending 24 of those years in Bressay. He first came to Shetland in 1934 to Burra, before moving back to Orkney in 1936. He returned to Shetland in 1939 as a locum in Uyeasound, he was transferred to Mid Yell at the outbreak of WWI. He moved back to Unst in 1945, getting a position in Baltasound. Next, he transferred to Whiteness & Weisdale for 2 years before moving to Bressay. He began his working life in ironmongery and grocery, but took evening classes to retrain into church work.',NULL,NULL,'I138704','James_Matches','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1903 Births", "1974 Deaths", "Orcadians"]',0,1,120862286);
INSERT INTO "people" VALUES(244,'James McCullie','james-mccullie','1856-06-11','1934','Lochee',NULL,'James McCullie was a school teacher and County Councillor for Aithsting between 1892 and 1895.','James was a teacher at the Happyhansel School in Walls. An argument erupted at the first Zetland County Council election concerning the seat that James McCullie was contesting. The argument centered around the electoral roll and nominations. James beat [person:archibald-garriock:Archibald Garriock] by 44 votes to 2, but the Council wound up appointing Archibald over James. On 18 April 1924, the McCullies emigrated to Canada aboard the Matagama.',NULL,NULL,'I127056','James_McCullie','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Death Date", "Incomers to Shetland", "1856 Births", "1934 Deaths", "Teachers"]',0,NULL,NULL);
INSERT INTO "people" VALUES(245,'James Moodie','james-moodie',NULL,'1724-02-04',NULL,NULL,'James Moodie of Orkney was a Member of Parliament for Orkney and Shetland from 1715 to 1722. He was the second son of Royal Navy Captain James Moodie of Melsetter, Orkney. His mother was the daughter of James Douglas, 11th Earl of Morton.',NULL,NULL,NULL,NULL,'James_Moodie','["Members of the Parliament of Great Britain"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(246,'James Morrison','james-morrison','1877-01-05','1937-12-29','Skeld','Lerwick','Eleaser John James Garrick Morrison was a stonemason, builder and Lerwick Town Councillor first between 1919 and 1925, then again in 1932 when he was appointed following John Campbell''s resignation until 1935. He was also the father of [person:alexander-morrison:Alexander Morrison].','James followed the family tradition of becoming a builder. His father had built the Skeld, Scalloway and Whiteness schools, and as a result, James moved around all three towns as a child, before the family settled at Hellister in Whiteness. James attended the Whiteness school, leaving at the age of 14, and began work with [person:peter-anderson:Peter Anderson] in his butchery. After a year, he moved to Glasgow and worked as a mason and stonecutter at the form of P & W. Anderson. Through this firm he was employed as a foreman on various building works in Glasgow. In 1900, his uncle, Magnus secured the contract for building new premises on Commericial Road for [person:john-tait:John Tait], and he requested James return to Lerwick to act as foreman on the site. Although he thought his visit only temporary, he was continually furnished with work and so eventually he settled in Lerwick, and was connected to his uncle''s firm for over 35 years. Some of the building sites of which he was the foreman include a bakehouse for William Hall, the Shetland Hosiery Company''s premises, [person:edwyn-tait:Edwyn Tait]''s premises and the Territorial Drill Hall. He was also involved in the building of the Bruce Hostel, and alterations to the Anderson Institute and Commercial Bank. In political, he was a Liberal',NULL,NULL,'I63732','James_Morrison','["Lerwick Town Councillors"]',1,1,285456097);
INSERT INTO "people" VALUES(247,'James Mouat (i)','james-mouat-i','1764-09-09','1852-01-25','Wormadale','Lerwick','James Mouat was a grocer, house proprietor and Lerwick Town Councillor. He was a distant relative of Robert Stewart, Earl of Orkney (7th Great-grandfather through his wife). His son [person:james-mouat-ii:James] and his grandson, [person:james-goudie:James Mouat Goudie], were also Lerwick Town Councillors.',NULL,NULL,NULL,'I15357','James_Mouat_(i)','["Lerwick Town Councillors", "1764 Births", "1852 Deaths", "Natives of Shetland", "Merchants", "Mouat"]',1,1,NULL);
INSERT INTO "people" VALUES(248,'James Mouat (ii)','james-mouat-ii','1807-04-26','1853-02-28','Lerwick','Lerwick','James Mouat was a shipping agent, distributor of stamps and Lerwick Town Councillor. His father, [person:james-mouat-i:James Mouat], was also a town councillor. He was a distant relative of Robert Stewart, Earl of Orkney (6th Great-grandfather) and his cousin three-times-removed, [person:james-mouat-iii:James], was also a Councillor. His newphie, [person:james-goudie:James Mouat Goudie], was a councillor and Provost of Lerwick.',NULL,NULL,NULL,'I18286','James_Mouat_(ii)','["Lerwick Town Councillors", "1807 Births", "1853 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(249,'James Mouat (iii)','james-mouat-iii','1867-03-17','1937-04-28','Tingwall','Lerwick','James Peter Mouat was a commission agent and a County Councillor for Tingwall between 1919 and 1935. His brother [person:henry-mouat:Henry] became the Provost of Lerwick. He was a distant relative of Robert Stewart, Earl of Orkney (10th Great-grandfather), a cousin three-times-removed of [person:james-mouat-ii:James] and the great nephew of [person:james-mouat-i:James].','His family moved to Girlsta when he was young, with his father running the local mill, lime kiln and farm there. He studied for the Civil Service but felt compelled to work with his father owing to his advancing years. As a young man, he took up land surveying and had an involvement with the Crofters Commission when it arrived in Shetland. In 1895, the family left Girlsta and settled in North Hammersland, Tingwall. He represented a number of firms from the Scottish Mainland as a Commission Agent, and he also was involved in agricultural sales. In 1918, he settled in Lerwick.',NULL,NULL,'I82425','James_Mouat_(iii)','["Zetland County Councillors", "1867 Births", "1937 Deaths"]',1,1,179953606);
INSERT INTO "people" VALUES(250,'James Nicolson (i)','james-nicolson-i','1888-11-02','1965-09-23','Sound','Lerwick','James John Nicolson was a County Councillor for Gulberwick between 1951 and 1955.','Born near Clickimin, James''s family moved to a Brindister croft when he was young. At the age of 14, he became a crane boy aboard the St Rognvald and moved from there into deep water sailing. In 1918 James worked with North of Scotland Company and was aboard the St Magnus when she was torpedoed off Peterhead. His final ship was the St Sunniva, in 1919. He then returned to Shetland where he began a milk round in Lerwick and began expanding his farm holdings, including buying land in Gulberwick. Around 1955 he retired and passed the farm down to his family. He had a hand in much of the agriculture industry in Shetland, he was President of the Cunningsburgh Agricultural Society, an office-bearer for the Shetland Sheepdog Trials, a former Chair of the National Farmers Union in Shetland and Chair of the Shetland Marts. He was also a founding member of Shetland Lime Ltd.',NULL,NULL,'I33711','James_Nicolson_(i)','["Zetland County Councillors", "1888 Births", "1965 Deaths"]',1,1,179138534);
INSERT INTO "people" VALUES(251,'James Nicolson (ii)','james-nicolson-ii','1927-10-17','2003-03-12','Bruntskerry','Aberdeen','James William ''Jeemie'' Nicolson was a truck driver for Shetland Lime Ltd., owner of Lochside Taxis and a Shetland Islands Councillor for Sandness And Walls between 1986 and 1990 as an independent.',NULL,'Retirement.jpg',NULL,'I68712','James_Nicolson_(ii)','["Shetland Islands Councillors", "1927 Births", "2003 Deaths"]',1,0,216695452);
INSERT INTO "people" VALUES(252,'James Ogilvy','james-ogilvy','1794-11-29','1848','Lerwick','New Orleans','James Ogilvy was a merchant and Lerwick Town Councillor. His uncle [person:charles-ogilvy-i:Charles], and two of his cousins, [person:charles-ogilvy-ii:Charles] and [person:john-ogilvy:John] were also councillors',NULL,NULL,NULL,'I18310','James_Ogilvy','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Death Date", "1794 Births", "1848 Deaths", "Natives of Shetland", "Merchants", "Ogilvy"]',1,NULL,NULL);
INSERT INTO "people" VALUES(253,'James Paton (i)','james-paton-i','1900-06-17','1981-08-26','Lerwick',NULL,'James John Paton was a Lerwick Town Councillor between 1960 and 1975 and a Shetland Islands Councillor for Lerwick Twageos between 1978 and 1982. He was the grandfather of former Shetland Islands Councillor for the same area, [person:james-paton-ii:James]. as well as the Lerwick Twageos seat at the 1978 Shetland Islands Council election.',NULL,NULL,NULL,'I27567','James_Paton_(i)','["Shetland Islands Councillors", "Lerwick Town Councillors", "1900 Births", "1981 Deaths"]',1,NULL,290836564);
INSERT INTO "people" VALUES(254,'James Paton (ii)','james-paton-ii','1961-04-30',NULL,'Lerwick',NULL,'James John Paton is a former Shetland Islands Councillor for Lerwick Twageos from May 1986 until he resigned in August 1988. He was the grandson of former Shetland Islands Councillor for the same area, [person:james-paton-i:James].',NULL,NULL,NULL,'I199333','James_Paton_(ii)','["Shetland Islands Councillors", "1961 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(255,'James Peterson','james-peterson','1899-09-25','1963-11-11','Unst','Lerwick','James George ''Pete'' Peterson was the founder of Grantfield Stores and a Lerwick Town Councillor from 1945 to 1955.','Pete spent all his life in the grocery trade. He started work as an apprentice with Messrs D & G Kay, working his way up to becoming Manager. In 1931, he took over Anderson''s grocery shop at Grantfield and grew the business considerably. In WWI, he was decorated for bravery on the Western Front. After the war, he joined the council and was at the forefront of discussions around improving Shetland.',NULL,NULL,'I42070','James_Peterson','["Lerwick Town Councillors", "1899 Births", "1963 Deaths"]',1,1,287143237);
INSERT INTO "people" VALUES(256,'James Pottinger (i)','james-pottinger-i','bef 1790','1836-06-18',NULL,'Edinburgh','James Pottinger was a purser for the Royal Navy and a Lerwick Town Councillor.',NULL,NULL,NULL,'I21859','James_Pottinger_(i)','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "Councillors - Missing Birth Location", "1836 Deaths", "Seaman", "Pottinger"]',NULL,0,NULL);
INSERT INTO "people" VALUES(257,'James Pottinger (ii)','james-pottinger-ii','1897-04-07','1980-02-27','Setter','Lerwick','James Pottinger was a general merchant and County Councillor first for Burra between 1938 and 1955, then for Sandwick between 1955 and 1958, and finally for Whalsay And Skerries between 1964 and 1973.',NULL,'Janetcourtnyopening.jpg',NULL,'I88244','James_Pottinger_(ii)','["Zetland County Councillors", "1897 Births", "1980 Deaths", "Biography Missing"]',1,1,120393470);
INSERT INTO "people" VALUES(258,'James Pottinger (iii)','james-pottinger-iii','1872-11-20','1961-04-12','Nesting','Edinburgh','James John Pottinger was a compositor, briefly a Lerwick Town Councillor from 1919 until his resignation in 1921 and a County Councillor for Lerwick Central between 1919 until he resigned in May 1921. His brother, [person:francis-pottinger:Francis] was also a County Councillor.','In 1893, James was working and living in Edinburgh, and joined the Social Democratic Federation. His brother Francis joined him in 1896. James was for some time employed by R & R Clark, a printers in Edinburgh. Around 1911, he was elected as President of the Edinburgh and Leith Printing Establishments Association. In early 1918, James was appointed as secretary for the Edinburgh Labour Party, but had resigned by the start of 1919.',NULL,NULL,'I28933','James_Pottinger_(iii)','["Lerwick Town Councillors", "1876 Births", "1948 Deaths"]',1,0,284526131);
INSERT INTO "people" VALUES(259,'James Ritch','james-ritch',NULL,NULL,NULL,NULL,'James Mark Ritch is a former Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'James_Ritch','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(260,'James Scott','james-scott','1785-03-06','1859-12-20','Melby','Musselburgh, East Lothian','James Scott was a surgeon and Lerwick Town Councillor.','James entered the Navy in 1803 as assistant surgeon of HMS Fisgard and saw action in 1804 off Porto Severa (location unknown). Having been promoted to the rank of Surgeon in 1805 and appointed to HMS Rose, he continued his service in the Mediterranean and West India stations until 1807, when he joined the Bantern, which participated in the Battle of Copenhagen. He was with the Rose until her loss in 1809 at Bic Island in the St Lawrence River. Through the shipwreck he experienced extreme hardships due to the ice, but eventually returned to England and joined the Euryallus, captained by [person:george-dundas:George Dundas], who was twice MPs for Orkney and Shetland. In 1811, he joined the HMS Centaur and until 1815 was also a member of the crew on the Sybile and Rivole. After many years at sea, he was ashore long enough to graduate from the University of Paris, but was called again into active service in 1824 with the HMS Britannia, serving until 1826. That year, he was selected by Sir William Burnett, the late Director-General of the Medical Department of the Navy for the honour position of Lecturer to the Royal Naval Hospital at Haslar, Gosport, and as curator of its museum. In 1830, he was appointed to run the Lunatic Asylum at the same facility. He resigned from his position at Haslar in 1838, was involved in the new Denham Park Asylum in Uxbridge, but by November of that same year he had resigned his position "in consequence of the proprietors wishing to interfere with his arrangements" (Salisbury & Winchester Journal 12 Nov 1838). He moved to settle in Portsmouth. He sustained severe injuries during an accident wherein he was crushed between a drawbridge and a cart that limited his ability to move. In 1846, he received the rank of Deputy Inspector-General of Hospitals and Fleets.',NULL,NULL,'I18362','James_Scott','["Lerwick Town Councillors", "1785 Births", "1860 Deaths", "Natives of Shetland", "Doctors"]',1,0,NULL);
INSERT INTO "people" VALUES(261,'James Shearer','james-shearer','1867-04-07','1949-03-28','Clate',NULL,'James Shearer was a County Councillor.','James was educated at Livister School and like many young men in Shetland took to the sea after completing his education. While in the merchant navy, he sustained an injury to his leg which ended that career, and he returned to Shetland where he became a fisherman. He was first on the vessel Union that operated out of Whalsay, and later he had a sailing boat built, named Ocean Spray. He became a Commission Agent and in 1911 placed the first order for a steamer to be built for a Shetland owner. This was the Lily Jane, registered in Lowestoft and operated by a crew of Lowestoft men. He then had another two steamers built, Star of Thule and Maid of Thule (later known as Clings Water). All three of his boats entered service at the outbreak of WWI. At that point, James joined the Royal Naval Volunteer Reserve and served throughout the war, at one point being in charge of boom defence at the southern mouth of Lerwick''s harbour. His nephew, [person:magnus-shearer-i:Magnus] was also involved in Local Government.',NULL,NULL,'I50882','James_Shearer','["Zetland County Councillors", "1867 Births", "1949 Deaths"]',1,NULL,292642475);
INSERT INTO "people" VALUES(262,'James Smith (i)','james-smith-i','1877-07-07','1943-04-18','Mid Yell','Lerwick','James Andrew ''Ooie Jeemie'' Smith was a shopkeeper and Lerwick Town Councillor from 1934 to 1941, as provost from 1936 until his resignation in 1941. His brother in law [person:john-leslie-ii:John Leslie] was also a Councillor and his daughter, Patricia, was married to Major [person:william-anderson-ii:Bill Anderson]','He first had a wool and hosiery business in his native island of Yell, and moved after World War I to set up in Lerwick. He was a founder and President of the Shetland Woollen Industry Association, whose principal aim was the protection of Shetland''s hand-knitted industry by means of a trademark.','James Smith Provost.png','James Smith Headshot.png','I19636','James_Smith_(i)','["Lerwick Town Councillors", "Zetland County Councillors", "Council Leaders", "Lerwick Town Council Provosts", "1877 Births", "1943 Deaths", "Councillors pictured"]',1,1,202663152);
INSERT INTO "people" VALUES(263,'James Smith (ii)','james-smith-ii','1899-12-14','1981-05-03','Ulsta','Crueton, Bressay','James Smith was a merchant seaman and County Councillor for Bressay between 1949 and 1955. His brother, [person:prophet-smith:Prophet], was a councillor for the Lerwick Town Council, Zetland County Council and the Shetland Islands Council, as well as the Labour candidate in the 1945 UK General election for Labour.',NULL,NULL,NULL,'I120105','James_Smith_(ii)','["Zetland County Councillors", "Seamen", "1899 Births", "1981 Deaths", "Biography Missing"]',1,1,179137392);
INSERT INTO "people" VALUES(264,'James Smith (iii)','james-smith-iii','1941-10-02',NULL,'Sandwick',NULL,'James Laurence Barclay ''Jeemie Blub'' Smith is a former marine engineer and Shetland Islands Councillor for Sandwick.',NULL,NULL,NULL,'I71567','James_Smith_(iii)','["Shetland Islands Councillors", "Engineers", "1941 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(265,'James Sutherland','james-sutherland','1847-03-11','1918-03-23','Papil','Newhaven, Sussex','James Henderson Sutherland was a fishcurer and County Councillor.','Though born in Unst, James moved to Lerwick as a young man and spent time between both areas. James worked for some time with D. & J. Sutherland, merchants in Unst. His son John was a well known heraldic artist in Edinburgh. In February 1892, James was appointed as Postmaster in Unst.',NULL,NULL,'I85516','James_Sutherland','["Zetland County Councillors", "1847 Births", "1918 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(266,'James Tait','james-tait','1922-11-27','2011-04-29','Sandwick','Edinburgh','James Williamson Tait was a Lerwick Town Councillor from 1952 to 1958.','James worked for the Post Post Office as an engineer. In the late 1940s, James was the Secretary of the Shetland Labour Party. James''s work saw him transferred to Edinburgh in later life. In August 2002, he was a proposer for Labour candidate Norman Bonney the Balerno ward of the Edinburgh City Council.','JamesWTait.png',NULL,'I19850','James_Tait','["Lerwick Town Councillors", "1922 Births", "2011 Deaths", "Labour"]',1,0,NULL);
INSERT INTO "people" VALUES(267,'James Taylor','james-taylor','1906-03-31','1981-11-08','Whiteness','Lerwick','James John ''Jim'' Taylor was the founder of J. J. Taylor (''Jim Taylor''s''), a shop which still exists today, and also was a Lerwick Town Councillor.','Jim took over [person:george-nelson:George Nelson]''s business on Commercial Road, and expended its offering from dairy to include more, and a new confectionery section. He was the final Provost representing the Lerwick Town Council, which was replaced by the Shetland Islands Council.','JJ Taylor Provost.png','James J Taylor Headshot.png','I262258','James_Taylor','["Lerwick Town Councillors", "1906 Births", "1981 Deaths", "Natives of Shetland", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(268,'James Thomason','james-thomason','1853-05-15','1924-03-07','Hildasay','Walls','James Thomason was a farmer, factor and County Councillor for Walls between 1907 and 1919.','At an early age, James went to sea. When [person:herbert-anderton:Herbert Anderton] purchased Vaila in 1883, James became Factor to the estate. At one point, James acted as factor for five different proprietors the main two were Foster of Burrastow, Anderton of Vaila. The remaining three, Allan, Richards and Ridout, were absorbed into the Vaila estate.’',NULL,NULL,'I71527','James_Thomason','["Zetland County Councillors", "1853 Births", "1924 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(269,'James Tulloch','james-tulloch','1812-03-01','1899-10-08','Sand','Glasgow','James Tulloch was a general merchant, grocer, draper, blacksmith and a Lerwick Town Councillor.','In 1835, James started a blacksmith in Lerwick and continued for some years until he switched professions and became a draper, which he continued through until 1890. After retiring from his business, he moved briefly to Edinburgh before later heading west to Glasgow to spend his final years living with his sons. He was a staunch Liberal who was a supporter of Gladstone.',NULL,NULL,'I96692','James_Tulloch','["Lerwick Town Councillors", "1812 Births", "1899 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(270,'James Wallace','james-wallace','1954-08-25',NULL,NULL,NULL,'James Robert ''Jim'' Wallace, Baron Wallace of Tankerness, PC, QC (born 25 August 1954) is a British politician and leader of the Liberal Democrats in the House of Lords. He was formerly Leader of the Scottish Liberal Democrats, Member of Parliament (MP) for Orkney and Shetland, Member of the Scottish Parliament (MSP) for Orkney, the first Deputy First Minister of Scotland in the Scottish Executive and Advocate General for Scotland.','Lord Wallace was born in Annan in Dumfriesshire, Scotland, and grew up there. As a boy, his first interest in politics was stoked when he collected autographs from politicians visiting the local area: he still possesses one from Tam Dalyell, with whom he later served in the House of Commons. After finishing school in Annan he was accepted by Downing College, Cambridge, where he obtained a joint degree in Economics and Law, and was also rumoured to have been a member of the ''Three Kings'' society. From there he returned to Scotland to read Law at Edinburgh, graduating in 1977. Based in Edinburgh, he practised as an advocate at the Scottish Bar, mostly in civil law cases.',NULL,NULL,NULL,'James_Wallace','["Members of the Parliament of the United Kingdom", "Liberals", "Liberal Democrats"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(271,'James White','james-white','1886-02-03','1961-05-10','Aithsting','Aithsting','James Robert White was a County Councillor initially for Dunrossness North from 1922 to 1925, then for Lerwick Central 1928 to 1929, and finally for Sandsting from 1930 and 1932.','He began his working life in Scalloway, before serving in WWI as a gunner. After the war he returned to Sand and established a shop there. After some years, he established J. R. White & Co in Lerwick with his brother. He was a founding member of the Shetland Woollen Industries Association and its first secretary, as well as being involved in the Shetland Baptist Association.',NULL,NULL,'I63868','James_White','["Zetland County Councillors", "1886 Births", "1961 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(272,'James Williamson','james-williamson','1912-03-03',NULL,'Lerwick',NULL,'James David Williamson was a Lerwick Town Councillor. .',NULL,NULL,NULL,'I22864','James_Williamson','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Death Date", "1912 Births", "1985 Deaths"]',1,NULL,NULL);
INSERT INTO "people" VALUES(273,'James Yorston','james-yorston','1790-03-06','1849-02-10','Lerwick','Lerwick','James Yorston was a purser, agent for the National Bank and a Lerwick Town Councillor.',NULL,NULL,NULL,'I17142','James_Yorston','["Lerwick Town Councillors", "1790 Births", "1849 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(274,'Jemima Walterson','jemima-walterson','1912-06-28','2003-06-24','Aith','Lerwick','Jemima Walterson MBE (neé Smith) was a teacher and a Shetland Islands Councillor for Scalloway between 1978 and 1982.',NULL,'Jwalterson.jpg',NULL,'I60487','Jemima_Walterson','["Shetland Islands Councillors", "Teachers", "1912 Births", "2009 Deaths", "Female"]',1,1,195894644);
INSERT INTO "people" VALUES(275,'Jo Grimond','jo-grimond','1913-07-29','1993-10-24',NULL,NULL,'Joseph Grimond, Baron Grimond, CH, CBE, TD, PC, known as Jo Grimond, was a British politician, leader of the Liberal Party from 1956 to 1967 and again briefly on an interim basis in 1976. Jo Grimond was a long-term supporter of Scottish home rule; and, during his leadership, he successfully argued that the Liberal Party support the abolition of Britain''s nuclear arsenal.','Grimond was born in St Andrews, Fife, and educated at Eton College and Balliol College, Oxford. He was at school and university with, among others, cricket commentator Brian Johnston and playwright William Douglas-Home. He received a First Class honours degree in Politics, Philosophy and Economics. He became a barrister, being admitted to the bar as a member of Middle Temple.','Jo Grimond.jpg',NULL,NULL,'Jo_Grimond','["Members of the Parliament of the United Kingdom", "Liberals"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(276,'Joan Easten','joan-easten','1946-06-06',NULL,NULL,NULL,'Joan Wilma Easten (neé Irvine) is a former Shetland Islands Councillor for Unst between 1990 and 1999, where she stood as a Shetland Movement candidate.',NULL,NULL,NULL,'I28236','Joan_Easten','["Shetland Islands Councillors", "1946 Births", "Female"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(277,'Joan McLeod','joan-mcleod','1918-11-10','1999-12-10','Meal','Overtonlea, Levenwick','Joan McLeod (neé Jarmson) was a County Councillor from 1961 until 1975 and a Shetland Islands Councillor from 1974 until 1994.','Joan spent a great deal of her career in public service, with more than 33 as an elected councillor. She also represented the council on various external bodies, such as the COSLA social work committee and the Aberdeen Town and County Association for Teaching the Blind at their Homes.',NULL,NULL,'I195683','Joan_McLeod','["Zetland County Councillors", "Shetland Islands Councillors", "Female", "1918 Births", "1999 Deaths"]',1,1,179137890);
INSERT INTO "people" VALUES(278,'John Anderson','john-anderson','1852-04-26','1938-03-16','Lerwick','Lerwick','John Bannatyne Anderson was a solicitor and County Councillor who represented Lerwick North between the years of 1890 and 1901, Northmavine South from 1901 to 1904 and Sandsting, 1904-1907. He was also a Lerwick Town Councillor between 1886 and 1891. His brother, [person:robert-anderson-ii:Robert], was a Lerwick Town Councillor.','John was educated at the Anderson Institute and went to Edinburgh in 1869 aged 17 to take legal training. He served an apprenticeship and studied law while in Edinburgh, and was admitted as a law agent on 10 January 1882. He returned to Shetland and started his own firm at Anderson Place, before moving to 58 Commercial Street. Although on the County Council he elected to the Lerwick North seat, he transferred in 1901 to Northmavine South as Lerwick members were excluded from parts of the County business in which Lerwick had no interest. He retired from his firm in 1935 and his business was taken over by Peter Goodlad, under the name J. B. Anderson & Goodlad. Politically, John was a Liberal and was the local Liberal Agent for a number of years. He was described by the Shetland Times as "one of Shetland''s most prominent and most respected sons" when he died in 1938.','JB Anderson.png','JB Anderson headshot.png','I87228','John_Anderson','["Lerwick Town Councillors", "Zetland County Councillors", "1853 Births", "1938 Deaths"]',1,1,182210487);
INSERT INTO "people" VALUES(279,'John Balfour','john-balfour',NULL,NULL,NULL,NULL,'John Balfour (6 November 1750 – 15 October 1842) was a Scottish politician and a civil servant in the East India Company with connections to the Orcadian island of Shapinsay.','John Balfour was the son of William Balfour, a factor to the Dundas family. The family was descended from the Balfours of Trenabie on the island of Westray. Having made a fortune in India, John Balfour married the widow of a Colonel Mackennan, who along with other British expatriates, had lent money to the Rajah of Tanjore, who then refused to repay the loans.',NULL,NULL,NULL,'John_Balfour','["Members of the Parliament of Great Britain", "Members of the Parliament of the United Kingdom"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(280,'John Bruce','john-bruce','1837-06-09','1907-07-04','Sandwick','Edinburgh','John Bruce was a landlord and merchant who lived at Sandlodge in Sandwick. He was a bitter opponent of the crofting legislation of the 1880s, and unsuccessfully pursued the captors of the whales in the Hoswick whale case of 1888-1890.','He was most commonly referred to as John Bruce the Younger He was also the owner of the smack Columbine, which drifted to Norway with only Betty Mouat onboard. Bruce was elected the member for Dunrossness South on the Zetland County Council at its inception in 1890. He was then elected to the position of Convener of the County, the first person to hold the role, which he retained until his death in 1907. Bruce purchased Lunna House, the Hunter of Lunna family estate from [person:robert-bell:Robert Hunter Bell] in May 1893 for the sum of £9740.00.',NULL,'John Bruce Headshot.png','I12498','John_Bruce','["Zetland County Councillors", "Conveners of the Zetland County Council", "1837 Births", "1907 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(281,'John Butler','john-butler','1925-11-01','1984-05-12','Walney Island','Lerwick','John Charles Butler was a customs officer, Lerwick Town Councillor between 1971 to 1975, and a Shetland Islands Councillor for Lerwick Breiwick between 1974 and 1982.',NULL,NULL,NULL,'I25371','John_Butler','["Shetland Islands Councillors", "Lerwick Town Councillors", "1925 Births", "1984 Deaths"]',0,1,292342561);
INSERT INTO "people" VALUES(282,'John Campbell (i)','john-campbell-i','1887-09-23','1954-09-03','Lerwick','Lerwick','John Campbell was a pharmacist and Lerwick Town Councillor from 1925 until his resignation in May 1932. Campbell was also the Guizer Jarl in 1923.','The eldest son of the Burgh Surveyor, Alexander Campbell, John was educated at the Anderson Institute and was subsequently apprenticed with [person:arthur-porteous:Arthur Porteous] at his Lerwick pharmacy. Upon completion of his apprenticeship, in 1907, John moved to Edinburgh where he was employed by Basildons, and in 1911 he qualified as a Member of the Pharmaceutical Society at the Heriot Watt College. From 1911 onwards, John returned to work back with Arthur Porteous until Arthur retired in 1932, wherein John took over the business. He was the Up Helly-Aa Guizer Jarl in 1923, and was an advocate for the festival.',NULL,NULL,'I71191','John_Campbell_(i)','["Lerwick Town Councillors", "1887 Births", "1954 Deaths"]',1,1,166072294);
INSERT INTO "people" VALUES(283,'John Campbell (ii)','john-campbell-ii','1875','1946-09-21','Hamilton','Glasgow','Captain John Archibald Campbell was a merchant seaman and County Councillor, representing Fetlar between 1937 and 1945. His father, [person:james-campbell:James], was the first Zetland County Councillor to represent Fetlar.','John was working in Singapore around the time that his father fell ill in 1922, and was able to get home to see him for 5 days before he passed.','JohnArchibaldCampbell.png',NULL,'I285066','John_Campbell_(ii)','["Zetland County Councillors", "1875 Births", "1946 Deaths", "Biography Missing"]',0,0,NULL);
INSERT INTO "people" VALUES(284,'John Cowie','john-cowie','1813-08-18','1866-08-26','Sandsting','Lerwick','Doctor John Cowie was a surgeon and Lerwick Town Councillor. His brother, [person:isaac-cowie:Isaac], was also a Lerwick Town Councillor.',NULL,NULL,NULL,'I45528','John_Cowie','["Lerwick Town Councillors", "1813 Births", "1866 Deaths"]',1,1,175967472);
INSERT INTO "people" VALUES(285,'John Eunson','john-eunson','1920','1978-09-15','Whalsay','Banchory, Aberdeen','John William Eunson was an RAF Pilot trainee, teacher in Scunthorpe, member of the London County Council, Lerwick Town Councillor and was a Conservative candidate for the 1955 Parliament election.','In his life he worked for the Anglo-Iranian Oil Company and the North of Scotland Hydro-Electric Board (1953-1957). During his time in the RAF he was involved in an accident which saw him break his back and lose a leg. His obituary in the Shetland Times notes that &quot;Jon made light of his physical disabilities and few realised the suffering he concealed with his ready smile and jocular manner&quot;. As indicated by the previous line, he was often referred to as &quot;Jon&quot;.',NULL,NULL,'I353125','John_Eunson','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1920 Births", "1978 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(286,'John Gear','john-gear','1904-05-28','1992-03-08','Lerwick','Aberdeen','John ''Johnnie'' Gear was a Post Office clerk, telegraphist, Lerwick Town Councillor and Lerwick Up Helly-Aa Guizer Jarl in 1935.','John Gear was born in Lerwick and started work in the Post Office in 1918. Initially a telegraph messenger he later became a sorting clerk and telegraphist. In 1942 he was promoted to Orkney, becoming postmaster at Lyness, the office for Scapa Flow. His next move was to Gourock as postmaster, then to Thurso as heads postmaster and finally back to Orkney as head postmaster at Kirkwall. He retired in 1966.','Postalworkers.jpg',NULL,'I124873','John_Gear','["Lerwick Town Councillors", "1904 Births", "1992 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(287,'John Goudie','john-goudie','1874-07-25','1949-12-02','Dunrossness','Dunrossness','John James Goudie was a County Councillor for Dunrossness North between 1934 and 1949.','He spent a short time in insurance work in Edinburgh after leaving school, before going to America as a school teacher, and later as a farmer with his brother Gilbert in South Dakota. He stayed in America for 16 years before returning back to Shetland to help his father run the family''s Dunrossness farm.','John James Goudie.png','John Goudie Headshot.png','I68889','John_Goudie','["Zetland County Councillors", "1874 Births", "1949 Deaths"]',1,1,179138298);
INSERT INTO "people" VALUES(288,'John Graham','john-graham','1921-07-12','2008-02-22','St. Olaf Street','Lerwick','John James Graham was an author, editor, teacher and Shetland Islands Councillor. John compiled the Shetland Dictionary and is one of the key figures in Shetland culture in the latter half of the 20th century.','Graham was born in Lerwick in 1921, but spent the first five years of his life in Stromfirth, Weisdale, after which the family moved to Tingwall, where he went to Gott Public School. He then attended the Lerwick Central School. John served with honour in the RAF during World War II, then entered Edinburgh University where he was active in student literary circles along with his brother Lollie Laurence I. Graham. John graduated M.A.in 1950. He became an English teacher at the Anderson Educational Institute from 1950 until 1966, was made headmaster of the Lerwick Central Secondary School in 1966, and then headmaster of the Anderson High School in 1970, where he remained until he retired in 1982. He subsequently served as member for Sound on the Shetland Islands Council. With his brother Lollie (Laurence) Graham, John Graham was co-editor of quarterly magazine The New Shetlander from 1956 to 1998. As president of the Shetland Folk Society he was instrumental in the reprinting of Jakob Jakobsen''s dictionary, sacrificing his own 1st edition so that the facsimile might be created.','John_J_Graham.png',NULL,NULL,'John_Graham','["Shetland Islands Councillors", "Writers", "Natives of Shetland", "Teachers", "1921 Births", "2008 Deaths", "Councillors pictured"]',1,1,295041231);
INSERT INTO "people" VALUES(289,'John Harrison (i)','john-harrison-i','1836-06-21','1903-06-26','Lerwick','Lerwick','John Harrison was a fish merchant, auctioneer, commission agent and Lerwick Town Councillor.','In 1903, John was imprisoned for two months in Lerwick for financial crimes related to the Bankruptcy Act. He died a few months later in his home, West Hall. His nephew, [person:john-harrison-ii:John] was a County Councillor.',NULL,NULL,'I9197','John_Harrison_(i)','["Lerwick Town Councillors", "1836 Births", "1903 Deaths"]',1,1,179947228);
INSERT INTO "people" VALUES(290,'John Harrison (ii)','john-harrison-ii','1878-08-05','1960-09-05','Lerwick','Lerwick','John Harrison was a draper and a County Councillor for Sandness between 1921 and 1925. His uncle, [person:john-harrison-i:John] was a Lerwick Town Councillor.',NULL,NULL,NULL,'I18072','John_Harrison_(ii)','["Zetland County Councillors", "1878 Births", "1960 Deaths"]',1,1,179947272);
INSERT INTO "people" VALUES(291,'John Henderson','john-henderson','1873-05-02','1938-11-16','Setter','40 Percy Gardens, Tynemouth','John Percy Henderson was a dentist in Lerwick, a Lerwick Town Councillor between 1916 and 1919, and County Councillor initially for Delting North between 1907 to 1913, then for Whiteness & Weisdale from 1914 to 1919, and finally for Burra between 1922 and 1938.','Founder of Henderson & Scott, dentists. John left Shetland as a young age and lived in Gateshead for some years, where there exists a large bakery business that was set up by members of his family. Around 1896, he returned to Shetland and opened a dental practice. He retired from his practice in 1935, which was continued by partner G. M. Scott until at least 1958. In 1937 or 1938 he moved to Tynemouth.',NULL,'John Percy Henderson Headshot.png','I85430','John_Henderson','["Zetland County Councillors", "Lerwick Town Councillors", "1873 Births", "1938 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(292,'John Hughson','john-hughson','1778','1862-02-11','Whalsay','Lerwick','John Hughson was a joiner, merchant and Lerwick Town Councillor.',NULL,NULL,NULL,'I90991','John_Hughson','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1778 Births", "1862 Deaths", "Natives of Shetland", "Merchants", "Hughson"]',1,1,175653600);
INSERT INTO "people" VALUES(293,'John Inkster (ii)','john-inkster-ii','1887-02-01','1971-12-23','North Roe','Lerwick','John Nicolson Inkster was a bank manager in Lerwick and a Lerwick Town Councillor.','John spend his entire working life in the service of the North of Scotland (later Clydesdale) Bank. He joined the bank as an apprentice, and worked on the mainland for some years. He returned to Shetland as manager of the Lerwick branch in 1936 and remained in position until he retired in 1947.',NULL,NULL,'I27505','John_Inkster_(ii)','["Lerwick Town Councillors", "1887 Births", "1971 Deaths"]',1,1,202747633);
INSERT INTO "people" VALUES(294,'John Inkster (iii)','john-inkster-iii','1944-12-09','2021-12-12','Hamnavoe',NULL,'John Alistair Inkster is a former Shetland Islands Councillor who represented Burra and Trondra from 2003 until 2007.',NULL,NULL,NULL,'I27161','John_Inkster_(iii)','["Shetland Islands Councillors", "Natives of Shetland", "1944 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(295,'John Irvine (i)','john-irvine-i','1873-10-10','1945-04-25','Lerwick','Dunrossness','John Robertson Irvine was a County Councillor for Dunrossness South from June 1919 until December 1919, and 1925 to 1931. He failed to get re-elected at the 1919 County Council election, but was elected to serve the Dunrossness North constituency from 1925 until he resigned in 1931.','John was the Principle of Messrs Alex Irvine and Sons, builders and contractors. At a boy he served his time with his father as a joiner in the family business. He worked for some time in Edinburgh before returning to join his father and brothers in the business. The firm built homes and several schools.',NULL,NULL,'I97397','John_Irvine_(i)','["Zetland County Councillors", "1877 Births", "1959 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(296,'John Irvine (ii)','john-irvine-ii','1901-03-02','1968-09-15','Lerwick','Lerwick','John William ''Donnie'' Irvine was a registrar and County Councillor for Gulberwick from 1955 until his resignation in October 1958.','John joined the police office of the Shetland County Council in 1917. He transferred into the county office in 1924 and was appointed to the position of County Clerk in 1935. In November 1939, he was appointed as Shetland''s welfare officer. Upon retirement in the early 1960s, he had 44 years service with the council. He was a keen footballer, representing Shetland against Orkney as a right-back. He was also the Guizer Jarl for the Lerwick Up Helly-Aa in 1931.',NULL,NULL,'I160568','John_Irvine_(ii)','["Zetland County Councillors", "1901 Births", "1968 Deaths"]',1,1,179138540);
INSERT INTO "people" VALUES(297,'John Irvine (iii)','john-irvine-iii','1859-03-10','1913-07-25','Borough','New Zealand','John George Shewards Irvine was a grocer and Lerwick Town Councillor from 1901 until he resigned in December 1909.','John had a business, Thomson & Co. Provision Merchants with Laurence Thomson, from which he retired in 1904. Laurence kept the business running under the same name. In February 1905, John set up the Zetland Liberal Association with [person:alexander-mitchell-i:Alex Mitchell].',NULL,NULL,'I92038','John_Irvine_(iii)','["Lerwick Town Councillors", "1859 Births", "1913 Deaths"]',1,0,176096921);
INSERT INTO "people" VALUES(298,'John Jamieson','john-jamieson','1907-10-26','1982-01-28','Northmavine','Lerwick','John Jamieson was a headteacher, agricultural adviser for Shetland, County Councillor and Shetland Islands Councillor, first for Whalsay And Skerries between 1945 and 1947, then Northmavine South between 1972 and 1975, then Northmavine from 1974 to 1978.','He was also Vice-Chairman for Hjaltland Housing Association Ltd. from 1975 until his death in 1982 and Hjaltland-owned John Jamieson Closs in Lerwick is named after him.',NULL,NULL,'I20887','John_Jamieson','["Shetland Islands Councillors", "Zetland County Councillors", "1907 Births", "1982 Deaths"]',1,1,290592715);
INSERT INTO "people" VALUES(299,'John Johnson','john-johnson','1901-10-21','1987-02-27','Kirkhouse','Whiteness','John James ''Fleein Jack'' Johnson was a pilot, County Councillor for Whiteness And Weisdale between 1973 and 1975 and Shetland Islands Councillor for Whiteness, Weisdale & Tingwall from 1974 until 1978.','John left Whiteness school at 14 and went to sea, first on the smack Bertie. He later joined the crew of Alex. Sandison & Son''s ''Silver Lining'', on which he spent most of WWI before moving on to a steamer. He joined the RAF in 1921, being one of the first Shetland men to do so. He was stationed on an RAF base near Heliopolis in Egypt where he undertook his flight training. He later flew Vickers Vimy and Virginia bombers, leaving a distinguished RAF career in 1933. He took on a commercial pilot''s licence and flew with Highland Airways on their Orkney service before the outbreak of WWII. During that war, John was a flying instructor and test pilot. He was demobbed in 1945 with the rank of Flight Lieutenant and the Air Force Medal. He returned to the sea aboard the seine netter Pioneer and later aboard the Endeavor. A disastrous fishing season in 1961 saw that boat sold and John return to the merchant navy. He served on the Ferndene and with Salvesens on the Scotland to Norway trade route before he retired in 1965. John originally backed the Labour party politically, but disagreements led him to support the Scottish National Party in 1968.','JohnJJohnson.png',NULL,'I172195','John_Johnson','["Zetland County Councillors", "Shetland Islands Councillors", "1901 Births", "1987 Deaths"]',1,1,260955024);
INSERT INTO "people" VALUES(300,'John Laurenson','john-laurenson','1924-02-25','1992-01-08','Lerwick','Dunedin, New Zealand','John Morrison Laurenson was a Zetland County Councillor for Fetlar from 1970 to 1975.',NULL,NULL,NULL,'I175904','John_Laurenson','["Zetland County Councillors", "1924 Births", "1992 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(301,'John Leisk','john-leisk','1845-05-27','1929-05-26','Uyea','Lerwick','John Leisk was a Lerwick Town Councillor.','John arrived in Lerwick in 1861 aged 16, starting his working career with [person:george-tait:George Reid Tait] at 171 Commercial Street. In September 1871, with Alexander Sandison, he purchased Tait''s business and began trading under the name Messrs Leisk and Sandison, continuing until Alexander''s death in 1918. He then entered into partnership with John Harrison until 1928 when Leisk retired, while Harrison continued to operate the business as Leisk and Sandisons. He was a member of the Lerwick Harbour Trust for 43 years, and was one of the guarantors for the new Victoria Pier, and later served as the Chairman of the body. As a member of the Town Council, he and [person:alfred-stove:Alfred Stove] were involved in planning of the New Town. He was additionally a member of a number of other bodies, including the Lerwick Gaslight Company, Feuars and Heritors and a Director of the Shetland Fishermen''s Widows'' Relief Fund. As a young man, he was also interested in photography.','John Leisk Provost.png','John_Leisk_Headshot.png','I10067','John_Leisk','["Lerwick Town Councillors", "Councillors pictured", "1845 Births", "1929 Deaths"]',1,1,175853107);
INSERT INTO "people" VALUES(302,'John Leslie (i)','john-leslie-i','1836-03-02','1876-05-05','Scholland','Lerwick','John Leslie was a merchant and Lerwick Town Councillor.',NULL,NULL,NULL,'I82601','John_Leslie_(i)','["Lerwick Town Councillors", "1836 Births", "1876 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(303,'John Leslie (ii)','john-leslie-ii','1873-03-11','1943-03-09','Reawick','Lerwick','John Leslie was a general merchant, hosiery dealer and County Councillor for Aithsting and Sandsting between 1922 and 1925 (as the two counties were joined by the council), then from 1925 to 1928, he represented Aithsting solely. His brother in law [person:james-smith-i:James A. Smith] was also a Councillor.','John started a business in Lerwick after WWI, but temporarily closed it in order to travel the world. He visited New Zealand, Australia and America on his trip before returning.',NULL,NULL,'I35707','John_Leslie_(ii)','["Zetland County Councillors", "1873 Births", "1943 Deaths"]',1,1,185393217);
INSERT INTO "people" VALUES(304,'John Love','john-love','1851','1932','Glasgow','Edinburgh','Reverend John Love was a minister in Yell for 24 years and a County Councillor for the Yell South parish between 1890 and 1892.','John was educated at the Church of Scotland Training College in Glasgow, later attending Glasgow University for further education in theology. After completing his studies, he began his career with the Presbytery in Greenock, and was later an assistant minister in the parish of Dunoon and Kilmun. He was ordained into Yell on 8 April 1886, serving until 1910 when he moved to the Quarff Church of Scotland until late 1916. He was involved in a number of bodies outside the church, including the Parish council, and School Board. He was also a Justice of the Peace. Upon his retiral in 1916, he left Shetland.',NULL,NULL,'I136847','John_Love','["Zetland County Councillors", "Councillors - Clergymen", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1851 Births", "1932 Deaths"]',0,0,283255729);
INSERT INTO "people" VALUES(305,'John Meiklejohn','john-meiklejohn','1850-11-09','1912-08-22','Caithness','Novar, Evanton, Ross-shire','John James Robertson Meiklejohn was a farm overseer from Bressay. He was a County Councillor for the Bressay constituency between 1890 and 1892.','John arrived in Shetland in the early 1870s as a manager for John Walker at Maryfield in Bressay. Walker had sheep farms across Shetland, and John was responsible for managing the various flocks. The Marquis of Londonderry became tenant of the farm after Walker, and John continued on in his role. The Marquis wanted to establish a stud of Shetland ponies for his County Durham mines, which was successful under John''s supervision. In November 1892, he left Shetland to become the factor for Ronald Munro-Ferguson of Novar, Ross-shire.','JohnMeiklejohn.png',NULL,'I268290','John_Meiklejohn','["Zetland County Councillors", "1850 Births", "1912 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(306,'John Morrison (i)','john-morrison-i','1753-08-21','1821-04-16','Kenmore','Lerwick','John Morrison was a wright, merchant and a Lerwick Town Councillor. He was married to Barbara Anderson, sister of [person:arthur-anderson:Arthur Anderson]. He arrived in Shetland with [person:robert-deans:Robert Deans], who also became a town councillor, to work on Fort Charlotte. John built a pier, which due to a legal ruling was declared illegal, and led to his ultimate downfall. This contentious pier later became Victoria Pier, which remains the name for the largest pier in Lerwick Town Centre.',NULL,NULL,NULL,'I45613','John_Morrison_(i)','["Lerwick Town Councillors", "Incomers to Shetland", "1753 Births", "1821 Deaths", "Merchants", "Morrison"]',0,1,175653558);
INSERT INTO "people" VALUES(307,'John Nicolson','john-nicolson','1937-09-26','2019-10-09','Lerwick',NULL,'John Peter Nicolson is a former Shetland Islands Councillor for Yell South then for Yell between 1996 and 2007.',NULL,NULL,NULL,'I153917','John_Nicolson','["Shetland Islands Councillors", "Natives of Shetland", "1937 Births"]',1,NULL,284523629);
INSERT INTO "people" VALUES(308,'John Ogilvy','john-ogilvy','1800-02-16','1840-10-31','Seafield','London','John Ogilvy was a banker, landed proprietor and Lerwick Town Councillor. His father, [person:charles-ogilvy-i:Charles], his younger brother [person:charles-ogilvy-ii:Charles] and his uncle [person:james-ogilvy:James] were also councillors in Lerwick.',NULL,NULL,NULL,'I6261','John_Ogilvy','["Lerwick Town Councillors", "1800 Births", "1840 Deaths"]',1,0,290640360);
INSERT INTO "people" VALUES(309,'John Pearson (i)','john-pearson-i','1853-07-04','1940-12-29','Lunnasting','Lunnasting','John Pearson was a merchant, wire fencer and County Councillor for Nesting between 1914 and 1919. His son, [person:john-pearson-ii:John], was also a councillor for the same area.','John was part of the firm John Pearsons & Sons in Vidlin.',NULL,NULL,'I32393','John_Pearson_(i)','["Zetland County Councillors", "Natives of Shetland", "1853 Births", "1940 Deaths", "Biography Missing"]',1,1,290232917);
INSERT INTO "people" VALUES(310,'John Pearson (ii)','john-pearson-ii','1891-03-08','1969-12-27','Lunnasting','Lunnasting','John Robert Bell Pearson was a County Councillor for Nesting between 1948 and 1952. His father [person:john-pearson-i:John] was also a councillor for the same area.','',NULL,NULL,'I32429','John_Pearson_(ii)','["Zetland County Councillors", "1891 Births", "1969 Deaths", "Biography Missing"]',1,1,255833898);
INSERT INTO "people" VALUES(311,'John Priest','john-priest','1885-10-15','1964-12-02','Norwick','Kelda, Baltasound','John Henry Priest was a County Councillor for Unst North between 1952 and 1955.','During WWI, John was a Leading Seaman with the Royal Navy Reserve.',NULL,NULL,'I27967','John_Priest','["Zetland County Councillors", "1885 Births", "1964 Deaths", "Biography Missing"]',1,1,NULL);
INSERT INTO "people" VALUES(312,'John Rae','john-rae','1904-12-22','1985-11-14','Edinburgh','Weisdale','John Gordon ''Jack'' Rae was a missionary, jeweller and County Councillor.','Jack first arrived in Shetland and was a missionary on Foula. He stayed in the Weisdale Manse with his wife margaret and two sons, Alistair and Kenneth. He set up his jewellery shop after Robinson and Morrison moved into their present shop. In 1963 the Jewellery Business expanded and moved into their new present premises at Soundside, Weisdale the present business is called Shetland Jewellery where the Jewellery is produced in their workshop and is combined with a retail outlet and display area. In Lerwick at 90-92 Commercial Street their shop still operates as J. G. Rae Ltd and Kenneth is the Key pin of both operations.',NULL,NULL,'I428158','John_Rae','["Zetland County Councillors", "Councillors - Clergymen", "1904 Births", "1985 Deaths"]',0,1,255834014);
INSERT INTO "people" VALUES(313,'John Ratter','john-ratter','1891-01-21','1959-01-28','Northmavine','Cullivoe, Yell','John Scott Ratter was a County Councillor in Yell from 1948 to 1952.','John succeeded his father in the merchant business L. J. Ratter in Cullivoe. He was known as a skilled sailor in and out of Shetland.',NULL,NULL,'I19696','John_Ratter','["Zetland County Councillors", "1891 Births", "1959 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(314,'John Robertson (i)','john-robertson-i','1810-11-29','1892-04-09','Murron','Lerwick','John Robertson was a general merchant and had a lengthy spell in the Lerwick Town Council, representing initially from 1850 to 1874, then again from 1876 to 1890, a total of 38 years.','John was a very well known public figure in Shetland, with his obituary taking up three columns in the Shetland Times. He was born in Lunnasting, and moved to Lerwick in 1826 aged 16. He first worked in his brother Robert''s shop, before setting up his own grocery shop in February 1832 on Commercial Street. Alongside his grocery business, John ventured into fishcuring with his brother Robert from 1832-1844 but there was a near collapse of the industry. He then set up sites in Dunrossness and Skerries, before also expanding his grocery business into Vidlin and Lunnasting. Although his curing businesses were shut down around 1855, he continued to run his grocery stores until 1885. In 1859 when [person:william-merrylees:William Merrylees] died, John was appointed an Agent of the North of Scotland Company with William''s son [person:charles-merrylees:Charles]. He held this post until resigning in 1874, leaving Charles as the sole manager of the company. In 1864, he set out to raise funds to improve the Victoria Pier, raising £300 when £500 was needed, so he subsequently made up the shortfall. He was involved in setting up the Lerwick Gas Light Company and his grocery store in Lerwick was the first shop on the Isle to have gas lighting in 1858. In 1877, he went to London to promote the Lerwick Harbour Bill to Parliament with a committee. He was also the Chair of the Harbour Board. He was first elected to be a Commissioner of the Police in 1842, and joined the Lerwick Town Council in 1850. He served the Council for 40 years, and spent the final seven as the Chief Magistrates of the Burgh. As a councillor in 1862, he was an important part of helping Lerwick improve in line with the Lindsay act, which sought to improve sanitation in the town. He was the Junior Baillie from 1865-1874. Other titles he held were Director of the North Sea Fisher and Zetland New Fishery Company. He was also a Commissioner of Supply, a Road Trustee and a Justice of the Peace. As well as holding a Licensing Justice role, wherein he always voted with the temperance movement. He was a member of the Parochial Board, a director of the Lerwick Town Hall Company and a director of the Shetland Fishermen''s Widows'' Relief Fund. In politics, he was a Liberal, and a member of the Dissenting Church of Scotland, having previously been in the United Presbyterian, His nephew, [person:john-robertson-ii:John], was also a Lerwick Town Councillor.',NULL,NULL,'I11290','John_Robertson_(i)','["Lerwick Town Councillors", "1810 Births", "1892 Deaths"]',1,1,290623430);
INSERT INTO "people" VALUES(315,'John Robertson (ii)','john-robertson-ii','1826-03-25','1905-02-02','Lerwick','Lerwick','John ''o da Trance'' Robertson was a spirit merchant, grocer and also had a lengthy spell as a Lerwick Town Councillor, initially from 1859 until 1874, then again from 1878 to 1905, a total of 42 years. In the Town Council minutes and the election results he is listed as ''John Robertson Jr'', this is due to another [person:john-robertson-i:John Robertson], an uncle to Robertson, who was in office during a similar period of time.','Besides the general business of a merchant, John was involved in fishcuring at North Ness and Levenwick (both white fish and herring). In politics, he was a Liberal. His death caused the Lerwick Town Council by-election in 1905.','j_r_jr.png','John Robertson Jr Headshot.png','I18328','John_Robertson_(ii)','["Lerwick Town Councillors", "Zetland County Councillors", "1826 Births", "1905 Deaths", "Councillors pictured"]',1,1,290654210);
INSERT INTO "people" VALUES(316,'John Robertson (iii)','john-robertson-iii','1841-05-25','1922-01-10','Delting','Rubislaw, Aberdeen','John Robertson was a farmer, housebuilder and a County Councillor for Whiteness And Weisdale between 1890 and 1904. His uncle [person:hugh-robertson:Hugh] was also a County Councillor.','Born in Delting, he and his brother Magnus moved to Weisdale in 1872 where they established the joinery and housebuilding firm M & J Robertson. Around 1912, he joined family in Aberdeen where he stayed until his death.',NULL,'John Robertson iii Headshot.png','I120463','John_Robertson_(iii)','["Zetland County Councillors", "Councillors pictured", "1841 Births", "1922 Deaths", "1939 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(317,'John Robertson (iv)','john-robertson-iv','1878-01-27','1958-07-16','Lerwick','Lerwick','John William Robertson was one of Shetland''s most daring entrepreneurs and a Lerwick Town Councillor','Robertson was the son of Thomas Murray Robertson and Grace Pottinger. He began his working life as a clerk in the North of Scotland shipping Company''s office in Lerwick, and later became purser on the Earl of Zetland. Eventually he became a commission agent. He was the secretary of a group who acquired the steamer Norseman to ply between the mainland and Shetland, as part of an unsuccessful scheme to compete against the North of Scotland''s company''s monopoly in the islands. Soon afterwards he bought a coal hulk, and built up a successful business supplying steam drifters. He then bought the property of the Malakoff company to do repair and carpentry work. After the First World War he established the slipway and an engineering shop there. During the war he was a salvage contractor: he salvaged the sunken steam drifter Foxglove, renaming her Fitful Head. He ploughed back the profits he made with her into the purchase of more drifters. As a result he formed a herring salesman''s business as well, and eventually had curing stations at Lerwick and Collafirth. The drifters were requisitioned during the war, and at that point Robertson branched into marine repairs and the servicing of naval ships. After the war he bought extensive property at Garthspool, with a view to establishing a shipyard capable of accommodating trawlers. He also formed the Scapa Flow Salvage Company, Ltd, and successfully raised four of the German destroyers which had been scuttled there. By 1927, like many others, he was in financial difficulties. The Scapa company survived, however, and was eventually renamed Robertsons (Lerwick) Ltd, coal merchants, drifter owners and salvage contractors. Robertson became a member of the County Council in 1907, and he was convener from 1917-23. In later years he was member for North Unst, retiring in 1949. Before the second world war he was a town councillor. He was a staunch Conservative, unlike his equally brilliant brother James Robertson. He died in Lerwick on 16 July 1958. In 1906 he became the first leader of the Up Helly-Aa fire festival to use the title ''Guizer Jarl''. Previously, the title had been ''Chief Worthy Guizer''. His son, [person:lindsay-robertson:Lindsay], was also a councillor for Unst North from 1955 until 1958.','JW Robertson.png','JW Robertson headshot.png','I28793','John_Robertson_(iv)','["Lerwick Town Councillors", "Zetland County Councillors", "Conveners of the Zetland County Council", "1878 Births", "1958 Deaths", "Councillors pictured"]',1,1,175911768);
INSERT INTO "people" VALUES(318,'John Sandison','john-sandison','1858-12-12','1936-03-04','Cullivoe','Uyeasound, Unst','John Peter Sandison son of [person:alexander-sandison:Alexander Sandison] was a County Councillor first for Yell North between 1907 and 1910 then for Unst South between 1910 and 1929. His brother [person:thomas-sandison:Thomas J. Sandison] was also a councillor.','John had a lifelong connection to the agricultural sector in Shetland. He was a well known flockmaster throughout Shetland and in Scotland.','JohnSandison.png',NULL,'I16462','John_Sandison','["Zetland County Councillors", "Natives of Shetland", "1858 Births", "1936 Deaths", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(319,'John Scott','john-scott','1936',NULL,NULL,NULL,'Sir John Hamilton Scott is a former Lord Lieutenant for Shetland from 1994 up to his retirement on his 75th birthday, November 30th 2011.','He was made a Knight Commander of the Victorian Order (KCVO) in the Queen’s Birthday Honours List in June 2011. John is the father of [person:tavish-scott:Tavish Scott], who was elected as the Liberal Democrat Member of the Scottish Parliament for Shetland at the inception of the Parliament in 1999.','John Scott.jpg','John Scott Headshot.png',NULL,'John_Scott','["Zetland County Councillors", "1936 Births", "Councillors pictured"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(320,'John Sinclair','john-sinclair','1874-03-02','1935-12-07','Graven','Perth','John Thomas James Sinclair was a herring exporter, clerk, Lerwick Town Councillor first between 1904 to 1906 and later from 1915 to 1933 and a County Councillor between 1921 and 1928.','After leaving school, John served as an assistant in his father''s shop in Mossbank. He moved to Lerwick around 1890 where he was an assistant to the grocery business of [person:andrew-smith:Andrew Smith], and worked there for five years. In 1895, his father was lost at sea and John returned home to Graven. Later, Andrew Smith began business as a shipbroker in connection with the herring fisheries, and by 1900 John returned to Lerwick to take up the post of cashier in the business. After the business grew rapidly, Andrew formed a company with John and Max Schultze, trading under Messrs Andrew Smith & Schultze, which had three permanent offices; Lerwick, Peterhead and Yarmouth. He was made an Honorary Sheriff Substitute of the Sheriffdom of Caithness, Orkney and Shetland in 1932.','JTJ Sinclair Provost.png','John TJ Sinclair Headshot.png','I119064','John_Sinclair','["Lerwick Town Councillors", "Zetland County Councillors", "1874 Births", "1935 Deaths", "Councillors pictured"]',1,0,NULL);
INSERT INTO "people" VALUES(321,'John Small','john-small','1855-06-17','1942-07-09','Dunfermline','Lerwick','John Small was a solicitor and County Councillor initially for Yell South between 1892 and 1895 then Nesting between 1895 and 1910.','Small was a solicitor who practised in Lerwick between 1889 until his retirement in 1939. He had graduated the University of Edinburgh in 1880 as a Bachelor of Law. He had been a manager of St. Ringans Church and was a treasurer for over 30 years. He also had a long connection with the Shetland Literary and Scientific Society.',NULL,NULL,'I174443','John_Small','["Zetland County Councillors", "1855 Births", "1942 Deaths"]',0,1,NULL);
INSERT INTO "people" VALUES(322,'John Smith (i)','john-smith-i','1860-08-23','1932-03-25','Bressay','Lerwick','John Smith was an ironmonger and Lerwick Town Councillor between 1907 and 1921.',NULL,NULL,NULL,'I132010','John_Smith_(i)','["Lerwick Town Councillors", "1860 Births", "1932 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(323,'John Smith (ii)','john-smith-ii','1899-09-18','1978','Yell',NULL,'John Robertson ''J.R.'' Smith was a County Councillor for Bressay between 1960 and 1966 and a Lerwick Town Councillor between 1966 and 1970, first as an independent then later a Labour candidate.','John came to Lerwick as a boy and was educated there. He described his early years as a period of hardship: "Ours way a large family, nine to be precise, and there was poverty. All hands had to be earning to achieve any semblance of respectability in the community". He served in the army during the war. He wound up in Canada after the war, explaining "I was deported from Toronto in the terrible thirties when I was on the loose. I took a deputation to the Mayor of Toronto in an attempt to get young fellows from England and Scotland warmer clothing to face the Canadian winter. We were kindly received and the Mayor promised to issue warmer clothing to the young lads. Two later later, I had along train journey with two large detectives to St John''s, and was put on a liner for London". Before the outbreak of WWII, John lived in London and was a councillor in Hammersmith. During the war, he joined the Air Force, and one of his first postings coincidentally took him back home for the first time in 20 years, as he was stationed at Sullom Voe. He was subsequently posted East, at one point addressing a left wing conference in Ceylon. He returned to Shetland at the conclusion of the war, and was for some years the manager of the Shetland Hand Knitting Industry. He spent the last years of his retirement living in Aberdeen. John was a committed socialist all his life. His brother Willie also became a councillor.',NULL,NULL,'I24132','John_Smith_(ii)','["Lerwick Town Councillors", "Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Death Date", "1899 Births", "1978 Deaths"]',1,NULL,260954136);
INSERT INTO "people" VALUES(324,'John Stewart','john-stewart','1901-03-20','1956-12-12','Kirkabister','Yell','John Stewart was a County Councillor for Yell North from 1952 until 1955.','As a young man, John worked for the merchant navy and later returned to Shetland to run a ferry service in Yell. During WWI he was employed by the council doing construction work in Graven, and after the was focussed on crofting. He was known as an accomplished sailor in Shetland with his boat Miss Gadabout. John, and Yell man Campbell Nisbet were killed in a boating accident during a strong storm.','John Stewart.jpg','John Stewart Headshot.png','I23844','John_Stewart','["Zetland County Councillors", "Natives of Shetland", "Councillors pictured", "1901 Births", "1956 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(325,'John Sutherland','john-sutherland','1876-05-26','1959-03-18','Leons','Brevik Hospital, Lerwick','John Sutherland was was a County Councillor first for Nesting from 1935 until 1938, then Aithsting between 1945 and 1955 and finally Delting North between 1955 and 1958.','He was a Road Surveyor for the North Isles District when appointed interim Road Surveyor for the County and Mainland District in 1915. In 1919, he was appointed Assistant County Road Surveyor to R. S. W. Paterson and when the latter left Shetland in 1923, John was appointed as County Road Surveyor in November 1923 and kept that role until he retired in June 1935. He was a member of the Education Authority from 1919 until 1938, and again from 1945 until 1958. His obituary describes him as being "forthright in his criticisms at the Council and Committee tables, and any business which did not meet with his approval was "ruthlessly condemned". Despite this, he maintained a "strong strain of humour".','Drever-etal.jpg',NULL,'I57808','John_Sutherland','["Zetland County Councillors", "1876 Births", "1959 Deaths"]',1,1,178996135);
INSERT INTO "people" VALUES(326,'John Tait','john-tait','1833-06-01','1904-09-17','Lerwick','Lerwick','John Tait was a general merchant and Lerwick Town Councillor.','<strong>Work</strong>

John''s first job out of school was working with [person:william-merrylees:William Merrylees], before moving on to work with William Irvine, a merchant in Lerwick. Both he and William moved to Hay and Company until there was a vacant lot where Gifford and Thomson had been based in Lerwick, and John left Hay and Co to open up his own grocery store. He sold this business is 1873 and moved to Aberdeen, where he continued operating a grocers until 1878, when he returned to Shetland. Upon returning to Shetland he returned to Hay and Co as a manager, and eventually became a partner, wherein the business became John Tait and Co, with the second partner [person:alexander-hay:Alexander C. Hay]. Eventually, John''s son John took on the partnership too. His son, James was an anthropologist, photographer and guide famous for his work with First Nations communities in Canada.

<strong>Outside of work</strong>

<strong>Educator</strong>

John contributed a great deal to Shetland, as evidenced by his obituary taking up almost half a page in the Shetland Times. When he was a young man, there was a local proposal to institute a ''night school'' to help the children of poor families receive a better education. John became a teacher through this programme and was the secretary of the committee set up to lead the project. It was while he was involved in this scheme that he brought it to the attention of [person:arthur-anderson:Arthur Anderson], the first Member of Parliament for Orkney and Shetland to be born in Shetland. Arthur''s legacy in education - the construction of the Anderson Educational Institute, later the Anderson High School, is well known and Anderson is often credited as the father of modern education in Shetland - but John played a significant role in appealing to the isles MP and was a crucial part of igniting Anderson''s interest in helping the local children receive a better education.

<strong>Diarist</strong>

While under the employ of William Irvine, John was passed a diary/logbook that William had begun but lost interest in continuing writing further. From 1852 until his death, John wrote in the diary every day and the Shetland Times described the book as one of the best insights into the development of Lerwick in the latter half of the 19th century. Unfortunately, the fate of the book is unclear.

<strong>Prize shooter</strong>

John was a member of the Zetland Rifles'' Club, which was established in 1858. As a shooter, he won a number of medals at competitions.','John Tait.jpg',NULL,'I10049','John_Tait','["Lerwick Town Councillors", "1833 Births", "1904 Deaths", "Councillors pictured"]',1,1,207847981);
INSERT INTO "people" VALUES(327,'John Tulloch (i)','john-tulloch-i','1862-05-01','1921-09-08','Lerwick','Lerwick','John Samuel Tulloch was a solicitor and Lerwick Town Councillor.',NULL,NULL,NULL,'I29935','John_Tulloch_(i)','["Lerwick Town Councillors"]',1,1,163057241);
INSERT INTO "people" VALUES(328,'John Tulloch (ii)','john-tulloch-ii','1912-08-21','1999-09-26','Setter','Scalloway','John Robertson Tulloch was a County Councillor for Yell South initially between 1955 and 1958 then later from 1964 to 1966.','John worked as a joiner and along with his father, John, and uncle he built most of the coffins in the West Yell and Ulsta.','John R. Tulloch Wedding.jpg','John R Tulloch Headshot.png','I16385','John_Tulloch_(ii)','["Zetland County Councillors", "1912 Births", "1999 Deaths", "Natives of Shetland", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(329,'John Tulloch (iii)','john-tulloch-iii','1857-09-20','1912-04-09','Sandfield','Vancouver, Canada','John Malcolmson Tulloch was a merchant and a County Councillor for Cunningsburgh between 1896 and 1901.','John left Shetland as a young man and worked for some time with Messrs James J. Goudie & Co, Glasgow, operated by a cousin of his. He joined the army and rose to the rank of sergeant with the 78th Highlanders. He was discharged from the army in the 1880''s through injury. He joined the firm of Andrew Smith, before eventually starting his own company, then becoming a partner in a a firm of salesmen and becoming a fish salesman himself. Latterly, he became a flesher. He unknowingly was suffering from cancer of the stomach and travelled to Vancouver in 1911 to visit friends, hoping that his ailing health would improve with a change of climate, but succumbed to his condition in 1912. In politics, he was a believer in Liberalism and was a member of the Congressional Church.',NULL,NULL,'I78582','John_Tulloch_(iii)','["Zetland County Councillors", "1857 Births", "1912 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(330,'John Tulloch (iv)','john-tulloch-iv','1900-06-17','1993-11-11','Northmavine','Lerwick','John Tulloch was a merchant (John Tulloch Knitting and Weaving factory) and County Councillor for Northmavine North between 1925 and 1935. His son [person:andrew-tulloch:Andrew] was also a councillor.','John ran the successful knitwear firm John Tulloch Knitting And Weaving until 1947, when he sold the business. In 1948, then founded knitwear company John Tulloch (Shetland Products) Ltd based in Montfield. In 1976, John was the first recipient of an honorary life membership to the Shetland Chamber Of Commerce. He had at that time been a member for 40 years, 12 of those as vice-chair.',NULL,NULL,'I81835','John_Tulloch_(iv)','["Zetland County Councillors", "1900 Births", "1993 Deaths"]',1,1,295392733);
INSERT INTO "people" VALUES(331,'John Williamson (ii)','john-williamson-ii','1897-09-12','1950-10-23','Bixter','Aithsting','John Gilbert Williamson was a general merchant and County Councillor for Walls.',NULL,NULL,NULL,'I40909','John_Williamson_(ii)','["Zetland County Councillors", "1897 Births", "1950 Deaths", "Biography Missing"]',1,1,261022562);
INSERT INTO "people" VALUES(332,'John Williamson (iii)','john-williamson-iii','1879','1951-02-07','Lerwick','Lerwick','John Andrew Williamson was a compositor, printer, Lerwick Town Councillor between 1941 and 1945, and a County Councillor for Gulberwick from 1949 until his death in 1951.','John worked as a printer for 58 years. As a young man, he enjoyed cliff climbing and continued to participate in that hobby until just four months before his death. He was a member of the Life-Saving Association and held a long-service medal of that body. He represented Labour at the 1949 Zetland County Council election. Upon his death, the Town Hall and County Buildings (where the court is now) flew their flags at half mast.',NULL,NULL,'I18771','John_Williamson_(iii)','["Lerwick Town Councillors", "Zetland County Councillors", "1879 Births", "1951 Deaths"]',1,1,179138521);
INSERT INTO "people" VALUES(333,'John Williamson (iv)','john-williamson-iv','1895-06-23','1955-07-01','Mounthooly Street','Ulsta, Yell','John Keith Herculson ''Johnnie'' Williamson was a shop manager and a County Councillor for Yell South from 1940 until 1949, then again between 1950 and 1952.','John was educated at Burravoe School, and as a young lad moved to Lerwick, first taking up employment with D & G Kay''s and Hunter & Sinclair. He returned to Yell to work with Manson & Co in Burravoe, leaving to volunteer for service in the Royal Navy Reserve in WWI. He saw active service throughout the war and upon demobbing, joined the merchant navy. In 1923, when [person:andrew-clark:Andrew D. Clark] acquired George Laurence & Co in Ulsta, hired John as manager, with John later living above the shop. In 1953, after 30 years of service, he took over the business.',NULL,NULL,'I136577','John_Williamson_(iv)','["Zetland County Councillors", "1895 Births", "1955 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(334,'Jonathan Wills','jonathan-wills','1947-06-17',NULL,'Oxford',NULL,'Dr. Jonathan Witney Garriock Wills is a Shetland journalist, author, broadcaster, political activist, Shetland Islands Councillor, mariner and wildlife expert, whose colourful career over the past forty years saw him elected as the first student to be Rector of the University of Edinburgh, Muckle Flugga Lighthouse boatman, Scotland correspondent for The Times, Senior Producer at BBC Radio Shetland, and editor of the Shetland Times, before he pioneered the e-media Shetland News. He has also held a number of public posts and has written books for children.','Wills is now a writer and freelance environmental consultant who has specialised in the oil industry for over 25 years. He is the author of A place in the sun - a study of the development of the oil terminal at Sullom Voe in the Shetland Islands of Scotland - and Innocent Passage - a detailed account of the wrecking of the tanker Braer in 1993. A frequent speaker at conferences on oil and the environment, he has also written and broadcast extensively about oil in Alaska. In his 1990 British TV documentary, ''Slick Operators'', he revealed that the Exxon Valdez disaster could not have happened if the oil companies had implemented in Alaska the tanker surveillance scheme they had helped to set up in Shetland ten years earlier. Dr Wills operates a wildlife tourism business around some of Shetland''s finest seabird and seal colonies during the summer months, and is an honorary warden of the Noss Island National Nature Reserve. He holds MA and PhD degrees in Geography from the University of Edinburgh.',NULL,NULL,'I188284','Jonathan_Wills','["Shetland Islands Councillors", "Incomers to Shetland", "1947 Births", "Labour", "Writers"]',0,NULL,NULL);
INSERT INTO "people" VALUES(335,'Joseph Leask','joseph-leask','1797-09-13','1882-11-16','Symbister','Lerwick','Joseph Leask was a shipmaster, drapier, clothier and Lerwick Town Councillor.','Leask was the eldest son of Capt. Thomas Leask and Elizabeth Johnson. The family moved to Lerwick in 1806, and in 1814 Joseph began working [person:george-linklater:George Linklater], a merchant and magistrate in the town. Joseph began his own mercantile and shipping business in 1822. He became a town councillor in 1835 and served until 1850, then returned from 1862 until 1865. When it was decided that Shetland required municipal buildings in order to conduct official business, a Limited Liability Company was formed - Lerwick Town Hall Company Limited - and Leask became the chairman of the group. Leask was an extremely successful businessman, and assembled a large landed estate, with its centre at Sand in [Sandsting]. He was extremely interested in Shetland’s maritime affairs, and gave lively evidence about them to Frank Buckland’s Herring Fishery Commission in the 1860s. At the end of his life he played an important part in the great herring fishery that had just arrived in Shetland, by assisting fishermen to buy the new large boats, and by providing accommodation for them at his premises at Garthspool. He died in Lerwick on 16 November 1882. On 13 July, Leask fell from his horse and broke his leg. His estate owned the Caroline, a 33 tonne, oak-built 55ft sloop, Venus, a 53 tonne schooner and the hull of Milberg, another schooner, weighing 137 tonnes. These were auctioned off in 1883 at Garthspool after his death. Politically, he was a Liberal. His obituary in the Shetland Times notes that despite being a member of the Parish Church, he contributed to all religious denominations.',NULL,NULL,'I29517','Joseph_Leask','["Lerwick Town Councillors", "1797 Births", "1882 Deaths"]',1,1,269969226);
INSERT INTO "people" VALUES(336,'Joseph Linklater','joseph-linklater','1909-04-05','1993-04-08','Lerwick','Tauranga, New Zealand','Joseph Laurence Linklater was a Lerwick Town Councillor.','In WWII, Joseph served in the Royal Army Service Corps, enlisting 26 Jan 1939. His enlistment papers describe him as an Electrician. He was discharged from 5 Apr 1954. Joseph emigrated to New Zealand on s.s. Southern Cross which left Southampton on 6th March 1956, arriving in Wellington on 9th April 1956.',NULL,NULL,'I113517','Joseph_Linklater','["Lerwick Town Councillors", "1909 Births", "1993 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(337,'Joseph Peterson (i)','joseph-peterson-i','1861-08-22','1953-04-24','Turill','Weathersta','Joseph ''Josie'' Peterson was a County Councillor for Delting South between 1919 and 1922. His nephew, [person:joseph-peterson-ii:Joseph] was also a County Councillor.','Joseph only went to formal education for three-quarters of a year. Education at that time was paid, and in a family of six money was scarce. Joseph began working with the fish trade on the beach at Voe, before setting off to Faroe on the Voe smacks belonging to T. M. Adie & Sons. After a time away from Shetland with the deep sea fishing industry, he returned to Shetland and returned to fishing around Faroe with Messrs Nicolson & Co, Scalloway, as mate and later Skipper of the ship Violet. As the Faroese fishery trade dwindled, Joseph turned to the herring trade and was employed by [person:john-robertson-iv:John W. Robertson]. When WWI broke out, he joined the Shetland Royal Navy Reserves and served throughout. In politics, he was a Liberal. Skipper Joseph Peterson proved the most outstanding success among later day Faroe skippers and a capable navigator.
* Captain Adam Halcrow, The Sail Fishermen Of Shetland (1950)',NULL,NULL,'I109414','Joseph_Peterson_(i)','["Zetland County Councillors", "1861 Births", "1953 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(338,'Joseph Peterson (ii)','joseph-peterson-ii','1906-07-01','1986-02-28','Sullom','Lerwick','Joseph Peterson was a County Councillor for Northmavine North between 1951 and 1955. His uncle, [person:joseph-peterson-i:Joseph] was also a County Councillor.',NULL,NULL,NULL,'I88579','Joseph_Peterson_(ii)','["Zetland County Councillors", "1906 Births", "1986 Deaths", "Biography Missing"]',1,1,287152773);
INSERT INTO "people" VALUES(339,'Joseph Pole','joseph-pole','1885-09-09','1965-11-16','Mossbank','Lockerbie','Joseph Garfield Gordon Pole was a business partner in Pole, Hoseason and Co. and County Councillor for Delting North between 1922 and 1945. His father, [person:william-pole:William] was also a county councillor for the same area between 1904 and 1907.','Through Pole, Hoseason & Co, Joseph was one of the pioneering wool exporters in Shetland. The firm had a knitwear factory in Mossbank for nearly half a century from which he retired in 1947. He then moved to Lockerbie where he opened a shop to retail Shetland woolen products, running the shop until 1964.',NULL,NULL,'I8188','Joseph_Pole','["Zetland County Councillors", "1885 Births", "1965 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(340,'Joseph Simpson','joseph-simpson','1937',NULL,NULL,NULL,'Joseph Gilbert ''Josie'' Simpson is a former Shetland Islands Counciller for the North Isles ward. His wife, [person:hazel-simpson:Hazel], was also a councillor, representing Whalsay And Skerries between 1993 and 1994, following the death of [person:henry-stewart:Henry Stewart].',NULL,NULL,NULL,NULL,'Joseph_Simpson','["Shetland Islands Councillors", "Natives of Shetland", "1937 Births"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(341,'Kenneth Thomson','kenneth-thomson','1932','1991-05-05','Edinburgh','Sanquhar, Dunfries and Galloway','Reverend Kenneth Thomas Thomson was a Minister for the United Free Church and a Lerwick Town Councillor in 1961.','He was ordained in Shetland in 1957 and demitted on 24 February 1977. The Shetland Library, following their move to the St. Ringan''s Church premises published a history of ministers there, and say of Rev Thomson: "In 1958 during the ministry of the Rev K T, Thomson and through an agreement with the Parish Church St Ringan''s once again became United Free. The Rev K T Thomson was witness to the move from St Olaf''s United Free Church to St Ringan''s. His ministry lasted from 1958 until 1961." He holds the perhaps unfortunate record of the shortest council tenure in the history of any modern political institution in Shetland, at 4 days. He was elected on 1 May, and when the council met on 5 May, it was established that as Thomson had failed to declare that he had received pay through dealings with the Anderson Educational Institute as a relief teacher. The Shetland Times article on the issue was headlined: "Councillor for five minutes". His earnings did not prohibit him sitting on the Town Council, but as all Lerwick Town Councillors gained a seat within the County Council, it was that body that had the conflict.',NULL,NULL,NULL,'Kenneth_Thomson','["Lerwick Town Councillors", "Councillors - Clergymen", "Councillors - Missing B/D", "Councillors - Missing Birth Date"]',0,0,NULL);
INSERT INTO "people" VALUES(342,'Lachlan MacFadyen','lachlan-macfadyen','1860-04-15','1939-10-29','Shandon','Tillicoulty, Clackmannanshire','Reverend Lachlan MacFadyen was a minister, justice of the peace and a County Councillor for Yell North from 1922 until 1925.','The son of Alexander M and Elizabeth Mitchell, Lachlan was educated at Garelochhead Primary School, University of Glasgow, University of Edinburgh, New College Edinburgh and Glasgow F C College. He was ordained by the Congregational Union at Tillicoultry Congregational Church 27 Nov 1894 but resigned 1910. He was then later admitted to the United Free Church in 1910, and was inducted in to North Yell on 9 Sept 1910. During the first World War, he did service with Scottish Churches Huts in France 1918. On 24 July 1925 he was transferred and inducted to Coalsnaughton. Married 22 Dec 1889 Jeanie Rae Faichney. Justice of the Peace for Orkney and Shetland 1919.','Lmacfadyen.jpg',NULL,NULL,'Lachlan_MacFadyen','["Zetland County Councillors", "Councillors - Clergymen", "Incomers to Shetland", "1860 Births", "1939 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(343,'Laura Baisley','laura-baisley',NULL,NULL,NULL,NULL,'Laura Baisley is a former Shetland Islands Councillor for the North Isles ward from 2007 to 2012.',NULL,NULL,NULL,NULL,'Laura_Baisley','["Shetland Islands Councillors", "Councillors - Missing All", "Female"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(344,'Laurence Anderson','laurence-anderson','1870-03-11','1929-02-27','Out Skerries','Lerwick','Laurence Anderson was a wine and spirit merchant and a County Councillor for Cunningsburgh between 1919 and 1922.','Laurence came to Lerwick at a young age and worked under [person:gilbert-harrison:Gilbert Harrison]. He was quickly promoted to manager of Harrison''s Clickimin Bar, and continued in the role as Gilbert''s son William took over following his father''s death. Eventually Laurence took over the Commercial Bar on Commercial Road. He held this as a licenced bar until 1921 when the licence lapsed as a result of the first No Licence poll, but he carried it on as a restaurant and billiards room. In 1923, he added a grocery business at Grantfield, and became a wholesale licensed dealer. He also erected a car garage at Brucefield and rented it out to car owners.',NULL,NULL,'I13557','Laurence_Anderson','["Zetland County Councillors", "1870 Births", "1929 Deaths"]',1,1,179137751);
INSERT INTO "people" VALUES(345,'Laurence Bruce (ii)','laurence-bruce-ii','1896-11-15','1981-03-14','Haroldswick','Unst','Laurence Bruce was a County Councillor for Unst North between 1949 and 1952.',NULL,NULL,NULL,'I63376','Laurence_Bruce_(ii)','["Zetland County Councillors", "1896 Births", "1981 Deaths", "Natives of Shetland"]',1,1,179953901);
INSERT INTO "people" VALUES(346,'Laurence Andrew Cogle','laurence-cogle','1884-12-09','1960-04-24','Houlland','Lerwick','Laurence Andrew Cogle was a shipping clerk and Lerwick Town Councillor between 1925 and 1936.','For most of his life, he worked for the North of Scotland Shipping Company, having served the business for 51 years when he retired in 1953. He was actively involved with the church and taught Sunday School in St Columba''s Church for more than 50 years. He was also the Honorary Treasurer of the Sunday School for 44 years, and a church elder for 37. For a number of years, his tall, outstanding figure had been part and parcel of the business life of Lerwick, centered around Victoria Pier.','Bowlers.jpg',NULL,'I56786','Laurence_Cogle','["Lerwick Town Councillors", "1884 Births", "1960 Deaths"]',1,1,215970614);
INSERT INTO "people" VALUES(347,'Laurence Edmondston','laurence-edmondston','1900-03-23','1987-09-13','Edinburgh','Unst','Lt.-Col. Laurence David Edmondston was a County Councillor for Unst North between 1958 and 1961.','Laurence graduated from Sandhurst just WWI, and subsequently joined the Royal Scots through which he served in Yemen, India and Burma (Myanmar). While serving in Burma, he developed an interest in big game hunting and collected several record trophies, but shortly thereafter became more a conservationist. His new focus helped create the Hermaness Nature Reserve on his native isle. When he left the army, he joined the Bombay and Burma Teak Company, foresting teak wood in Burma. The outbreak of WWII saw him immediately rejoin the army, serving in the Middle East and beyond. He was posted back to India in 1944 and was put in charge of Military Police, returning to his Burmese job when the war ended. When he returned to Shetland, he came with enough teak to build a boat, which he christened Vega. He later also had the Stormalong built. Laurence believe that the Vega had been destroyed in a hurricane after he parted with it, but learned a few weeks before his death that it was still in use in Florida. Laurence''s great-grandfather, Doctor Laurence Edmondston, was a brother to [person:arthur-edmondston:Arthur], the who was elected to lead the first ever inception of the Lerwick Town Council.','Ledmondston.jpg',NULL,'I10729','Laurence_Edmondston','["Zetland County Councillors", "1900 Births", "1987 Deaths"]',0,1,175852586);
INSERT INTO "people" VALUES(348,'Laurence Johnson','laurence-johnson','1890-05-13','1982-02-13','Collafirth','Lerwick','Laurence Gilbert Johnson was a farmer, County Councillor and author. He was the first son of William Johnson and Margaret Copland.','Johnson saw, and in later years reminisced about the last days of the haaf fishing based at Ronas Voe where his father was a skipper; on three occasions he and his brothers attended the fishing foy there. When the fishery ended, Johnson''s father took tenancy of the sheep farm at Setter in Mid Yell, and Laurence and his brothers continued to work the farm after the old man died. Johnson played an active part in Yell affairs: he was a County Councillor and a founder member of the debating society. He became a firm friend of the Yell scholar Laurence Williamson. When Williamson died, Johnson salvaged his papers, and in due course wrote a biography of him: &quot;Laurence Williamson of Mid Yell&quot;, published in a limited edition in 1971.',NULL,NULL,'I115447','Laurence_Johnson','["Zetland County Councillors", "1890 Births", "1982 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(349,'Laurence Laurenson (i)','laurence-laurenson-i','1799-09-29','1867-11-11','Quoys','Lerwick','Laurence Laurenson was a draper, hosier, founder of Laurenson &amp; Company, and a Lerwick Town Councillor. His first child, [person:arthur-laurenson:Arthur Laurenson] was also a town councillor.',NULL,NULL,NULL,'I13127','Laurence_Laurenson_(i)','["Lerwick Town Councillors", "1799 Births", "1867 Deaths"]',1,1,163057235);
INSERT INTO "people" VALUES(350,'Laurence Laurenson (ii)','laurence-laurenson-ii','1856-07-20','1916-07-14','Lerwick','Lerwick','Captain Laurence Laurenson was a captain in the Gordon Highlanders, a woollen draper, hosier and Lerwick Town Councillor, first from February until November in 1905, then again from 1913 until his death in July 1916.','In 1864-5, when Laurence was still a boy, the his family moved to America. Unfortunately, his father Peter and brother Scott both died within the first two years, so his mother Bruce returned to Lerwick. After completing his education in Lerwick, Laurence joined Laurenson & Co, at the time the oldest hosiery merchants in Shetland. An able worker, Laurence became a partner in the business relatively early and helped grow the business. In the early 1870s, he joined the 1st Zetland Rifles, and was a member of that Corps until it disbanded in 1883. On the formation of the 7th Volunteer Battalion Gordon Highlanders in 1900, he joined and was appointed first a provisional sergeant, before coming a qualified sergeart and later a colour-sergeant of his company. He was called up to fight in WWI, but stayed in Shetland, where he became a Recruiting Officer for the isles.','CaptainLaurenson.png',NULL,'I18169','Laurence_Laurenson_(ii)','["Lerwick Town Councillors", "1856 Births", "1916 Deaths"]',1,1,107102150);
INSERT INTO "people" VALUES(351,'Laurence Laurenson (iii)','laurence-laurenson-iii','1880-12-15','1960-01-07','Kirkabister','Lerwick','Laurence Laurenson was a fish salesman, a Lerwick Town Councillor between 1934 and 1937, and also a County Councillor for Cunningsburgh between April 1940 and May 1945.','Laurence began work in the grocery trade, but after a period in Ayr he returned to Shetland and was employed by Captain Johnson, [person:john-robertson-iv:John W. Robertson] and the Moray Firth Fish Selling Company. He sold at Sandwick, Lerwick and other ports, before later going into business on his own.',NULL,NULL,'I62538','Laurence_Laurenson_(iii)','["Lerwick Town Councillors", "Zetland County Councillors", "1880 Births", "1960 Deaths"]',1,1,179137842);
INSERT INTO "people" VALUES(352,'Laurence Robertson (i)','laurence-robertson-i','1863-08-30','1933-01-07','Lunnasting','Aberdeen','Laurence Robertson was a County Councillor for Delting South between 1907 and 1913.','In his early days, Laurence went to sea but met his future wife on a visit home and decided to leave the sea and focus on farming in Setter. His agricultural work was extensive, including the rearing and dealing of sheep, cattle and ponies. He took over the farm in Kergord and later in Berry, Scalloway. His wife, Margaret, mainly ran the Berry operation while Laurence focussed on Setter. Later, the couple reduced their holdings to just the Setter estate. His work with animals gave him a degree of veterinary knowledge, and he was called upon often for animal health questions by his neighbours.',NULL,NULL,'I32809','Laurence_Robertson_(i)','["Zetland County Councillors", "1863 Births", "1933 Deaths"]',1,0,179138187);
INSERT INTO "people" VALUES(353,'Laurence Sandison','laurence-sandison','1884-03-22','1934-09-30','Upper Sound','Lerwick','Laurence Sandison was a butcher assistant and a Lerwick Town Councillor. He was also the Lerwick Up Helly Aa Guizer Jarl in 1914 a member of the Social Democratic Federation, like several pre-war jarls. He died in a motor accident.','After leaving school, Laurence worked with [person:john-irvine-iii:John G. Irvine] in his flesher business, and continued working there until John and his family moved to New Zealand. Until the breakout of WWI, Laurence had a fleshing business. During the war, he server in the anti-aircraft section of the Royal Garrison Artillery. After serving in WWI, Laurence worked with James Smith up until the time of his death. At his time of death, Laurence lived with [person:robert-blance:Robert Blance], who was married to his sister, Jean.',NULL,NULL,'I93633','Laurence_Sandison','["Lerwick Town Councillors", "1884 Births", "1934 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(354,'Laurence Smith','laurence-smith','1891-02-01','1964-05-27','Whiteness',NULL,'Laurence William Smith was a confectioner, tobacconist, County Councillor for Whiteness And Weisdale between 1928 and 1945, and a Lerwick Town Councillor.','After leaving school in Whiteness, he worked in Lerwick as a message boy with [person:john-irvine-iii:John G. Irvine], and later started up the business of Ridland & Smith with Henry Ridland. He served in WWI with the Gordon Highlanders and was wounded at Bentecourt and had to have his left leg amputated at the knee, and was the recipient of an artificial leg. When he came out of the Army, he worked for a short time in Edinburgh working for Tods, but soon returned to Ridland & Smith''s. Then he bought a small shop in Commercial Street before moving into the premises that became Universal Stores. He retired in 1958. He was a keen sailor and was commodore of the Lerwick Boating Club from 1949 to 1952. Although unable to play football through his war injury, he was a keen supporter of local football, serving a term as the president of the Shetland Football Association.',NULL,NULL,'I225276','Laurence_Smith','["Zetland County Councillors", "Lerwick Town Councillors", "1891 Births", "1964 Deaths"]',1,NULL,285904351);
INSERT INTO "people" VALUES(355,'Laurence Stove','laurence-stove','1833-10-08','1889-04-12','Lerwick','Macgregor''s Rutland Hotel, Edinburgh','Laurence Greig Stove was an ironmonger, merchant and Lerwick Town Councillor between the years of 1871 and 1889.','Laurence Stove served as a carpenter''s apprentice in Lerwick until 1851. He then moved to Glasgow and remained there until the outbreak of the Crimean War (1852), where he went out in a Turkish transport and remained in the Turkish service until the war was over, whereupon he returned back to Shetland. He constructed a saw mill with his brother in Lerwick which contained the first steam machinery imported into the isles and he went into business as a wood merchant. He subsequently worked as an ironmonger and ship chandler in commercial Street, continuing to work until his death. His brother [person:alfred-stove:Alfred] was also a Lerwick Town Councillor.',NULL,NULL,'I123843','Laurence_Stove','["Lerwick Town Councillors", "1833 Births", "1889 Deaths"]',1,0,214369359);
INSERT INTO "people" VALUES(356,'Leonard Groat','leonard-groat',NULL,NULL,NULL,NULL,'Leonard George Groat is a former Shetland Islands Councillor who represented the Lerwick North constituency, initially from 1982 to 1999, then again from 2003 to 2007.',NULL,NULL,NULL,'I37782','Leonard_Groat','["Shetland Islands Councillors", "1937 Births"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(357,'Leonard Lyell','leonard-lyell','1850-10-21','1926-09-18',NULL,NULL,'Leonard Lyell, 1st Baron Lyell was a Liberal Member of Parliament for Orkney and Shetland.','The eldest son of Colonel Henry Lyell and Katharine Murray Lyell, he was a nephew of Sir Charles Lyell, 1st Baronet, the geologist. He served as Liberal Member of Parliament for Orkney and Shetland from 1885 to 1900, and was commissioned a Deputy Lieutenant for Forfarshire in December 1901. He was created a baronet in 1894 and raised to the peerage as Baron Lyell of Kinnordy in the County of Forfar, on 4 July 1914. His only son Charles Henry Lyell was also a Liberal MP but as he died in 1918 his son Charles Anthony Lyell succeeded to both the baronetcy and barony. }} Category: Members of the Parliament of the United Kingdom Category: Liberals','Leonard Lyell.jpg',NULL,NULL,'Leonard_Lyell','["Members of the Parliament of the United Kingdom", "Liberals"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(358,'Leslie Angus','leslie-angus','1940-11-30','2019-10-01','Lerwick',NULL,'Leslie ''Gussie'' Angus is a former Shetland Islands Councillor.',NULL,NULL,NULL,'I70125','Leslie_Angus','["Shetland Islands Councillors", "Natives of Shetland", "1940 Births", "Liberal Democrats"]',1,NULL,NULL);
INSERT INTO "people" VALUES(359,'Leslie Eunson','leslie-eunson','1922-04-15','2000-03-19','Houl',NULL,'Leslie John William Eunson was an insurance agent and a Shetland Islands Councillor, representing Lerwick Braewick from 1982 until 1986. His late brother Cecil was also a councillor for a lengthy period. Although an insurance agent for most of his life, Leslie had served in the RAF in India in the latter parts of the second World War. He was also a keen footballer, playing as a defender for Bigton alongside fellow councillor Willie Tait. between 1964 and 1972 he was the President of the Shetland Football Association. He also held interests in darts and fishing.',NULL,'Leunson.JPG',NULL,'I97835','Leslie_Eunson','["Shetland Islands Councillors", "1922 Births", "2000 Deaths"]',1,NULL,NULL);
INSERT INTO "people" VALUES(360,'Lewis Garriock','lewis-garriock','1877-06-02','1938-04-06','Dundee','Scalloway','Lewis James Garriock was a County Councillor for Tingwall between 1909 and 1913. In 1935, his wife, [person:selina-garriock:Selina], became the first ever female County Councillor elected in Shetland. He was a distance relative of Sandsting County Councillor [person:simon-garriock:Simon Garriock] (4th cousin twice removed) and his great uncle, [person:james-greig:James Greig], was a Lerwick Town Councillor.','He studied at the University of St. Andrews, where he was an accomplished all-round athlete. After serving the County Council, he was an active participant in a large number of committees and a member of various bodies, as well as a very active participant of the church in Scalloway.',NULL,NULL,'I68323','Lewis_Garriock','["Zetland County Councillors", "1877 Births", "1938 Deaths"]',0,1,175652867);
INSERT INTO "people" VALUES(361,'Lewis Smith','lewis-smith','1952-03-16',NULL,'Lerwick',NULL,'Lewis Shand Smith is the Chief Executive of the Ombudsman Service, a private-sector complaints resolution organisation, a former Rector of St. Magnus Church, former Shetland Islands Councillor convener and councillor from 1990 until 1999',NULL,NULL,NULL,'I29473','Lewis_Smith','["Shetland Islands Councillors", "Conveners of the Shetland Islands Council", "Council Leaders", "1952 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(362,'Lindsay Robertson','lindsay-robertson','1905-02-15','1994-09-08','Lerwick','Lerwick','Lindsay Robertson was a County Councillor for Unst North from 1955 to 1958. His father was [person:john-robertson-iv:John W. Robertson].','Lindsay was educated at the small school in Hayfield Cottage under teacher Miss Donaldson, before joining the Anderson Educational Institute in 1910. After a short spell at Glasgow High School, he joined his father, [person:john-robertson-iv:John]''s firm, North Ness Engineering, aged 16. A decline in the industry saw Lindsay become a taxi driver in 1927, before securing work in commercial transport with his uncle, James Jamieson. In 1937, he became joint managing director in the family firm. During WWII, the company had government salvage contracts, and Lindsay learned to dive. After the war, Lindsay delivered mail to Fair Isle via the Lord Curzon and ran the family business when his father retired, until Hay & Co took it over. He was appointed the Danish Vice-Consul in September 1959, was decorated with the Royal Order of Knight of the Dannebrog in 1969 and retired from that post in 1970. He was also made vice-consul of Iceland in 1962, and full consul 1974. In that role, he received the Icelandic Order of the Falcon, retiring in 1985.',NULL,NULL,'I26158','Lindsay_Robertson','["Zetland County Councillors", "1905 Births", "1994 Deaths"]',1,1,175911786);
INSERT INTO "people" VALUES(363,'Lindsay Smith','lindsay-smith',NULL,NULL,NULL,NULL,'Lindsay S. Smith is a former Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'Lindsay_Smith','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(364,'Loretta Hutchison','loretta-hutchison','1947-08-18','2024-02-17','Whalsay',NULL,'Loretta Hutchison (Neé Stewart) is a former Shetland Islands Councillor for Whalsay and Skerries. Her father, [person:henry-stewart:Henry], also represented the constituency.',NULL,NULL,NULL,'I230008','Loretta_Hutchison','["Shetland Islands Councillors", "Natives of Shetland", "Female", "1947 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(365,'Magnus Flaws (i)','magnus-flaws-i','1893-06-14','1959-06-14','Dunrossness','Dunrossness','Magnus Robert Flaws was a fisherman, later a farm manager, then farmer, and County Councillor for Dunrossness South between 1952 and 1955. He is a distant relation to Shetland Islands Councillor [person:magnus-flaws-ii:Magnus Laurence Flaws] (3rd cousin two times removed).','Magnus farmed at Quendale.',NULL,NULL,'I184477','Magnus_Flaws_(i)','["Zetland County Councillors", "1893 Births", "1959 Deaths", "Biography Missing"]',1,1,179138367);
INSERT INTO "people" VALUES(366,'Magnus Flaws (ii)','magnus-flaws-ii','1947-06-28',NULL,'Wick',NULL,'Magnus Laurence ''Sonny'' Flaws is a manager and former Shetland Islands Councillor for Dunrossness South and later Dunrossness between 1986 and 1999. He is a distance relation to Zetland County Councillor [person:magnus-flaws-i:Magnus Robert Flaws] (3rd cousin two times removed).',NULL,NULL,NULL,'I184477','Magnus_Flaws_(ii)','["Shetland Islands Councillors", "1947 Births"]',0,NULL,NULL);
INSERT INTO "people" VALUES(367,'Magnus Gray','magnus-gray','1882-03-19','1966-04-16','Skellister','Lerwick','Magnus Gray was a sub-postmaster and a County Councillor.',NULL,NULL,NULL,'I37608','Magnus_Gray','["Lerwick Town Councillors", "1882 Births", "1966 Deaths", "Biography Missing"]',1,1,NULL);
INSERT INTO "people" VALUES(368,'Magnus Manson','magnus-manson','1879-06-26','1943-10-23','Fladdabister','Schoolhouse, Fetlar','Magnus Laurence Manson, son of Capt. James Manson and Jean Halcrow. He became a law apprentice with J.B. Anderson, solicitor, and remained with him for many years. He was much more interested in politics than the law, however, and spent much of his spare time reading socialist literature. In 1905 he and his friend Frank Pottinger formed a branch of the Social Democratic Federation in Lerwick.','Manson was a fine public speaker, and played an active part in the Lerwick Literary and Debating Society. ‘His discerning criticism and weighty arguments often completely disarmed his opponents’, said The Shetland News in an obituary, ‘and his broadsides were periodically interlarded with shafts of irony or sarcasm’. At election meetings he was noted for his trenchant heckling. He became a member of Lerwick School Board in 1906, and was eventually chairman of it. He was a member of Lerwick Town Council from 1916-1934. Manson married Harriet Helen Wallace, a teacher, in 1918, and moved to Fetlar when she became headmistress there in 1929. He died on 23 October 1943.',NULL,NULL,'I174532','Magnus_Manson','["Lerwick Town Councillors", "1879 Births", "1943 Deaths"]',1,1,284529812);
INSERT INTO "people" VALUES(369,'Magnus Sandison','magnus-sandison','1900-12-24','1989-03-05','Benston','Montrose','Magnus John Sandison was an employee of the Mission to Seafarers (the ''Flying Angel'') when it was located in Charlotte Street and was also a Lerwick Town Councillor between 1958 and 1959.','Magnus left Shetland as a young man and joined the Merchant Navy for eight years, before becoming a member of the Salvation Army. He returned to Shetland in 1934 and worked as a missionary for the Church of Scotland in Burravoe, Yell for a number of years. He left Shetland during WWII to work for the British Sailor''s Society, and eventually returned back to work in that organisation''s Lerwick mission. He again left Shetland in 1960 to Montrose intending to retire, but the Church of Scotland called on his services and he served for 10 more years in the Parish Church at Gourdon.','MagnusSandison.png',NULL,'I159831','Magnus_Sandison','["Lerwick Town Councillors", "1900 Births", "1989 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(370,'Magnus Shearer (i)','magnus-shearer-i','1890-07-12','1961-03-08','Clate','Lerwick','Magnus ''Magnie'' Shearer was the managing director of J &amp; M Shearer Ltd, Lerwick Town Councillor and County Councillor for Whalsay And Skerries between 1924 until his election onto the Town Council in 1936. He represented Whalsay and Skerries again between 1947 and 1958 He was the father of [person:magnus-shearer-ii:Magnus].','After leaving school, he served as a cook on board the Whalsay herring boat ''Reindeer'', but thereafter began a cooper''s apprenticeship under his father, making barrels in Lerwick for A. Wood &amp; Sons, who later employed him on a station in Shields. He joined the Gordon Highlanders in 1912, and in 1914 when war broke out he was called back to Lerwick. He left Shetland with other GHs in 1915 and was picked for officer training and commissioned in 1916 before crossing to France where he served on the Western Front as a Lieutenant in the 9th Gordon Highlanders. He volunteered for overseas active service and held the Volunteer Medal. He declined a post in Nova Scotia as a fishery officer to return to Shetland, and set up a Herring curing business in Lerwick, J &amp; M Shearer. When the Second World War broke out he was against called for duty, being asked to take command with the rank of Major. He was initially posted away from Shetland but returned in 1941, remaining in the Military Control until the end of the war in 1945. He then received a Territorial Decoration and was accorded the rank Lt-Col. In public life, he was a councillor, a Justice of the Peace in 1949, a vice-consul for Sweden, an honorary Sheriff-Substitute. Politically, he was a Conservative, and was adopted early in the 1950''s as a prospective parliamentary candidate but he resigned in 1953 owing to illness.','Magnus Shearer Provost.png','Magnus Shearer Headshot.png','I51559','Magnus_Shearer_(i)','["Lerwick Town Councillors", "Zetland County Councillors", "1890 Births", "1961 Deaths", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(371,'Magnus Shearer (ii)','magnus-shearer-ii','1924-02-27','2007-07-22','2 South Albany Street','Lerwick','Magnus MacDonald Shearer was the Managing Director of J. & M. Shearer Ltd, a Justice of the Peace, a member of the Lerwick Harbour Trust, honorary consul for Sweden and Germany, and a Lerwick Town Councillor.','He was educated at Lerwick Central Public School,and the Anderson Educational Institute. In 1942 he was called up to the Royal Navy, serving in the North Atlantic, at the D-Day landings, in the Mediterranean and in the Far East. After the war Mr Shearer joined the family fish-curing business J &amp; M Shearer Ltd in 1946 and continued there until his retirement in 1984. Magnus M. Shearer had many civic duties:
*He was appointed a Justice of the Peace in 1969 and remained one for the rest of his life. *He was a member of Lerwick Town Council from 1962 - 1969 *and of Lerwick Harbour Trust from 1960 - 1975, being in the chair from 1967 - 1972.
*He became honorary secretary of the Lerwick Lifeboat Station in 1968 until 1992. *From 1958 - 1994 he was honorary consul for Sweden, and *served as honorary consul for the Federal Republic of Germany from 1972 - 1987.
*He was also an elder of St Columba''s Church for 54 years. From 1982 until his 70th birthday in 1994 Magnus M. Shearer served as Lord Lieutenant of Shetland, being replaced by [person:john-scott:John Scott]. Magnus married Maisie Henderson in 1949 fathering one son also called Magnus.','Magnus M Shearer.jpg',NULL,'I72008','Magnus_Shearer_(ii)','["Lerwick Town Councillors", "1924 Births", "2007 Deaths", "Councillors pictured"]',NULL,1,NULL);
INSERT INTO "people" VALUES(372,'Malcolm Bell','malcolm-bell','1964-01-10',NULL,'Lerwick',NULL,'Malcolm John Bell is a former Police Inspector and the current Convener of the Shetland Islands Council. Malcolm was first elected to Lerwick North in 2012.',NULL,NULL,NULL,'I200819','Malcolm_Bell','["Shetland Islands Councillors", "Natives of Shetland", "1964 Births", "Conveners of the Shetland Islands Council"]',1,NULL,NULL);
INSERT INTO "people" VALUES(373,'Malcolm Bray','malcolm-bray','1947-04-02','2006-02-20','Lerwick','Edinburgh','Captain Malcolm Smith Bray was a pilot for Logan Air and a Shetland Islands Councillor for Sandwick from 1982 until his resignation in 1987.',NULL,NULL,NULL,'I77011','Malcolm_Bray','["Shetland Islands Councillors", "1947 Births", "2006 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(374,'Malcolm Laing','malcolm-laing','1762','1818-11-06',NULL,NULL,'Malcolm Laing was a historian, advocate and Member of Parliament for Orkney and Shetland from 1807 to 1812.','He was born to Robert Laing and Barbara Blaw at the paternal estate of Strynzia or Strenzie, on Stronsay, Orkney; Samuel Laing and Gilbert Laing Meason were his brothers. He attended the grammar school in Kirkwall, and was a student at Edinburgh University. He joined the Speculative Society in 1782. In 1785 Laing was admitted advocate, and from 1789 for five years was advocate for poor litigants.[4] During 1790 he was working on the electoral roll in Orkney, in the Whig interest. In 1794, with Adam Gillies, he defended Joseph Gerrald in his sedition case. Sir James Mackintosh, a friend, regarded Laing''s delivery as far too fast, and an impediment to his legal career; Henry Cockburn, Lord Cockburn commented quite positively on his "hard, peremptory, Celtic manner and accent". Laing signed the declaration of the Society of Friends of the People in 1794, and joined the Whig Club. A personal friend of Charles James Fox, he was one of a group of advisers of Fox during the first years of the 19th century on his work of British history, with William Belsham, Samuel Heywood and James Maitland, 8th Earl of Lauderdale. He was Member of Parliament for Orkney and Shetland from 1807 to 1812, brought in by the Ministry of All the Talents. In 1808 Laing suffered a breakdown, and withdrew from public life. He introduced merino sheep on the islands of Eday and Sanday, purchasing a flock from Tweeddale that had belonged to Sir James Montgomery, 1st Baronet. At the end of his life he tried to introduce the brown hare.','Malcolm Laing.jpg',NULL,NULL,'Malcolm_Laing','["Members of the Parliament of the United Kingdom"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(375,'Malcolm Smith','malcolm-smith','1856-12-01','1935-03-12','Hoswick',NULL,'Sir Malcolm Smith was a Liberal Member of Parliament for Orkney and Shetland. Smith was born and brought up in a crofting family in Hoswick Shetland but moved to the port of Leith as a young man. There he prospered as a businessman and became the Provost of Leith from 1908 to 1917, shortly before the town was incorporated into the city of Edinburgh. He was elected unopposed as the Member of Parliament for Orkney and Shetland in a by-election in May 1921, following the death of the sitting MP, [person:cathcart-wason:Cathcart Wason]. Having stood in the by-election as a Coalition Liberal, supporting the coalition government led by David Lloyd George, he stood at the 1922 general election as a National Liberal, but was defeated by the Liberal party candidate [person:robert-hamilton:Robert Hamilton]. He is buried in Warriston Cemetery to the south-east of the vaults.',NULL,NULL,NULL,'I77030','Malcolm_Smith','["Members of the Parliament of the United Kingdom", "Liberals"]',1,NULL,NULL);
INSERT INTO "people" VALUES(376,'Mark Burgess','mark-burgess','1970-03-16',NULL,'Edinburgh',NULL,'Mark Burgess is a Shetland Islands Councillor, representing Shetland Central since 2012.','Mark is a columnist and photographer for the Shetland Times newspaper, as well as a teacher at the Shetland College and a self-employed web designer. Prior to being a councillor, he had held posts on the Scalloway Community Council, Scalloway Public Hall Committee, Scalloway Museum Committee, Scalloway School Parent Council and the Shetland Arts Board,',NULL,NULL,'I225338','Mark_Burgess','["Shetland Islands Councillors", "Natives of Shetland", "1970 Births"]',0,NULL,NULL);
INSERT INTO "people" VALUES(377,'Mary Colligan','mary-colligan','1935-02-09','2025-07-13','Bigton',NULL,'Mary Ursula ''Masie'' Colligan (neé Goudie) is a former teacher and Shetland Islands Councillor for the Delting area from 1990 until 2003.',NULL,NULL,NULL,'I132068','Mary_Colligan','["Shetland Islands Councillors", "Natives of Shetland", "Female", "1935 Births", "Teachers"]',1,NULL,NULL);
INSERT INTO "people" VALUES(378,'Michael Johnston','michael-johnston','1962-08-06','2016-07-14',NULL,NULL,'Michael Frederick Balfour Johnston was the proprietor of Lochside Stores and a Shetland Islands Councillor for Lerwick Twageos.',NULL,NULL,NULL,'I172526','Michael_Johnston','["Shetland Islands Councillors", "1962 Births", "2016 Deaths"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(379,'Michael Stout','michael-stout','1960-10-31',NULL,'Lerwick',NULL,'Michael William Stout is a Shetland Islands Councillor, representing the Lerwick North ward since 2012.','Michael descended from Fair Isle, but moved with his family to Bressay in 2000. He worked for COPE Ltd and was the manager of Shetland Alcohol Trust, as well as being a self-employed sound engineer and technician for the Shetland Arts. He worked in Devon for a short period. He was a strong opponent of the Viking Energy windfarm He was a member of the band Hom Bru.',NULL,NULL,'I98442','Michael_Stout','["Shetland Islands Councillors", "Natives of Shetland", "1960 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(380,'Mitchell Williamson','mitchell-williamson','1884','1959-02-01','Out Skerries','Aberdeen','Mitchell Humphray ''Greasy Mike'' Williamson was a County Councillor for Whalsay And Skerries between 1922 and 1924.','This profile comes from the Shetland Times
Shetland Times, 7 February 1959 Many tributes will be paid to the memory of Mr Mitchell U. Williamson, who died at his home in Aberdeen on Sunday, but the tribute most deserved and the one he himself would have appreciated most is that at the end of a long and successful business career, mainly in Aberdeen, he was as much a &quot;Skerries boy&quot; and a true Shetlander as on the day when he first left home. Aged 74, Mr Williamson was afflicted by serious illness in recent years, but seemed to be in better health a few months ago when he made what was to be his last visit to Shetland. In recent weeks however his condition deteriorated and his death was not unexpected at the last. Mitchell Williamson''s early life followed the pattern of so many of his contemporaries - he worked as a beach boy in Skerries, he went to the haaf in the last of the sixareens and one day in his early teens literally ran away to sea. This first venture beyond the isles he was wont to recall - a sailing drifter called at the isle to see if they could pick up a cook. Mitchell, first to greet the arrivals, offered himself for the job, rushed home to pack a few belongings and to bid farewell to his mother, and thus set out to find success in a busy world. From the haaf and the herring fishing, the young seafarer turned to the merchant navy and joined the R.N.R. In the last years of his life, when he went cruising in search of health and sunshine, he liked to recall that his first cruises were as a deckhand in the old St Sunniva with which the North of Scotland Company pioneered cruises to the Norwegian fjords. While in the North ships, Mr Williamson saw the opportunities for commercial enterprise in Shetland and his first (and not very successful) essay at business life was as a commission agent for margarine. From this beginning, Mr Williamson got a real opportunity as agent for the wholesale firm of Aitken &amp; Wright, travelling the length and breadth of the isles on their behalf and managing their warehouse. In 1923 he went to Aberdeen where he opened the firm''s branch there and became their representative in Orkney. Mr G.H. Burgess succeeded him at Lerwick. In 1932, Mr Williamson became a partner in the firm of A. &amp; R. Gray in Aberdeen, becoming managing director on the death a few years later of the senior partner. under his direction the business expanded rapidly, developing a strong connection in the North. Mr Williamson also became chairman of the board of A.B. Chalmers (Inverness) Ltd., thus bringing the whole North of Scotland into his purview. Beyond the business world, Mr Williamson had many interests. His public career started just after the first war, when he became a member of Lerwick Harbour Trust and of the Education Authority. When he went to Aberdeen he took great interest in the Harbour Board there and was convener of its finance committee for many years. During the second war he was area chairman of the Ministry of Information and greatly enjoyed the contacts he made in that capacity with visiting speakers and VIPs of many kinds. Probably the most absorbing work from Mr Williamson''s point of view was as a member of the Scottish Tourist Board from its inception. He threw himself wholeheartedly into the work of selling Scotland as a tourist centre and toured America and south Africa in that cause. Last year Mr Williamson endowed a fund to provide an annual prize for the child at Skerries school who was considered to have the most initiative and leadership. It was his hope to present this prize personally in 1959.','Mitchell Williamson.png','Mitchell Williamson Headshot.png','I12768','Mitchell_Williamson','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1882 Births", "1959 Deaths", "Councillors pictured"]',1,0,NULL);
INSERT INTO "people" VALUES(381,'Norman Cameron','norman-cameron','1896-02-15','1967-04-09','Ryde',NULL,'Norman Ogilvy Mouat Cameron was a County Councillor for Bressay between 1934 and 1945. His grandfather, [person:thomas-cameron:Thomas] was a Lerwick Town Councillor from 1876 until 1883.','Norman was born on the Isle of Wight, where his father William was the vicar of the Holy Trinity Church. After William was sent to South Africa to be the Bishop of Cape Town, Norman was sent to Winchester Boarding School. He attempted to join the army in 1914 but was refused on medical grounds. He was successful in 1915 and he left New College, Oxford for Sandhurst. After Sandhurst, he was commissioned in the Cameron Highlanders and went to France where he joined the 1st Battalion at the end of 1915. A foot injury he sustained at the Battle of the Somme all but ended his active military career. He did rejoin his Batallion in 1919 on the Rhine, but was sent home for medical reasons. After the military, he rejoined Oxford and studied in history, and after completing his studied worked for the Department of Printed Books at the British Museum. Health issues, and the inheritance of land in Shetland, meant that he left that job and moved to Shetland in 1929. As a reservist, he rejoined his regiment in WWII and served in home stations and as as adjutant of the Shetland Home Guard.',NULL,NULL,'I39751','Norman_Cameron','["Zetland County Councillors", "1896 Births", "1967 Deaths"]',0,NULL,NULL);
INSERT INTO "people" VALUES(382,'Patrick Blair','patrick-blair',NULL,NULL,NULL,NULL,'Patrick Blair of Littleblair was a member of the Parliament of Scotland for Orkney and Shetland in 1663 and 1669-2. He was a Sheriff deputy and held courts in Kirkwall in 1664.',NULL,NULL,NULL,NULL,'Patrick_Blair','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(383,'Peter Anderson','peter-anderson','1861-03-17','1914-05-08','Haggersta','Edinburgh','Peter Anderson was a butcher at Globe Butchers and a County Councillor for Whiteness And Weisdale from 1904 until his death in 1914.','He began work as a house builder before becoming a butcher. He was one of the most prominent local cattle and pony deals in Shetland and was largely instrumental in forming the Pony Stud Book Society. He exported ponies as far as America. Upon his death, [person:robert-ganson-i:Convener Ganson] said that almost every crofter in Shetland would miss his presence.',NULL,NULL,'I108529','Peter_Anderson','["Zetland County Councillors", "1861 Births", "1914 Deaths"]',1,0,285738865);
INSERT INTO "people" VALUES(384,'Peter Campbell','peter-campbell',NULL,NULL,NULL,NULL,'Peter Campbell is a current Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'Peter_Campbell','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(385,'Peter Dalziel','peter-dalziel','1901-10-25','1977-03-30','Lerwick','Lerwick','Peter Dalziel was a Lerwick Town Councillor between 1934 and 1937, then 1938 to 1946.','He served for some years as the chairman of the Electricity Committee on the Town Council at the time in which the council provided electricity to the town. He was credited with working hard to improve the conditions of housing in Lerwick. He advocated for local men to be prioritised to work on Council developments.',NULL,NULL,'I160467','Peter_Dalziel','["Lerwick Town Councillors", "1901 Births", "1977 Deaths"]',1,1,292294896);
INSERT INTO "people" VALUES(386,'Peter Garriock (i)','peter-garriock-i','1826-10-07','1885-07-08','Lerwick','Lerwick','Peter Garriock was a ship owner and Lerwick Town Councillor between 1859 and 1871. His son, [person:andrew-garriock:Andrew] was a Zetland County Councillor in Northmavine.','He opened business with James Mouat, as a commission agent. He was an agent for the New Zealand New Shipping Company, one of the principal promoters of the North Sea Fisheries Company, Lerwick Gas Light Company & Distributor of Stamps. He was also an inspector of the poor, and Clerk to the School Board for 9 years.',NULL,NULL,'I18331','Peter_Garriock_(i)','["Lerwick Town Councillors", "1826 Births", "1885 Deaths"]',1,1,290620551);
INSERT INTO "people" VALUES(387,'Peter Garriock (ii)','peter-garriock-ii',NULL,NULL,NULL,NULL,'Peter John Garriock is a former Zetland County Councillor for Sandness, having been the final representative for the area in 1973 until it merged with the Shetland Islands Council in 1975.',NULL,NULL,NULL,NULL,'Peter_Garriock_(ii)','["Zetland County Councillors", "Councillors Missing B/D - All", "Biography Missing"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(388,'Peter Georgeson','peter-georgeson','1863-09-17','1949-03-23','Walls','Lerwick','Peter Georgeson was a merchant and a County Councillor for Walls initially between 1890 and 1892 then again from 1893 until 1904.','Peter''s father George had a shop in Walls, and Peter joined the firm at a young age. He retired in 1929, with the family moving to America. They were only there for four years before they returned to Lerwick.',NULL,NULL,'I40011','Peter_Georgeson','["Zetland County Councillors", "1863 Births", "1949 Deaths"]',1,1,179954246);
INSERT INTO "people" VALUES(389,'Peter Goodlad','peter-goodlad','1857-12-02','1936-11-13',NULL,NULL,'Peter Scott Goodlad was a Lerwick Town Councillor between 1893 and 1920, becoming the Provost from 1915 until he retired.','Peter was a native of Tingwall and served as a shoemakers apprentice under David Affleck. He established Goodlad and Coutts with his cousin J. J Coutts in 1891 and his brother [person:james-goodlad:James] became a partner. Principally, the business made footwear, sea-boots and high lass boots. They exported across the United Kingdom, colonies and even as far as India. The firm opened up branches in Sandwick, Fraserburgh, Peterhead and Kirkwall. Peter travelled to England, Holland and Germany on business with the firm. The Shetland News describe him as ''staunchly Liberal'' as well as being abstinent from alcohol and a strong temperance advocate.','PS Goodlad Provost.png','PS Goodlad Headshot.png','I45508','Peter_Goodlad','["Lerwick Town Council Provosts", "Lerwick Town Councillors", "1857 Births", "1936 Deaths", "Councillors pictured"]',NULL,NULL,290900907);
INSERT INTO "people" VALUES(390,'Peter Guy','peter-guy',NULL,NULL,NULL,'Darlington','Peter Newlyn Guy is an author and former Shetland Islands Councillor for Yell South from 1993 to 1996.','Peter first came to Shetland in 1975 when he was posted to Saxa Vord while serving with the R.A.F. He left in 1976 but returned in 1979 when he became Sullom Voe''s external affairs superintendent. After leaving that job, he was elected to the Shetland Islands Council. In 1996, he left Shetland having bought a farm in Yorkshire.',NULL,NULL,NULL,'Peter_Guy','["Shetland Islands Councillors", "Writers"]',NULL,0,NULL);
INSERT INTO "people" VALUES(391,'Peter Henry','peter-henry','1900-02-13','1979-02-05','Walls','Lerwick','Peter John Henry was a seaman and County Councillor from 1955 until his resignation in 1960',NULL,NULL,NULL,'I57597','Peter_Henry','["Zetland County Councillors", "1900 Births", "1979 Deaths", "Biography Missing"]',1,1,NULL);
INSERT INTO "people" VALUES(392,'Peter Hunter','peter-hunter','1913-12-07','2002-03-11','Lerwick','Lerwick','Peter Benjamin Andrew ''Benji'' Hunter was a company director and a County Councillor for Unst South between 1961 and 1970, then later Nesting for the Shetland Islands Council between 1978 and 1990.','Peter was the Managing Director of Shetland Lime Ltd from 1953 to 1973.','Retirement.jpg',NULL,'I29464','Peter_Hunter','["Shetland Islands Councillors", "Zetland County Councillors", "1913 Births", "2002 Deaths"]',1,1,290865596);
INSERT INTO "people" VALUES(393,'Peter Laurenson','peter-laurenson','1914-01-01','2007-08-30','4 Chromate Lane','Lerwick','Peter Tait Laurenson was a Lerwick Town Councillor between 1972 and 1975. He was elected under the Labour banner.','Peter was the manager of the local branch of the Scottish Gas Board in the 1960''s and 70''s.',NULL,NULL,'I164571','Peter_Laurenson','["Lerwick Town Councillors", "1914 Births", "2007 Deaths"]',NULL,1,216686113);
INSERT INTO "people" VALUES(394,'Peter Malcolmson','peter-malcolmson','1939-07-27',NULL,'Lerwick',NULL,'Peter Malcolmson is a former welfare officer and Shetland Islands Councillor first for Lerwick Lower Sound then for Lerwick Upper Sound, Gulberwick and Quarff between 1994 and 2003.',NULL,NULL,NULL,'I171061','Peter_Malcolmson','["Shetland Islands Councillors", "Liberal Democrats", "Natives of Shetland", "1939 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(395,'Peter Robertson','peter-robertson','1915-03-03','1997-01-03','4 Magnus Street','16 Harbour Street, Lerwick','Peter Robertson was an ironmonger, manager of Stove and Smith''s and Lerwick Town Councillor between 1961 and 1970.','He spent all his working life in Lerwick, getting his first job in 1929 after leaving school aged 14 was as a temporary clerk in a fish curers office in the Lerwick Fish Market. In November of that year, he joined Stove & Smith and stayed working with the firm for 54 years. In later life, he became a Deacon at his church. He was married twice and had 2 children by his first marriage. His first wife was Ann Brown, a teacher by occupation, and they were married in 1942 by the Rev, George Smith, UF Church Lerwick. Ann died in 1967. Peter remarried in 1970 to Christina Keith, a nurse from Yell, this was in the Congregational Church by Rev, H Woodhouse. Christina died 2 months after Peter.',NULL,NULL,'I108531','Peter_Robertson','["Lerwick Town Councillors", "1915 Births", "1997 Deaths"]',1,1,290831306);
INSERT INTO "people" VALUES(396,'Peter Watts','peter-watts',NULL,NULL,NULL,NULL,'Peter Watts is a former architect and Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'Peter_Watts','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(397,'Peter Williamson','peter-williamson','1814-11-07','1858-03-25','Burradale','Lerwick','Peter Williamson was a shop owner in Lerwick who murdered his wife and three of his six children and killed himself in their house at the foot of Fox Lane in 1858. Another of his children was injured but survived, whilst another child was not home at the time of the attack. Prior to the tragedy, he was a Lerwick Town Councillor between 1850 until his death in 1858.','Peter Williamson was born in Northmavine in 1814, and at some point moved to Lerwick. He worked as a general merchant, draper and a grocer throughout his career. I haven''t been able to pin down exactly where his shop was based, but we know that the crime took place in a house above a shop at the foot of Fox Lane. Peter was a well-liked and well-respected man in Lerwick. He wasn''t the richest man in town, but his business was showing no signs of financial problems. Everything was going good. In his home normally lived 9 people: Peter, his wife Agnes, his six children William (16 in 1858), John (14), Agnes (12), Gilbert, (10), Peter (4) and Barbara (0) and a maid-servant whose identity is unknown. In March, Gilbert was up in Northmavine at his grandparents house for a visit. Peter managed a farm remotely, presumably in his native Northmavine, and he also acted as an agent for the Peterhead whaling boats that visited Shetland annually to collect crew members. It was pretty common for men in this period of Shetland''s history to have more than one job, Peter was no exception. Politically, he was first elected to the Lerwick Town Council in 1850, and was again elected in 1853 and 1856. Only 11 men were elected every 3 years in Lerwick (until 1876), and these positions were not usually open to the common man. That tells you a lot about his standing in the community. I presume he may have stood again in 1859. But on 25 March 1858, it all came to an end.

<strong>The Night Before</strong>

On Wednesday 24th, Peter went about his business as usual, according to those who came into contact with him. The last time Peter was seen alive by a member of the public was between 10 and 11 of that day. After completing his business for the day, he returned home about 11 and instructed the maid-servant to close up the house and head to bed, which she did. It is thought that it was some time later before he went to bed. Peter was known to lie late in the morning and work late. It is thought that he either went to bed or prepared to go for bed, because he was partly wearing his "night attire" - let''s just call them pyjamas. In his bedroom slept his wife Agnes and his daughter, who had been allowed to sleep in the parents'' bed because she had been sick. The three boys - though it was not their usual arrangement - slept 3-to-a-bed in the attic.
At some point after midnight, Peter got out of bed and decided to slaughter his entire family.

<strong>The Morning After</strong>

In the morning, the eldest boy of the family, William, was found still alive. He was wounded and bleeding from a gash in his throat, and his head and face had been fearfully disfigured. In another room, Peter''s wife was discovered breathing her last breath with injuries similar to William, but of a more serious nature. Little Agnes was found dead in a pool of blood on the bed. Another room contained a dead boy, and Peter, the infant, was found close to his father, with his head nearly severed from his neck. The father, our Peter, had also The report of the event concluded that Peter had murdered his entire family before turning to himself.

<strong>The Crime</strong>

Upon deciding to commit the heinous crime, Peter headed downstairs and check if the servant girl was sleeping. We know this because when she woke up her door was open where she had closed it. With everyone asleep, Peter armed himself with a heavy iron hammer or cleaver used for kitchen purposes, and also with a knife and razor. His first victim was his wife. Her skull was battered in on both sides and she had a gash on her throat. Agnes had gone through the same process. Awakened by the noise, the boys quickly learned what was happening and attempted to escape their father. William was lacerated about the head and throat like his mother and sister, but succeeded in escaping with his life. The head of Peter, the infant, was smashed and almost severed from his body. John (14) had made an attempt as escaping but was caught by Peter and shared the same fate as the other murdered Williamsons. For anyone keeping count, there are four victims: wife Agnes, John, Agnes, Peter. William, Gilbert, Barbara and the maid for various reasons had evaded murder from what I understand. Peter''s own suicide raised considerable questions to me in terms of method, because the way it was described in the reports of the event don''t clear it up. I''ll write it out here as they did and if anyone can help me understand what it means I''d be interested to hear it. "Throwing himself upon his back on the middle of the floor of the same room in which he stood, Peter placed his neck against the leg of the table, thus preventing any chance of the wound being partial and, drawing towards him a chair which stood in the apartment, he passed his arm round one of its lower supporters thereby ensuring equal steadiness of the hand as of the neck." "By this finesse of arrangement he was enabled to carry out his horrible design with fatal precision. With such strength did he, thus assisted, inflect a wound upon his throat that the neck was laid open ear to ear, and the blade of the razor penetrated the very bone." The maid had only been made aware of the state of matters when William, who had escaped Peter, had run into find his mother, only to find her murdered, ran into the maid''s bed and sprung into the bed next to her, screaming, wounded and bloody. Some up-late nearby builders heard the screams, and the timeline isn''t clear at this point but I can only assume that the maid upon learning the fate that had befallen the Williamsons ran out into the street.

<strong>Motive</strong>

The Inverness Courier disappointingly concluded "no motive can be assigned". The Nairnshire Telegraph and General Advertiser for the Northern Counties speculated that "it would appear Peter latterly took to the drink".
Peter had, according to friends and acquaintances, shown nothing but love to his family. His business was doing well and to the public he appeared of sound mind. However, in the wake of the event, those who had dealt with him closely had come to recognise that he had had an increasingly troubled mind and thought that the murderous rampage may have been due to insanity. There is one thing we do know that can give us a clue to the mental state of Peter. On the evening before the murders took place, Peter was engaged in conversation with two representatives of Glasgow and Aberdeen businesses. In that conversation, Peter turned the discussion towards famous hangman William Calcraft, murder, Burke and Hare, the most effective method of taking life away, and Peter suggested that death could most easily be accomplished by a sound stroke from a hammer on the skull of the victim. The two south men didn''t think any of this discussion, although they sought to change it. Peter declined an invitation to join them after closing the shop, but was apparently in good spirits when he left them.',NULL,NULL,'I34841','Peter_Williamson','["Lerwick Town Councillors", "1814 Births", "1858 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(398,'Prophet Smith','prophet-smith','1909-10-23','1979-04-12','Ulsta','Lerwick','Prophet James Laurence Smith, was a seaman and a journeyman politician, standing for election in all four possible elected bodies: the UK Parliament, the Zetland County Council, the Lerwick Town Council and lastly the Shetland Islands Council. He held elected positions in the latter three bodies at various points between 1944 and 1978.','Prophet became a seaman at an early age. There is a vivid anonymous account by him of his seagoing career in Peter Jamieson''s Letters from Shetland (1949). He subsequently became an organiser for the National Union of Seamen in Lerwick, and later in Greenock. He returned to Shetland again as area organiser for the Scottish Agricultural Organisation Society. He eventually became a full-time member of the Highlands and Islands Development Board, on its formation in 1965, responsible for its fisheries expansion programme. He served there for 11 years until his retrial. Prophet Smith was the first Labour candidate in the Orkney and Shetland constituency, in 1945. Despite finishing in third (last), he achieved a respectable 29% of the vote, falling just under 1,100 votes short of the winner, [person:basil-neven-spence:Basil Neven-Spence]. That election also saw the first attempt by [person:jo-grimond:Jo Grimond] at the Orkney and Shetland seat. He was a County Councillor for Nesting between 1952 and 1955 and Bressay from 1955 to 1960. He was County convener for four years. He was also an unsuccessful candidate for Nesting in 1949, and had a short spell as a Shetland Islands Council councillor after his retirement, representing Dunrossness, failing to be re-elected to the same seat in 1978. He also briefly represented the Lerwick Town Council between November 1944 and February 1945. His brother, [person:james-smith-ii:James], was a Zetland County Councillor for Bressay from 1949 to 1955.','Psmith.jpg',NULL,'I139644','Prophet_Smith','["Lerwick Town Councillors", "Shetland Islands Councillors", "Zetland County Councillors", "1909 Births", "1979 Deaths"]',1,1,288403730);
INSERT INTO "people" VALUES(399,'Raymond Bentley','raymond-bentley','1923-11-19','1992-08-07','Bourne','Lerwick','Raymond Ronald William ''Ray'' Bentley was a civil aviation fireman and County Councillor for Dunrossness South between 1967 and 1975, then again from 1978 to 1986.','Raymond first came to Shetland with the Royal Air Force during WWII, where he met and married a local woman, and remained for the rest of his life. He worked at Sumburgh Airport for 36 years and was the final Vice Convener of the Zetland County Council, from 1973.','RaymondBentley.png',NULL,'I200300','Raymond_Bentley','["Zetland County Councillors", "Shetland Islands Councillors", "1923 Births", "1992 Deaths"]',0,1,179138380);
INSERT INTO "people" VALUES(400,'Richard Honyman','richard-honyman','1787-05-04','1842-02-23','Orkney','Edinburgh','Sir Richard Bempdé Johnstone Honyman, 2nd Baronet was a Scottish official of the British East India Company who served for six years in the House of Commons as the Member of Parliament (MP) for Orkney and Shetland.','Honyman was the second son of Sir William Honyman, 1st Baronet, SCJ (Lord Armadale), of Armadale in Sutherland and Graemsay in Orkney. His mother Mary was a daughter of the notorious judge Lord Braxfield. The family claimed maternal descent from Sir Robert Stewart, an illegitimate son of King James V of Scotland. He was educated in England at Eton, and in 1806 he joined the British East India Company as a writer (junior clerk). After several promotions he became deputy commercial resident in Ramnad in 1809, and returned to Britain in 1811. He finally left the East India Company in 1816.',NULL,NULL,NULL,'Richard_Honyman','["Members of the Parliament of the United Kingdom"]',0,0,NULL);
INSERT INTO "people" VALUES(401,'Rick Nickerson','rick-nickerson','1949-06-29',NULL,'Halifax',NULL,'Richard Chadsey ''Rick'' Nickerson is a musician and former Shetland Islands Councillor for the Shetland South ward from 2007 to 2012.',NULL,NULL,NULL,NULL,'Rick_Nickerson','["Shetland Islands Councillors", "Incomers to Shetland", "1949 Births"]',0,NULL,NULL);
INSERT INTO "people" VALUES(402,'Robert Adair','robert-adair',NULL,'2002-03-22',NULL,'Lerwick','Robert ''Bob'' Adair was a Senior Lecturer and Lerwick Town Councillor.','Bob was a member of the National Health Executive Council, serving until 1974, with the last six years as chairman. He was on the Shetland Health Board from 1974 until 1985. Bob resigned from the council in 1963 to complete his studies in engineering, and in the 1969 was a teacher.','Radair.png',NULL,'I258210','Robert_Adair','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1922 Births", "2002 Deaths"]',NULL,1,NULL);
INSERT INTO "people" VALUES(403,'Robert Anderson (i)','robert-anderson-i','1903-04-11','1967-06-26','Burravoe','Lerwick','Robert Andrew ''Oily Bob'' Anderson was an oil depot surveyor and a Lerwick Town Councillor, having been Provost between 1950 and 1953.','He was first elected as a Labour Candidate in 1943, and became provost between 1950-3. In 1960, he was appointed honorary treasurer of the Council. It is noted that he &quot;seldom arrived at a meeting without his homework done. It was seldom one could challenge his authority: he always pulled facts from somewhere to prove his point. In 1965 he was awarded Freeman of the Burgh (and remains the only individual to have had held this title).','Robert Anderson Provost.png',NULL,'I34316','Robert_Anderson_(i)','["Lerwick Town Councillors", "Lerwick Town Council Provosts", "1903 Births", "1967 Deaths", "Councillors pictured"]',1,1,214625417);
INSERT INTO "people" VALUES(404,'Robert Anderson (ii)','robert-anderson-ii','1839','1921-02-15','Lerwick','Lerwick','Robert Charles Jack ''Bob'' Anderson was a draper, hosier, co-founder of Anderson &amp; Company and Lerwick Town Councillor between 1871 and 1874. His brother, [person:john-anderson:John], was a Lerwick Town Councillor, Zetland County Councillor and Convenor of the latter body.','Upon leaving school, Robert joined the business of his uncle, [person:robert-linklater:Robert Linklater], who was one of the leading hosiery dealers in Shetland. When Robert''s business expanded into Edinburgh, Robert temporarily relocated there to help establish the new premises which continued until the death of Robert in 1872. Robert continued to run the firm for 12 years after his uncle''s passing, before eventually joining his younger brother Thomas in forming the Messrs Anderson & Co. As of 2024, a business in Lerwick still trades under the Anderson & Co name.',NULL,NULL,'I10469','Robert_Anderson_(ii)','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1839 Births", "1921 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(405,'Robert Anderson (iii)','robert-anderson-iii','1936-09-27','2007-11-20','114 Commercial Street','Lerwick','Robert James Anderson was a civil engineer and a Shetland Islands Councillor for Lerwick North between 1999 and 2003. He was elected as a Scottish Liberal Democrat councillor.',NULL,NULL,NULL,'I14157','Robert_Anderson_(iii)','["Shetland Islands Councillors", "1936 Births", "2007 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(406,'Robert Baikie','robert-baikie',NULL,'1817-04-04',NULL,NULL,'Robert Baikie was a Member of Parliament for Orkney and Shetland from 1781 was elected as MP to represent the constituency of Orkney &amp; Shetland, on 10th October 1780, replacing [person:thomas-dundas-ii:Thomas Dundas], he serving until 1781 when the seat was taken by [person:charles-dundas:Charles Dundas]','Baikie was oldest the son of James Baikie of Tankerness and his wife Janet, a daughter of William Douglas, and heiress of the Monteiths of Egilshay. His father was provost of Kirkwall during the Jacobite rising of 1745, and was paid a pension by the Earls of Morton for his support of their electoral interests. However, in 1766 James Douglas, 14th Earl of Morton sold all his interests in Orkney to Sir Lawrence Dundas. At the 1768 general election Sir Lawrence installed as the Member of Parliament (MP) for Orkney and Shetland his older brother Thomas Dundas, who was returned unopposed. Thomas stood down in 1770, and the following year Thomas''s son Captain Thomas Dundas was elected unopposed. He was returned unopposed at the 1774 general election. However, Sir Lawrence had alienated both the lairds and merchants of Orkney. When he opposed Lord North''s government, the Orkney opposition received £300 from secret service funds to support a government candidate. Baikie was chosen to stand, and at the 1780 general election, Baikie was elected as the Member of Parliament (MP) for Orkney and Shetland by 11 votes to the 5 won Sir Lawrence''s nephew Charles Dundas.[4] However, Baikie''s election had been achieved only by excluding seven supporters of Dundas, and after an election petition the seat was awarded to Dundas on 28 February 1781. Baikie stood again at the 1784, but was defeated by 12 votes to 7 by the returned Colonel Thomas Dundas. }} Category: Members of the Parliament of Great Britain',NULL,NULL,NULL,'Robert_Baikie','["Members of the Parliament of Great Britain"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(407,'Robert Balfour','robert-balfour','1901-01-28','1975-02-17','Lunnister','Lerwick','Robert Balfour was a merchant seaman County Councillor first for Northmavine South between 1955 and 1967, then Northmavine North between 1973 and 1975.',NULL,NULL,NULL,'I91291','Robert_Balfour','["Zetland County Councillors", "1901 Births", "1975 Deaths", "Biography Missing"]',1,1,289012768);
INSERT INTO "people" VALUES(408,'Robert Bell','robert-bell','1856-08-10','1907-03-01','at Middlebie House near Lerwick','Symbister, Whalsay','Robert Hunter Bell of Lunna was a County Councillor, representing Nesting between 1890 and 1892. His father was Robert Bell, Advocate, Sheriff Substitute of Shetland.','In some early photographs, one of which dates from 1863, he looks far from robust, and indeed there is evidence to suppose that he suffered from ill health for the whole of his life. Doubtless he would have been taught how to fish for trout in Spiggie, Brow and other lochs, and would have ridden &quot;Jack&quot;, the Shetland pony provided by Clickim''In Robie, and taken walks with his father''s dog, &quot;Brush&quot;. He would have seen, during these few early years in Shetland, the phenomenon of the skies described by his father some twelve years before his birth, the &quot;Aurora Borealis&quot;, called in Shetland, &quot;The Mirrie Dancers&quot; [in the Diary, Robert Bell writes, &quot;In the evening there was the most extraordinary display of the Aurora Borealis that I have ever seen, ''The Merry Dancers'', as the country people call them...&quot; 29th September, 1844 - ''Mirrie'' is old Scots for ''Merry'', generally in use between the 15th and 17th centuries, and lingering on in Shetland to this day.]. But his mother died when he was seven years old, leaving a family of very young children. Agnes McCrae Bruce of Symbister came to the rescue, and married Sheriff Bell a few years later. The family then removed to Falkirk, Robert Bell having been appointed one of the Sheriff Substitutes for the Counties of Stirling, Clackmanan, and Dumbarton. At this time, Robert was sent to the Academy in Edinburgh, and thereafter he began a career in banking, beginning as a clerk. This occupation appears to have given him very little pleasure, and there is no evidence to show that he pursued it after his marriage. On the 29th of July, 1885, he married Kate Jane Morton, the daughter of Thomas Morton, a Marine Engineer (then retired), the ceremony taking place at the West Coates Established Church in Edinburgh (now demolished). The Service was conducted by the Reverend R.G.Forrest, D.D., the Minister of the West Coates Church. On the death of his father on the 9th September, 1887, Robert entered as heir to the estate of Lunna, and found that it was weighed down by legal or real burdens, extending to several thousands of pounds. He is listed in a contemporary publication as a Magistrate for Orkney and Shetland, and it is known that he did Committee work in local government. Nevertheless, he was forced to face the reduced circumstances of his estate. Down in Edinburgh, his father''s sister, Grace Hamilton Bell, a spinster, (died 13th July, 1889), had taken a dislike to Robert and to his wife, Kate Jane Morton, and while leaving all her money to Robert''s younger full and half brothers and sisters, she placed them under an obligation to have nothing to do with their eldest brother and his wife, nor with any of their descendants. This was imposed on them on pain of disinheritance, and if they refused to obey her terms, the money was to go to the Barclay Free Church in Edinburgh. In this way, Robert was unable to turn to his siblings to help him out of his predicament. Quite properly, the Crofters Commission was to reduce the rents of tenants by perhaps some 25%, and there was a slump in the fishing industry. Robert drew up a Trust Deed, designed to honour the debts owed by the estate, and was almost immediately evicted from the house of Lunna by the Trustee. At exactly this time, his wife left him, and divorce proceedings were completed in January, 1896. In her evidence to the Court, Kate Jane Morton stated that it was she who had been deserted by Robert, and that the desertion was wilful and malicious. Some details in the evidence submitted to the Court by Kate Jane Morton do not appear to be supported by facts, and are in conflict with each other. Robert did not compear before Lord Stormonth Darling, nor his deputy, Lord Low, to defend the case. Kate Jane Morton claimed that she was ready to return to her husband, and wanted to do so, but that he was opposed to any reunion. His voice was never heard. In 1907, broken in health, Robert died at Symbister House, on the island of Whalsay.',NULL,NULL,'I37399','Robert_Bell','["Natives of Shetland", "Zetland County Councillors", "1856 Births", "1907 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(409,'Robert Black','robert-black','1932-12-10','2022-07-26','Quendale','Bressay','Robert Irvine ''Bertie'' Black is a former Shetland Islands Councillor initially for Gulberwick, Quarff and Cunningsburgh then for Lerwick Harbour and Bressay.',NULL,NULL,NULL,'I84276','Robert_Black','["Shetland Islands Councillors", "Natives of Shetland", "1932 Births"]',1,1,288364877);
INSERT INTO "people" VALUES(410,'Robert Blance','robert-blance','1889-08-26','1963-10-02','Lerwick','Lerwick','Robert Bruce Blance was a Post Office clerk, telegraphist and a Lerwick Town Councillor between 1950 and 1962.','Robert worked his entire career for the Post Office, rising to the level of assistant postmaster by the time he retired around the late 1940''s. He was a staunch Labour Party supporter, serving as Secretary and Treasurer of the local branch.','Robert Blance Provost.png','Robert Blance Headshot.png','I123985','Robert_Blance','["Lerwick Town Councillors", "1889 Births", "1963 Deaths", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(411,'Robert Bruce','robert-bruce','1907-10-11','1983-08-17','Burma','Sandwick, Shetland','Robert Hunter Wingate Bruce was Lord Lieutenant of Shetland and County Councillor. He resided at Sandlodge, Sandwick.','He was born Robert Bruce Wingate, son of John Bruce Wingate, and grandson of Elizabeth Helen Bruce of Sumburgh, who married the Rev. T.D. Wingate. John Bruce Wingate inherited the Sumburgh and Lunna estates in 1939 on the death of his uncle, Robert Hunter Bruce, and changed his name to John Bruce: at the same time Robert Bruce Wingate changed his name to Robert Hunter Wingate Bruce. He married in 1935 Valmai Muriel Chamberlain, (b. Abt 1906, d. 14 May 1998), of Hailsworth, Gloucestershire. Educated at Rugby and Oxford, he joined the L.M.S. Railway in 1930. He held various positions with the railway until 1941, when he was loaned to the Ministry of Economic Warfare, on whose behalf he spent a month in Washington in 1942. In 1943 he was recalled to the railway, and appointed manager of a line in Northern Ireland, with a payroll of about 2000. He became railway liaison officer with the British and American armed forces. In May, 1946, he resigned to run the Sumburgh and Lunna estates, which he inherited from his father. He lived in Shetland from 1946 to 1952, and for part of that period was a county councillor and a member of the Highlands and Islands Panel. He represented Dunrossness North between 1949 and 1952, and again between 1963 and 1967. He was Lord Lieutenant for Shetland] from 1963 to 1982. In 1952 he accepted a five-year appointment as principal representative in Southern Africa of the Rio Tinto Company. During his chairmanship, the companies carried out a large programme of mining exploration in Northern Rhodesia, Southern Rhodesia and South Africa. Bruce also served as a director of three large copper mining companies in Northern Rhodesia, and he was a director of the Merchant Bank of Central Africa. He returned to Shetland in late 1957, and was adopted as Tory candidate for Orkney and Shetland in March 1958. He was defeated in the subsequent general election. Robert played an active part in the Shetland Council of Social Service, as part of a movement to revitalise Shetland economically. He also served as Chairman of the Hjaltland Housing Association Ltd. from 1975 to 1983. Following the death of Mrs Bruce in 1998 the Sumburgh and Lunna estates passed in to the hands of descendants of his eldest sister, Elizabeth Helen Wingate, who on January 7th 1930 had married Lestock George Robert Forbes Hamilton Bell, grandson of Robina Hunter, heiress of Lunna House and the Hunter of Lunna family estate and her husband Robert Bell. Thus strengthening the already significant links between the Bruce of Sumburgh and Hunter of Lunna families and estates.','R. H. W. Bruce H. H. A. Plaque - Shetland Museum and Archives RY00836.jpg',NULL,'I197159','Robert_Bruce','["Zetland County Councillors", "1907 Births", "1983 Deaths"]',0,1,288878991);
INSERT INTO "people" VALUES(412,'Robert Coutts','robert-coutts','1870-11-26','1952-06-19','Sandness',NULL,'Robert Thomas Charles Scott ''Robbie'' Coutts was a factor to the Vaila estate and a County Councillor for Walls between 1921 and 1925.','Robert was the factor to the Vaila estate for most of his life, retiring in 1949.',NULL,NULL,'I54682','Robert_Coutts','["Zetland County Councillors", "1870 Births", "1952 Deaths", "Biography Missing"]',1,NULL,292023888);
INSERT INTO "people" VALUES(413,'Robert Deans','robert-deans','1754-08-18','1834-04-24','East Lothian','Lerwick','Robert Deans was a merchant in Lerwick. He came to Shetland for the repair of Fort Charlotte on 24th March 1781, and was appointed tacksman at Gremista. He was also a Town Councillor between 1818 and 1820, and again from 1823 to 1829. In 1791, he was tasked to draw up plans for a Poorhouse with John Murray. In 1815 he was employed by Feuars and Heritors.',NULL,NULL,NULL,'I45555','Robert_Deans','["Lerwick Town Councillors", "Incomers to Shetland", "Deans", "1754 Births", "1834 Deaths"]',0,1,NULL);
INSERT INTO "people" VALUES(414,'Robert Douglas','robert-douglas',NULL,'1745',NULL,NULL,'Robert Douglas, was a Member of Parliament for Orkney and Shetland from 1730 until his death in 747. He was replaced by [person:james-halyburton:John Halyburton] in 1747. }} Category: Members of the Parliament of Great Britain',NULL,NULL,NULL,NULL,'Robert_Douglas','["Members of the Parliament of Great Britain"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(415,'Robert Feather','robert-feather',NULL,NULL,NULL,NULL,'Robert Geoff Feather is a former Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'Robert_Feather','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(416,'Robert Ganson (i)','robert-ganson-i','1855-09-25','1936-02-17','Delting','Lerwick','Robert Dowell Ganson O.B.E. was a business chairman, a Lerwick Town Councillor between 1903 and 1932, and a County Councillor, representing Bressay first between 1892 - 1895 and 1898 and 1913, Sandwick between 1913 and 1919, and Nesting between 1922 and 1928. He was a chairman for the Ganson Bros company which was established in 1883 and operated until the 1970''s as a carriage hiring company, and later a garage. His son, [person:robert-ganson-ii:Robert] had a similarly notable life in business and local government. His involvement with Brentham House in Lerwick and that area led to the alley leading to Brentham Court being renamed Ganson Lane.','Ganson was first a Law Clerk in Lerwick under James G. Galloway, the Procurate-Fiscal. With his brother he founded Ganson Bros as carters and hirers and he acquired farmland at the Ness of Sound. He grew Ganson Bros to be the largest and most extensive hiring company in Shetland. This progress was driven by the company''s ability to keep up with development in car motor technology. After his brother passed away, he continued extend his farmland and built several buildings in Lerwick including Brentham Place. He held a keen interest in agriculture and was a judge at livestock shows, as well as being a prominent member of the Shetland Agricultural Education Advisory Committee. He was also the Clerk to the Bressay School Board from 1872 until 1919 (43 years), the Clerk to the Lerwick School Board from 1890 to 1910 and was decorated with an O.B.E. for his work as Convener on Emergency War Committees.','RD Ganson Provost.png','RD Ganson Headshot.png','I84530','Robert_Ganson_(i)','["Zetland County Councillors", "Lerwick Town Councillors", "1855 Births", "1936 Deaths", "Natives of Shetland", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(417,'Robert Ganson (ii)','robert-ganson-ii','1896-07-31','1976-01-09','Lerwick','Lerwick','Robert James Hay ''Bertie'' Ganson was a company director and County Councillor for Delting South between 1922 and 1928, then Sandness from 1928 to 1932, and again from 1949 to 1970. He also represented the Lerwick Town Council between 1932 and 1947. His father, [person:robert-ganson-i:Robert] was involved at a similar level in local politics.','Bertie had a lifelong connection to his father''s firm Ganson Bros. Ltd, who were Ford dealers and self-drive hire in Shetland. Around the age of 18, Bertie joined the business but the outbreak of WWI soon interrupted his work, as he was call up to serve. He was in France with the 51st Division, then with the Royal Flying Corps and the Royal Air Force. After the war, he returned to work in the family business, and when his father died in 1936, Bertie took charge of the business, the largest of its kind at that point. Key to the success of the business was the main contract, which saw Gansons busses travel all over the mainland - but the Post Office began deploying its own vehicles in 1947, ending the 60-year connection. The busses were said to have travelled 75,000 miles a year on average.',NULL,NULL,'I84533','Robert_Ganson_(ii)','["Zetland County Councillors", "Lerwick Town Councillors", "1896 Births", "1976 Deaths"]',1,1,178362988);
INSERT INTO "people" VALUES(418,'Robert Garrick','robert-garrick','1917-01-14','1993-10-15','Aithsting','Lerwick','Robert Arthur Cumming Garrick was a merchant seaman and County Councillor for Aithsting between 1961 and 1973.',NULL,NULL,NULL,'I40070','Robert_Garrick','["Zetland County Councillors", "1917 Births", "1993 Deaths", "Biography Missing"]',1,1,295673222);
INSERT INTO "people" VALUES(419,'Robert Goudie','robert-goudie','1798-04-26','1869-11-20','Cunningsburgh','Lerwick','Robert Goudie was an ironmonger, founder of R. Goudie and Son at 113 Commercial Street, an insurance agent and a Lerwick Town Councillor. His son, [person:james-goudie:James], became the Provost of Lerwick.',NULL,NULL,NULL,'I68962','Robert_Goudie','["Lerwick Town Councillors", "1798 Births", "1869 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(420,'Robert Gray','robert-gray','1928-11-28','2004-06-12','Midgarth','Lerwick','Robert Stewart Gray was a general merchant, and County Councillor for Yell South between 1966 and 1975. When the County Council reformed as the Shetland Islands Council, he continued to represent Yell South from 1974 until 1993.','He was almost exclusively known as Stewart Gray.',NULL,NULL,'I20855','Robert_Gray','["Shetland Islands Councillors", "Zetland County Councillors", "1928 Births", "2004 Deaths", "Biography Missing"]',1,1,NULL);
INSERT INTO "people" VALUES(421,'Robert Haldane','robert-haldane','1848-07-20','1914-05-10','Edinburgh','Northmavine','Robert Camperdown Haldane was a County Councillor for Northmavine North between 1903 and 1907.','He was educated at Loretto School and Edinburgh Academy. Upon finishing school, he left the UK for Sri Lanka (Ceylon) where he lived for a number of years. He purchased the estates of North Roe and Lochend and in 1898 returned to Shetland. He held the office of Justice of the Peace. He was recognised by the Lord Lyon King of Arms and matriculated his arms at the Lyons Office on 8 April 1907.',NULL,NULL,'I68005','Robert_Haldane','["Zetland County Councillors", "1848 Births", "1914 Deaths"]',0,1,NULL);
INSERT INTO "people" VALUES(422,'Robert Hamilton','robert-hamilton','1867-08-26','1944-07-15','Mortlake','University College Hospital, London','Sir Robert William Hamilton was elected as MP for the constituency of Orkney &amp; Shetland on 15 November 1922, replacing [person:malcolm-smith:Malcolm Smith]. He served until 1935 when he was replaced by [person:basil-neven-spence:Basil Neven-Spence].','Hamilton was the second son of Sir Robert G. C. Hamilton who was Governor of Tasmania. He was educated at St Paul’s School and Trinity Hall, Cambridge. He was knighted in 1918. In 1925 he married Gertrude Williamson of Kirkwall, Orkney. In 1905 Hamilton was appointed Principal Judge and Chief Justice of the East Africa Protectorate. He was appointed as Chairman of the Civil Service Commission in 1918. He retired from the civil service in 1920.[2]','RobertHamilton.jpg',NULL,'I18045','Robert_Hamilton','["Members of the Parliament of the United Kingdom", "Liberals"]',0,0,NULL);
INSERT INTO "people" VALUES(423,'Robert Henderson (i)','robert-henderson-i',NULL,NULL,NULL,NULL,'Robert Henderson of Holland was a Burgh and Shire Commissioner for Orkney and Shetland to the Parliament of Scotland in 1617.',NULL,NULL,NULL,NULL,'Robert_Henderson_(i)','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(424,'Robert Henderson (ii)','robert-henderson-ii','1838-08-13','1898-06-19','Scousburgh',NULL,'Robert Henderson was a merchant (R & T Henderson), Sunday School teacher (Cloddieknowe) and County Councillor in Shetland, representing Dunrossness North between 1890 and 1898. He died in June of an election year, and his seat lay empty for two months before the County Council appointed Reverend [person:charles-whyte:Charles Whyte] in August.','Robert inherited R & T Henderson''s after the death of his father, Gavin, bringing his brother Thomas in as a partner. Robert was interested in growing Shetland''s reputation as a tourist destination for trout fishing, and had built a lodging house for this purpose. He was a member of the Parochial board, Parish Council and was a member of the School Board. He was also a member of the Baptist Church, and conducted services in Dunrossness and occasionally Lerwick. He was described as a staunch supporter of the Liberal cause.',NULL,NULL,'I89662','Robert_Henderson_(ii)','["Zetland County Councillors", "1838 Births", "1898 Deaths"]',1,NULL,179138235);
INSERT INTO "people" VALUES(425,'Robert Henderson (iii)','robert-henderson-iii',NULL,NULL,NULL,NULL,'Robert Henderson is a former Shetland Islands Councillor.',NULL,NULL,NULL,NULL,'Robert_Henderson_(iii)','["Shetland Islands Councillors", "Councillors - Missing All"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(426,'Robert Hicks','robert-hicks','1809','1863-02-13','England','Lerwick','Robert Hicks was a bookseller, chemist and Lerwick Town Councillor.','In 1848, Robert was appointed as Consul at Lerwick for the King of Hanover.',NULL,NULL,'I9098','Robert_Hicks','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1806 Births", "1863 Deaths"]',0,1,NULL);
INSERT INTO "people" VALUES(427,'Robert Honyman (i)','robert-honyman-i',NULL,NULL,NULL,NULL,'Admiral Robert Honyman (c. 1765 – 31 July 1848) was a Scottish admiral in the British Royal Navy who served in the French Revolutionary Wars and in the Napoleonic Wars. A native of Orkney, he also held office for ten years as a member of parliament (MP) for Orkney and Shetland.','Honyman was born in about 1765, the oldest son of Patrick Honyman of Graemsay, Orkney. His mother Margaret, a daughter of Patrick Sinclair of Durwin, was his father''s second wife. His older half-brother William Honyman, Lord Armadale was a Lord of Justiciary. The family claimed maternal descent from Sir Robert Stewart, an illegitimate son of King James V of Scotland. He married before 1808 Margaret Henrietta Knight, the granddaughter of Admiral Sir John Knight. They had one son and one daughter.',NULL,NULL,NULL,'Robert_Honyman_(i)','["Members of the Parliament of Great Britain", "Members of the Parliament of the United Kingdom"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(428,'Robert Honyman (ii)','robert-honyman-ii',NULL,'1808-11-20',NULL,'Jamaica','Colonel Robert Honyman ( b. circa 1781, d. 20 November 1808, Jamaica) was a British Army officer from Orkney who briefly held office as the Member of Parliament for Orkney and Shetland.','Honyman was born in about 1781, the oldest child of the lawyer William Honyman (later the Lord of Session Lord Armadale) and his wife Mary, the daughter of Lord Braxfield. He served as major in Reay’s Fencibles from 1794 to 1798, and was then on half-pay with the Yorkshire Fusiliers until 1802. He served as a volunteer during the Napoleonic Campaign in Egypt, where he impressed senior officers including Sir John Moore. He was brevet Lieutenant Colonel in 1802, and the following year was a major in the 93rd Foot,[1] which he led in 1806 in the successful attack on the Cape of Good Hope under Sir David Baird.[3] He was severely wounded in the attack. In 1806 he was promoted to Lieutenant Colonel of the 18th Foot. Later that year he returned to Orkney, where at the general election in December 1806 he was returned unopposed in his father''s interest as MP for Orkney and Shetland. With his father''s influence in Orkney facing a severe challenge, he served only one term, and did not contest the next election in June 1807. Like his uncle [person:robert-honyman-i:Robert], who preceded him as MP, he was away on active service for much of his time in office, and there is no record of him having voted or spoken in the House of Commons. In 1807 he was involved in the suppression of a mutiny of black troops in Jamaica, where he died of fever on 20 November 1808. }} Category: Members of the Parliament of the United Kingdom',NULL,NULL,NULL,'Robert_Honyman_(ii)','["Members of the Parliament of the United Kingdom"]',NULL,0,NULL);
INSERT INTO "people" VALUES(429,'Robert Hunter (i)','robert-hunter-i','1856-07-10','1923-03-01','Hogan','Union Bank office, Lerwick','Robert Bruce Hunter was a bank agent at the Union Bank and a Lerwick Town Councillor. He died in his office, aged 67. His father, [person:samuel-hunter:Samuel] and his brother [person:james-hunter-ii:James] were both councillors in Lerwick.','Robert was educated at the Anderson Institute under Principal Nathaniel Leask. After school, he joined the Union Bank of Scotland in Lerwick and remained there for some years. A promotion saw him take on the accountancy of the Haymarket branch of the same bank in Edinburgh. After a few years moved back to Lerwick and took on the same role back in the Lerwick branch. When [person:alexander-mitchell-i:Alexander Mitchell] retired from his job as Agent of the bank, Robert was promoted into that role. He was interested in boating and swimming, being involved in the Swimming Club and the relaunch of the Lerwick Boating Club.',NULL,NULL,'I18091','Robert_Hunter_(i)','["Lerwick Town Councillors", "1856 Births", "1923 Deaths"]',1,1,163057197);
INSERT INTO "people" VALUES(430,'Robert Hunter (ii)','robert-hunter-ii','1874-08-13','1948-02-23','Billister','Nesting','Robert Hunter was a merchant, wool dealer and registrar and a County Councillor for Nesting between 1920 and 1922, having been co-opted to the vacancy left following the death of his brother, [person:james-hunter-iv:James]. Robert was an agent for the Shipwrecked Mariners'' Society and other Sailors Orphan Society, with other appointments including; district receiver of wreck, clerk to the local Old Age Pensions Committee, collector of rates, registrar and chairman of the Nursing Association. He had been a Baptist and attended church the day before his death, where he appeared in good health.',NULL,NULL,NULL,'I29429','Robert_Hunter_(ii)','["Zetland County Councillors"]',1,1,288609893);
INSERT INTO "people" VALUES(431,'Robert Inkster','robert-inkster','1852-10-12','1919-05-09','South Shields','Scalloway','Robert Inkster was a commercial clerk and a County Councillor, first for Burra between 1909 to 1913, then for Tingwall from 1913 until his death in 1919.','Robert was born in South Shields where his parents had relocated around the 1850''s. By the early 1860''s, the family had returned to Shetland and had settled in Walls. His first job was as a shop assistant to Messrs Garriock & Co in Raewick where he remained until 1873, when he left Shetland. He was employed in an iron works in Cleveland, Ohio, and returned to Shetland in 1877. Though he intended on returning to America, an opening for a manager position with Garriock & Co''s Scalloway operation arose, which he accepted. After that company dissolved, Robert was the factor for Mrs Garriock''s estate, and held the same role in Burra for a Mr Gilmour. He was deeply religious, and was for some years the secretary of the Scalloway Congressional Church, as well as the senior deacon. He was a firm believer in Liberalism.',NULL,NULL,'I60123','Robert_Inkster','["Zetland County Councillors", "1852 Births", "1919 Deaths"]',0,1,179137424);
INSERT INTO "people" VALUES(432,'Robert Isbister','robert-isbister','1853-12-24','1907-05-14','Boddam','Sumburgh, Dunrossness','Robert Henry Isbister was a clerk, business partner and County Councillor from 1898 until his death in 1907.','Robert was heavily involved in public life, as chairman of the Parish Council of Dunrossness, a member of the School Board, a Justice of the Peace and the Vice Chair of the Broonie''s Taing Pier Trust.',NULL,NULL,'I122577','Robert_Isbister','["Zetland County Councillors", "1853 Births", "1907 Deaths"]',1,1,184994942);
INSERT INTO "people" VALUES(433,'Robert Jamieson (i)','robert-jamieson-i','1876-03-01','1943-10-31','Norby','Voe','Robert Jamieson was a sub-postmaster and County Councillor for Sandness between 1925 and 1928.','On leaving school, Robert joined Messrs T. M. Adie & Sons in Voe. When [person:robert-coutts:Robert Coutts] retired from the Ha'' shop in Sandness, Robert took over the premises, forming Robert Jamieson & Sons. In addition to being the Postmaster for the area, Robert was also the Registrar of Sandness. In the 1920s, he purchased a large sheep farm at Teagon in Voe where he successfully built up the business of Jamieson & Pole, also becoming Postmaster of Voe. In business he was one of the early adopts of cars sales and hiring in Shetland.',NULL,NULL,'I12813','Robert_Jamieson_(i)','["Zetland County Councillors", "1876 Births", "1943 Deaths"]',1,1,179947323);
INSERT INTO "people" VALUES(434,'Robert Johnson (i)','robert-johnson-i','1903-01-28','1970-07-11','Vidlin','Aberdeen','Robert Alexander ''Bingo'' Johnson was a clerk in the office of the Procurator Fiscal and a County Councillor for Gulberwick from 1958 until his death in 1970, also having been the convener.','Robert was educated in Lerwick. Upon completing school in 1917, he joined the Sheriff Clerk''s office. In 1930, he succeeded Archibald Clark as Sheriff Clerk. He had a key role in the founding of the Scottish National Farmers Union, and was secretary of that organisation for 25 years. He was the secretary of the Shetland Flock Book Society, and the Shetland Cattle Herd Book, as well as a director of the Shetland Lime Ltd. He was also the Lerwick Up Helly-Aa Guizer Jarl in 1928.','Fetlar School Opening.jpg',NULL,'I34247','Robert_Johnson_(i)','["Zetland County Council Conveners", "Zetland County Councillors", "1903 Births", "1970 Deaths"]',1,0,179138552);
INSERT INTO "people" VALUES(435,'Robert Johnson (ii)','robert-johnson-ii','1929-03-09','2014-08-12','Raefirth','Whalsay','Robert Lyle ''Bob'' Johnson is a former Shetland Islands Councillor.',NULL,NULL,NULL,'I20196','Robert_Johnson_(ii)','["Shetland Islands Councillors", "Councillors - Missing All"]',1,1,216847545);
INSERT INTO "people" VALUES(436,'Robert Linklater','robert-linklater','1811-12-11','1874-04-18','Tingwall','Edinburgh','Robert Linklater was a general merchant, draper and grocer in Lerwick, and also a Lerwick Town Councillor from 1853 until his death in 1874.',NULL,NULL,NULL,'I16434','Robert_Linklater','["Lerwick Town Councillors", "1811 Births", "1874 Deaths"]',1,0,163057209);
INSERT INTO "people" VALUES(437,'Robert Ollason','robert-ollason','1887','1961-01-22','Lerwick','Lerwick','Robert ''Robbie'' Ollason was a prominent local public figure in Shetland. He was a mercantile clerk and later had a newsagents &amp; stationers shop at 155 Commercial Street, (where the The Stage Door operated, across from [person:john-rae:John Rae]''s jewellers), in later life he was a member of the Shetland Health Board where he played an important role in getting the New Gilbert Bain Hospital built. However, he died before it was opened. He was very involved in local government and represented the Lerwick Town Council between 1919 to 1936, and 1945 to 1960, a total of 32 years. He also represented Whalsay And Skerries between 1938 and 1945.',NULL,'Robert Ollason Provost.png','Robert Ollason Headshot.png','I27257','Robert_Ollason','["Zetland County Councillors", "Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1887 Births", "1961 Deaths", "Councillors pictured"]',1,1,214369391);
INSERT INTO "people" VALUES(438,'Robert Ramsay','robert-ramsay','1874-10-17','1957-08-14','Lerwick','Lerwick','Captain Robert Henderson Ramsay was a photographer and Lerwick Town Councillor between 1912 and 1921.','Robert took up photography at an early age, and worked with Valetine & Sons, Dundee, to capture landscapes in Orkney and Shetland to be used as postcards. He enlisted in the 7th Volunteer Battalion Gordon Highlanders in 1902. Mobilised in 1914, he served in his Regiment as Adjutant until 1916 when he returned to civilian life. The Shetland Museum''s online photo archive has 833 photos which list him as the photographer, and these can be viewed here.','Rramsay.jpg',NULL,'I30735','Robert_Ramsay','["Lerwick Town Councillors", "1874 Births", "1957 Deaths"]',1,1,291574510);
INSERT INTO "people" VALUES(439,'Robert Scott','robert-scott','1840-11-10','1906-10-14','Lerwick','Selkirk, Manitoba, Canada','Robert Scott was a shopman, ship''s agent and Lerwick Town Councillor between 1874 and 1876. He was unsuccessful in getting re-elected at the 1876 Lerwick Town Council Election. He and his wife subsequently moved to Canada with his sister Ann.',NULL,NULL,NULL,'I67254','Robert_Scott','["Lerwick Town Councillors", "1840 Births", "1906 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(440,'Robert Sinclair','robert-sinclair','1814','1891-07-16','Twatt, Aithsting','Victoria, Australia','Robert Sinclair was a draper, folklorist and Lerwick Town Councillor.','He moved to Lerwick and worked for draper James Linklater, before eventually setting up his own business, &quot;Robert Sinclair &amp; Co.&quot;, at 60 Commercial Street. He built St Clair Villa in Clairmont Place in Lerwick''s new town. Sinclair gave lengthy evidence to the Truck Commission in 1872 about the hosiery trade in the islands. He was also a keen folklorist. In 1879 he contributed a long account of ''Da tief o'' da Neean'', a story about a mythical Aithsting outlaw, to The Shetland Times. He also wrote important notes on Shetland folklore and folk-life, which appear in The Shetland Folk Book, 9, 1995. With [person:arthur-laurenson:Arthur Laurenson] and other Lerwegians with antiquarian interests he studied Icelandic. In 1885, however, he, his wife Anne More (1825-1891), and their large family, emigrated to New Zealand. Robert died in Australia in 1891. Sinclair''s third child George Sinclair (1852-1928) shared his father''s interests. He kept a notebook with important folklore information, some of it derived from Robert, which is now in the State Library, Victoria (microfilm copy in Shetland Archives). He advised the German folklorist Karl Blind on Shetland lore, and wrote a version of the gruesome Shetland story ''Lang lies Lowrie at da Mill, or Lowrie''s grienin wife'', which is published in The Shetland Folk Book, 8, 1988.',NULL,NULL,'I52864','Robert_Sinclair','["Lerwick Town Councillors", "1812 Births", "1891 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(441,'Robert Smith','robert-smith','1871-04-02','1948-03-05','Camb','Yell','Robert John Smith was a merchant and County Councillor for Yell North from 1932 until his death in 1948.','Robert Smith was a merchant, and had a business at Gossabrough, East Yell where all the family were born. Then after the First World War he bought the property at Ravensgio, Mid Yell, from his wife''s uncle William Watson Johnson, where he had the business until his death. Jemima Jane and her husband carried on the business until 1955 when it was sold and they moved to Aberdeen.','Yellgroup.jpg',NULL,'I9081','Robert_Smith','["Zetland County Councillors", "1871 Births", "1948 Deaths"]',1,1,290829225);
INSERT INTO "people" VALUES(442,'Robert Stout (i)','robert-stout-i','1841','1915-04-10','Lerwick','Lerwick','Robert Stout was a postmaster and Lerwick Town Councillor initially between 1871 and 1876, then later from 1906 until his death in 1915. His death caused a war time Lerwick Town Council by-election in 1915.','His first job was as a shipping clerk at the Aberdeen, Leith and Clyde Shipping Company, which became the North of Scotland Orkney And Shetland Steam Navigation Company. He then joined the Post Office, and when Peter Ross retired, Robert was appointed Postmaster in Lerwick. During his time, the postal service underwent dramatic transformations within Shetland, with increasing mail steamers, the establishment of rural post offices and the extension of telegraphs. When Robert joined the Post Office, it was located in a small shop across from the Queen''s Hotel, and mail arrived once per week to Shetland, while mail to the rural districts were carried by men. By 1907, Shetland had five mail deliveries per week, and a telephone system had been established, and country mails were carried by carriage and steamer. He retired around 1907, but continued his work as a registrar.','Robert Stout Provost.png','Robert Stout Headshot.png','I86036','Robert_Stout_(i)','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1841 Births", "1915 Deaths", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(443,'Robert Strachan','robert-strachan','1925-09-12','1997-02-15','Peterhead','Aberdeen','Robert ''Bob'' Strachan was a Post Office Engineer, a County Councillor for Burra and a Lerwick Town Councillor between 1959 and 1962.','In 1963, he was Shetland''s Civil Defence Officer, and served four years. He then took up a role with the Orkney County Council as development assistant, and performed the same duties for Caithness in the mid 1970''s. In 1974, he took up a new job in a private industry in Caithness.',NULL,NULL,'I356483','Robert_Strachan','["Lerwick Town Councillors", "Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1926 Births", "1997 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(444,'Robert Sutherland','robert-sutherland','1870-03-04','1942-12-21','Deepdale','Sand, Sandsting','Robert Alexander Sutherland was a ploughman, farmer, merchant and County Councillor for Sandsting between 1919 and 1922.','',NULL,NULL,'I107353','Robert_Sutherland','["Zetland County Councillors", "1870 Births", "1942 Deaths", "Biography Missing"]',1,1,NULL);
INSERT INTO "people" VALUES(445,'Ronald Cumming','ronald-cumming','1923-08-15','2007-02-04','Golspie','Aberdeen','Ronald Patrick ''Ronnie'' Cumming was a Consultant Surgeon at the Gilbert Bain Hospital and a Lerwick Town Councillor from 1967 until 1975. and the Lerwick Breiwick seat at the inaugural Shetland Islands Council election 1974.','Ronald graduated M.B, Ch.B. from the University of Aberdeen in 1945 and took up his first post as assistant G.P in Huntly. He followed this with assistant in the Department of Anatomy in 1947. He was assistant G.P in Rhynie in 1949, Junior Surgical Officer at Ronkswood Hospital, Worcester in 1950 then Senior House Officer and Registrar at Victoria Hospital, Burnley. He obtained his F.R.C.S in 1952 from Edinburgh. He became Senior Registrar at Aberdeen General Hospital Ronald was appointed as consultant general surgeon at the Gilbert Bain in late 1957, replacing Charles Anderson who had been transferred to Arbroath. For some years prior, Ronald had been a relief surgeon for the Isles. He held this new role until 1980. He retired from his profession in 1985. He was also a member of the British Medical Association North Sea Oil Working Party in the 1970s. He was made a Fellow of the British Medical Association in March 1982 on nomination of the Shetland branch of the British Medical Association',NULL,NULL,NULL,'Ronald_Cumming','["Lerwick Town Councillors", "1923 Births", "2007 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(446,'Ross Smith','ross-smith','1815-05-01','1887-07-06','Mailand','Edinburgh','Ross Smith was a watch and compass maker and Lerwick Town Councillor. Smith also had worked as a reporter for the Shetland Advertiser.','His obituary in the Shetland Times noted that he was a great advocate for the waterworks scheme, and for moving the gasworks further away from residential areas than originally planned. He was a contributor to the Shetland Advertiser, an early newspaper in Shetland. He is described as one of Lerwick''s first photographers, and politically moved from Liberal to Conservatism in his older age. The Shetland Times described this transition as "when his health began to fail and he lost some of his vigour, he drifted round to Conservatism". James W. Irvine, in his book Lerwick: Birth and Growth of an Island Town, notes that Smith was largely responsible for turning inaction into action regarding the building of the ''New Town'' in Lerwick. His son [person:william-smith-ii:William] was also a Lerwick Town councillor.',NULL,NULL,'I10997','Ross_Smith','["Lerwick Town Councillors", "1815 Births", "1887 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(447,'Samuel Fordyce','samuel-fordyce','1852','1921-10-18','Aberdeen','Lerwick','Samuel William Fordyce was a plumber and County Councillor for Gulberwick from 1910 until his death in 1921.','Fordyce arrived in Shetland in 1887, working as a plumber to John M. Aitken, later starting his own business which he operated up to his death.',NULL,NULL,'I106207','Samuel_Fordyce','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1855 Births", "1921 Deaths"]',0,1,179138480);
INSERT INTO "people" VALUES(448,'Samuel Hunter','samuel-hunter','1824-06-25','1858-02-02','Lerwick','Lerwick','Samuel Dunn Hunter was a merchant and Lerwick Town Councillor between 1850 until his death in 1858. Hunter''s father, [person:james-hunter-i:James] was a councillor from 1835 to 1847. Two of Samuel''s sons, [person:james-hunter-ii:James] and [person:robert-hunter-i:Robert], were also councillors.',NULL,NULL,NULL,'I3427','Samuel_Hunter','["Lerwick Town Councillors", "1824 Births", "1858 Deaths"]',1,1,163057194);
INSERT INTO "people" VALUES(449,'Samuel Laing','samuel-laing','1812-12-12','1897-08-06','Edinburgh','Sydenham','Samuel Laing was a railway administrator, Member of Parliament for Orkney and Shetland, and writer on science and religion during the Victorian era.','<strong>Early life</strong>

Samuel Laing was born on 12 December 1810 in Edinburgh, Scotland. He was the nephew of Malcolm Laing, the historian of Scotland; and his father, also called Samuel Laing (1780–1868), was a well-known author, whose books on Norway and Sweden attracted much attention. Samuel Laing the younger entered St John''s College, Cambridge in 1827, and after graduating as Second Wrangler and Smith''s Prizeman, was elected a fellow. He remained at Cambridge temporarily as a coach, before being called to the bar in 1837.

<strong>Career</strong>

He became private secretary to Henry Labouchere, later 1st Baron Taunton, who was then the President of the Board of Trade. In 1842, he was made secretary to the railway department, and retained this post until 1847. He had by then become an authority on railways, and had been a member of the Dalhousie Railway Commission; it was at his suggestion that the "parliamentary" rate of a penny a mile was instituted. In 1848, he was appointed chairman and managing director of the London, Brighton and South Coast Railway (LB&SCR), and his business acumen showed itself in the largely increased prosperity of the line. He also became chairman (1852) of the Crystal Palace Company, but retired from both posts in 1855. In 1852, he was elected to Parliament as a Liberal Party candidate in Wick Burghs. After losing his seat in 1857, he was re-elected in 1859, and appointed Financial Secretary to the Treasury; in 1860 he was made finance minister in India. On returning from India, he was re-elected to parliament for Wick in 1865. He was defeated in 1868, but in 1873 he was returned for Orkney and Shetland, and retained his seat till 1885. Meanwhile he had been reappointed chairman of the Brighton line in 1867, which was now on the point of bankruptcy following the over-ambitious expansion plans of the previous chairman. He continued in that post until 1896, and gradually restored the company to financial health. He was also chairman of the Railway Debenture Trust and the Railway Share Trust. Although often claimed to have been the father of the novelist Mary Eliza Kennard (1850–1936), this is incorrect.

<strong>Later Life</strong>

In later life, he became well known as an author, his Modern Science and Modern Thought (1885), Problems of the Future (1889) and Human Origins (1892). Laing''s attitude was generally positive towards new developments in science, and he offered an optimistic vision of progressive modernity. He also wrote on religion. His book A Modern Zoroastrian argued that the ancient religion of Zoroastrianism was more consistent with modern scientific thought than was traditional Christianity. He argued that the "all pervading principle of polarity" that was central Zoroastrian thought has been confirmed by science, and that modern Christianity should abandon its traditional theology to centre on the figure of Jesus as an ideal of humanity.','Samuel Laing.jpg',NULL,'I433423','Samuel_Laing','["Members of the Parliament of the United Kingdom", "Liberals"]',0,0,NULL);
INSERT INTO "people" VALUES(450,'Selina Garriock','selina-garriock','1877','1938-09-02','New York, USA','Scalloway','Selina Garriock (neé Darrell) was a County Councillor for Tingwall from 1935 until her death in 1938, and was the first woman elected to the Zetland County Council. [person:charlotte-nicol:Charlotte Nicol] was technically the first women on the body, by default through her election to the Lerwick Town Council in 1933. Her husband, [person:lewis-garriock:Lewis], was also a Councillor.','<strong>Early Life</strong>

Selina was born to George Frederick Darrell and Mary B. Usher, she was the youngest of two, having one sister, Jean. She met and married [person:lewis-garriock:Lewis] in 1903 in Broughty Ferry. Shortly thereafter they moved to Shetland where the lived in Gibblestone House. In 1913, they built a cottage on Westshore.

<strong>Public activities</strong>

Described as an "intelligent and well-educated woman", she was a member of a number of public bodies, including the Education Committee from 1934 until her death, she was the Chair of the School Management Committee, a founding member of the Tingwall, Whiteness & Weisdale Nursing Association and President of Scalloway W.R.I. In 1935, she was elected to the Tingwall (which incorporated Scalloway) seat on the Zetland County Council. [person:lewis-garriock:Lewis] had also held the seat from 1909 until 1913. As a Councillor, she was described as one of the most regular attendees, and the Shetland News concluded that "no district could have a more devoted, earnest and attentive member". She died in office, with an election due in December of the same year.

<strong>Later life</strong>

Having lost her husband in April of 1938, she had experienced considerable strain looking after him. She had suffered from a protracted illness and after returning from a short trip to the Scottish Mainland, her health continued to deteriorate. Despite her illness, she still attended a W.R.I. flower and vegetable show and was still receiving phone calls on the day of her death. She suddenly became very ill on the same Friday evening and passed away. Such was her standing in the community that her funeral was a public one. All businesses in Scalloway closed during her funeral, and the flag of the County Buildings on Lerwick were flown at half mast. She is buried in the Tingwall kirkyard.',NULL,NULL,'I68324','Selina_Garriock','["Zetland County Councillors", "Incomers to Shetland", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "Female", "1877 Births", "1938 Deaths", "Died in Office"]',0,1,175625832);
INSERT INTO "people" VALUES(451,'Simon Garriock','simon-garriock','1897-03-14','1973-08-25','Skeld','Raewick, Sandsting','Simon Garriock was a County Councillor for Sandsting between 1945 and 1955. He was a distant relative of Tingwall County Councillor [person:lewis-garriock:Lewis Garriock] (4th cousin twice removed).',NULL,NULL,NULL,'I36913','Simon_Garriock','["Zetland County Councillors", "1897 Births", "1973 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(452,'Simson Wallace','simson-wallace','1867-04-02','1940-11-13','Scoonie','Pittenweem, Anstruther, Fife','Reverend Simson Wallace was a minister and a County Councillor for Cunningsburgh between 1925 and 1927.','He first represented Eshaness United Free Church from 7 April 1897 until he was transferred to Longformacus in 1909. He was transferred back to Shetland from Longformacus and was ordained to the Cunningsburgh United Free Church on 2 February 1912, he transferred out of Shetland to Botriphnie & Cairnie on 2 Feb 1927, resigning from the County Council and causing a Cunningsburgh by-election. He died of heart failure in November, 1940 during a committee meeting at St. Fillan''s Church in Pittenweem.',NULL,NULL,'I74885','Simson_Wallace','["Zetland County Councillors", "Councillors - Clergymen", "1867 Births", "1940 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(453,'Sinclair Duncan','sinclair-duncan','1827-04-21','1927-02-06','Hoswick','Seaview House, Hoswick','Sinclair Thomson Duncan was for a time a wholesale merchant at Leith, and subsequently a travelling commission agent. He returned to Hoswick in the 1870s. Duncan was elected to serve as a County Councillor for Sandwick from 1890 to 1904. Duncan was also the leader of the salvors in the Hoswick Whale Case.',NULL,NULL,NULL,'I83262','Sinclair_Duncan','["Zetland County Councillors", "1827 Births", "1927 Deaths"]',1,1,195782381);
INSERT INTO "people" VALUES(454,'Sinclair Johnson','sinclair-johnson','1863-08-16','1927-03-23','Aithsting','New Zealand','Sinclair Johnson was a draper and Lerwick Town Councillor between 1899 and 1907.','Sinclair was born in Aithsting and upon leaving school moved to Lerwick and began working as an assistant to William Irvine, a job he held for several years. After William gave up the business, Sinclair entered employment with Frederick Adie until the 1880s, when Fred left Shetland for Canada. Thereafter, Sinclair opened his own business, as a draper and clothier under the name Sinclair Johnson & Co, which he ran until he left Shetland for New Zealand. He took a keen interest in the herring fishery, and part-owned some boats, although this arm of his business was not overall a success. In politics, he was an enthusiastic Liberal. Upon his death in 1927, he charitably bequeathed £10,000 to Hawke''s Bay Children''s Home, Napier; Gilbert Bain Hospital, Lerwick; Agnes Weston''s Sailor''s Rest, Portsmouth and Dr. Barnardo''s Home in London.',NULL,NULL,'I44151','Sinclair_Johnson','["Lerwick Town Councillors", "1863 Births", "1927 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(455,'St. Clair Pottinger','st-clair-pottinger','1891-05-30','1973-03-23','Gremista','Cunningsburgh','St Clair Arthur Alexander Pottinger was a merchant navy officer and County Councillor for Cunningsburgh between 1945 and 1949',NULL,NULL,NULL,'I269791','St._Clair_Pottinger','["Zetland County Councillors", "1891 Births", "1973 Deaths", "Biography Missing"]',1,1,NULL);
INSERT INTO "people" VALUES(456,'Steven Coutts','steven-coutts','1982-11-18',NULL,'Lerwick',NULL,'Steven William Coutts is a Shetland Islands Councillor, representing the North Isles since 2012.','Steven runs a business consultancy out of Yell, and has undertaken work on behalf of the Energy Saving Trust.',NULL,NULL,'I20409','Steven_Coutts','["Shetland Islands Councillors", "Natives of Shetland", "1982 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(457,'Tavish Scott','tavish-scott','1966-05-06',NULL,NULL,NULL,'Tavish Hamilton Scott is a farmer and the Scottish Liberal Democrat Member of the Scottish Parliament for Shetland, a post he has held since 1999. He was also previously a Shetland Islands Councillor and led the Scottish Liberal Democrats from 2008 until 2011..','Tavish was the first of two children born to [person:john-scott:John Scott] and Wendy (neé Ronald). He was born in Inverness, educated at the Anderson High School in Lerwick before going on to do a BA (Hons) in Business Studies at Napier College in Edinburgh. After graduating, he worked as a parliamentary assistant to MP [person:james-wallace:Jim Wallace], then as a Press Officer for the Scottish Liberal Democrats before eventually returning to Shetland where he became a farmer and a Shetland Islands Councillor.','Tavish results.png',NULL,'I283258','Tavish_Scott','["1966 Births", "Members of the Scottish Parliament", "Liberal Democrats", "Shetland Islands Councillors"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(458,'Theodore Andrew','theodore-andrew','1898-02-14','1960-09-05','Walls','Gilbert Bain Hospital','Reverend Theodore Andrew was a minister and County Councillor for Walls between 1928 and 1930.','Theodore was educated in Shetland and Glasgow University. He served the Church of Scotland initially in Walls from 1924 or 1926 until he was transferred to Dundee Chapelshade on 20 March 1930. He subsequently had spells in Brechin and Dumfries. He returned to Shetland to serve in Sandwick from 1954 until 1959 when Sandwick joined with Cunningsburgh and Quarff, which he represented from then until his death.',NULL,NULL,'I54920','Theodore_Andrew','["Zetland County Councillors", "Councillors - Clergymen", "1898 Births", "1960 Deaths"]',1,1,270027656);
INSERT INTO "people" VALUES(459,'Theodore Smith','theodore-smith','1952-05-21',NULL,'Lerwick',NULL,'Theodore George Cameron ''Theo'' Smith is a Shetland Islands Councillor, representing the Shetland West since 2012.','Theo is a Chartered Architectural Technologist and has spend his career in the building and construction trade.',NULL,NULL,'I140191','Theodore_Smith','["Shetland Islands Councillors", "Natives of Shetland", "1952 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(460,'Thomas Anderson (i)','thomas-anderson-i','1855-11-03','1936-12-19','Hillswick','Pahiatua, New Zealand','3 November 1855, Hillswick, d. 19 December 1936, Pahiatua, New Zealand) was a merchant and a livestock breeder, dealer and exporter. He was also a County Councillor first for Northmavine South between 1890 and 1901, then Northmavine North from 1907 to 1913. His mother, Eupehemia Anderson (neé Merrylees) was the daughter of [person:william-merrylees:William Merrylees], who was a Lerwick Town Councillor. His cousin [person:charles-merrylees:Charles] was also a councillor in Lerwick.','Thomas began his working life in his father''s shop, Messrs John Anderson & Sons. The extensive business had large fishing interests, both in herring and white fish trade, as well as rearing, dealing and exporting cattle, ponies, sheep and lambs. He became a partner in the business with his brother Gilbert. On the death of their father in 1911, the brothers continued running the business in partnership. Gilbert died in 1919. As the fishing industry declined, so did Thomas''s business. A combination of this decline and the death of Gilbert saw him sell the business to one of his employees, who began trading under Messrs W. S. Manson & Co. He emigrated to New Zealand in 1922.',NULL,NULL,'I68998','Thomas_Anderson_(i)','["Zetland County Councillors", "1855 Births", "1936 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(461,'Thomas Anderson (ii)','thomas-anderson-ii','1861-01-21','1938-04-17','Bressay','Lerwick','21 January 1861, Bressay, d. 17 April 1938, Lerwick) was a wine and spirit merchant and a County Councillor, representing a number of constituencies. First he was elected for Whalsay And Skerries from 1904 until 1907, next Bressay between 1913 and 1922, then later he was briefly attached to Gulberwick from 1924 to 1925. Finally he represented Nesting between 1932 and 1935.','Anderson''s first worked with William S. Smith, and was later employed in Andrew Smith''s grocery shop. After feeling he had satisfactory experience as a merchant, he bought over the grocery and provision left by the late J. J. Heddell at the Market Cross and became a very well known merchant in Lerwick - and in Bressay, where he had opened a shop. Outside of work he had a great interest in agricultural. He was a governor of the North of Scotland College of Agriculture, president of the Shetland Flock Book Society, a member of the Shetland Cattle Herd Book Society, vice-president of the Tingwill Agricultural Improvement and Discussion Society, and he also acted as a judge for many of Shetland''s agricultural shows. On top of these commitments, he also was a director for the Shetland Fishermen''s Widows'' Relief Fund and a member of the executive committee of the Shetland Chamber of Commerce.',NULL,NULL,'I129730','Thomas_Anderson_(ii)','["Zetland County Councillors", "1861 Births", "1938 Deaths"]',1,1,178996255);
INSERT INTO "people" VALUES(462,'Thomas Anderson (iii)','thomas-anderson-iii','1866-06-19','1920-12-17','Kergord','Lerwick','19 June 1866, Kergord, Weisdale, d. 17 December 1920, Lerwick) was a sheep farmer and a County Councillor for Aithsting between 1915 and 1920. His [person:james-anderson-i:father] and [person:james-anderson-ii:brother], both named James, were also councillors.','Thomas grew up in relative comfort as the son of a successful crofter, but at an early age took ill and had to be treated on the Scottish mainland. When a boating accident off Vementry took the lives of his younger brother, as well as William Fraser, proprietor of Vementry, Thomas was appointed as factor to William''s estate and held that post until death.','Tanderson.jpg',NULL,'I51606','Thomas_Anderson_(iii)','["Zetland County Councillors", "1866 Births", "1920 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(463,'Thomas Balfour','thomas-balfour','1810-04-02','1838-03-30','Shapinsay','Edinburgh','Thomas Balfour was the Conservative Member of Parliament for Orkney and Shetland from 1835 to 1837.',NULL,NULL,NULL,NULL,'Thomas_Balfour','["Conservatives", "Members of the Parliament of the United Kingdom", "Conservatives"]',0,0,NULL);
INSERT INTO "people" VALUES(464,'Thomas Cameron','thomas-cameron','1819-09-09','1892-12-21','Garth','Lerwick','Major Thomas Mouat Cameron was a Lerwick Town Councillor from 1876 until he chose to retire in September 1883. He served as Chief Magistrates of the Lerwick Town Council from 1876 until his resignation in 1883. His grandson, [person:norman-cameron:Norman], was a Zetland County Councillor for Bressay.','Thomas was educated at a Military Academy in Edinburgh, before joining the East India Company in 1838. He served for 12 years, returning to Shetland in 1850 until 1852, before heading back out to India, where he stayed until his retiral in 1861. By 1871, he owned the Annesbrae Estate and later the Garth. He was a member of the Commissioners of Supply, the Convener of the Zetland Road Board, as well as many other positions in Shetland:—Deputy-Lieutenant, Honorary Sheriff-Substitute, Vice-President i of the Orkney and Zetland Association, President of the Shetland Literary and Scientific Society, Chairman of Directors '' of the Lerwick Town Hall Company, and of the Shetland Fishermen’s Widows’ Relief'' Fund, and Chairman of the Lerwick Harbour Trust. He was also a Trustee of the Feuars and Heritors and Convener of the Heritors’ Committee for Parochial Buildings.',NULL,NULL,'I39747','Thomas_Cameron','["Lerwick Town Councillors", "1819 Births", "1892 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(465,'Thomas Dundas (i)','thomas-dundas-i',NULL,'1786-04-16',NULL,NULL,'Thomas Dundas was a Member of Parliament for Orkney and Shetland from 1768 until 1771, replacing [person:james-douglas:James Douglas]. He served until 1770 when he was replaced by his son, [person:thomas-dundas-ii:Thomas] He was also a Burgess of Edinburgh, Deputy Lyon King at Arms, and Commissioner of Police.','Dundas was the oldest son of Thomas Dundas of Fingask. His father was a bailie of Edinburgh and a woollen draper in the Luckenbooths. The family''s lands in Perthshire were lost in the 17th century, but the bailie bought lands in Stirlingshire. Young Tomas and his brother Lawrence left their father''s ailing business, Thomas acting as agent for Lawrence''s highly profitable business supplying the British Army. Thomas became a burgess of Edinburgh in 1734, and deputy Lord Lyon King of Arms from 1744 to 1754. In 1737 he married Anne, daughter of James Graham of Airth, a judge of the Scottish court of Admiralty. After her death he remarried, to Lady Janet Maitland, daughter of the 6th Earl of Lauderdale. They had two sons and five daughters. Dundas bought the Carronhall estate in 1749, but his career remained dependant on his increasingly powerful younger bother, in whose interest he was elected in 1768 as the Member of Parliament (MP) for Orkney and Shetland. He held the seat until December 1770, when he was appointed as a police commissioner, and in 1771 his oldest son [person:thomas-dundas-ii:Thomas] was returned as MP in his place. The younger Thomas went on to become a notable general in the British Army, serving briefly as Governor of Guadeloupe before his early death. The other son, [person:charles-dundas:Charles], was an MP for nearly 50 years before being ennobled as Baron Amesbury.',NULL,NULL,NULL,'Thomas_Dundas_(i)','["Members of the Parliament of Great Britain", "1786 Deaths"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(466,'Thomas Dundas (ii)','thomas-dundas-ii','1750-06-30','1794-06-03',NULL,NULL,'Major General Thomas Dundas was a Member of Parliament for Orkney and Shetland, first from 1771 until 1789, then again from 1781 until 1790. His first stint in the role saw him replace his father, [person:thomas-dundas-i:Thomas], until 1780 when he was replaced by [person:robert-baikie:Robert Baikie]. His second period in office was from 1781 until 1790 when he was replaced by [person:john-balfour:John Balfour]','He held the rank of Major-General in the 80th Regiment of the British Army. He died on 3rd June 1794, in Guadeloupe, of Yellow Fever, and was buried at Fort Mathilde (now called Fort Delgres) in Guadeloupe. When the French retook the island, on 10th December 1794, the french commander, Victor Hughes, issued the following proclamation; "That the remains of Thomas Dundas, interred at Guadeloupe, shall be taken up and given as prey to the birds of the air" The desecration of the grave, by the French, of such a distinguished British officer caused outrage in Britain, and as a result of a vote in the House of Commons, it was agreed that a statue should be erected in St. Pauls Cathedral to the memory of Major General Thomas Dundas. The statue can be seen here. A Plaque was erected in Trinidad to his memory, which reads: "To the memory of Major-General Thomas Dundas, who, with great professional abilities and with a mind generous and brave, fell a sacrifice to his zeal and exertion in the service of his King and country, on the 3rd day of June 1794, in the fourty fourth year of his age. His remains were interred in the principal bastion of Fort Maltilde, in the island of Guadelope, in the conquering of which he bore a most distinguished share, and which he commanded at his death. This tablet was erected by his brother officers as a mark of their high esteem for his many valuable qualities, and their regret for his loss." }} Category: Members of the Parliament of Great Britain
Category: 1750 Births
Category: 1794 Deaths','ThomasDundas.jpg',NULL,NULL,'Thomas_Dundas_(ii)','["Members of the Parliament of Great Britain", "1750 Births", "1794 Deaths"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(467,'Thomas Gifford','thomas-gifford','1819','1899','Delting','Busta, Delting','Thomas Gifford was a County Councillor for Delting South between 1890 and 1898.','Thomas was factor of the Busta estate for 43 years, from 1856 til death. As a young man, Thomas worked on the sea, working on the east coast of the USA before returning to Shetland. He was the Clerk of the Highland Destitution Board, member of the Road Trustees, was a Commissioner of Supply among many other appointments.',NULL,NULL,'I10610','Thomas_Gifford','["Zetland County Councillors", "1819 Births", "1899 Deaths"]',1,1,284880822);
INSERT INTO "people" VALUES(468,'Thomas Gilbertson','thomas-gilbertson','1793-10-01','1868-01-27','Geosetter','Lerwick','Thomas Gilbertson was a tailor, clothier and Lerwick Town Councillor first between 1850 and 1853, then again between 1862 and 1865. His youngest son, Robert Gilbertson, was the founder of Gilbertson Park. He owned property at 101 Commercial Street and Gilbertson''s Court.',NULL,NULL,NULL,'I84556','Thomas_Gilbertson','["Lerwick Town Councillors", "1793 Births", "1868 Deaths"]',1,1,175856805);
INSERT INTO "people" VALUES(469,'Thomas Irvine (ii)','thomas-irvine-ii','1879','1946-06-06','Lerwick','Lerwick','Thomas Arthur Irvine was a baker and Lerwick Town Councillor.',NULL,NULL,NULL,'I106675','Thomas_Irvine_(ii)','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1879 Births", "1946 Deaths"]',1,1,216266143);
INSERT INTO "people" VALUES(470,'Thomas Johnston (i)','thomas-johnston-i','1873-08-12','1936-10-29','Lerwick','Lerwick','Thomas Johnston was a solicitor and Lerwick Town Councillor. He died in his family home, 83 King Harald Street, aged 63.','Despite not having much financial opportunity for further education, Thomas was determined to pursue a career in law. He worked for a short period with The Shetland Times, and at age 18 he was a law apprentice with Alexander Bain, the sole partner of Sievwright & Macgregor. He completed his five year apprenticeship and moved to Edinburgh to work for Mack and Grant W.S., before returning home to work with [person:john-bruce:John Bruce], as a factor. Alongside his job in Sumburgh, he was the Clerk to the School Board of Dunrossness and to the Parish Council. After his wife, a teacher, was placed in a school in Belhelvie, the family moved to Aberdeenshire, where he joined the clerical staff of John Duthie Sons & Coy Ltd, shipbuilders based in Footdee. Some five years later, the family moved back to Shetland after his with Jessie took on a teaching job in Trondra. He stayed with the shipbuilders until 1925. Thomas succeeded [person:alexander-hay:Alexander C. Hay] as Chamberlain for the Marquis of Zetland and also as factor for the Hayfield estate. He held both offices until his death. In Shetland, he eventually had his own firm, Thomas Johnston & Company, in partnership with FG Heddell. Eventually, this firm was amalgamated with J Small B.L. to form J. Small, Johnston & Cowie. In 1936, he withdrew from the partnership and began his own firm again.',NULL,NULL,'I107581','Thomas_Johnston_(i)','["Lerwick Town Councillors", "1873 Births", "1936 Deaths"]',1,1,274926386);
INSERT INTO "people" VALUES(471,'Thomas Johnston (ii)','thomas-johnston-ii','1894-11-20','1972-06-05','Lerwick','Lerwick','Thomas ''Tammy'' Johnston was Town Clerk from 1949 to 1960 and a County Councillor, for Gulberwick from 1925 to 1936, with 1935-6 as convener, standing down from the ZCC on 5 September 1936.','Johnston was handicapped at a young age, having one of his legs amputated. This, as Jim Taylor noted, did not prevent him from being involved in all manner of activities throughout his life. He worked as a clerk in the Procurator Fiscal''s office and then later took up a similar role with the National Insurance Committee, holding the position until 1937. He was the county assessor between 1937-1949 (sometimes referred to as ''County aggressor''). In 1935 he was appointed as Convenor of the Zetland County Council, a position which he held until 1936, and he is listed as being responsible for the Lerwick Landward Housing Scheme, which ''[eliminated] the squalor of the then Fleet Street and Pig Street of the Skibbadock and Garthspool areas&quot;. As Town Clerk he carried out exhaustive research which assisted in the establishment of the Shetland Museum.','Thomas Johnston.png',NULL,'I81878','Thomas_Johnston_(ii)','["Zetland County Councillors", "1894 Births", "1972 Deaths", "Johnston", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(472,'Thomas Manson (i)','thomas-manson-i','1885-07-10','1940-09-20','Yell','Lerwick','Thomas Robert Manson was a merchant and County Councillor for Yell South between 1919 and 1922, and again from 1932 until his death in 1940.','Thomas began his career at sea with the North of Scotland Company''s steamer Queen, before joining some vessels that operated internationally. He moved into herring fishing where for some time he was a part owner of the Cygnet with Captain Hercules Hunter. When that industry collapsed, he joined D & G Kay in Lerwick and was transferred to their Burravoe branch. While in Yell, he branched out into his own business trading under Manson & Co. After selling his business, and just before the outbreak of WWI, he purchased the Royal Hotel in Lerwick and ran it for several years. He gave up the hotel after the war and returned to Yell.',NULL,NULL,'I19349','Thomas_Manson_(i)','["Zetland County Councillors", "1885 Births", "1940 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(473,'Thomas Manson (ii)','thomas-manson-ii','1904-02-09','1996-01-23','Hillhead','Lerwick','Dr. Thomas Mortimer Yule ''Mortie'' Manson was an author, editor, scholar and Shetland Islands Councillor. His father Thomas Manson, publisher and author, his mother Margaret Elizabeth Lillias (neé Crutwell), . ''Mortie'' was the fifth of five children and was musical like his father. He worked in T &amp; J Manson, eventually editing the Shetland News until the firm''s demise. In retirement he was a very popular member on Shetland Islands Council and active in public life generally. As ''T. M. Y. Manson'', he was author of scholarly articles and popular works alike. Manson organised the first Viking Congress in Lerwick in 1950. In recognition of his achievement Aberdeen University gave him the degree of doctor of laws. He received a tribute volume on his 80th birthday: Essays in Shetland history : heiđursrit to T.M.Y. Manson, edited by Barbara Crawford, 1984. Tom died on the 23rd of January, 1996 at the Viewforth Eventide Home, Lerwick, and is buried in Knab Road Cemetery. His great grandfather, [person:gilbert-tait:Gilbert Tait], was a Lerwick Town Councillor for 25 years.',NULL,'TMY Manson.png',NULL,'I18281','Thomas_Manson_(ii)','["Shetland Islands Councillors", "Writers", "Natives of Shetland", "1904 Births", "1996 Deaths"]',1,1,163057266);
INSERT INTO "people" VALUES(474,'Thomas Nicolson','thomas-nicolson','1793-11-16','1865-12-15','Kirkwall','Blythswood, Glasgow','Thomas Balfour Nicolson was a Customs Officer as a Lerwick Town Councillor.',NULL,NULL,NULL,'I404765','Thomas_Nicolson','["Lerwick Town Councillors", "1793 Births", "1865 Death", "Nicolson", "Orcadians", "Biography Missing"]',0,0,NULL);
INSERT INTO "people" VALUES(475,'Thomas Sandison','thomas-sandison','1855-05-07','1930-06-09','Lerwick','Unst','Thomas Johnson Sandison son of [person:alexander-sandison:Alexander Sandison] was a County Councillor for Unst South between 1898 and 1901 and Yell North between 1906 and 1907, before finally returning to Unst South, serving from 1907 until 1910. His dad [person:alexander-sandison:Alexander Sandison] and brother [person:john-sandison:John] was were both councillors.','Thomas joined his father''s business at a young age and spent his career there. He was a church Elder and a member of the School Board. When he died he left an estate valued £9,350, worth about £515k in 2024.','ThomaSandison.png',NULL,'I16460','Thomas_Sandison','["Zetland County Councillors", "1855 Births", "1930 Deaths", "Councillors pictured"]',1,1,182190864);
INSERT INTO "people" VALUES(476,'Thomas Sinclair','thomas-sinclair','1899-07-12','1982-01-12','Lerwick','Lerwick','Thomas Arthur Sinclair was the Lerwick postie and a Town Councillor, initially between 1936 to 1938, then later following the death of [person:william-smith-iii:William G. Smith], he was elected in 1942 until 1945. He later served from May to November in 1946.','Thomas was for some time in the 1930''s the vice-president of the Lerwick Workmen''s Club, and President from November 1935 and by 1942 was secretary of the same club. In later years he was an avid writer of letters to the Shetland Times. He stood for and was elected under the Labour Party banner.',NULL,NULL,'I31689','Thomas_Sinclair','["Lerwick Town Councillors", "1889 Births", "1982 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(477,'Thomas Stove','thomas-stove','1935-07-17',NULL,'Wart',NULL,'Thomas William Stove is a former Zetland County Councillor and Shetland Islands Councillor for Sandwick.',NULL,NULL,'Tom Stove Headshot.png','I35658','Thomas_Stove','["Zetland County Councillors", "Shetland Islands Councillors", "1935 Births", "Biography Missing"]',1,NULL,NULL);
INSERT INTO "people" VALUES(478,'Tom Henderson','tom-henderson','1911-06-29','1982-10-15','Dunrossness',NULL,'Thomas ''Tom'' Henderson, was the first curator of the Shetland Museum, holding the position from 1964 to 1978.','In the early part of his life he had been at sea in the Merchant Navy. During the war he was wounded, and while recuperating he read voraciously and began to write. He became a respected author and story-teller. His work was published in both local and national magazines, and what is probably his best known work, ''The Night that Mouat was Lost'', a short story about the Tragedy at Spiggie 1887 appeared in the New Shetlander and eventually in the anthology ''Nordern Lichts''. His family were partners in the business of R &amp; T Henderson of Whillygarth, Scousburgh, and Tom inherited croft land, which included Spiggie Loch, the island of Colsay, and the small ''Henderson''s Hotel'' (now Spiggie Lodge), which he operated for a number of years in partnership with his wife. He was co-opted on to the Zetland County Council in 1952 to fill the vacancy created by the departure of [person:robert-bruce:Robert Bruce], a seat he held for the next 11 years. The final three, from 1960-63, were also as Convener of the County. He served at one time or another on numerous public committees, including the Board of Management of Shetland Hospitals, Lerwick Harbour Trust (now Lerwick Port Authority), the Fishermen''s Mission (R.N.M.D.S.F), and the Shetland Folk Society. He was also a founder member of both the Shetland Group and the Shetland Movement. Around 1970 he sold most of his property at Scousburgh, only retaining Colsay, and purchased the the Old Manse at 9 Commercial Street, Lerwick, which, dating from the late 1600s, is generally believed to be the oldest inhabited house in Lerwick. In 1977 he was made a Fellow of the Society of Antiquaries of Scotland, and was awarded the M.B.E. As curator he wrote the introduction and captions to the book Shetland From Old Photographs. Henderson was an internationally respected expert on Shetland''s maritime history, and in the 1940s planned a work on Shetland shipwrecks with R. Stuart Bruce, never completed. His essay ''Shipwreck and underwater archaeology in Shetland'' appears in B Smith ed., Shetland Archaeology (1985).','Kennemerland pipe - Shetland Museum and Archives SL04291.jpg',NULL,'I97945','Tom_Henderson','["Zetland County Council Conveners", "Zetland County Councillors", "1911 Births", "1982 Deaths"]',1,NULL,NULL);
INSERT INTO "people" VALUES(479,'Vaila Wishart','vaila-wishart','1949-06-11',NULL,'Lerwick',NULL,'Vaila Wishart is a Shetland Islands Councillor, representing Shetland Central since 2012.','Vaila spent much of her professional career as a journalist. She worked at Radio Shetland and was the editor of the Shetland Times for 14 years.',NULL,NULL,'I29961','Vaila_Wishart','["Shetland Islands Councillors", "Natives of Shetland", "1949 Births", "Female"]',1,NULL,NULL);
INSERT INTO "people" VALUES(480,'Westwood Hay','westwood-hay','1871-10-07','1946-09-03','Bombay','Torquay','Colonel Westwood Norman Hay CIE was a County Councillor for Tingwall between 1938 and 1945.','He served in the Indian Staff Corps, and on August 4 1893 he was promoted to 2nd Lieutenant in that force. He saw active service in China in 1900, East AFrica in 1917-18, Afghanistan in 1919, India and Pakistan 1919-21. He retired in 1923. He received a CIE in the 1917 New Years Honours. Westwood was a member of the Bedford Town Council from Feb 1925 until Oct 1932, and again from 1933 to 1935. He inherited Hayfield Estate after the death of Elizabeth Hay in March 1937. In WWII he was appointed as chairman of the Shetland Territorial Force Association. When Hayfield was requisitioned for use in the war, he moved to Torquay.',NULL,NULL,'I6339','Westwood_Hay','["Zetland County Councillors", "1871 Births", "1946 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(481,'William Adie','william-adie','1839-04-02','1903-06-01','Voe','Voe, Delting','William Jamieson Adie was merchant, fishcurer and a County Councillor for Delting South from 1899 until his deteriorating health led him to step down in February 1903. His son, [person:james-adie:James], took up the vacant seat.','William was tutored at home by Sandsting minister William Rose, and later joined his father''s business (merchant/fishcuring) which was one of the largest in Shetland at the time. At the time of his joining, the main fish was cod and ling. Over time, herring emerged as the primary fish - "King Herring" as the Shetland Times named it. William was a staunch advocate for the established church, and had "little interest" in politics but was of Conservative persuasion.',NULL,NULL,'I9136','William_Adie','["Zetland County Councillors", "1833 Births", "1903 Deaths"]',1,1,179138031);
INSERT INTO "people" VALUES(482,'William Anderson (i)','william-anderson-i','1890-08-13','1962-11-02','Hillswick','Lerwick','William Slater Anderson was a joiner and a Lerwick Town Councillor between 1937 and 1952. According to his obituary in the Shetland Times, he was an active member of the Kirk.','William started working as a joiner in Lerwick in 1908 with Messrs Williamson & Dalziel, and remained in that profession his entire career. He was as Gordon Highlanders in WWI and was wounded near Arras in 1916. He later transferred to the Royal Flying Corps and returned to France as a mechanic. During the WWII he was with the Gordons Home Defence Company.',NULL,NULL,'I140826','William_Anderson_(i)','["Lerwick Town Councillors", "1890 Births", "1962 Deaths"]',1,1,175858384);
INSERT INTO "people" VALUES(483,'William Anderson (ii)','william-anderson-ii','1919-12-22','2003-08-08',NULL,'Lerwick','Major William Archibald ''Bill'' Anderson was a schoolmaster and Shetland Islands Councillor for Scalloway between 1982 and 1994. His wife, Patricia, was the daughter of [person:james-smith-i:James A. Smith].',NULL,NULL,NULL,'I20284','William_Anderson_(ii)','["Shetland Islands Councillors", "1919 Births", "2003 Deaths"]',NULL,1,NULL);
INSERT INTO "people" VALUES(484,'William Angus','william-angus','1779-12-03','1848','Firth',NULL,'William Angus was a merchant and Town Councillor between 1818 and 1826.',NULL,NULL,NULL,'I50335','William_Angus','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Death Date", "1779 Births", "1848 Deaths", "Natives of Shetland", "Merchants", "Angus"]',1,NULL,NULL);
INSERT INTO "people" VALUES(485,'William Bruce (i)','william-bruce-i','1863-09-23','1944-01-18','Lerwick','Lerwick','William Arthur Bruce was a laird and County Councillor for Whalsay And Skerries between 1890 and 1904','William''s father Robert was the Laird of Whalsay, and the family descended from William Bruce, who became the landowner in the 16th century. Robert died when William was just ten, and too young to immediately take over as laird. William instead went to be educated at the Merchiston and Loretto schools in Edinburgh, and studied at Edinburgh University. Upon completion of his studies, aged 21, he took over management of the estate. At that time, it was one of the largest single estates in the isles, comprising of Whalsay, Skerries and parts of Nesting, Bigton and Fladdabister.',NULL,NULL,'I9244','William_Bruce_(i)','["Zetland County Councillors", "1863 Births", "1944 Deaths"]',1,1,181925184);
INSERT INTO "people" VALUES(486,'William Bruce (ii)','william-bruce-ii','1882-03-14','1943-01-18','Whalsay','Lerwick','William Bruce was a ship carpenter and Lerwick Town Councilor.','At the age of 14, William became an apprentice with Robertson and Sinclair, carpenters at Garthspool. After serving his time with them, he began working with [person:john-robertson-iv:John W. Robertson], who at that time was the owner of the Malakoff Slipway. He reached the rank of Foreman and continued to hold that position when Malakoff were acquired by Innes Smith in 1928. He was a member of the Labour Party in Shetland.',NULL,NULL,'I34310','William_Bruce_(ii)','["Lerwick Town Councillors", "1882 Births", "1943 Deaths"]',1,1,291529387);
INSERT INTO "people" VALUES(487,'William Carson','william-carson','1890-12-14','1937-09-11','Auldearn','Earl of Zetland','Reverend William Graham Carson was the minister for Fetlar and a County Councillor for the same area from 1932 until his death in 1937.','William trained as an educator and became the sole teacher in Olnafirth school in 1911. In 1914, he was appointed as assistant teacher in Lerwick Central School and remained there until 1916 when he left teaching to enter the ministry with the Church of Scotland. He attended Glasgow University and graduated in 1922 wherein he was called to the Fetlar Parish, a position he held until his death aboard the Earl of Zetland.',NULL,NULL,'I348727','William_Carson','["Zetland County Councillors", "Councillors - Clergymen", "1891 Births", "1937 Deaths"]',0,1,NULL);
INSERT INTO "people" VALUES(488,'William Clark (i)','william-clark-i','1782','1854-03-27','Unst','Lerwick','William Alexander Clark was a grocer, spirit dealer and Lerwick Town Councillor.',NULL,NULL,NULL,'I11947','William_Clark_(i)','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1782 Births", "1854 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(489,'William Clark (ii)','william-clark-ii','1865-05-21','1948-08-06','Uyeasound','Hillsgarth','William Fordyce Clark was a Shetland author and County Councillor. Clark represented Unst South between 1936 and 1938.','William was educated in Unst before joining [person:alexander-sandison:Alexander Sandison] & Sons at Baltasound. He left for Edinburgh aged 24 to work in insurancem, first as a correspondence clerk and latterly as Managing Director of the Scottish National Key Registry and Assurance Association Ltd. He had a keen interest in writing, and his first public venture into journalism was a report of a lively election meeting in Unst in 1886, in Boys'' Own Paper. After retiring in Edinburgh in 1934, he returned to Unst.','WFClark1.jpg',NULL,'I11261','William_Clark_(ii)','["Zetland County Councillors", "Writers", "1865 Births", "1948 Deaths"]',1,1,182022107);
INSERT INTO "people" VALUES(490,'William Collie','william-collie','1909-03-24','1960','107 John Street',NULL,'William Bain Collie was a County Councillor for Bressay from 1945 until 1949, representing the Labour Party.','William spent his life working at sea and succeeded [person:prophet-smith:Prophet Smith] as Chairman of the Seaman''s Union in Shetland in January 1945. He held that post until it shut down in around 1950. He and his wife moved to Aberdeen. The Shetland Archives has a copy of the manifesto he used during his 1945 campaign, and also two articles written by him in the only two editions of The Shetland Monthly ever published, entitled Trades Unionism in Shetland and Trade Union Affairs.',NULL,NULL,NULL,'William_Collie','["Zetland County Councillors", "Councillors - Missing B/D", "Labour", "1909 Births", "1960 Deaths"]',1,NULL,NULL);
INSERT INTO "people" VALUES(491,'William Conochie','william-conochie','1898-11-25','1969-10-12','Kilmacolm','Lerwick','William Kenneth Conochie was a stationer who founded the Conochies shop on Commercial Street, which is still open today. He was also a Lerwick Town Councillor between 1949 and 1963.','William arrived in Shetland in 1922 to take over the business of [person:george-anderson:George Anderson] in Commercial Street. He continued to grow the business, retiring in 1967. Between wars, William wat a member of the British Legion and a pipe major in the band. He was a reserve officer and was called up during WWII, and spent time with the Shetland Defence Battalion, the Royal Army Service Corps in Orkney, Inverness and latterly the Highland Division. He became only the second non Shetland-born person to become Provost when he was elected into that role in 1956.','William Conochie Provost.png','William Conochie Headshot.png','I103586','William_Conochie','["Lerwick Town Councillors", "1898 Births", "1969 Deaths", "Councillors pictured"]',0,1,216659999);
INSERT INTO "people" VALUES(492,'William Copland','william-copland','1789-02-23','1866-07-02','St Ola','Orkney','William Copland was a merchant and Lerwick Town Councillor.',NULL,NULL,NULL,'I324138','William_Copland','["Lerwick Town Councillors", "1789 Births", "1866 Deaths", "Orcadians"]',0,0,NULL);
INSERT INTO "people" VALUES(493,'William Craigie','william-craigie',NULL,'1712',NULL,NULL,'William Craigie (d. 1712) was a member of the Parliament of Scotland for Orkney and Shetland first in 1681, then again 1689-1690, 1696-1701. He was Knighted in 1690 by King William III. He was the Stewart Principle and tacksman of Earldom estates 1686-1691 also farmed Bishopric rents. His eldest son was killed at the Battle of Blenheim in 1704. The family lost much of its importance falling on evil days financially when trade slumped due to a series of bad harvests at the end of the 17th century. He was jailed for debt to Sir Archibald Steuart of Burray in 1703.',NULL,NULL,NULL,NULL,'William_Craigie','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(494,'William Cumming','william-cumming','1920-10-16','2004-12-28','Hamnavoe','Lerwick','William Albert Cumming was a builder, County Councillor and Shetland Islands Councillor.',NULL,NULL,NULL,'I34348','William_Cumming','["Zetland County Councillors", "Shetland Islands Councillors", "1920 Births", "2004 Deaths", "Biography Missing"]',1,1,120393449);
INSERT INTO "people" VALUES(495,'William Douglas','william-douglas',NULL,NULL,NULL,NULL,'William Douglas of Egilsay, Orkney (c. 17th Century) was a Burgh commissioner for Shetland in 1667. He was the father of Orkney and Shetland''s first MP in the unified Parliament, [person:alexander-douglas:Alexander Douglas]. Egilsay Community Association list on their history page that: ''As part of the Bishopric estate the whole of Egilsay was feued to the Monteith family in the 16th Century. On the marriage of Marjorie Monteith to William Douglas, Chamberlain of Orkney, commemorated in the initialled skewputt, the island passed to the Douglas family.'' There remains the Douglas house on Egilsay, named Howan House, and the Buildings At Risk register notes the following:
&quot;The skewputt to the north east is initialled WD MM for William Douglas and his wife Marjorie Monteith, 17th century owners and heirs to the Island of Egilsay. The interior of the house retains a carved lintel on the south wall inscribed 16.AMICUS.ET.GENO.81., decorated with a heart and fleur-de-lis transforming into roses and thistles. A badly weathered stone fireplace with fluted jambs sits in the west gable&quot; Category:Burgh and Shire Commissioners to the Parliament of Scotland',NULL,NULL,NULL,NULL,'William_Douglas','["Burgh and Shire Commissioners to the Parliament of Scotland"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(496,'William Duncan (i)','william-duncan-i','1820','1897-05-19','Noness, Sandwick','Bournemouth','William Duncan was a grocer, general merchant and Lerwick Town Councillor. Duncan had many sporadic stints in the council, first from 1874 to 1876, then when the council had a vacancy to fill in 1880 he was a councillor until 1884. Again, the council turned to Duncan due to a vacancy after the 1884 election, and he then served until he tendered his resignation on July 12th (which was finally accepted by the council on October 15th).',NULL,'WilliamDuncan.png',NULL,'I16491','William_Duncan_(i)','["Lerwick Town Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "Councillors pictured", "1820 Births", "1897 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(497,'William Duncan (ii)','william-duncan-ii','1858-02-18','1945-06-21','Lerwick',NULL,'William Rae Duncan was a merchant in Scalloway and a County Councillor for Tingwall between 1901 and 1909. His grandfather [person:andrew-duncan:Andrew] was Sheriff-Substitute for Shetland, and his uncle [person:andrew-duncan-ii:Andrew] a Lerwick Town Councillor.',NULL,NULL,NULL,'I10539','William_Duncan_(ii)','["Zetland County Councillors", "1858 Births", "1945 Deaths"]',1,NULL,196135758);
INSERT INTO "people" VALUES(498,'William Fotheringham','william-fotheringham','1873-09-10','1926-04-09','Forfar','Deaconess Hospital, Edinburgh','Reverend William Fotheringham was appointed Minister of Dunrossness Baptist Church in 1901, a post he held until 1917 when he transferred to become Minister of Lerwick Baptist Church.','Shortly after his appointment in 1901 he was elected on to the Dunrossness School Board, and in 1912 was both architect and administrator of building the new Dunrossness Baptist Church. He joined the Zetland County Council in 1907 filling the seat vacated by the death of [person:john-bruce:John Bruce], which he held until 1919. During his time on the Council he became Chairman of the County Roads Committee, Chairman of the Mainland District Committee and Vice-Convener of the County. During his period at Lerwick Baptist Church he became a member of the newly formed Council Education Committee, a governor of the Anderson Educational Institute and Padre to the seaplane base at Cat Firth, Nesting. He had a keen interest and understanding of medical matters, and in particular the care and treatment of T.B. In 1919, on behalf of the Trustees of the Old Gilbert Bain Hospital he personally purchased and installed an X-Ray machine and other electrical equipment, and was for a time honorary radiographer. He was also a keen naturalist, and wrote Nature Notes in the Shetland News newspaper in 1921 under the pen-name Zoe. Outside of Shetland, he was the minister of the Pathhead Baptist Church in Kirkauldy from August 1924 to March 1926.',NULL,NULL,'I441499','William_Fotheringham','["Zetland County Councillors", "Councillors - Clergymen", "1873 Births", "1926 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(499,'William Fox','william-fox','1954-02-01',NULL,'Lerwick',NULL,'William ''Billy'' Fox is a Shetland Islands Councillor, representing Shetland Central since 2012. He was also an Independent candidate for the 2011 Scottish Parliament election.','In his early career, Billy worked in the building trade as well as the Nature Conservancy Council and some years off at the fishing. After that, he worked for 22 years for BP at Sullom Voe, first as a jetty operator and ending as a Shift Team Leader. He founded the environmental anti-Viking Energy windfarm pressure group Sustainable Shetland, which grew to over 800 members under his leadership. He challenged incumbent [person:tavish-scott:Tavish Scott] at the 2011 Scottish Parliament election and achieved a respectable 30% of the vote - the highest of any independent candidate on the Constituency ballot.',NULL,NULL,'I38321','William_Fox','["Shetland Islands Councillors", "Natives of Shetland", "1954 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(500,'William Glover','william-glover','1851','1909-09-26','Paisley','Whitburn United Free Manse, West Lothian','Reverend William Henry Glover was a minister and County Councillor for Fetlar between 1893 and 1895.','William studied at and graduated from the University of Glasgow. He was appointed to the Unst Uyeasound United Free Church on 20 September 1888, serving until 1904. He then moved to Whitburn United Free Church.',NULL,NULL,'I277481','William_Glover','["Zetland County Councillors", "Councillors - Clergymen", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1851 Births", "1909 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(501,'William Greig','william-greig','1857-12-18','1919-12-23','Unst','Lerwick','William James Greig was a house painter, hairdresser and County Councillor for Lerwick North in 1919. His tenure as a councillor lasted only three weeks, as he died on 23 December.','William came to Lerwick aged 9 where he attended a parish school, and later the Anderson Educational Institute. After leaving work, he began working as a painter with a John Stopani, before heading to Edinburgh where he continued to develop his trade for some years. Upon his return to Shetland, he opened his own painting business, and later opened a hairdresser on Montyhooly Street. The latter business eventually was moved to Charlotte Street, where he worked for 30 years.',NULL,NULL,'I26112','William_Greig','["Zetland County Councillors", "1857 Births", "1919 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(502,'William Hamilton','william-hamilton','1905-12-01','1997-11-25',NULL,'Aberdeen','William Robert Thomas ''Bob'' Hamilton was a County Councillor for Nesting between 1955 and 1973. His father, [person:zachary-hamilton:Zachary] was a County Councillor for Yell North from 1890 until his death in 1905, just 21 days after William''s birth.','William spent a large part of his youth out of Shetland, at the Edinburgh Academy, at a boarding school in England and at the University of Edinburgh. In 1929, he sailed to New Zealand where he farmed sheep during the depression. In WWII, he volunteered for the New Zealand Army and saw action in the North African Campaign. He was captured in 1942 and became a prisoner of war in Germany. Despite several escape attempts, he saw out the rest of the war in captivity. After the war, he settled in Shetland and became a partner in the Adie business in Voe (his mother was the daughter of [person:william-adie:William Adie]).',NULL,NULL,'I68187','William_Hamilton','["Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Location", "1905 Births", "1997 Deaths"]',NULL,0,289470593);
INSERT INTO "people" VALUES(503,'William Hay','william-hay','1787-10-08','1858-05-28','Lerwick','Lerwick','William Hay of Hayfield was a trader, farmer and Lerwick Town Councillor. He was married three times and fathered 16 children across the first two. His 12th and 15th children, [person:george-hay:George] and [person:arthur-hay:Arthur] were both. Lerwick Town Councillors. Quote from Bayanne: &quot;He built the Docks at Freefield, did much for the prosecution of the fisheries, improvement of agriculture and construction of roads throughout the county.&quot; He was married to Margaret Ogilvy, daughter of [person:charles-ogilvy-i:Charles] and brother of [person:charles-ogilvy-ii:Charles], both councillors. His short obituary in the Orcadian described him as "the most enterprising man in these islands and oldest merchant".',NULL,NULL,NULL,'I6253','William_Hay','["Lerwick Town Councillors", "Natives of Shetland", "1787 Births", "1858 Deaths", "Farmer", "Hay"]',1,1,175653514);
INSERT INTO "people" VALUES(504,'William Henry','william-henry','1878-05-25','1965-12-01','Sandsting','Sandsting','William Henry was a motor hirer and County Councillor for Sandsting between 1938 and 1945.',NULL,NULL,NULL,'I53647','William_Henry','["Zetland County Councillors", "1878 Births", "1965 Deaths", "Biography Missing"]',1,1,179949271);
INSERT INTO "people" VALUES(505,'William Jamieson','william-jamieson','1871-06-13','1937-01-21','Sandwick','Sandwick','William Jamieson was a merchant and County Councillor for Sandwick between 1919 and 1932.','William left school aged 14 and joined his brother George in Edinburgh. William first worked there in a grocery business, and the brothers started their own in Lawn Market in that city. Shortly thereafter, they opened a shop in Sandwick named G. R. & W. Jamieson, calling it Central Stores. William, despite only being young, came up to manage the shop and did so for the next 50 years. Additionally to their grocery business, they expanded into fishcuring for both white fish and herring. Both were discontinued by 1920. William was an early advocate of the poultry industry in Shetland.',NULL,NULL,'I104567','William_Jamieson','["Zetland County Councillors", "Natives of Shetland", "1871 Births", "1937 Deaths", "Councillors pictured"]',1,1,NULL);
INSERT INTO "people" VALUES(506,'William Leslie','william-leslie','1878','1937-07-19','Sumburgh','Boddam, Dunrossness','William Leslie was a merchant, sub-postmaster and County Councillor for Dunrossness South between 1922 and 1929.','William operated as the Registrar Officer in Dunrossness and a Justice Of The Peace.',NULL,NULL,'I188622','William_Leslie','["Zetland County Councillors", "1878 Births", "1937 Deaths", "Biography Missing"]',1,1,NULL);
INSERT INTO "people" VALUES(507,'William Levie','william-levie','1831-08-30','1901-01-27','Aberdeen',NULL,'Reverend William Levie was the Minister of Nesting and a County Councillor for Nesting between 1892 and 1895.','Levie studied Divinity at the University of Aberdeen. His first experience of Shetland was in a teaching role Yell, during a vacation from University. Following his graduation, he returned to Shetland as an assistant minister in Sandwick. He served here until Reverend Shand, minister for Nesting, passed away, and Levie took up the post. Levie had heart troubles in his later age, and spent the last five months of his life in confined to his bed.',NULL,NULL,'I8153','William_Levie','["Zetland County Councillors", "Councillors - Clergymen", "1831 Births", "1901 Deaths"]',0,NULL,175853548);
INSERT INTO "people" VALUES(508,'William MacDougall','william-macdougall','1856','1931','Melrose, Roxburghshire',NULL,'William MacDougall was an Agent for the Commercial Bank Lerwick Town Councillor from 1910 until he resigned in April 1912.','William arrived in Shetland in 1907, succeeding [person:charles-laurenson:Charles Laurenson] who had been appointed Agent at the Chief Office in Greenock. William was in post until 1920. In the early 1900''s he was the Chair of the Eyemouth Parish Council.',NULL,NULL,NULL,'William_MacDougall','["Lerwick Town Councillors", "1856 Births", "1931 Deaths", "Councillors - Missing Birth Date\u200f\u200e", "Councillors - Missing Birth Location\u200f\u200e", "Councillors - Missing Death Date\u200f\u200e", "Councillors - Missing Death Location"]',0,NULL,NULL);
INSERT INTO "people" VALUES(509,'William Manson','william-manson','1943-05-15',NULL,'Kilwinning',NULL,'William Henry ''Bill'' Manson is a former Shetland Islands Councillor, most recently representing Shetland North from 2007 to 2012. He is a former chairman of Viking Energy.','Manson, when he was first elected in 1991, worked as a services superintendent at Sullom Voe.',NULL,NULL,'I115578','William_Manson','["Shetland Islands Councillors", "Natives of Shetland", "1943 Births"]',0,NULL,NULL);
INSERT INTO "people" VALUES(510,'William Marshall','william-marshall','1924-04-12','1995-08-18','Huddersfield','Bathgate, West Lothian','Reverend William Marshall was a Church of Scotland minister for the parish of Delting and a County Councillor for Delting North between 1961 and 1963. He was transferred from Inch to Delting on 27 October 1960 and resigned his position on 31 Jul 1963.',NULL,NULL,NULL,NULL,'William_Marshall','["Zetland County Councillors", "Councillors - Clergymen", "1924 Births", "1995 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(511,'William McDougall','william-mcdougall','1878','1937-02-24','St Mungo, Dumfriesshire','Peebles','William Laidlaw McDougall was a native of Dumfriesshire who moved to Dunrossness in 1907 to become factor to [person:john-bruce:John Bruce] of the Bruce of Sumburgh family. He first was elected to the Lerwick Town Council in 1910, later failing to get on to the Zetland County Council for Nesting. In 1913, he was elected to represent Northmavine North. After this he represented Dunrossness South from 1919 until 1922, then again from 1929 until his death in 1937.','After completing his education, William entered the legal profession in Dumfriesshire with a firm that had links to the Jardine estate. Later, he had further legal training in Edinburgh and it was while there that he was appointed by Robert Bruce to be the factory of the Sumburgh estate in 1907. Robert had inherited Sumburgh after the death of [person:john-bruce:John Bruce] in 1907, but he did not want to live in Shetland, and so he formed the Sumburgh Company Ltd company and hired William to run the company after [person:robert-isbister:Robert Isbister] died. In 1910, he was appointed a Justice of the Peace. A contribution to the Shetland Times explains more about William''s background.','W Laidlaw McDougall.png','W Laidlaw headshot.png','I264602','William_McDougall','["Lerwick Town Councillors", "Zetland County Council Conveners", "Zetland County Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1878 Births", "1937 Deaths", "Councillors pictured"]',0,0,179138346);
INSERT INTO "people" VALUES(512,'William Merrylees','william-merrylees','1795-04-04','1859-06-06','East Linton','Lerwick','William Merrylees was an agent for Aberdeen Leith and Lerwick Shipping Company, Session Clerk Parish of Lerwick, teacher of music and Lerwick Town Councillor.','William Merrylees was born at East Linton in Scotland and married into the Mouat family of North Hamarsland, Shetland. He was once a cattle dealer and grocer in the premises that was occupied by Anderson and Goodlad (solicitors in Lerwick). He was an Agent for the Shipping Company in Lerwick until the time of his death and was succeeded by Mr John Robertson. William is listed in the Shetland Directory for 1854 as follows: Merrylees, William, agent for the Aberdeen Leith and Clyde Shipping Company-agent for the Northern Assurance Company,and session-clerk of Lerwick, dwelling house Twageos; office 20 Commercial Street. He was endowed with musical talent and trained under Mr Glass who did so much to encourage a love of music in the town before his comparatively early death. Mr Merrylees carried on the tradition, becoming leader of the music performed at the Parish Church. There was a large family: William who had married in America and Sarah who also went there; Euphemia born in 1831, the wife of John Anderson, merchant in Hillswick; Christina, died on 17th November 1896, having married Rev.Alexander Reid, Lerwick minister; John, in America, married to Martha Barr of Buffalo; another daughter who was unmarried ran a private school in Mounthooly Street; Charles was joint agent of the Shipping Company with Baillie Robertson. The office and the lodberry or store was at 16 Commercial Street. The goods were taken ashore in flit boats. Carts conveyed goods to Scalloway and thence to west side ports. At that time the male population was mainly engaged in the seal and whale fishing besides white fishing in home waters. The Post Office was the small shop opposite the Queen''s Hotel, the road system was poor and mails were conveyed by carriers who walked with the load strapped to their backs. Communication with the North isles was by sailing craft, all of which gradually improved. His son, [person:charles-merrylees:Charles] was also a Lerwick Town Councillor, and his grandson, [person:thomas-anderson-i:Thomas Anderson] was a County Councillor.',NULL,NULL,'I40214','William_Merrylees','["Lerwick Town Councillors", "1795 Births", "1859 Deaths"]',0,1,176070770);
INSERT INTO "people" VALUES(513,'William Peterson','william-peterson','1923-11-22','1994-07-17',NULL,NULL,'William ''Willie'' Peterson was an auctioneer, a Lerwick Town Councillor and a Shetland Islands Councillor for Lerwick Sound between 1974 and 1976. He was for many years auctioneer at the old Shetland Marts on the South Road (Site now Tesco''s Supermarket).','Willie was educated in Lerwick, and upon leaving school he found work as an apprentice panel beater. The outbreak of WWII saw him work in a slaughterhouse. He was said to have been called up three times for service, but each time he was taken off the boat to continue his work at the slaughterhouse. He received discharge papers despite not actually having served in the army, a rare occurence. Willie joined the Shetland Marts in 1946 as a trainee auctioneer. He branched out on his own in 1951 for two years, until the Marts bought his business and installed him as a director of the new firm. He effectively ran the Shetland Marts from then on, becoming Managing Director and latterly Chairman. He was the 1970 Guizer Jarl for the Lerwick Up Helly-Aa, and represented ''Einar Thambarskelver''.',NULL,NULL,'I37111','William_Peterson','["Lerwick Town Councillors", "Shetland Islands Councillors", "1923 Births", "1994 Deaths"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(514,'William Playfair','william-playfair','1926','1999-11-16',NULL,NULL,'William ''Bill'' Playfair was a quantity surveyor and a Shetland Islands Councillor for Unst between 1978 and 1982. He was also the vice-chair of the Shetland Conservative Association.',NULL,NULL,NULL,'I107273','William_Playfair','["Shetland Islands Councillors", "Councillors - Missing B/D", "Councillors - Missing Birth Date", "1999 Deaths", "Conservatives"]',NULL,NULL,NULL);
INSERT INTO "people" VALUES(515,'William Pole','william-pole','1839-12-19','1921-07-30','North Yell','Mossbank, Delting','William Pole was a general merchant and a County Councillor for Delting North between 1904 and 1907. His youngest child, [person:joseph-pole:Joseph], was also a county councillor for the same area between 1922 and 1945. William Pole unsuccessfully stood in the inaugural Zetland County Council election in 1890.','William worked with Captain Craigie in the laying of roads in Shetland, and he was involved in the first ever Valuation Roll of Shetland. Later, he joined the Union Bank, before joining his father''s firm in Greenbank, Yell. In 1864, he moved to Mossbank and joined the business of James Hoseason. When James died, Robert Hoseason returned from Australia and with William they formed Pole, Hoseason and Co. Eventually, one of his sons took over when William retired.','WilliamPole.png',NULL,'I8118','William_Pole','["Zetland County Councillors", "Councillors pictured", "1839 Births", "1921 Deaths"]',1,1,175853432);
INSERT INTO "people" VALUES(516,'William Ratter','william-ratter','1952-03-25',NULL,'Lerwick',NULL,'William Andrew ''Drew'' Ratter is a Shetland Islands Councillor first for Delting West from 1994 until 2007 then Shetland North since 2012.',NULL,NULL,NULL,'I115062','William_Ratter','["Shetland Islands Councillors", "Natives of Shetland", "1952 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(517,'William Robb','william-robb','1940-09-18','2005-06-14','Elderslie','Troon, Ayrshire','Reverend William Clement Robb was a minister for the Church of Scotland and a County Councillor for Delting South between 1970 and 1975.','He was a Church of Scotland minister for Delting and was ordained on 17 June 1968, retiring on 31 October 1976. He later became a minister at Glasgow''s Househillwood St Christopher''s on the 25 March 1981. In 1994, he was jailed for seven years for sexual offences against young boys. He was released in 1998.',NULL,NULL,NULL,'William_Robb','["Zetland County Councillors", "Councillors - Clergymen", "1940 Births", "2005 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(518,'William Robertson','william-robertson','1828-11-10','1883-10-22','Lerwick','Lerwick','William Robertson was a grocer and a Lerwick Town Councillor.',NULL,NULL,NULL,'I88961','William_Robertson','["Lerwick Town Councillors", "1828 Births", "1883 Deaths"]',1,1,291860939);
INSERT INTO "people" VALUES(519,'William Shand','william-shand','1843-02-26','1929-12-06','Old Machar','Lerwick','William Murdoch Shand was a shipping agent and County Councillor for Gulberwick between 1901 and 1910, and later Sandwick between 1911 and 1913.','William was the son of a miller and grain merchant, and worked for some time in the Aberdeen offices of the North of Scotland and Orkney and Shetland Steam Navigation Company, reaching the position of cashier. He was appointed as agent for the firm in Lerwick in 1878, succeeding [person:charles-merrylees:Charles Merrylees], who moved to the Aberdeen branch to be a Manager. William continued as Agent until he retired in 1906 and was succeeded by [person:william-merrylees:William Merrylees]. He was a Director of the Lerwick Gaslight Company.',NULL,NULL,'I197411','William_Shand','["Zetland County Councillors", "1843 Births", "1929 Deaths", "Incomers to Shetland"]',0,1,NULL);
INSERT INTO "people" VALUES(520,'William Sievwright (i)','william-sievwright-i','1791-10-06','1870-06-26','Nesting',NULL,'William Sievwright was a writer, councillor and procurator in the Sheriff Court of Zetland and Notary Public. Sievwright''s political career as a Lerwick Town Councillor was lengthy, stretching 27 years, with the last 9 being as the Senior Baillie. His son, [person:william-sievwright-ii:William], was also a councillor. Sievwright, and his son played significant roles in the growth of Lerwick, being a Feuror and Heritor.',NULL,NULL,NULL,'I3500','William_Sievwright_(i)','["Lerwick Town Councillors", "1791 Births", "1870 Deaths"]',1,NULL,175653712);
INSERT INTO "people" VALUES(521,'William Sievwright (ii)','william-sievwright-ii','1838-04-05','1909-04-20','Lerwick','Gisbourne, New Zealand','William Sievwright was a Lerwick Town Councillor and was the son of procurator fiscal, town councillor, and writer William. Sievwright Jr was a lawyer at the legal firm Sievwright and Stout. His first marriage was to Margaret Neven-Spence, to whom he had two children. He later remarried (1878) and had two children to Margaret Home Richardson, a teacher and nurse. She is also listed as being a feminist, political activist, community leader. She met William in New Zealand and they married on 29 November 1878 in Wellington. She is noted as playing a role in helping empower women in New Zealand. Teara.govt.nz have a biography which can be read here.',NULL,'William Sievwright.gif',NULL,'I4317','William_Sievwright_(ii)','["Lerwick Town Councillors", "1838 Births", "1909 Deaths", "Councillors pictured"]',1,0,NULL);
INSERT INTO "people" VALUES(522,'William Sinclair','william-sinclair','1876-09-26','1945-05-10','Quarff','Lerwick','William ''Floorie'' Sinclair was a baker, a Provost of the Lerwick Town Council, and a County Councillor.','William was educated at St Magnus Walker''s School before going on to the Anderson Institute. He apprenticed with Malcolmsons & Co as a baker, and he later joined John Black & Sons and became a foreman there. After leaving that job, he joined Andrew Blance at the Alexandra Bakery. He then left baking and became a School Attendance Officer for a period, before returning to his trade, rejoining Black & Sons, which he continued through to around the start of the 1940s. He was a lifelong abstainer and a prominent member of the Independent Order Of Rechabites. He was also Worthy Chief Guizer in 1901, and the Guizer Jarl for the Lerwick Up Helly Aa in 1908.','William Sinclair Provost.png','William Sinclair Headshot.png','I235710','William_Sinclair','["Lerwick Town Council Provosts", "Lerwick Town Councillors", "Zetland County Councillors", "Councillors pictured", "1876 Births", "1945 Deaths"]',1,1,179137798);
INSERT INTO "people" VALUES(523,'William Smith (i)','william-smith-i','1871-11-27','1949-04-02','Sandwick','Sandwick','William Smith was a merchant and a County Councillor for Sandwick between 1904 and 1910.','William served his apprenticeship with [person:andrew-smith:Andrew Smith], but moved to Johannesburg around the age of 21. He returned to Shetland after the death of his father in 1896 and took over the family business. He kept running the business until 1927. During WWI he attained the rank of Paymaster-Lieutenant in the Royal Naval Reserve, and had a number of further public appointments such as the Broonie''s Taing Pier Trust and the Recreation Club and Public Hall committees of Sandwick.',NULL,NULL,'I103578','William_Smith_(i)','["Zetland County Councillors", "1871 Births", "1949 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(524,'William Smith (ii)','william-smith-ii','1849-04-15','1920-04-23','Lerwick','Lerwick','William Spence Smith was a draper, founder of Smith &amp; Robertson, and a Lerwick Town Councillor between 1907 until his resignation in 1916. His father [person:ross-smith:Ross Smith] was also a Lerwick Town councillor.','After leaving school, William started work in the booksellers shop of Charles D. Jamieson. Later, he worked with [person:george-tait:George Reid Tait] where he worked closely with seafarers, especially whalers. He spent a short time in Edinburgh, but otherwise lived his whole life in Lerwick. He started Smith & Robertsons with [person:hugh-robertson:Hugh Robertson], a drapers and outfitters.',NULL,NULL,'I11002','William_Smith_(ii)','["Lerwick Town Councillors", "1849 Births", "1920 Deaths"]',1,1,290655038);
INSERT INTO "people" VALUES(525,'William Smith (iii)','william-smith-iii','1897-06-19','1942-02-28','Mid Yell','Glasgow','William Guthrie ''Bill'' Smith was the Lerwick postman and Lerwick Town Councillor until his death in 1942.','William received his education in Lerwick and worked for a year or so until the war broke out. He volunteered for service on 25 November 1915 and served with the Gordon Highlanders in France, being dischanged in February 1919. He was involved in battle during the war, but escaped it without injury. AFter the water, William was employed in South Shields with the Ministry of Labour in South Shields. Later, he entered the employment of Messrs Williamson & Co, fish salesmen, as a foreman. His father had performed a similar role in Lerwick, and in April 1925, William joined the Lerwick Post Office as a postman. He served for 15 years, retiring in 1940 owing to ill health. He was for some time the chairman of the Lerwick branch of the Union of Post Office Workers. He also acted as secretary of the local branch of the Transport and General Workers Union. He stood under the Labour banner when he was elected in 1937.',NULL,NULL,'I23011','William_Smith_(iii)','["Lerwick Town Councillors", "1897 Births", "1942 Deaths"]',1,0,NULL);
INSERT INTO "people" VALUES(526,'William Smith (iv)','william-smith-iv','1919-08-20','2012-09-05','Hamnavoe','Lerwick','William Angus ''Bill'' Smith BEM was a former Post Office engineer, signal engineer, Lerwick Town Councillor, Shetland Islands Councillor and member of numerous other public bodies. In total, he was a councillor for 32 years when he retired in 1999.','<strong>Early Life</strong>

William Angus Smith was born in 1919 in Burra, the seventh and final child of James Smith (b. 1879) a fisherman and crofter, and Mary Jane Cumming (b. 1879). To his family and close friends he was ''Billy'' but otherwise he was known as ''Bill''. He was first educated at Hamnavoe Primary School and later moved on to the Anderson Educational Institute, as it was known. He left school aged 18 and his first job was also the one which he retained until retirement; a Post Office Telecomms engineer (barring 6 years of military service). Bill was first called up to the miliary in 1940 and worked as a signal engineer. During his term he served in various Middle Eastern and Asian countries, including Egypt, Syria, Iraq, Burma, Lybia, Germany and Palestine. Upon his return, he married Daisy Manson (1923-2005) and together they had 4 children.

<strong>Council Years</strong>

<strong>Lerwick Town Council</strong>

After the war, Bill joined the Labour party. He first properly became enlightened to political thought during his training in Yorkshire, where a Yorkshireman had shared an interest and inspired Bill. Although he had never really given a thought to becoming a councillor, he had canvassed for other well known Labour candidates such as [person:alexander-morrison:Alex Morrison]. It took a colleague at the Post Office to convince Bill to stand and in 1967, he submitted his nomination form. The Lerwick Town Council at the time was a 12-member council which represented Lerwick and elected normally four individuals every year. At this election, Bill came in fourth and was elected, gathering 604 votes, with the next nearest Labour man coming in seventh. Bill''s seat was up for election again in 1969 and this would be the last time he would stand as a Lerwick Town Councillor. The election itself was a sweeping victory for the Labour party, with all four vacant seats won. Bill came in third with 1,054 votes. It was during this period of office that Bill became Provost, taking over from [person:eric-gray:Eric Gray] and holding the post from 1971 until 1974 when Jim Taylor took over. The Lerwick Council eventually dissolved in August 1975 and was replaced by the Shetland Islands Council.

<strong>Shetland Islands Council</strong>

The first ever Shetland Islands Council election occurred in 1974, one year before it officially began business. Bill, describing the situation, said that to him and a few other councillors the end of the LTC and beginning of the SIC &quot;felt more like a takeover&quot;. Despite this, Bill stood in the Lerwick West constituency and was elected unopposed. Lerwick West was abolished for the next election in 1978, and Bill stood for the Lerwick Central constituency and he was successful in this election, and every following one; 1982, 1986, 1990, 1994. In 1978, he beat James Wiseman by 200 votes, and for the following two elections he was unopposed. In 1990, he beat Liberal Democrat candidate Kenneth Crossan by 91 votes, and independent Tommy Goudie in 1994 by 146 votes. Bill decided not to stand again in 1999, ending his 32 years of service as a councillor.

<strong>Post-Council Life</strong>

In reflecting upon his decision to end his council career, Bill admitted that he had caught himself increasingly wondering if the "old way" of Council business was better than the newer way. He knew that this attitude wasn''t productive and he didn''t want to hold up progress and so felt that he should no longer continue as a councillor. He was in his 80''s when he left the council and retired to his home in Lerwick where he resided until his death in 2012 at the age of 93.','Bill Smith.png','Bill Smith Headshot.png','I121507','William_Smith_(iv)','["Lerwick Town Councillors", "Shetland Islands Councillors", "1919 Births", "2012 Deaths", "Labour"]',1,1,NULL);
INSERT INTO "people" VALUES(527,'William Spence','william-spence','1782-09-03','1849-07-19','Hamar','Lerwick','William Spence was a staff-surgeon and Lerwick Town Councillor.','William was a staff-surgeon in the Royal Navy, and was a descendent of the Spence of Greenfield family. He was the first chairman of the fee-paying Subscription School in Lerwick, which operated from 1839 until 1844. He lived in Greenfield Cottage, near modern day Church Road in Lerwick. William had a chromate ore crushing operation in the garden at the back of the house. His interest in this activity was linked to his daughter, Jane, who married Gilbert Spence of Hammer in Unst, who operated a chromate quarry there.',NULL,NULL,'I4220','William_Spence','["Lerwick Town Councillors", "1782 Births", "1849 Deaths", "Spence"]',1,1,205467575);
INSERT INTO "people" VALUES(528,'William Stove','william-stove','1941-05-06',NULL,'Lerwick',NULL,'William Nicolson ''Billy'' Stove is a former Shetland Islands Councillor who represented Lerwick Clickimin from 1994 until 2007.',NULL,NULL,NULL,'I59616','William_Stove','["Shetland Islands Councillors", "Natives of Shetland", "1941 Births"]',1,NULL,NULL);
INSERT INTO "people" VALUES(529,'William Tait','william-tait','1928-05-18','2021-03-19','Ireland',NULL,'William ''Willie'' Tait is a former whaler, crofter and Shetland Islands Councillor first for Dunrossness North between 1978 and 1999, then Sandwick from 1999 until 2007.',NULL,NULL,NULL,'I55663','William_Tait','["Shetland Islands Councillors", "Natives of Shetland", "1928 Births"]',0,NULL,NULL);
INSERT INTO "people" VALUES(530,'William Thomson (i)','william-thomson-i','1906-10-29','1959-12-22','Swinister','Sandwick','William Thomson was a Garage Owner, Car Hirer and Convener of the County Council.
He was County Councillor for Sandwick between 1935 and 1955.','William went in to business as a car hirer at Swinster, Sandwick sometime before 1923, which developed in to goods and passenger carrying work when a Model T Ford was purchased in or around that year. The business bought its first bus in 1936 and traded under the name &quot;Thomson&quot; until 1962 when it merged with the fellow Sandwick bus operator &quot;P. J. Smith&quot; to become the &quot;Sandwick Transport Co.&quot; In 1940 he bought the business of &quot;Thomson''s Motor Garage&quot; in Lerwick from Charlie Thomson, situated on the Esplanade (now demolished}, which continued trading under the same business name and went on to become a Vauxhall - Bedford dealership.','Willie Thomsons bus - Shetland Museumand Archives NE04557.jpg',NULL,'I167619','William_Thomson_(i)','["Zetland County Councillors", "1906 Births", "1959 Deaths"]',1,1,NULL);
INSERT INTO "people" VALUES(531,'William Thomson (ii)','william-thomson-ii','1925-03-07','1993-03-02','Baltasound','Twatt','William Gray ''Willie'' Thomson was briefly a County Councillor for Unst North between 1973 and 1975,','He worked for the council most of his life and was the first chair of the Lerwick Community Council, in the 1970''s.',NULL,NULL,'I39783','William_Thomson_(ii)','["Zetland County Councillors", "1925 Births", "1993 Deaths"]',1,1,215498646);
INSERT INTO "people" VALUES(532,'William Thomson (iii)','william-thomson-iii','1933','2016','Ayrshire -','Aberdeen','William Paterson Loudon Thomson OBE, MA, M.Univ., Dip.Ed., FSA Scot was a historian and Lerwick Town Councillor.','He was educated at Dundee and the University of St Andrews. He was the first teacher of geography at the Anderson Educational Institute, Lerwick, in 1958, and became headmaster at Kirkwall Grammar School in 1971. He was a town councillor in Lerwick from 1968-1971. He is author of a very fine History of Orkney (1987), later New History of Orkney (2001, 2008), which contains much of interest for students of Shetland. Thomson has taken a special interest in the problem of runrig agriculture in Shetland and Orkney. He dealt with the subject first in a pioneering article ''Funzie, Fetlar: a Shetland run-rig township in the nineteenth century'', Scottish Geographical Magazine, 86, 1970; he has returned to it in his recent collection of essays Orkney Land and People (2008).',NULL,NULL,NULL,'William_Thomson_(iii)','["Lerwick Town Councillors", "1933 Births", "2016 Deaths"]',0,0,NULL);
INSERT INTO "people" VALUES(533,'William Tulloch','william-tulloch','1858-09-02','1943-07-02','Lerwick','Lerwick','William Arthur Alexander Tulloch was clerk of the Lerwick Harbour Trust (now Lerwick Port Authority) and also a County Councillor for Lerwick North from 1901 until 1919, losing the 1919 election. William first stood as a Councillor in an 1896 Aithsting by-election, but ended up receiving zero votes again victor [person:george-johnston:George Johnston]''s 56. William had initially been put forward for the seat by [person:archibald-garriock:Archibald Garriock], on the understanding that [person:george-johnston:George Johnston] was not going to stand, but by the time the latter decided to stand it was too late to cancel the by-election.','William was born at 45 Commercial Street, a premises in which he would later conduct business. He was educated at Hunter''s School in Lerwick, later going to the Anderson Educational Institute where in 1872 he won the dux medal in Latin. He went on to George Waterson''s College in Edinburgh and upon leaving education joined Messrs Laurenson & Coy, drapers and milliners with his uncle, [person:arthur-laurenson:Arthur Laurenson]. In 1887, he became the sole partner to the business.',NULL,NULL,'I13173','William_Tulloch','["Zetland County Councillors", "1858 Births", "1943 Deaths"]',1,1,163057253);
INSERT INTO "people" VALUES(534,'Williamina Tait','williamina-tait','1935-06-20','2014-05-03','Baridster','St. Andrews, Fife','Williamina Petricia ''Ena'' Tait (neé Jamieson) was a Zetland County Councillor and Shetland Islands Councillor for the Walls and Sandness and Walls constituencies from 1970 until 1978, where she failed to get re-elected.',NULL,NULL,NULL,'I41235','Williamina_Tait','["Zetland County Councillors", "Shetland Islands Councillors", "Female", "1935 Births", "2014 Deaths", "Biography Missing"]',1,0,NULL);
INSERT INTO "people" VALUES(535,'Zachary Hamilton','zachary-hamilton','1855-04-03','1905-12-23','Bressay','Unst','Zachary Macaulay Hamilton, son of the Reverend Zachary, was a County Councillor for Yell North from 1890 until his death in 1905. His son, [person:william-hamilton:William] was a County Councillor for Nesting between 1955 and 1973. He withdrew from the running of the Unst South seat in the inaugural Zetland County Council election in 1890, but was elected to represent Yell North at the same election anyway.','After completing his education, Zachary became a sheep farmer and breeder. He later had a dalliance in the herring-curing but it was not a success. In later life, he became the Factor to the estates of Garth, Annsbrae and Burravoe. Despite his bad experience with fishcuring, he maintained a passion for boats and fishing, and used his privileged position to help other Shetlanders acquire boats and gears. He was involved in the Shetland Agricultural Society.',NULL,NULL,'I17127','Zachary_Hamilton','["Zetland County Councillors", "1855 Births", "1905 Deaths"]',1,1,175970989);
INSERT INTO "people" VALUES(536,'Beatrice Wishart','beatrice-wishart',NULL,NULL,NULL,NULL,'Beatrice Wishart is the Scottish Liberal Democrat Member of the Scottish Parliament for Shetland Islands. She won the seat at the 2019 by-election following the resignation of Tavish Scott, and was re-elected in 2021. She previously served as a Shetland Islands councillor for Lerwick South from 2017.',NULL,NULL,NULL,NULL,NULL,'["Female", "Shetland Islands Councillors"]',NULL,NULL,NULL);
