INSERT INTO "people" VALUES(563,'Andrew Duncan (ii)','andrew-duncan-ii','1800-10-13','1852-09-01','Lerwick','Lerwick','Andrew Duncan was a writer in Lerwick and a Lerwick Town Councillor between 1829 and 1832. He was the eldest son of [person:andrew-duncan:Andrew Duncan], Sheriff Substitute for Shetland, and a nephew of fellow councillor [person:gilbert-duncan:Gilbert Duncan]. He was elected to the council on 3 September 1829, styled "Andrew Duncan Junior, Writer" in the minute book to distinguish him from his father, who presided over the same meeting as Sheriff. He served until the election of 6 September 1832, at which he was not returned. As a lawyer he represented the plaintiff in Eunson v. Bruce of Symbister, a tenancy dispute that ran through the late 1840s and early 1850s.',NULL,NULL,NULL,'I10526',NULL,'["Lerwick Town Councillors", "Solicitors", "1800 Births", "1852 Deaths", "Duncan"]',1,1,NULL);
INSERT INTO "people" VALUES(564,'Magnus Burns','magnus-burns','1757','1846-01-09','Cruicikirk, Unst','Lerwick','Magnus Burns was a merchant in Lerwick and a Lerwick Town Councillor between 1830 and 1832. He was elected at a by-election on 21 April 1830 to fill the vacancy caused by the death of [person:alexander-irvine:Alexander Irvine], and was not returned at the election of 6 September 1832. Pressed into the Royal Navy in 1793, he lost an arm at Lord Howe''s victory of 1 June 1794 before settling in Lerwick as a merchant and property owner; Burns Lane is named after the houses he built there. He was the father of Lerwick Town Councillor [person:david-burns:David Nisbet Burns].',NULL,NULL,NULL,'I122332',NULL,'["Lerwick Town Councillors", "1757 Births", "1846 Deaths"]',1,1,NULL);
CREATE TABLE referenda (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    date TEXT,
    question TEXT,
    description TEXT,         -- context/intro text
    turnout_pct REAL,
    wiki_page_title TEXT
);
INSERT INTO "referenda" VALUES(1,'1975 European Economic Community Membership Referendum','1975-european-economic-community-membership-referendum','1975-01-01',NULL,'In 1975 there was a referendum which asked "Should Britain remain part of the European Economic Community?" (the forerunner of the European Union). 

Significantly, Shetland and the Western Isles were the only two county areas in the United Kingdom which voted against joining the European Organisation.',47.1,'1975_European_Economic_Community_Membership_Referendum');
INSERT INTO "referenda" VALUES(2,'1979 Scottish Devolution Referendum','1979-scottish-devolution-referendum','1979-01-01',NULL,'In 1979 there was a referendum to see if power should be devolved and a Scottish Parliament created. The statement which the people of Scotland were given to vote on was "Do You Want The Provisions Of The Scotland Act 1978 To Be Put Into Effect?".

Shetlanders rejected the proposal by the largest margin in Scotland, with Orkney closely behind at 72% (with the next nearest at 59% in the Borders). Despite a majority of Scots voting in favour of the proposal (51.6%), the Act required a total of 40% of the registered electorate to vote in favour for the referendum to pass. On a turnout of 64%, only 32.1% of registered Scottish voters voted Yes, therefore the Labour Government of the day deemed that Scotland would not get a Parliament.',50.3,'1979_Scottish_Devolution_Referendum');
INSERT INTO "referenda" VALUES(3,'1997 Scottish Devolution Referendum','1997-scottish-devolution-referendum','1997-01-01',NULL,'In 1997 there was a referendum to see if power should be devolved and a Scottish Parliament created. The Scottish public were asked to vote on two statements:

* "I agree/do not agree that there should be a Scottish Parliament as proposed by the Government?".
* "I agree/do not agree that a Scottish Parliament should have tax-varying powers"

Nationally, Scots voted 74% ''agree'' to the first question, and 63% ''agree'' to the second. In Shetland, these figures were 62% and 52% respectively. For the both questions, Shetland had the 5th highest ''disagree'' vote of all counties in Scotland.',37.6,'1997_Scottish_Devolution_Referendum');
INSERT INTO "referenda" VALUES(4,'2011 Alternative Vote Referendum','2011-alternative-vote-referendum','2011-01-01',NULL,'In 2011 there was a referendum which asked "At present, the UK uses the "first past the post" system to elect MPs to the House of Commons. Should the "alternative vote" system be used instead?" 

Every single county area in the UK rejected the Alternative Vote referendum. 

53.7 per cent of Shetland voters cast their ballots with 5,079 (55 per cent) saying no and 4,121 (45 per cent) saying yes',53.7,'2011_Alternative_Vote_Referendum');
INSERT INTO "referenda" VALUES(5,'2014 Scottish Independence Referendum','2014-scottish-independence-referendum','2014-01-01',NULL,'In 2011 there was a referendum which asked "Should Scotland be an independent country?" 

Shetland, along with all but five constituencies in Scotland voted against Independence. The turnout was among the largest in Shetland''s voting history, at 83.7%.',83.7,'2014_Scottish_Independence_Referendum');
INSERT INTO "referenda" VALUES(6,'2016 European Union Membership Referendum','2016-european-union-membership-referendum','2016-01-01',NULL,'In 2016 there was a referendum which asked "Should the United Kingdom remain a member of the European Union or leave the European Union?" 

Every constituency in Scotland voted Remain, but the overall UK result was 52% in favour of leaving the European Union.',70.4,'2016_European_Union_Membership_Referendum');
CREATE TABLE referendum_results (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    referendum_id INTEGER NOT NULL REFERENCES referenda(id),
    question_label TEXT,      -- for multi-question referenda (e.g. 1997 had 2 questions)
    option_name TEXT NOT NULL, -- 'Yes', 'No', 'Remain', 'Leave', etc.
    votes INTEGER,
    percentage REAL,
    won INTEGER NOT NULL DEFAULT 0  -- boolean
);
